EXDATA.written = {"subjects":{"computer":{"name":"컴퓨터 일반","topics":["운영체제","시스템 설정","하드웨어","소프트웨어","자료 표현","네트워크·인터넷","멀티미디어","정보 보안","최신 기술"]},"spreadsheet":{"name":"스프레드시트 일반","topics":["환경·파일","입력·편집","서식","수식·함수","데이터 관리","데이터 분석","차트","출력","매크로·VBA"]},"database":{"name":"데이터베이스 일반","topics":["DB 개념","테이블","관계·키","쿼리·SQL","폼","보고서","매크로·모듈"]}},"levels":{"c2":{"name":"2급","subjects":["computer","spreadsheet"],"minutes":40},"c1":{"name":"1급","subjects":["computer","spreadsheet","database"],"minutes":60}},"perSubject":20,"subjectCut":40,"averageCut":60,"questions":[{"id":"pc-0001","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"소프트웨어를 설치하지 않고 인터넷을 통해 필요한 만큼 빌려 쓰는 클라우드 서비스 형태는?","options":["PaaS","SaaS","VPN","IaaS"],"answer":1,"explain":"SaaS는 소프트웨어를, PaaS는 개발 플랫폼을, IaaS는 서버·저장소 같은 인프라를 서비스로 제공한다."},{"id":"pc-0002","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"바로 가기 아이콘에 관한 설명으로 옳지 않은 것은?","options":["바로 가기 아이콘을 삭제하면 원본 파일도 함께 삭제된다","폴더·드라이브·프린터에도 바로 가기를 만들 수 있다","하나의 원본에 여러 개의 바로 가기를 만들 수 있다","바로 가기 파일의 확장자는 .lnk이다"],"answer":0,"explain":"바로 가기는 원본의 위치 정보만 가진 연결 파일이므로 지워도 원본에는 영향이 없다. 반대로 원본을 지우면 바로 가기는 실행되지 않는다."},{"id":"pc-0003","subject":"computer","levels":["c1"],"topic":"운영체제","q":"CPU 하나로 여러 프로그램을 동시에 주기억장치에 올려 두고 번갈아 실행하여 CPU 유휴 시간을 줄이는 방식은?","options":["다중 처리","일괄 처리","실시간 처리","다중 프로그래밍"],"answer":3,"explain":"다중 프로그래밍은 CPU 하나로 여러 프로그램을 번갈아 처리한다. 다중 처리는 CPU 여러 개로 동시에 처리하는 방식이다."},{"id":"pc-0004","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"전파로 태그(Tag)의 정보를 접촉 없이 읽어 물류·재고·출입 관리에 쓰는 기술은?","options":["테더링","지그비(ZigBee)","블루투스","RFID"],"answer":3,"explain":"RFID는 태그와 판독기로 사물을 식별한다. 지그비는 저전력 근거리 무선 네트워크(센서·스마트 홈), 테더링은 스마트폰을 핫스팟으로 쓰는 기능이다."},{"id":"pc-0005","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows 사용자 계정에 관한 설명으로 옳지 않은 것은?","options":["표준 사용자도 다른 사용자 계정을 만들고 삭제할 수 있다","표준 사용자가 시스템 설정을 바꾸려면 관리자 승인이 필요하다","관리자는 다른 계정의 유형을 바꿀 수 있다","Microsoft 계정과 로컬 계정을 모두 사용할 수 있다"],"answer":0,"explain":"다른 사용자 계정을 만들거나 삭제하고 유형을 바꾸는 일은 관리자 계정만 할 수 있다."},{"id":"pc-0006","subject":"computer","levels":["c1"],"topic":"시스템 설정","q":"인쇄 대기열(인쇄 작업 창)에서 할 수 있는 작업으로 옳지 않은 것은?","options":["인쇄가 시작된 문서를 다른 프린터로 넘겨 이어서 인쇄","대기 중인 문서의 인쇄 작업 취소","대기 중인 문서의 인쇄 우선순위 변경","인쇄 작업의 일시 중지와 다시 시작"],"answer":0,"explain":"이미 인쇄가 시작된 문서를 다른 프린터로 보내 이어서 인쇄할 수는 없다. 취소·일시 중지·순서(우선순위) 변경은 할 수 있다."},{"id":"pc-0007","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"IPv4 주소에 관한 설명으로 옳지 않은 것은?","options":["32비트 주소 체계이다","16비트씩 8부분을 콜론(:)으로 구분한다","A~E 클래스로 나뉜다","8비트씩 4부분을 점(.)으로 구분한다"],"answer":1,"explain":"16비트씩 8부분을 콜론으로 구분하는 것은 128비트 IPv6이다."},{"id":"pc-0008","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"휴지통에 관한 설명으로 옳지 않은 것은?","options":["속성에서 파일을 휴지통에 두지 않고 바로 제거하도록 할 수 있다","휴지통의 파일을 더블클릭하면 원래 앱에서 열어 편집할 수 있다","휴지통에서 복원한 파일은 삭제 전의 원래 위치로 돌아간다","드라이브마다 휴지통의 최대 크기를 따로 정할 수 있다"],"answer":1,"explain":"휴지통 안의 파일은 실행하거나 편집할 수 없고 더블클릭하면 속성 창이 열린다. 먼저 복원해야 쓸 수 있다."},{"id":"pc-0009","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"일정 기간 무료로 쓰거나 일부 기능을 제한해 배포하고, 계속 쓰려면 정식 제품을 구입해야 하는 소프트웨어는?","options":["번들 소프트웨어","셰어웨어","프리웨어","패치 프로그램"],"answer":1,"explain":"셰어웨어는 기간·기능 제한 후 구입을 유도한다. 프리웨어는 기간 제한 없이 무료이다."},{"id":"pc-0010","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"소프트웨어 종류와 설명의 연결로 옳지 않은 것은?","options":["알파 버전: 일반 사용자에게 공개해 오류를 찾는다","데모 버전: 홍보를 위해 기능·기간을 제한해 배포한다","베타 버전: 정식 출시 전 일반 사용자에게 공개해 시험한다","번들: 하드웨어나 다른 제품을 살 때 함께 제공된다"],"answer":0,"explain":"일반 사용자에게 공개해 시험하는 것은 베타 버전이다. 알파 버전은 개발 회사 내부에서 시험한다."},{"id":"pc-0011","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"프린터 성능 단위 중 1분 동안 인쇄할 수 있는 페이지 수를 나타내는 것은?","options":["LPM","PPM","CPS","DPI"],"answer":1,"explain":"PPM은 분당 페이지 수, CPS는 초당 문자 수, LPM은 분당 줄 수, DPI는 1인치당 점의 수(해상도)이다."},{"id":"pc-0012","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"이전에 복사한 여러 항목을 목록으로 보여 주어 골라서 붙여 넣을 수 있게 하는 클립보드 검색 기록 창을 여는 키는?","options":["Win+B","Win+G","Win+N","Win+V"],"answer":3,"explain":"Win+V는 클립보드 검색 기록을 연다(설정에서 켜야 기록됨). Win+G는 Xbox Game Bar, Win+B는 알림 영역으로 포커스 이동, Win+N은 알림 센터(Windows 11)이다."},{"id":"pc-0013","subject":"computer","levels":["c1"],"topic":"운영체제","q":"대용량 플래시 메모리용으로 만들어져 4GB가 넘는 파일을 저장할 수 있고 여러 운영체제와 호환성이 좋은 파일 시스템은?","options":["CDFS","FAT32","FAT16","exFAT"],"answer":3,"explain":"exFAT는 USB 메모리·SD 카드용으로 4GB 초과 파일을 지원한다. FAT32는 파일 하나가 4GB를 넘을 수 없다."},{"id":"pc-0014","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"운영체제의 성능 평가 기준 중 사용자가 작업을 맡긴 뒤 결과를 받을 때까지 걸린 시간을 뜻하는 것은?","options":["반환 시간(Turnaround Time)","사용 가능도(Availability)","신뢰도(Reliability)","처리 능력(Throughput)"],"answer":0,"explain":"반환 시간은 짧을수록 좋다. 처리 능력은 단위 시간당 처리량, 사용 가능도는 필요할 때 즉시 쓸 수 있는 정도, 신뢰도는 오류 없이 처리하는 정도이다."},{"id":"pc-0015","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"무손실 압축을 쓰고 트루컬러와 알파 채널(반투명)을 지원하며, GIF를 대체하려고 만든 웹 그래픽 형식은?","options":["TIFF","PNG","BMP","JPEG"],"answer":1,"explain":"PNG는 무손실 압축과 투명도를 지원하지만 애니메이션은 기본 기능이 아니다."},{"id":"pc-0016","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"Linux에 관한 설명으로 옳지 않은 것은?","options":["소스 코드가 공개된 유닉스 계열 운영체제이다","다중 사용자·다중 작업을 지원한다","서버와 임베디드 장치에 널리 쓰인다","특정 회사만 소스 코드를 고칠 수 있는 상용 운영체제이다"],"answer":3,"explain":"Linux는 소스 코드가 공개된 오픈 소스 운영체제로 누구나 수정·배포할 수 있다."},{"id":"pc-0017","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"인가된 사용자만 정보에 접근할 수 있도록 하여 정보가 노출되지 않게 하는 보안 요소는?","options":["무결성","부인 방지","가용성","기밀성"],"answer":3,"explain":"기밀성은 허가된 사람만 볼 수 있게 하는 것이다. 무결성은 허가된 사람만 수정하는 것, 가용성은 필요할 때 쓸 수 있는 것이다."},{"id":"pc-0018","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"여러 장의 디스크 원판에서 같은 위치에 있는 트랙들의 모임을 뜻하는 것은?","options":["트랙(Track)","섹터(Sector)","클러스터(Cluster)","실린더(Cylinder)"],"answer":3,"explain":"실린더는 같은 반지름의 트랙 묶음이다. 섹터는 트랙을 나눈 최소 기록 단위, 클러스터는 섹터 여러 개를 묶은 할당 단위이다."},{"id":"pc-0019","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"정상적인 인증 절차를 거치지 않고 시스템에 접근할 수 있도록 몰래 만들어 둔 통로는?","options":["백도어(Back Door)","스니핑(Sniffing)","루트킷(Rootkit)","웜(Worm)"],"answer":0,"explain":"백도어는 트랩 도어라고도 하며, 개발자가 남기거나 공격자가 심는다."},{"id":"pc-0020","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"10명이 서로 1:1로 비밀 통신을 하려고 대칭키 방식을 쓸 때 필요한 키의 개수는?","options":["10개","20개","45개","90개"],"answer":2,"explain":"대칭키는 두 사람마다 키 하나가 필요하므로 n(n-1)/2 = 10×9/2 = 45개이다. 공개키 방식이라면 2n = 20개이다."},{"id":"pc-0021","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"CPU의 클럭 속도에 관한 설명으로 옳은 것은?","options":["단위는 bps이며 1초에 전송하는 비트 수이다","단위는 dpi이며 1인치에 찍는 점의 수이다","단위는 Hz이며 같은 구조라면 높을수록 빠르다","단위는 MIPS이며 1초에 처리하는 명령어 수이다"],"answer":2,"explain":"클럭은 CPU가 1초에 내는 신호 주기 수로 Hz(GHz)로 나타낸다. MIPS·bps·dpi는 다른 성능 단위이다."},{"id":"pc-0022","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"시스템 파일·설치된 앱·레지스트리를 복원 지점 때의 상태로 되돌리며, 개인 문서 파일에는 영향을 주지 않는 기능은?","options":["파일 히스토리","시스템 복원","디스크 정리","드라이브 최적화"],"answer":1,"explain":"시스템 복원은 시스템 설정을 이전 복원 지점으로 되돌린다. 개인 파일을 이전 버전으로 되살리는 것은 파일 히스토리이다."},{"id":"pc-0023","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows에 로그인할 때 자동으로 실행되는 앱을 [사용 안 함]으로 바꿀 수 있는 곳은?","options":["이벤트 뷰어의 [응용 프로그램] 로그","장치 관리자의 [시스템 장치]","디스크 관리의 [볼륨] 목록","작업 관리자의 [시작 앱] 탭"],"answer":3,"explain":"작업 관리자의 [시작 앱](Windows 10은 [시작프로그램]) 탭이나 [설정]-[앱]-[시작 프로그램]에서 자동 실행을 끌 수 있다."},{"id":"pc-0024","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows에서 파일이나 폴더 이름으로 사용할 수 없는 것은?","options":["회의록(최종)","회의록 #2","회의록?최종","회의록_최종"],"answer":2,"explain":"\\ / : * ? \" < > | 는 이름에 쓸 수 없다. 밑줄·괄호·공백·#은 사용할 수 있다."},{"id":"pc-0025","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows의 프린터 설정에 관한 설명으로 옳지 않은 것은?","options":["인쇄 대기 중인 문서는 일시 중지하거나 취소할 수 있다","네트워크 프린터도 기본 프린터로 지정할 수 있다","기본 프린터는 한 컴퓨터에 여러 대를 동시에 지정할 수 있다","프린터를 따로 고르지 않으면 기본 프린터로 인쇄된다"],"answer":2,"explain":"기본 프린터는 한 번에 한 대만 지정된다. 로컬·네트워크 프린터 모두 기본 프린터가 될 수 있다."},{"id":"pc-0026","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 내용을 저장 장치(디스크)에 기록한 뒤 전원을 완전히 끄고, 다시 켜면 이전 작업 상태로 복원하는 전원 모드는?","options":["빠른 사용자 전환","절전 모드","최대 절전 모드","화면 보호기"],"answer":2,"explain":"최대 절전 모드는 메모리 내용을 디스크에 저장하고 전원을 끈다. 절전 모드는 메모리에 전원을 유지한 채 대기한다."},{"id":"pc-0027","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 표시줄의 앱 아이콘을 마우스 오른쪽 단추로 눌렀을 때 그 앱에서 최근에 연 파일 등이 표시되는 목록은?","options":["점프 목록","위젯","작업 보기","빠른 링크 메뉴"],"answer":0,"explain":"점프 목록은 앱별 최근 항목·자주 쓰는 항목을 보여 준다. 빠른 링크 메뉴는 시작 단추 오른쪽 클릭(Win+X)으로 연다."},{"id":"pc-0028","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"인쇄할 데이터를 디스크에 임시로 저장했다가 프린터 속도에 맞춰 보내, 인쇄 중에도 다른 작업을 할 수 있게 하는 기능은?","options":["캐싱(Caching)","스풀(Spool)","인터리빙(Interleaving)","디더링(Dithering)"],"answer":1,"explain":"스풀은 느린 출력 장치와 빠른 CPU의 속도 차이를 줄인다. 스풀을 쓰면 인쇄 속도 자체는 빨라지지 않는다."},{"id":"pc-0029","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[설정]-[시스템]-[디스플레이]에 관한 설명으로 옳은 것은?","options":["해상도를 높이면 항목이 커지고 보이는 내용이 줄어든다","배율(%)을 높이면 텍스트와 앱 크기가 작아진다","해상도를 높이면 항목이 작아지고 더 많은 내용이 보인다","해상도는 [개인 설정]의 [테마]에서만 바꿀 수 있다"],"answer":2,"explain":"해상도가 높을수록 픽셀이 많아져 항목은 작게, 내용은 많이 보인다. 배율을 높이면 텍스트·앱이 커진다."},{"id":"pc-0030","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"대칭키(비밀키) 암호화 방식에 관한 설명으로 옳은 것은?","options":["키를 나눠 줄 필요가 없어 전자 서명에 주로 쓴다","대표적인 알고리즘은 RSA이다","공개키와 개인키 두 개의 키를 쓴다","암호화와 복호화에 같은 키를 쓴다"],"answer":3,"explain":"대칭키는 같은 키를 쓰며 DES·AES가 대표적이다. 두 키·RSA·전자 서명은 비대칭키(공개키) 방식의 특징이다."},{"id":"pc-0031","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"기계어와 1:1로 대응하는 기호(니모닉)로 명령을 표현하는 저급 언어는?","options":["JavaScript","C 언어","Python","어셈블리어"],"answer":3,"explain":"어셈블리어는 어셈블러로 기계어로 바뀌는 저급 언어이다. 나머지는 고급 언어이다."},{"id":"pc-0032","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"앱이 컴퓨터 설정을 바꾸려 할 때 알림을 표시해 관리자의 승인을 받도록 하는 Windows 기능은?","options":["Windows Defender 방화벽","파일 히스토리","사용자 계정 컨트롤(UAC)","BitLocker"],"answer":2,"explain":"UAC는 관리자 권한이 필요한 변경을 할 때 확인 창을 띄운다. BitLocker는 드라이브 암호화, 파일 히스토리는 개인 파일 백업 기능이다."},{"id":"pc-0033","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"인공 신경망을 여러 층으로 쌓아 데이터에서 특징을 스스로 학습하는 머신러닝 기법은?","options":["전문가 시스템","데이터 웨어하우스","딥러닝","RPA"],"answer":2,"explain":"딥러닝은 심층 신경망을 이용한 머신러닝이다. RPA는 반복 업무를 소프트웨어 로봇으로 자동화하는 기술이다."},{"id":"pc-0034","subject":"computer","levels":["c1"],"topic":"운영체제","q":"NTFS 파일 시스템에 관한 설명으로 옳지 않은 것은?","options":["파일·폴더 단위로 사용 권한을 지정할 수 있다","EFS를 이용해 파일을 암호화할 수 있다","파일 하나의 최대 크기가 4GB로 제한된다","사용자별 디스크 할당량을 설정할 수 있다"],"answer":2,"explain":"파일 하나가 4GB를 넘지 못하는 것은 FAT32의 제한이다. NTFS는 권한·암호화(EFS)·압축·디스크 할당량을 지원한다."},{"id":"pc-0035","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"인터프리터(Interpreter)에 관한 설명으로 옳은 것은?","options":["목적 프로그램을 만든 뒤 실행해 실행 속도가 빠르다","전체를 한꺼번에 번역하므로 번역 시간이 길다","프로그램을 한 줄씩 번역하며 바로 실행한다","C, C++ 같은 언어에서 주로 사용한다"],"answer":2,"explain":"인터프리터는 목적 프로그램을 만들지 않고 줄 단위로 번역·실행한다. 나머지는 컴파일러의 특징이다."},{"id":"pc-0036","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"64비트 Windows에 관한 설명으로 옳은 것은?","options":["32비트 CPU에도 그대로 설치할 수 있다","4GB보다 큰 주기억장치(RAM)를 활용할 수 있다","32비트 응용 프로그램은 전혀 실행할 수 없다","16비트 응용 프로그램을 그대로 실행할 수 있다"],"answer":1,"explain":"64비트 Windows는 4GB를 넘는 RAM을 쓸 수 있고 32비트 앱도 실행한다. 16비트 앱은 실행할 수 없고 64비트 CPU가 필요하다."},{"id":"pc-0037","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"네트워크에 흐르는 패킷을 몰래 엿보아 아이디·비밀번호 같은 정보를 가로채는 행위는?","options":["스푸핑(Spoofing)","피싱(Phishing)","스니핑(Sniffing)","서비스 거부(DoS)"],"answer":2,"explain":"스니핑은 도청하듯 패킷을 엿본다. 스푸핑은 주소 등을 위조해 다른 대상인 것처럼 속인다."},{"id":"pc-0038","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"다음 중 동영상 파일 형식이 아닌 것은?","options":["MOV","MP4","AVI","WAV"],"answer":3,"explain":"WAV는 오디오 형식이다. AVI(Microsoft), MP4(MPEG-4), MOV(Apple)는 동영상 형식이다."},{"id":"pc-0039","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"컴파일러가 만든 여러 목적 프로그램과 라이브러리를 연결하여 실행 가능한 로드 모듈을 만드는 프로그램은?","options":["링커(Linker)","어셈블러(Assembler)","컴파일러(Compiler)","로더(Loader)"],"answer":0,"explain":"원시 프로그램 → 컴파일러 → 목적 프로그램 → 링커 → 로드 모듈 → 로더 → 실행 순이다. 로더는 로드 모듈을 주기억장치에 올린다."},{"id":"pc-0040","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"최대 256색을 표현하며 여러 장면을 이어 간단한 애니메이션을 만들 수 있는 그래픽 형식은?","options":["GIF","JPEG","PNG","BMP"],"answer":0,"explain":"GIF는 8비트(256색)와 애니메이션을 지원한다. JPEG는 사진용 손실 압축, BMP는 압축하지 않는 Windows 기본 형식이다."},{"id":"pc-0041","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"8비트 2의 보수 표현으로 -5를 나타낸 것은?","options":["11111011","10000101","00000101","11111010"],"answer":0,"explain":"+5(00000101)의 1의 보수 11111010에 1을 더하면 11111011이다. 11111010은 1의 보수, 10000101은 부호와 절댓값 표현이다."},{"id":"pc-0042","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"시작 단추를 마우스 오른쪽 단추로 누르거나 Win+X를 누르면 나타나며, 장치 관리자·디스크 관리·터미널(Windows 10은 Windows PowerShell) 등을 바로 실행할 수 있는 메뉴는?","options":["알림 센터","작업 보기","점프 목록","빠른 링크 메뉴"],"answer":3,"explain":"Win+X 메뉴(빠른 링크 메뉴)에는 시스템 관리 도구가 모여 있다. 점프 목록은 작업 표시줄 앱 아이콘의 오른쪽 클릭 메뉴이다."},{"id":"pc-0043","subject":"computer","levels":["c1"],"topic":"시스템 설정","q":"바탕 화면·문서 등 개인 파일을 외부 드라이브에 주기적으로 백업해, 실수로 지우거나 바꾼 파일을 이전 버전으로 복원할 수 있게 하는 기능은?","options":["시스템 복원","파일 히스토리","디스크 정리","BitLocker"],"answer":1,"explain":"파일 히스토리는 개인 파일의 여러 버전을 보관한다. 시스템 복원은 개인 파일이 아니라 시스템 상태를 되돌린다."},{"id":"pc-0044","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"시스템의 관리자 권한을 얻은 뒤 자신의 존재와 침입 흔적을 숨기도록 만든 악성 도구 모음은?","options":["루트킷(Rootkit)","혹스(Hoax)","애드웨어(Adware)","백도어(Back Door)"],"answer":0,"explain":"루트킷은 탐지를 피하도록 프로세스·파일을 숨긴다. 백도어는 인증 없이 들어오는 비밀 통로이다."},{"id":"pc-0045","subject":"computer","levels":["c1"],"topic":"시스템 설정","q":"[디스크 관리]에서 할 수 있는 작업으로 옳지 않은 것은?","options":["하드 디스크의 조각 모음 실행","드라이브 문자와 경로 변경","새 볼륨 만들기와 포맷","볼륨의 확장과 축소"],"answer":0,"explain":"조각 모음은 [드라이브 최적화]에서 한다. 디스크 관리는 파티션(볼륨) 생성·삭제·확장·축소, 포맷, 드라이브 문자 변경을 한다."},{"id":"pc-0046","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 바로 가기 키와 기능의 연결로 옳지 않은 것은?","options":["Win+R: [실행] 대화 상자 열기","Alt+Enter: 선택 항목의 속성 표시","Win+M: 열린 창을 모두 닫기","F2: 선택한 항목 이름 바꾸기"],"answer":2,"explain":"Win+M은 열린 창을 모두 최소화할 뿐 닫지 않는다(Win+Shift+M으로 복원). 나머지 연결은 모두 옳다."},{"id":"pc-0047","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"2진수를 4자리씩 묶어 한 자리로 나타낼 수 있는 진법은?","options":["10진법","8진법","32진법","16진법"],"answer":3,"explain":"2⁴ = 16이므로 4비트가 16진수 한 자리이다. 8진수 한 자리는 3비트이다."},{"id":"pc-0048","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"캐시 메모리에 관한 설명으로 옳지 않은 것은?","options":["CPU와 주기억장치의 속도 차이를 줄인다","주로 DRAM으로 만들어 주기적인 재충전이 필요하다","L1·L2·L3처럼 여러 단계로 구성할 수 있다","적중률이 높을수록 시스템 성능이 좋아진다"],"answer":1,"explain":"캐시 메모리는 재충전이 필요 없는 빠른 SRAM으로 만든다. DRAM은 주기억장치에 주로 쓴다."},{"id":"pc-0049","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"IPv6에 관한 설명으로 옳지 않은 것은?","options":["유니캐스트·멀티캐스트·애니캐스트 주소가 있다","브로드캐스트 주소로 네트워크의 모든 호스트에 전송한다","128비트 주소 체계이다","연속된 0은 ::로 한 번만 줄여 쓸 수 있다"],"answer":1,"explain":"IPv6에는 브로드캐스트가 없고 멀티캐스트로 대신한다. 주소 자동 설정과 보안(IPSec) 기능도 갖추고 있다."},{"id":"pc-0050","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"CPU가 기억장치의 어느 위치를 읽거나 쓸지 전달하는 데 쓰는 버스는?","options":["주소 버스","제어 버스","데이터 버스","확장 버스"],"answer":0,"explain":"주소 버스는 위치(주소)를, 데이터 버스는 데이터를, 제어 버스는 읽기·쓰기 같은 제어 신호를 전달한다."},{"id":"pc-0051","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"전원이 꺼져도 내용이 유지되고 블록 단위로 전기적으로 지우고 쓸 수 있어 SSD·USB 메모리에 쓰이는 기억장치는?","options":["플래시 메모리","DRAM","Mask ROM","SRAM"],"answer":0,"explain":"플래시 메모리는 EEPROM 계열의 비휘발성 메모리이다. SRAM·DRAM은 전원이 꺼지면 내용이 사라진다."},{"id":"pc-0052","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"1초 동안 처리할 수 있는 부동 소수점 연산의 횟수로 컴퓨터 성능을 나타내는 단위는?","options":["MIPS","Hz","FLOPS","bps"],"answer":2,"explain":"FLOPS는 초당 부동 소수점 연산 수이다. MIPS는 초당 명령어 수(백만 단위), Hz는 클럭 주파수, bps는 초당 전송 비트 수이다."},{"id":"pc-0053","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"IP 주소나 MAC 주소 등을 위조하여 신뢰받는 시스템인 것처럼 속여 접근하는 공격은?","options":["스푸핑(Spoofing)","스니핑(Sniffing)","트로이 목마(Trojan Horse)","키로거(Key Logger)"],"answer":0,"explain":"스푸핑은 IP·ARP·DNS 등 여러 형태로 위장한다."},{"id":"pc-0054","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"프로토콜이 서로 다른 네트워크를 연결하여 데이터 형식을 변환해 주는 장치는?","options":["리피터","브리지","게이트웨이","허브"],"answer":2,"explain":"게이트웨이는 서로 다른 프로토콜을 변환한다. 브리지는 같은 프로토콜의 LAN 구간을 연결한다."},{"id":"pc-0055","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"문서 작성 중 이모지·기호·GIF 등을 골라 입력할 수 있는 패널을 여는 바로 가기 키는?","options":["Win+Spacebar","Win+.(마침표)","Win+,(쉼표)","Win+Home"],"answer":1,"explain":"Win+.(또는 Win+;)은 이모지 패널을 연다. Win+,는 바탕 화면 잠깐 보기, Win+Space는 입력 언어 전환, Win+Home은 활성 창을 뺀 나머지 창 최소화이다."},{"id":"pc-0056","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"악성 코드에 감염된 여러 대의 컴퓨터를 이용해 특정 서버에 한꺼번에 많은 요청을 보내 서비스를 마비시키는 공격은?","options":["키로거(Key Logger)","DDoS(분산 서비스 거부)","피싱(Phishing)","스니핑(Sniffing)"],"answer":1,"explain":"DDoS는 좀비 PC(봇넷)를 동원한 분산 서비스 거부 공격으로 가용성을 해친다."},{"id":"pc-0057","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"문자 메시지 속 링크를 눌러 악성 앱을 설치하게 한 뒤 소액 결제나 정보 탈취를 하는 수법은?","options":["파밍(Pharming)","웜(Worm)","스미싱(Smishing)","스니핑(Sniffing)"],"answer":2,"explain":"스미싱은 SMS와 피싱을 합친 말이다."},{"id":"pc-0058","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"삭제한 뒤 휴지통에서 복원할 수 있는 경우는?","options":["로컬 하드 디스크의 파일을 Shift+Delete로 삭제한 경우","로컬 하드 디스크(C:)의 파일을 Delete 키로 삭제한 경우","USB 메모리의 파일을 Delete 키로 삭제한 경우","네트워크 드라이브의 파일을 Delete 키로 삭제한 경우"],"answer":1,"explain":"로컬 디스크에서 Delete로 지운 파일만 휴지통에 들어간다. 이동식 드라이브·네트워크 드라이브의 파일과 Shift+Delete로 지운 파일은 바로 삭제된다."},{"id":"pc-0059","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"현실과 가상이 결합된 3차원 가상 세계에서 사람들이 아바타로 사회·경제·문화 활동을 하는 것은?","options":["텔레매틱스","디지털 트윈","엣지 컴퓨팅","메타버스"],"answer":3,"explain":"메타버스는 가상 세계 속 활동 공간이다. 디지털 트윈은 실제 사물을 가상에 똑같이 만들어 시뮬레이션하는 기술이다."},{"id":"pc-0060","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"보조기억장치의 일부를 주기억장치처럼 사용하여 주기억장치보다 큰 프로그램을 실행할 수 있게 하는 기법은?","options":["연관 메모리","가상 메모리","캐시 메모리","버퍼 메모리"],"answer":1,"explain":"가상 메모리는 용량 확장이 목적이고, 캐시 메모리는 속도 향상이 목적이다."},{"id":"pc-0061","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"서로 다른 운영체제나 응용 프로그램 사이에서 데이터를 주고받을 수 있도록 중간에서 연결해 주는 소프트웨어는?","options":["펌웨어","셰어웨어","그룹웨어","미들웨어"],"answer":3,"explain":"미들웨어는 이기종 시스템 간 통신·데이터 교환을 중개한다."},{"id":"pc-0062","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"목적지까지 거쳐 가는 라우터 경로와 구간별 응답 시간을 표시하는 명령은?","options":["tracert","ping","nslookup","netstat"],"answer":0,"explain":"tracert는 경로를 추적한다. netstat는 현재 네트워크 연결과 포트 상태를 보여 준다."},{"id":"pc-0063","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"UDP에 관한 설명으로 옳은 것은?","options":["패킷 순서를 맞추고 손실되면 재전송한다","3방향 핸드셰이크로 연결을 설정한 뒤 전송한다","연결 설정 없이 보내 빠르지만 전달을 보장하지 않는다","IP 주소를 MAC 주소로 바꾸어 준다"],"answer":2,"explain":"UDP는 비연결형으로 실시간 방송·음성 통화 등에 쓴다. 연결 설정·순서 보장·재전송은 TCP, IP→MAC 변환은 ARP이다."},{"id":"pc-0064","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"드라이브 최적화(디스크 조각 모음)에 관한 설명으로 옳지 않은 것은?","options":["조각 모음을 하면 드라이브의 저장 용량이 늘어난다","일정을 정해 주기적으로 자동 실행할 수 있다","흩어진 파일 조각을 모아 읽기 속도를 높인다","SSD는 조각 모음 대신 TRIM으로 최적화한다"],"answer":0,"explain":"조각 모음은 접근 속도를 높일 뿐 용량을 늘리지 않는다. 공간 확보는 디스크 정리로 한다."},{"id":"pc-0065","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"데이터를 중앙 클라우드로 보내지 않고 데이터가 생기는 곳 가까이에서 처리하여 지연 시간을 줄이는 기술은?","options":["엣지 컴퓨팅","블록체인","메타버스","그리드 컴퓨팅"],"answer":0,"explain":"엣지 컴퓨팅은 자율 주행·IoT처럼 빠른 응답이 필요할 때 쓴다. 그리드 컴퓨팅은 여러 컴퓨터를 묶어 하나처럼 쓰는 기술이다."},{"id":"pc-0066","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"이미지 가장자리의 계단 현상을 줄이기 위해 경계 픽셀에 중간 색을 넣어 부드럽게 보이게 하는 기법은?","options":["인터레이싱(Interlacing)","안티앨리어싱(Anti-aliasing)","디더링(Dithering)","필터링(Filtering)"],"answer":1,"explain":"디더링은 표현할 수 없는 색을 다른 색 점의 조합으로 비슷하게 만드는 기법이고, 인터레이싱은 이미지를 점차 선명하게 표시하는 기법이다."},{"id":"pc-0067","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기에서 선택한 파일을 휴지통에 보내지 않고 곧바로 영구 삭제하는 키는?","options":["Ctrl+Shift+N","Alt+F4","Ctrl+D","Shift+Delete"],"answer":3,"explain":"Shift+Delete는 휴지통을 거치지 않고 삭제한다. Ctrl+D는 Delete처럼 휴지통으로 보내고, Ctrl+Shift+N은 새 폴더 만들기, Alt+F4는 창 닫기이다."},{"id":"pc-0068","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"사람이 기억하기 쉬운 도메인 이름을 컴퓨터가 쓰는 IP 주소로 바꾸어 주는 시스템은?","options":["ARP","DNS","FTP","DHCP"],"answer":1,"explain":"DNS는 도메인 이름↔IP 주소를 변환한다. DHCP는 IP 자동 할당, ARP는 IP→MAC 주소 변환이다."},{"id":"pc-0069","subject":"computer","levels":["c1"],"topic":"시스템 설정","q":"돋보기를 실행하거나 화면을 확대하는 바로 가기 키는?","options":["Win+U","Win+Ctrl+Enter","Win+Ctrl+C","Win+더하기(+)"],"answer":3,"explain":"Win++는 돋보기를 켜고 확대하며 Win+Esc로 끈다. Win+Ctrl+Enter는 내레이터, Win+Ctrl+C는 색 필터, Win+U는 접근성 설정이다."},{"id":"pc-0070","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"약 10cm 이내 가까운 거리에서 기기끼리 접촉 없이 데이터를 주고받으며, 교통카드·모바일 결제에 쓰이는 기술은?","options":["블루투스","지그비","와이파이","NFC"],"answer":3,"explain":"NFC는 13.56MHz 대역의 초근거리 무선 통신이다. 블루투스는 수~수십 m 거리의 기기 연결에 쓴다."},{"id":"pc-0071","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"IP 주소에서 네트워크 주소 부분과 호스트 주소 부분을 구분하기 위해 쓰는 32비트 값은?","options":["DNS 서버 주소","서브넷 마스크","MAC 주소","기본 게이트웨이"],"answer":1,"explain":"서브넷 마스크로 네트워크를 나눈다. 기본 게이트웨이는 다른 네트워크로 나가는 출입구(라우터) 주소이다."},{"id":"pc-0072","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"ASCII 코드에 관한 설명으로 옳은 것은?","options":["7비트로 128가지 문자를 표현한다","숫자 한 자리를 4비트로 표현하는 코드이다","8비트로 256가지를 표현하는 대형 컴퓨터용 코드이다","16비트로 전 세계 문자를 모두 표현한다"],"answer":0,"explain":"ASCII는 7비트(128자)로 데이터 통신·PC에서 쓴다. 8비트 대형 컴퓨터용은 EBCDIC, 숫자 4비트는 BCD, 전 세계 문자는 유니코드이다."},{"id":"pc-0073","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"ROM 등에 저장되어 하드웨어를 제어하며, 업데이트로 기능을 개선할 수 있는 프로그램은?","options":["프리웨어","펌웨어","스파이웨어","미들웨어"],"answer":1,"explain":"펌웨어는 하드웨어와 소프트웨어의 중간 성격이며, 플래시 메모리에 저장되어 업그레이드할 수 있다."},{"id":"pc-0074","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":".pdf 파일을 열 때 사용할 앱을 바꾸려 할 때 이용하는 곳은?","options":["[설정]-[시스템]-[저장소]","[설정]-[앱]-[기본 앱]","[설정]-[접근성]-[텍스트 크기]","[설정]-[개인 설정]-[테마]"],"answer":1,"explain":"파일 형식·링크 유형별로 열 앱은 [기본 앱]에서 지정한다. 파일의 [속성]-[연결 프로그램 변경]으로도 바꿀 수 있다."},{"id":"pc-0075","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"텍스트뿐 아니라 이미지·음성·동영상 같은 파일을 전자 우편으로 보낼 수 있게 하는 규약은?","options":["POP3","SNMP","SMTP","MIME"],"answer":3,"explain":"MIME은 여러 형식의 데이터를 메일로 보낼 수 있도록 인코딩 방식을 정한다."},{"id":"pc-0076","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"컴퓨터를 켜면 POST로 하드웨어를 점검하고 운영체제를 불러오는 기본 입출력 시스템으로, 메인보드의 ROM(플래시 메모리)에 저장된 것은?","options":["레지스트리","가상 메모리","장치 드라이버","BIOS"],"answer":3,"explain":"BIOS는 펌웨어로 부팅 초기 하드웨어 점검(POST)과 부팅 장치 선택을 맡는다. 최근에는 UEFI가 이를 대신한다."},{"id":"pc-0077","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows의 [설정] 앱을 바로 여는 바로 가기 키는?","options":["Win+I","Win+P","Win+H","Win+U"],"answer":0,"explain":"Win+I는 설정을 연다. Win+P는 디스플레이 모드 선택, Win+H는 음성 입력, Win+U는 접근성 설정이다."},{"id":"pc-0078","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"정식 프로그램을 출시하기 전에 일반 사용자에게 공개하여 기능을 시험하고 오류를 찾는 버전은?","options":["베타 버전","패치 버전","알파 버전","데모 버전"],"answer":0,"explain":"베타 버전은 외부 사용자 대상 시험판이다. 알파 버전은 개발사 내부에서 시험하고, 데모 버전은 홍보용으로 기능을 제한한다."},{"id":"pc-0079","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"중앙 컴퓨터에 모든 단말기가 1:1로 연결되어, 중앙에 장애가 생기면 전체 통신이 멈추는 네트워크 형태는?","options":["성형(Star)","버스형(Bus)","망형(Mesh)","링형(Ring)"],"answer":0,"explain":"성형은 중앙 집중식이라 관리가 쉽지만 중앙 장애에 약하다. 버스형은 한 회선에 여러 단말을 연결한다."},{"id":"pc-0080","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"사용자가 태그를 직접 정의할 수 있어 구조화된 데이터를 주고받는 데 적합한 마크업 언어는?","options":["CSS","HTML","VRML","XML"],"answer":3,"explain":"XML은 사용자 정의 태그로 데이터 구조를 표현한다. HTML은 정해진 태그만 쓰고, VRML은 3차원 가상 공간 표현 언어이다."},{"id":"pc-0081","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"오픈 소스 소프트웨어에 관한 설명으로 옳지 않은 것은?","options":["Linux 운영체제가 대표적인 예이다","소스가 공개되면 저작권이 사라져 아무 조건 없이 쓸 수 있다","소스 코드를 공개해 누구나 수정·재배포할 수 있다","라이선스에 따라 수정본도 같은 조건으로 공개해야 할 수 있다"],"answer":1,"explain":"오픈 소스도 저작권이 있으며 GPL 등 라이선스 조건(출처 표시·소스 공개 등)을 지켜야 한다."},{"id":"pc-0082","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"연산장치에서 연산 결과를 일시적으로 기억하는 레지스터는?","options":["가산기","부호기","보수기","누산기"],"answer":3,"explain":"누산기는 연산 결과를 임시 저장한다. 가산기는 덧셈 회로, 보수기는 보수를 만드는 회로, 부호기는 제어장치의 구성 요소이다."},{"id":"pc-0083","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"레지스터에 관한 설명으로 옳지 않은 것은?","options":["CPU 내부에 있는 임시 기억 장소이다","플립플롭이나 래치로 구성된다","전원이 꺼져도 내용이 유지된다","CPU가 한 번에 처리하는 비트 수와 관련된다"],"answer":2,"explain":"레지스터는 CPU 안의 가장 빠른 휘발성 기억 장소로 전원이 꺼지면 내용이 사라진다. 플립플롭·래치로 만들며 크기는 CPU의 처리 단위(워드)와 관련된다."},{"id":"pc-0084","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[Windows 보안]에서 할 수 있는 작업이 아닌 것은?","options":["디스크 파티션의 크기 조정","방화벽 및 네트워크 보호 설정","앱 및 브라우저 컨트롤 설정","바이러스 및 위협 방지 검사"],"answer":0,"explain":"파티션 크기 조정은 [디스크 관리]에서 한다. Windows 보안은 바이러스 검사·방화벽·앱 및 브라우저 컨트롤 등을 관리한다."},{"id":"pc-0085","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"PCIe 버스를 통해 SSD를 연결하여 SATA보다 훨씬 빠른 전송 속도를 내도록 만든 저장 장치 인터페이스 규격은?","options":["eSATA","NVMe","IDE(PATA)","SATA"],"answer":1,"explain":"NVMe는 PCIe 기반의 SSD 전용 규격으로 SATA의 속도 한계를 넘는다. eSATA는 SATA의 외장용 규격이다."},{"id":"pc-0086","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"OSI 7계층 중 논리 주소(IP)를 이용해 경로를 선택(라우팅)하는 계층은?","options":["네트워크 계층","데이터 링크 계층","세션 계층","전송 계층"],"answer":0,"explain":"네트워크 계층은 라우팅과 IP 주소를 담당하며 라우터가 동작한다. 데이터 링크 계층은 MAC 주소로 인접 노드 간 전송을 맡는다."},{"id":"pc-0087","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"이미 배포된 프로그램의 오류를 고치거나 성능을 개선하기 위해 일부 파일을 수정·추가하는 것은?","options":["번들(Bundle)","벤치마크(Benchmark)","셰어웨어(Shareware)","패치(Patch)"],"answer":3,"explain":"패치는 프로그램 일부를 고치는 것이다. 벤치마크는 성능을 비교·평가하는 시험이다."},{"id":"pc-0088","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"임시 파일, 휴지통 파일, 임시 인터넷 파일 등 필요 없는 파일을 찾아 지워 저장 공간을 확보하는 도구는?","options":["디스크 정리","시스템 복원","디스크 검사(chkdsk)","드라이브 최적화"],"answer":0,"explain":"디스크 정리는 불필요한 파일을 삭제해 공간을 늘린다. 드라이브 최적화(조각 모음)는 속도 개선, chkdsk는 오류 검사 도구이다."},{"id":"pc-0089","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"주기억장치에서 읽거나 쓸 기억 장소의 주소를 기억하는 레지스터는?","options":["MBR(메모리 버퍼 레지스터)","MAR(메모리 주소 레지스터)","상태 레지스터","IR(명령 레지스터)"],"answer":1,"explain":"MAR은 접근할 주소를, MBR은 읽거나 쓸 데이터 자체를 임시로 기억한다."},{"id":"pc-0090","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"저작권법상 저작재산권에 해당하지 않는 것은?","options":["복제권","공중송신권","성명표시권","배포권"],"answer":2,"explain":"성명표시권은 공표권·동일성유지권과 함께 저작인격권이다. 저작재산권은 복제·공연·공중송신·전시·배포·대여·2차적저작물작성권이다."},{"id":"pc-0091","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"10진수 25를 2진수로 바르게 바꾼 것은?","options":["10011","10101","11001","11010"],"answer":2,"explain":"25 = 16+8+1 이므로 11001이다."},{"id":"pc-0092","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"RAID 1에 관한 설명으로 옳은 것은?","options":["데이터를 나누어 기록하고 중복 저장하지 않는다","같은 데이터를 두 디스크에 똑같이 기록한다","디스크 한 개를 여러 논리 드라이브로 나눈다","패리티 정보를 여러 디스크에 분산 저장한다"],"answer":1,"explain":"RAID 1은 미러링 방식이다. 나누어 기록만 하는 것은 RAID 0(스트라이핑), 패리티 분산 저장은 RAID 5이다."},{"id":"pc-0093","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"시험 답안지처럼 특수한 펜으로 표시한 위치를 빛으로 읽어 들이는 입력 장치는?","options":["MICR(자기 잉크 문자 판독기)","BCR(바코드 판독기)","OCR(광학 문자 판독기)","OMR(광학 마크 판독기)"],"answer":3,"explain":"OMR은 마크 위치를 읽는다. OCR은 인쇄된 문자를, MICR은 수표의 자성 잉크 문자를, BCR은 바코드를 읽는다."},{"id":"pc-0094","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"다음 그래픽 파일 형식 중 벡터 방식인 것은?","options":["PNG","BMP","SVG","JPG"],"answer":2,"explain":"SVG·WMF·AI는 벡터 형식이고 BMP·JPG·PNG·GIF는 비트맵 형식이다."},{"id":"pc-0095","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"화면에서 원하는 영역을 사각형·자유형 등으로 선택해 캡처하고 클립보드에 복사하는 바로 가기 키는?","options":["Win+Shift+M","Win+Shift+S","Win+Ctrl+D","Win+Home"],"answer":1,"explain":"Win+Shift+S는 캡처 도구의 영역 캡처를 실행한다. Win+Shift+M은 최소화한 창 복원, Win+Ctrl+D는 새 가상 데스크톱, Win+Home은 활성 창 외 최소화이다(Windows 11은 [설정]-[시스템]-[멀티태스킹]의 '제목 표시줄 창 흔들기'가 켜져 있어야 함)."},{"id":"pc-0096","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"열려 있는 모든 창을 숨기고 바탕 화면을 표시하며, 한 번 더 누르면 창들을 원래대로 되돌리는 바로 가기 키는?","options":["Win+L","Win+D","Win+P","Win+Tab"],"answer":1,"explain":"Win+D는 바탕 화면 표시/숨기기를 전환한다. Win+L은 잠금, Win+Tab은 작업 보기, Win+P는 디스플레이(프로젝트) 모드 선택이다."},{"id":"pc-0097","subject":"computer","levels":["c1"],"topic":"운영체제","q":"파일 탐색기에서 사용하는 키에 관한 설명으로 옳지 않은 것은?","options":["탐색 창에서 숫자 키패드의 *를 누르면 하위 폴더가 모두 닫힌다","Alt+↑를 누르면 상위 폴더로 이동한다","F4를 누르면 주소 표시줄의 목록이 표시된다","탐색 창에서 숫자 키패드의 +를 누르면 하위 폴더가 펼쳐진다"],"answer":0,"explain":"숫자 키패드의 *는 선택한 폴더의 하위 폴더를 모두 펼친다. 하위 폴더를 닫는 키는 숫자 키패드의 -이다."},{"id":"pc-0098","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"최소한의 드라이버와 서비스만으로 Windows를 시작하여 문제의 원인을 진단할 때 사용하는 시작 방식은?","options":["절전 모드","빠른 시작","안전 모드","최대 절전 모드"],"answer":2,"explain":"안전 모드는 기본 드라이버만 불러와 문제 진단에 쓴다. 절전·최대 절전은 전원 절약 상태이다."},{"id":"pc-0099","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"금융 기관 등을 사칭한 메일이나 가짜 사이트로 유인해 개인 정보를 빼내는 수법은?","options":["DDoS","피싱(Phishing)","파밍(Pharming)","스니핑(Sniffing)"],"answer":1,"explain":"피싱은 사용자가 가짜 링크를 누르도록 속인다. 파밍은 주소를 정확히 입력해도 가짜 사이트로 보낸다."},{"id":"pc-0100","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[인터넷 프로토콜 버전 4(TCP/IPv4) 속성]에서 IP를 수동으로 지정할 때 입력하는 항목이 아닌 것은?","options":["IP 주소","기본 게이트웨이","MAC 주소","서브넷 마스크"],"answer":2,"explain":"수동 설정 항목은 IP 주소·서브넷 마스크·기본 게이트웨이·DNS 서버 주소이다. MAC 주소는 네트워크 카드에 정해진 물리 주소이다."},{"id":"pc-0101","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"메일을 서버에 그대로 둔 채 여러 기기에서 폴더·읽음 상태를 동기화하며 볼 수 있는 메일 수신 프로토콜은?","options":["MIME","IMAP","POP3","SMTP"],"answer":1,"explain":"IMAP은 서버에서 메일을 관리한다. POP3는 메일을 내려받아 보는 방식이고, SMTP는 메일 전송용이다."},{"id":"pc-0102","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"패리티 비트에 관한 설명으로 옳은 것은?","options":["2비트 이상의 오류를 모두 검출하고 정정한다","1비트 오류를 검출하지만 정정은 하지 못한다","데이터를 압축하려고 덧붙이는 비트이다","오류가 난 위치를 찾아 스스로 고칠 수 있다"],"answer":1,"explain":"패리티 비트는 1의 개수를 짝수/홀수로 맞춰 홀수 개 비트 오류를 검출할 뿐 정정하지 못한다. 정정까지 하는 것은 해밍 코드이다."},{"id":"pc-0103","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"스마트폰의 모바일 데이터 연결을 이용해 노트북 같은 다른 기기를 인터넷에 연결해 주는 기능은?","options":["로밍","페어링","미러링","테더링"],"answer":3,"explain":"테더링은 스마트폰을 모뎀처럼 쓴다. 로밍은 다른 통신사·해외망 이용, 미러링은 화면 복제, 페어링은 블루투스 기기 등록이다."},{"id":"pc-0104","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"MPEG 표준에 관한 설명으로 옳지 않은 것은?","options":["MPEG-4는 저대역 통신·모바일 환경에도 쓰인다","MPEG-2는 디지털 TV와 DVD에 쓰인다","MPEG-1은 비디오 CD 수준의 화질을 목표로 한다","MPEG-7은 DVD·디지털 방송용 동영상 압축 표준이다"],"answer":3,"explain":"MPEG-7은 압축이 아니라 멀티미디어 검색을 위한 내용 기술(메타데이터) 표준이다. DVD·디지털 방송은 MPEG-2이다."},{"id":"pc-0105","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"다음 처리 속도 단위 중 가장 짧은 시간을 나타내는 것은?","options":["ns","ps","μs","ms"],"answer":1,"explain":"ms(10⁻³초) > μs(10⁻⁶초) > ns(10⁻⁹초) > ps(10⁻¹²초) 순으로 짧아진다."},{"id":"pc-0106","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"방화벽(Firewall)에 관한 설명으로 옳지 않은 것은?","options":["접속 기록을 남겨 침입 추적에 활용할 수 있다","정해진 규칙에 따라 패킷을 허용하거나 거부한다","내부 사용자에 의한 정보 유출도 모두 막을 수 있다","외부에서 들어오는 허가되지 않은 접근을 차단한다"],"answer":2,"explain":"방화벽은 외부 침입을 막는 장치로, 내부에서 일어나는 공격이나 유출은 막지 못한다."},{"id":"pc-0107","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"SRAM에 관한 설명으로 옳은 것은?","options":["재충전이 필요 없고 DRAM보다 빠르다","전원이 꺼져도 내용이 그대로 유지된다","콘덴서에 전하를 저장해 재충전이 필요하다","DRAM보다 값이 싸 주기억장치로 주로 쓴다"],"answer":0,"explain":"SRAM은 플립플롭으로 만들어 재충전이 없고 빠르며 비싸서 캐시에 쓴다. 콘덴서를 쓰고 재충전이 필요한 것은 DRAM이고, 둘 다 휘발성이다."},{"id":"pc-0108","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"바탕 화면을 선택한 상태에서 누르면 [Windows 종료] 대화 상자가 나타나는 바로 가기 키는?","options":["Alt+F4","Ctrl+F4","Ctrl+Esc","Shift+F10"],"answer":0,"explain":"바탕 화면에서 Alt+F4를 누르면 Windows 종료 창이 뜨고, 앱 창에서는 그 창을 닫는다. Ctrl+F4는 문서 창 닫기, Shift+F10은 바로 가기 메뉴, Ctrl+Esc는 시작 메뉴이다."},{"id":"pc-0109","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"모니터 관련 용어의 설명으로 옳지 않은 것은?","options":["해상도는 화면을 구성하는 픽셀 수로 나타낸다","재생률(Hz)이 낮을수록 화면 깜빡임이 줄어든다","화면 크기는 대각선 길이를 인치로 나타낸다","점 간격(도트 피치)이 좁을수록 화면이 선명하다"],"answer":1,"explain":"재생률은 1초에 화면을 다시 그리는 횟수로, 높을수록 깜빡임이 적고 움직임이 부드럽다."},{"id":"pc-0110","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"하드웨어 장치의 드라이버를 업데이트하거나 장치를 사용 안 함·제거로 설정할 수 있는 곳은?","options":["이벤트 뷰어","디스크 정리","장치 관리자","작업 스케줄러"],"answer":2,"explain":"장치 관리자에서 장치별 드라이버 업데이트·롤백·제거와 사용 안 함 설정을 한다."},{"id":"pc-0111","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"자외선을 쬐어 내용을 지운 뒤 다시 기록할 수 있는 ROM은?","options":["EEPROM","Mask ROM","PROM","EPROM"],"answer":3,"explain":"EPROM은 자외선으로, EEPROM은 전기적으로 지운다. Mask ROM은 제조할 때 기록, PROM은 한 번만 기록할 수 있다."},{"id":"pc-0112","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기에서 현재 위치에 새 폴더를 만드는 바로 가기 키는?","options":["Ctrl+N","Ctrl+W","Ctrl+Shift+E","Ctrl+Shift+N"],"answer":3,"explain":"Ctrl+Shift+N은 새 폴더를 만든다. Ctrl+N은 새 탐색기 창, Ctrl+W는 현재 창 닫기, Ctrl+Shift+E는 탐색 창에서 선택한 폴더까지 상위 폴더를 모두 펼친다."},{"id":"pc-0113","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"주소 대신 저장된 내용의 일부를 이용해 원하는 데이터를 찾아 접근하는 기억장치는?","options":["연관 메모리","가상 메모리","플래시 메모리","버퍼 메모리"],"answer":0,"explain":"연관 메모리(CAM)는 내용으로 검색하므로 매핑 테이블 등에 쓰인다."},{"id":"pc-0114","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"악기 연주 정보(음 높이·길이·세기 등)를 저장해 용량이 작지만 사람의 목소리는 저장할 수 없는 오디오 형식은?","options":["FLAC","MIDI","WAV","MP3"],"answer":1,"explain":"MIDI는 소리 자체가 아닌 연주 명령을 저장한다. WAV는 비압축 파형, MP3는 손실 압축, FLAC는 무손실 압축 형식이다."},{"id":"pc-0115","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"짝수(Even) 패리티를 쓰는 시스템에서, 패리티 비트를 포함해 받은 8비트 데이터 중 오류가 있다고 판단되는 것은?","options":["10110100","11010110","11110000","00000000"],"answer":1,"explain":"짝수 패리티는 1의 개수가 짝수여야 한다. 11010110은 1이 5개(홀수)이므로 오류이고, 나머지는 4개·4개·0개이다."},{"id":"pc-0116","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"USB 인터페이스에 관한 설명으로 옳지 않은 것은?","options":["허브를 이용하면 최대 127개 장치를 연결할 수 있다","핫 플러그(Hot Plug)를 지원한다","컴퓨터 전원을 끈 상태에서만 장치를 연결할 수 있다","Type-C 커넥터는 위아래 구분 없이 꽂을 수 있다"],"answer":2,"explain":"USB는 컴퓨터가 켜진 상태에서도 장치를 꽂고 뺄 수 있는 핫 플러그와 플러그 앤 플레이를 지원한다."},{"id":"pc-0117","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"드라이브 전체를 암호화하여 노트북을 분실하더라도 다른 사람이 데이터를 읽지 못하게 하는 Windows 기능은?","options":["EFS(파일 암호화)","사용자 계정 컨트롤","Windows Hello","BitLocker"],"answer":3,"explain":"BitLocker는 드라이브(볼륨) 단위 암호화이다. EFS는 파일·폴더 단위 암호화, Windows Hello는 얼굴·지문·PIN 로그인이다."},{"id":"pc-0118","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"샘플링 주파수 44.1kHz, 샘플 크기 16비트, 스테레오로 10초 동안 녹음한 비압축 오디오의 크기는?","options":["441,000바이트","882,000바이트","1,764,000바이트","3,528,000바이트"],"answer":2,"explain":"44,100 × (16÷8)바이트 × 2채널 × 10초 = 1,764,000바이트이다."},{"id":"pc-0119","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"스스로를 복제하여 네트워크를 통해 퍼지며 시스템 부하를 일으키는 악성 프로그램은?","options":["웜(Worm)","트로이 목마(Trojan Horse)","스파이웨어(Spyware)","애드웨어(Adware)"],"answer":0,"explain":"웜은 다른 파일에 기생하지 않고 스스로 복제·전파한다. 트로이 목마는 자기 복제를 하지 않는다."},{"id":"pc-0120","subject":"computer","levels":["c1"],"topic":"운영체제","q":"Windows의 라이브러리에 관한 설명으로 옳지 않은 것은?","options":["폴더를 라이브러리에 포함하면 원본 폴더가 라이브러리로 옮겨진다","사용자가 새 라이브러리를 직접 만들 수 있다","실제 파일을 저장하지 않고 여러 위치를 모아 보여 준다","서로 다른 드라이브에 있는 폴더도 함께 포함할 수 있다"],"answer":0,"explain":"라이브러리는 여러 위치의 폴더를 연결해 한곳에서 보여 주는 가상 폴더로, 포함해도 원본 폴더는 제자리에 있다."},{"id":"pc-0121","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"존 비트 4개와 디지트 비트 4개로 구성되어 256가지 문자를 표현하는 코드는?","options":["EBCDIC","BCD","ASCII","해밍 코드"],"answer":0,"explain":"EBCDIC은 8비트 확장 2진화 10진 코드로 대형 컴퓨터에서 쓴다. BCD는 존 2비트+디지트 4비트(6비트)이다."},{"id":"pc-0122","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"벡터(Vector) 방식 그래픽에 관한 설명으로 옳은 것은?","options":["대표적인 파일 형식은 BMP, JPG, GIF이다","사진처럼 색이 복잡한 이미지 표현에 알맞다","픽셀(점)의 모임으로 이미지를 표현한다","확대해도 계단 현상 없이 선명하다"],"answer":3,"explain":"벡터는 점·선·면을 수식으로 표현해 확대해도 깨지지 않는다. 나머지는 비트맵(래스터) 방식의 특징이다."},{"id":"pc-0123","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"HTTPS가 기본으로 사용하는 포트 번호는?","options":["80","21","25","443"],"answer":3,"explain":"HTTPS는 443, HTTP는 80, FTP(제어)는 21, SMTP는 25번 포트를 기본으로 쓴다."},{"id":"pc-0124","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"여러 사람이 일정·문서·전자 결재 등을 공유하며 함께 일할 수 있도록 돕는 소프트웨어는?","options":["애드웨어","펌웨어","그룹웨어","미들웨어"],"answer":2,"explain":"그룹웨어는 협업 지원 소프트웨어이다. 애드웨어는 광고를 보여 주는 소프트웨어이다."},{"id":"pc-0125","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"전송 중인 데이터의 내용을 몰래 바꾸는 수정(Modification) 공격이 직접 위협하는 보안 요소는?","options":["기밀성","가용성","부인 방지","무결성"],"answer":3,"explain":"수정은 무결성, 가로채기는 기밀성, 가로막기는 가용성을 위협한다."},{"id":"pc-0126","subject":"computer","levels":["c1"],"topic":"운영체제","q":"Windows 11에서 현재 창을 화면 분할 위치에 배치하는 창 맞춤 레이아웃(Snap layouts)을 표시하는 키는?","options":["Win+Q","Win+K","Win+T","Win+Z"],"answer":3,"explain":"Win+Z는 창 맞춤 레이아웃을 연다. Win+Q는 검색, Win+T는 작업 표시줄 앱 순환, Win+K는 캐스트이다."},{"id":"pc-0127","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"CPU의 제어장치를 구성하는 요소가 아닌 것은?","options":["명령 해독기(Instruction Decoder)","프로그램 카운터(PC)","누산기(Accumulator)","명령 레지스터(IR)"],"answer":2,"explain":"누산기는 연산장치에 속한다. 제어장치는 프로그램 카운터·명령 레지스터·명령 해독기·부호기·MAR·MBR 등으로 구성된다."},{"id":"pc-0128","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"웹 브라우저(클라이언트)에서 직접 실행되는 스크립트 언어는?","options":["JSP","ASP","JavaScript","PHP"],"answer":2,"explain":"JavaScript는 클라이언트 측 스크립트이다. PHP·JSP·ASP는 서버에서 실행된 뒤 결과 HTML을 보낸다."},{"id":"pc-0129","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"사물에 센서와 통신 기능을 넣어 인터넷으로 서로 정보를 주고받게 하는 기술은?","options":["블록체인","메타버스(Metaverse)","핀테크","사물 인터넷(IoT)"],"answer":3,"explain":"IoT는 사물끼리 연결해 정보를 주고받는다. 핀테크는 금융과 IT를 결합한 서비스이다."},{"id":"pc-0130","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기에서 마우스로 끌어 놓을 때의 결과로 옳은 것은?","options":["같은 드라이브의 다른 폴더로 Ctrl을 누른 채 끌면 복사된다","같은 드라이브의 다른 폴더로 그냥 끌면 복사된다","다른 드라이브로 그냥 끌면 원본이 이동된다","다른 드라이브로 Ctrl을 누른 채 끌면 원본이 이동된다"],"answer":0,"explain":"같은 드라이브는 그냥 끌면 이동, 다른 드라이브는 그냥 끌면 복사이다. Ctrl을 누르면 항상 복사, Shift를 누르면 항상 이동이다."},{"id":"pc-0131","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"실행 중인 창들의 축소판을 보여 주고, 키를 누른 채 Tab을 누를 때마다 다음 창을 선택해 전환하는 바로 가기 키는?","options":["Win+T","Alt+Tab","Alt+F4","Ctrl+Tab"],"answer":1,"explain":"Alt+Tab은 열린 창 사이를 전환한다. Alt+F4는 창 닫기, Ctrl+Tab은 앱 안의 탭 전환, Win+T는 작업 표시줄 앱 순환이다."},{"id":"pc-0132","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"서버·스토리지·네트워크 같은 컴퓨팅 인프라를 가상화하여 빌려주는 클라우드 서비스 형태는?","options":["CDN","PaaS","SaaS","IaaS"],"answer":3,"explain":"IaaS는 인프라를 제공한다. CDN은 콘텐츠를 여러 지역 서버에 분산해 빠르게 전달하는 망이다."},{"id":"pc-0133","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"모든 노드가 서로 직접 연결되어 신뢰성이 높고, 노드가 n개면 회선이 n(n-1)/2개 필요한 네트워크 형태는?","options":["성형(Star)","버스형(Bus)","계층형(Tree)","망형(Mesh)"],"answer":3,"explain":"망형은 경로가 여러 개라 장애에 강하지만 회선 비용이 많이 든다."},{"id":"pc-0134","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"OSI 7계층 중 데이터의 암호화·압축·코드 변환을 담당하는 계층은?","options":["표현 계층","세션 계층","응용 계층","데이터 링크 계층"],"answer":0,"explain":"표현 계층(6계층)은 데이터 형식 변환·암호화·압축을 맡는다. 세션 계층은 대화(연결) 설정과 동기화를 맡는다."},{"id":"pc-0135","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"빅데이터의 특징을 나타내는 3V에 해당하지 않는 것은?","options":["Velocity(속도)","Variety(다양성)","Volume(데이터 규모)","Visibility(가시성)"],"answer":3,"explain":"3V는 크기(Volume)·속도(Velocity)·다양성(Variety)이다. 여기에 정확성(Veracity)·가치(Value)를 더해 5V라고도 한다."},{"id":"pc-0136","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"전 세계의 문자를 하나의 체계로 표현하기 위해 만든 국제 표준 코드로, 한글 완성형과 조합형의 호환 문제를 해결한 것은?","options":["EBCDIC 코드","유니코드(Unicode)","ASCII(아스키) 코드","BCD 코드"],"answer":1,"explain":"유니코드는 모든 문자에 고유 번호를 붙인 국제 표준이며, UTF-8·UTF-16 등으로 저장한다."},{"id":"pc-0137","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"로그인할 때마다 새로 만들어지는 한 번만 쓸 수 있는 비밀번호는?","options":["PIN","SSO","CAPTCHA","OTP"],"answer":3,"explain":"OTP(One Time Password)는 재사용할 수 없어 안전하다. CAPTCHA는 사람과 프로그램 구별, SSO는 한 번 로그인으로 여러 서비스 이용이다."},{"id":"pc-0138","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"기억장치를 접근 속도가 빠른 것부터 바르게 나열한 것은?","options":["캐시 → 주기억장치 → 레지스터 → 보조기억장치","캐시 → 레지스터 → 주기억장치 → 보조기억장치","레지스터 → 주기억장치 → 캐시 → 보조기억장치","레지스터 → 캐시 → 주기억장치 → 보조기억장치"],"answer":3,"explain":"CPU 안의 레지스터가 가장 빠르고, CPU와 주기억장치 사이의 캐시, 주기억장치, 보조기억장치 순으로 느려진다."},{"id":"pc-0139","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"TCP/IP의 TCP와 IP 역할에 관한 설명으로 옳은 것은?","options":["TCP는 디지털 신호를 전기 신호로 바꾼다","TCP는 IP 주소를 도메인 이름으로 바꾼다","IP는 주소를 지정하고 패킷의 전송 경로를 정한다","IP는 데이터 오류를 검사하고 재전송을 요청한다"],"answer":2,"explain":"IP는 주소 지정과 경로 설정을, TCP는 데이터를 나누고 조립하며 오류 검사·재전송으로 신뢰성을 맡는다. 이름↔주소 변환은 DNS이다."},{"id":"pc-0140","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"파일을 끝까지 내려받지 않고도 데이터를 받는 대로 재생하는 기술은?","options":["트랜스코딩(Transcoding)","스트리밍(Streaming)","버퍼링(Buffering)","미러링(Mirroring)"],"answer":1,"explain":"스트리밍은 전송 중에 재생한다. 버퍼링은 끊김을 막으려고 데이터를 미리 받아 두는 과정이다."},{"id":"pc-0141","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"사용자의 파일을 암호화하여 열 수 없게 만든 뒤 복구 대가로 금전을 요구하는 악성 코드는?","options":["스파이웨어","루트킷","키로거","랜섬웨어"],"answer":3,"explain":"랜섬웨어는 몸값(Ransom)을 요구한다. 키로거는 키보드 입력을 몰래 기록한다."},{"id":"pc-0142","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"부동 소수점 표현 방식에 관한 설명으로 옳은 것은?","options":["문자 데이터를 표현하기 위한 방식이다","부호·지수부·가수부로 이루어진다","소수점 위치가 맨 오른쪽에 고정된다","정수만 표현하며 고정 소수점보다 연산이 빠르다"],"answer":1,"explain":"부동 소수점은 부호·지수부·가수부로 아주 크거나 작은 실수를 표현하며, 고정 소수점보다 연산이 느리다."},{"id":"pc-0143","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"거리가 멀어 약해진 신호를 증폭·재생하여 전송 거리를 늘려 주는 장비는?","options":["게이트웨이","라우터","스위치","리피터"],"answer":3,"explain":"리피터는 물리 계층 장비로 신호를 재생해 먼 곳까지 보낸다."},{"id":"pc-0144","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"새 장치를 연결하면 운영체제가 자동으로 인식해 알맞은 드라이버를 설치하고 설정해 주는 기능은?","options":["OLE(개체 연결 및 포함)","플러그 앤 플레이(PnP)","가상 메모리","멀티태스킹"],"answer":1,"explain":"플러그 앤 플레이는 하드웨어를 꽂기만 하면 자동으로 인식·설정한다. OLE는 다른 앱의 개체를 연결하거나 포함하는 기능이다."},{"id":"pc-0145","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"니블(Nibble)은 몇 비트로 구성되는가?","options":["2비트","4비트","8비트","16비트"],"answer":1,"explain":"니블은 4비트, 바이트는 8비트이다."},{"id":"pc-0146","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"URL https://www.example.com:8080/docs/index.html 에서 8080이 나타내는 것은?","options":["프로토콜","파일 경로","포트 번호","호스트 이름"],"answer":2,"explain":"URL은 프로토콜://호스트 주소:포트 번호/경로/파일 이름 형식이다. https는 프로토콜, www.example.com은 호스트이다."},{"id":"pc-0147","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"압축 프로그램·백신·이미지 뷰어처럼 컴퓨터 사용을 편리하게 돕는 작은 프로그램을 통틀어 이르는 말은?","options":["유틸리티","미들웨어","그룹웨어","펌웨어"],"answer":0,"explain":"유틸리티는 사용 편의를 높이는 보조 프로그램이다. 그룹웨어는 협업용 소프트웨어이다."},{"id":"pc-0148","subject":"computer","levels":["c1"],"topic":"운영체제","q":"Windows의 레지스트리(Registry)에 관한 설명으로 옳은 것은?","options":["하드 디스크에 흩어진 파일 조각을 모아 주는 관리 도구","삭제한 파일을 일정 기간 보관했다가 복원하는 공간","Windows와 앱의 설정을 계층 구조로 저장한 DB","부팅할 때 하드웨어를 검사하는 메인보드의 펌웨어"],"answer":2,"explain":"레지스트리는 하드웨어·소프트웨어·사용자 설정을 키와 값의 계층 구조로 저장한다. 잘못 고치면 부팅이 안 될 수 있다."},{"id":"pc-0149","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"HTML5에 관한 설명으로 옳은 것은?","options":["웹 문서를 서버에서 실행하는 서버 측 스크립트 언어이다","XML을 대체하기 위해 만든 데이터베이스 언어이다","별도 플러그인 없이 브라우저에서 동영상을 재생할 수 있다","액티브X가 있어야만 웹 문서를 표시할 수 있다"],"answer":2,"explain":"HTML5는 video·audio·canvas 요소로 플러그인 없이 멀티미디어를 다룬다."},{"id":"pc-0150","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"8진수 157을 16진수로 바꾼 값은?","options":["6F","5F","6E","9F"],"answer":0,"explain":"8진수 한 자리를 3비트로 바꾸면 001 101 111, 이를 4비트씩 묶으면 0110 1111 = 6F이다(10진수 111)."},{"id":"pc-0151","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"CPU를 거치지 않고 주변 장치와 주기억장치가 직접 데이터를 주고받게 하여 CPU 부담을 줄이는 방식은?","options":["폴링(Polling)","스풀링(Spooling)","DMA(직접 메모리 접근)","인터럽트(Interrupt)"],"answer":2,"explain":"DMA는 DMA 제어기가 메모리와 입출력 장치 사이의 전송을 맡는다. 폴링은 CPU가 장치 상태를 계속 확인하는 방식이다."},{"id":"pc-0152","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"다음 인터럽트 중 처리 우선순위가 가장 높은 것은?","options":["기계 착오(하드웨어 오류)","정전 등 전원 이상","0으로 나누기 같은 프로그램 오류","입출력 장치의 요청"],"answer":1,"explain":"인터럽트 우선순위는 전원 이상 > 기계 착오 > 외부 신호 > 입출력 > 프로그램 검사 > SVC 순이다."},{"id":"pc-0153","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"[작업 관리자]를 곧바로 실행하는 바로 가기 키로 옳은 것은?","options":["Ctrl+Esc","Ctrl+Shift+Tab","Ctrl+Shift+Esc","Alt+Esc"],"answer":2,"explain":"Ctrl+Shift+Esc는 작업 관리자를 바로 연다. Ctrl+Esc는 시작 메뉴, Alt+Esc는 열린 순서대로 창 전환, Ctrl+Shift+Tab은 앱 안에서 이전 탭으로 전환한다."},{"id":"pc-0154","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"하나의 CPU 칩 안에 연산 핵심 회로를 두 개 이상 넣어 여러 작업을 동시에 처리하게 한 것은?","options":["멀티코어 프로세서","파이프라이닝","듀얼 채널 메모리","오버클러킹"],"answer":0,"explain":"멀티코어는 한 칩에 코어 여러 개를 넣는다. 오버클러킹은 정격보다 높은 클럭으로 동작시키는 것이다."},{"id":"pc-0155","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"서로 다른 네트워크를 연결하고 가장 알맞은 경로를 골라 패킷을 전달하는 장비는?","options":["라우터","브리지","리피터","허브"],"answer":0,"explain":"라우터는 네트워크 계층 장비로 경로를 선택한다. 리피터는 신호 증폭, 브리지는 같은 종류의 LAN 연결이다."},{"id":"pc-0156","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"복사(Ctrl+C)나 잘라내기(Ctrl+X)한 데이터가 붙여 넣기 전까지 임시로 저장되는 메모리 영역은?","options":["클립보드","휴지통","캐시 메모리","스풀"],"answer":0,"explain":"클립보드는 복사·잘라내기한 내용을 임시로 보관한다. 스풀은 인쇄 데이터를 임시 저장하는 기능이다."},{"id":"pc-0157","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"16진수 2F를 10진수로 바꾼 값은?","options":["37","45","63","47"],"answer":3,"explain":"2×16 + 15(F) = 47이다."},{"id":"pc-0158","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"사용자가 올바른 주소를 입력해도 DNS나 호스트 파일을 변조해 가짜 사이트로 접속하게 만드는 수법은?","options":["피싱(Phishing)","키로거(Key Logger)","파밍(Pharming)","스미싱(Smishing)"],"answer":2,"explain":"파밍은 도메인을 탈취하거나 호스트 파일을 바꿔 사용자가 알아차리기 어렵다."},{"id":"pc-0159","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"하드 디스크에서 읽기/쓰기 헤드를 원하는 트랙으로 옮기는 데 걸리는 시간은?","options":["회전 지연 시간(Latency Time)","탐색 시간(Seek Time)","접근 시간(Access Time)","전송 시간(Transfer Time)"],"answer":1,"explain":"접근 시간 = 탐색 시간 + 회전 지연 시간 + 전송 시간이다. 회전 지연 시간은 원하는 섹터가 헤드 아래로 올 때까지의 시간이다."},{"id":"pc-0160","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"IPv4에서 기본 서브넷 마스크가 255.255.255.0이며 소규모 네트워크에 쓰는 클래스는?","options":["A 클래스","B 클래스","C 클래스","D 클래스"],"answer":2,"explain":"A는 255.0.0.0, B는 255.255.0.0, C는 255.255.255.0이다. D 클래스는 멀티캐스트용이다."},{"id":"pc-0161","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"송신자가 메시지를 보낸 사실이나 수신자가 받은 사실을 나중에 부인하지 못하게 하는 보안 요소는?","options":["접근 제어","기밀성","부인 방지","가용성"],"answer":2,"explain":"부인 방지는 전자 서명 등으로 송수신 사실을 증명한다."},{"id":"pc-0162","subject":"computer","levels":["c1"],"topic":"운영체제","q":"[실행](Win+R) 창에 입력했을 때 레지스트리 편집기가 열리는 명령은?","options":["regedit","msconfig","mstsc","dxdiag"],"answer":0,"explain":"regedit는 레지스트리 편집기, msconfig는 시스템 구성, dxdiag는 DirectX 진단 도구, mstsc는 원격 데스크톱 연결이다."},{"id":"pc-0163","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"영상과 음성을 압축하지 않은 디지털 신호로 케이블 하나에 함께 전송하는 인터페이스는?","options":["HDMI","PS/2","VGA","DVI"],"answer":0,"explain":"HDMI는 디지털 영상·음성을 함께 보낸다. VGA는 아날로그 영상, DVI는 주로 디지털 영상만 전송하고, PS/2는 키보드·마우스용이다."},{"id":"pc-0164","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"가상 데스크톱 관련 바로 가기 키의 설명으로 옳지 않은 것은?","options":["Win+Ctrl+→: 오른쪽 데스크톱으로 전환","Win+Ctrl+D: 새 가상 데스크톱 추가","Win+Ctrl+F4: 모든 가상 데스크톱 닫기","Win+Tab: 작업 보기 열기"],"answer":2,"explain":"Win+Ctrl+F4는 현재 사용 중인 가상 데스크톱 하나만 닫는다. 닫힌 데스크톱의 창은 옆 데스크톱으로 옮겨진다."},{"id":"pc-0165","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"JPEG 형식에 관한 설명으로 옳지 않은 것은?","options":["무손실 압축만 사용하므로 원본과 완전히 같다","24비트 트루컬러를 표현할 수 있다","손실 압축으로 사진 저장에 많이 쓰인다","압축률(품질)을 사용자가 조절할 수 있다"],"answer":0,"explain":"JPEG는 손실 압축 방식이라 압축할수록 화질이 떨어진다."},{"id":"pc-0166","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"거래 기록을 여러 참여자가 나누어 보관하고 블록을 사슬처럼 연결해 위·변조를 어렵게 하는 분산 원장 기술은?","options":["클라우드 컴퓨팅","핀테크","딥러닝","블록체인"],"answer":3,"explain":"블록체인은 중앙 서버 없이 참여자 모두가 장부를 공유한다."},{"id":"pc-0167","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"하드웨어나 다른 소프트웨어를 구입할 때 덤으로 함께 제공되는 소프트웨어는?","options":["번들","베타 버전","셰어웨어","알파 버전"],"answer":0,"explain":"번들은 제품에 끼워 주는 소프트웨어이다. 알파·베타 버전은 정식 출시 전 시험판이다."},{"id":"pc-0168","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"UEFI에 관한 설명으로 옳지 않은 것은?","options":["GPT 파티션 디스크로 부팅할 수 있다","보안 부팅(Secure Boot)을 지원한다","MBR 방식만 써서 2TB를 넘는 디스크로 부팅할 수 없다","마우스로 조작하는 그래픽 설정 화면을 제공할 수 있다"],"answer":2,"explain":"UEFI는 GPT를 지원해 2TB를 넘는 디스크로도 부팅할 수 있다. MBR만 쓰는 것은 기존 BIOS 방식의 한계이다."},{"id":"pc-0169","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"SATA 인터페이스에 관한 설명으로 옳은 것은?","options":["직렬 방식으로 데이터를 전송한다","병렬 방식이며 마스터/슬레이브 설정이 필요하다","무선으로 주변 장치를 연결하는 근거리 통신 규격이다","모니터와 그래픽 카드를 연결하는 영상 규격이다"],"answer":0,"explain":"SATA(Serial ATA)는 직렬 방식으로 케이블이 얇고 핫 플러그를 지원한다. 병렬 방식·마스터/슬레이브 설정은 PATA(IDE)의 특징이다."},{"id":"pc-0170","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"CPU 구성 요소와 역할의 연결로 옳은 것은?","options":["보수기 - 뺄셈을 위해 보수를 만든다","명령 해독기 - 두 수의 덧셈을 수행한다","프로그램 카운터 - 연산 결과의 부호를 기억한다","부호기 - 연산 결과를 누적해 저장한다"],"answer":0,"explain":"보수기는 뺄셈을 덧셈으로 처리하도록 보수를 만든다. 명령 해독기는 명령을 해독하고, 부호기는 해독한 명령을 제어 신호로 바꾼다."},{"id":"pc-0171","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"시스템 소프트웨어에 해당하지 않는 것은?","options":["장치 드라이버","워드프로세서","운영체제","컴파일러"],"answer":1,"explain":"워드프로세서는 특정 업무용 응용 소프트웨어이다. 운영체제·언어 번역기·장치 드라이버·유틸리티는 시스템 소프트웨어이다."},{"id":"pc-0172","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Shift를 다섯 번 연속 눌러 켤 수 있고, Ctrl·Alt·Shift 같은 키를 한 번에 하나씩 눌러도 함께 누른 것처럼 처리하는 접근성 기능은?","options":["고정 키","필터 키","돋보기","토글 키"],"answer":0,"explain":"고정 키는 조합 키를 차례로 눌러도 동시에 누른 것으로 처리한다. 토글 키는 Caps Lock 등을 누를 때 소리를 내고, 필터 키는 짧거나 반복된 입력을 무시한다."},{"id":"pc-0173","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"RISC 방식 프로세서에 관한 설명으로 옳은 것은?","options":["명령어 수가 많고 복잡해 프로그래밍이 쉽다","명령어 길이가 가변적이고 해독 회로가 복잡하다","명령어 수가 적고 형식이 단순해 처리가 빠르다","개인용 컴퓨터의 x86 CPU가 대표적인 예이다"],"answer":2,"explain":"RISC는 단순한 고정 길이 명령어를 쓴다. 명령어가 많고 복잡한 것은 CISC이며 x86 CPU가 대표적이다."},{"id":"pc-0174","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"유용한 프로그램처럼 위장해 설치되며, 자기 복제는 하지 않지만 정보 유출이나 원격 조종의 통로가 되는 악성 프로그램은?","options":["바이러스","웜","트로이 목마","혹스(Hoax)"],"answer":2,"explain":"트로이 목마는 정상 프로그램으로 위장한다. 혹스는 실제로는 없는 악성 코드를 있는 것처럼 알리는 거짓 경고이다."},{"id":"pc-0175","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"비대칭키(공개키) 암호화 방식에 관한 설명으로 옳지 않은 것은?","options":["암호화·복호화 속도가 대칭키 방식보다 빠르다","대표적인 알고리즘으로 RSA가 있다","공개키로 암호화한 데이터는 짝인 개인키로만 푼다","전자 서명에 이용할 수 있다"],"answer":0,"explain":"비대칭키 방식은 알고리즘이 복잡해 대칭키 방식보다 느리다. 대신 키 분배가 쉽다."},{"id":"pc-0176","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"자리를 비울 때 실행 중인 작업은 그대로 둔 채 컴퓨터를 잠가 잠금 화면으로 전환하는 바로 가기 키는?","options":["Win+K","Win+L","Win+S","Win+U"],"answer":1,"explain":"Win+L은 컴퓨터를 잠근다. Win+U는 접근성 설정, Win+S는 검색, Win+K는 캐스트(무선 디스플레이 연결)이다."},{"id":"pc-0177","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"2진수 101101을 10진수로 바꾼 값은?","options":["43","45","47","53"],"answer":1,"explain":"32+8+4+1 = 45이다."},{"id":"pc-0178","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"급여 계산처럼 일정 기간 데이터를 모아 두었다가 한꺼번에 처리하는 운영 방식은?","options":["시분할 처리(Time Sharing)","분산 처리(Distributed Processing)","실시간 처리(Real-time Processing)","일괄 처리(Batch Processing)"],"answer":3,"explain":"일괄 처리는 데이터를 모아 정해진 때에 한 번에 처리한다. 실시간 처리는 발생 즉시 처리하며 좌석 예약·은행 온라인 업무가 예이다."},{"id":"pc-0179","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"SSD(Solid State Drive)에 관한 설명으로 옳지 않은 것은?","options":["반도체 메모리를 사용해 데이터를 저장한다","HDD보다 읽기·쓰기 속도가 빠르다","헤드가 회전하는 원판을 읽으므로 충격에 약하다","소음과 발열이 적다"],"answer":2,"explain":"헤드와 회전 원판을 쓰는 것은 HDD이다. SSD는 기계 부품이 없어 충격에 강하고 빠르다."},{"id":"pc-0180","subject":"computer","levels":["c1"],"topic":"운영체제","q":"운영체제의 구성 중 제어 프로그램(Control Program)에 해당하는 것은?","options":["서비스 프로그램","감시 프로그램","언어 번역 프로그램","문제 프로그램"],"answer":1,"explain":"제어 프로그램은 감시·작업 관리·데이터 관리 프로그램이고, 처리 프로그램은 언어 번역·서비스·문제 프로그램이다."},{"id":"pc-0181","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"응답하지 않는 앱을 강제로 끝내려고 할 때 사용하는 방법으로 가장 알맞은 것은?","options":["디스크 정리에서 [시스템 파일 정리]","파일 속성에서 [읽기 전용] 지정","장치 관리자에서 [드라이버 롤백]","작업 관리자의 [프로세스] 탭에서 [작업 끝내기]"],"answer":3,"explain":"작업 관리자(Ctrl+Shift+Esc)의 [프로세스] 탭에서 앱을 선택해 [작업 끝내기]로 강제 종료한다."},{"id":"pc-0182","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"특정 호스트와 통신이 되는지 확인하고 응답 시간을 보여 주는 명령은?","options":["nslookup","tracert","ping","ipconfig"],"answer":2,"explain":"ping은 연결 여부를 확인한다. ipconfig는 내 IP 설정 확인, tracert는 경로 추적, nslookup은 DNS 조회 명령이다."},{"id":"pc-0183","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows에서 파일 탐색기 창을 바로 여는 바로 가기 키로 옳은 것은?","options":["Win+R","Win+E","Win+A","Win+X"],"answer":1,"explain":"Win+E는 파일 탐색기를 연다. Win+R은 [실행] 창, Win+X는 빠른 링크 메뉴, Win+A는 빠른 설정(Windows 10은 알림 센터)을 연다."},{"id":"pc-0184","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"다음에 실행할 명령어의 주소를 기억하는 레지스터는?","options":["누산기(AC)","명령 레지스터(IR)","프로그램 카운터(PC)","상태 레지스터(PSW)"],"answer":2,"explain":"프로그램 카운터는 다음 명령의 주소를, 명령 레지스터는 현재 실행 중인 명령을 기억한다."},{"id":"pc-0185","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"객체 지향 언어로, 컴파일한 바이트 코드를 가상 머신(JVM)에서 실행하므로 운영체제에 관계없이 동작하는 언어는?","options":["어셈블리어","COBOL","C","Java"],"answer":3,"explain":"Java는 JVM 덕분에 플랫폼에 독립적이다. COBOL은 사무 처리용 언어이다."},{"id":"pc-0186","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"MAC 주소를 확인해 목적지가 연결된 포트로만 프레임을 전달하는 데이터 링크 계층 장비는?","options":["스위치","리피터","더미 허브","라우터"],"answer":0,"explain":"스위치는 MAC 주소 표로 필요한 포트에만 전달한다. 더미 허브는 받은 신호를 모든 포트로 보낸다."},{"id":"pc-0187","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"오류를 검출할 뿐 아니라 1비트 오류를 스스로 정정할 수 있는 코드는?","options":["해밍 코드","그레이 코드","3초과 코드","패리티 비트"],"answer":0,"explain":"해밍 코드는 여러 개의 패리티 비트로 오류 위치를 찾아 정정한다."},{"id":"pc-0188","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"네트워크에 접속한 컴퓨터에 IP 주소·서브넷 마스크 등을 자동으로 할당하는 프로토콜은?","options":["SMTP","DNS","SNMP","DHCP"],"answer":3,"explain":"DHCP 서버가 IP 설정을 자동으로 나눠 준다. SNMP는 네트워크 장비 관리용 프로토콜이다."},{"id":"pc-0189","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"프로토콜과 용도의 연결로 옳지 않은 것은?","options":["SMTP - 전자 우편을 보낸다","SSH - 암호화된 원격 접속을 제공한다","Telnet - 원격 컴퓨터에 접속해 명령을 실행한다","FTP - 웹 문서를 하이퍼텍스트로 주고받는다"],"answer":3,"explain":"FTP는 파일 전송 프로토콜이다. 하이퍼텍스트 문서를 주고받는 것은 HTTP이다."},{"id":"pc-0190","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"객체 지향 프로그래밍에서 상위 클래스의 속성과 메서드를 하위 클래스가 물려받아 사용하는 특징은?","options":["다형성(Polymorphism)","추상화(Abstraction)","상속(Inheritance)","캡슐화(Encapsulation)"],"answer":2,"explain":"상속은 재사용성을 높인다. 캡슐화는 데이터와 메서드를 묶고 감추는 것, 다형성은 같은 메시지에 객체마다 다르게 반응하는 것이다."},{"id":"pc-0191","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"국내 도메인 이름에서 기관 성격과의 연결로 옳지 않은 것은?","options":["go.kr - 정부 기관","re.kr - 연구 기관","or.kr - 영리 기업","ac.kr - 대학"],"answer":2,"explain":"or.kr은 비영리 단체이고, 영리 기업은 co.kr이다."},{"id":"pc-0192","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"웹 사이트를 방문했을 때 로그인 상태·설정 같은 정보를 사용자 컴퓨터에 저장해 두는 작은 텍스트 파일은?","options":["쿠키(Cookie)","북마크(Bookmark)","플러그인(Plug-in)","캐시(Cache)"],"answer":0,"explain":"쿠키는 사이트가 사용자 정보를 기억하기 위해 남기는 파일이다. 캐시는 빠른 표시를 위해 웹 페이지 자료를 임시 저장한 것이다."},{"id":"pc-0193","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"건물·학교처럼 비교적 좁은 지역 안의 컴퓨터를 연결하는 고속 통신망은?","options":["MAN","VAN","WAN","LAN"],"answer":3,"explain":"LAN은 근거리 통신망이다. MAN은 도시 규모, WAN은 국가·대륙 규모, VAN은 부가 가치 통신망이다."},{"id":"pc-0194","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"설치된 앱을 제거하는 방법으로 옳지 않은 것은?","options":["[제어판]-[프로그램 및 기능]에서 [제거]","[설정]-[앱]에서 해당 앱을 선택해 [제거]","바탕 화면에 있는 앱의 바로 가기 아이콘 삭제","시작 메뉴에서 앱을 오른쪽 클릭해 [제거]"],"answer":2,"explain":"바로 가기 아이콘을 지워도 앱은 그대로 남는다. 앱 제거는 설정·제어판·시작 메뉴의 [제거]로 한다."},{"id":"pc-0195","subject":"computer","levels":["c1"],"topic":"운영체제","q":"두 대의 컴퓨터가 같은 업무를 동시에 처리하며 결과를 서로 점검하다가, 한쪽에 장애가 생기면 다른 쪽이 계속 처리하는 시스템은?","options":["다중 프로그래밍 시스템","듀얼 시스템(Dual System)","시분할 시스템","듀플렉스 시스템(Duplex System)"],"answer":1,"explain":"듀얼 시스템은 두 대가 함께 동작한다. 듀플렉스 시스템은 한 대가 처리하고 다른 한 대는 대기하다가 장애 때 넘겨받는다."},{"id":"pc-0196","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"하나의 이미지가 다른 이미지로 서서히 자연스럽게 바뀌어 가도록 만드는 그래픽 기법은?","options":["렌더링(Rendering)","리터칭(Retouching)","디더링(Dithering)","모핑(Morphing)"],"answer":3,"explain":"모핑은 두 이미지 사이를 부드럽게 변형한다. 렌더링은 3D 모델에 질감·빛을 입혀 사실감 있게 만드는 작업이다."},{"id":"pc-0197","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"종단 간 신뢰성 있는 전송과 오류·흐름 제어를 담당하며 TCP·UDP가 동작하는 OSI 계층은?","options":["표현 계층","전송 계층","네트워크 계층","물리 계층"],"answer":1,"explain":"전송 계층(4계층)은 송수신 프로세스 사이의 데이터 전달을 책임진다."},{"id":"pc-0198","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"8비트로 나타낼 수 있는 서로 다른 값의 개수는?","options":["128","256","512","1024"],"answer":1,"explain":"n비트는 2ⁿ가지를 표현하므로 2⁸ = 256가지이다."},{"id":"pc-0199","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"기억 용량 단위를 작은 것부터 큰 것으로 바르게 나열한 것은?","options":["KB → MB → TB → GB → PB","KB → GB → MB → TB → PB","KB → MB → GB → TB → PB","MB → KB → GB → PB → TB"],"answer":2,"explain":"각 단위는 2의 10제곱(1,024)배씩 커진다: KB < MB < GB < TB < PB < EB."},{"id":"pc-0200","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"운영체제가 각 프로그램의 CPU 사용 시간을 통제하여, 한 프로그램이 응답하지 않아도 다른 작업을 계속할 수 있게 하는 방식은?","options":["비선점형 멀티태스킹","일괄 처리","선점형 멀티태스킹","스풀링"],"answer":2,"explain":"Windows는 운영체제가 CPU를 빼앗아 다른 작업에 배분하는 선점형 멀티태스킹을 사용한다. 비선점형은 프로그램이 스스로 CPU를 내놓아야 한다."},{"id":"pc-0201","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"개인정보 보호법상 정보주체가 개인정보처리자에게 요구할 수 있는 권리로 옳지 않은 것은?","options":["자신의 개인정보 열람 요구","잘못된 개인정보의 정정·삭제 요구","개인정보 처리 정지 요구","개인정보처리자의 영업 비밀 전체 공개 요구"],"answer":3,"explain":"정보주체는 자신의 개인정보에 대한 열람·정정·삭제·처리 정지를 요구할 수 있다. 영업 비밀 공개는 포함되지 않는다."},{"id":"pc-0202","subject":"computer","levels":["c1"],"topic":"운영체제","q":"파일 시스템에 관한 설명으로 옳지 않은 것은?","options":["NTFS는 파일·폴더별로 접근 권한(보안)을 설정할 수 있다","FAT32는 파일 단위 압축·암호화(EFS)와 접근 권한 설정을 지원한다","FAT32는 파일 하나의 크기가 4GB 미만으로 제한된다","NTFS는 변경 내용을 로그로 남겨 갑작스러운 전원 차단 뒤의 복구에 유리하다"],"answer":1,"explain":"압축·암호화·접근 권한은 NTFS의 기능이며 FAT32에는 없다. FAT32의 파일 크기 제한(4GB 미만)도 자주 나오는 내용이다."},{"id":"pc-0203","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"8비트 데이터에서 상위 4비트는 0으로 지우고 하위 4비트는 그대로 두려면 어떤 연산을 하면 되는가?","options":["00001111과 OR","00001111과 AND","11110000과 AND","00001111과 XOR"],"answer":1,"explain":"AND는 0과 만나면 0이 되고 1과 만나면 원래 값이 유지된다. 지우려는 자리를 0으로 둔 마스크 00001111과 AND한다."},{"id":"pc-0204","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"멀티미디어의 특징으로 옳지 않은 것은?","options":["정보가 한 방향으로만 전달되는 단방향성","텍스트·소리·영상 등 여러 매체를 통합한다","정보를 디지털 데이터로 통합하여 처리한다","사용자의 선택에 따라 진행되는 쌍방향성이 있다"],"answer":0,"explain":"멀티미디어는 사용자와 상호작용하는 쌍방향 매체이다."},{"id":"pc-0205","subject":"computer","levels":["c1"],"topic":"운영체제","q":"메모리 관리에서 내부 단편화에 관한 설명으로 옳은 것은?","options":["빈 공간의 합은 충분하지만 연속된 공간이 없어 할당하지 못하는 현상이다","할당된 메모리 블록 안에서 프로세스가 쓰지 않아 낭비되는 공간이다","페이지 교체가 너무 잦아 속도가 떨어지는 현상이다","두 프로세스가 서로 상대의 자원을 기다리며 멈춘 상태이다"],"answer":1,"explain":"내부 단편화는 할당 단위가 필요보다 커서 블록 안에 남는 공간이다. 연속 공간이 없어 못 쓰는 것은 외부 단편화이다."},{"id":"pc-0206","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"요구 분석 → 설계 → 구현 → 테스트 → 유지보수를 순차적으로 진행하며 앞 단계로 되돌아가기 어려운 소프트웨어 개발 모델은?","options":["나선형 모델","폭포수 모델","프로토타입 모델","애자일 모델"],"answer":1,"explain":"폭포수 모델은 단계를 차례로 진행한다. 나선형은 위험 분석을 곁들여 반복하고, 애자일은 짧은 주기로 반복한다."},{"id":"pc-0207","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"UHD(4K) 해상도는?","options":["1920×1080","2560×1440","1280×720","3840×2160"],"answer":3,"explain":"UHD는 3840×2160이다. 1920×1080은 FHD, 2560×1440은 QHD이다."},{"id":"pc-0208","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"2진수 1011과 0110을 더한 결과는?","options":["10001","10101","10011","1111"],"answer":0,"explain":"1011(11)+0110(6)=10001(17)이다."},{"id":"pc-0209","subject":"computer","levels":["c1"],"topic":"운영체제","q":"NTFS 볼륨에서 개별 파일이나 폴더를 암호화하여 해당 사용자 계정으로만 열 수 있게 하는 기능은?","options":["BitLocker","사용자 계정 컨트롤(UAC)","파일 히스토리","EFS(암호화 파일 시스템)"],"answer":3,"explain":"EFS는 파일·폴더 단위 암호화이다. BitLocker는 드라이브 전체를 암호화한다."},{"id":"pc-0210","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"QR 코드에 관한 설명으로 옳은 것은?","options":["굵기가 서로 다른 세로선의 조합으로만 정보를 나타내는 1차원 코드이며 용량이 작다","숫자만 저장할 수 있어 웹 주소나 문자는 담을 수 없고 오류 정정 기능도 없다","스캐너를 정해진 한 방향으로 맞추어야만 판독할 수 있으며 비스듬히는 읽히지 않는다","2차원으로 정보를 담아 바코드보다 많이 저장하며 일부가 훼손되어도 복원할 수 있다"],"answer":3,"explain":"QR 코드는 오류 정정 기능이 있는 2차원 코드로 숫자·문자·URL을 담을 수 있다."},{"id":"pc-0211","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"공격자를 유인하려고 일부러 취약하게 만들어 둔 가짜 시스템으로, 공격 수법을 관찰·분석하는 데 쓰는 것은?","options":["방화벽","프록시 서버","백도어","허니팟"],"answer":3,"explain":"허니팟은 미끼 시스템이다. 백도어는 공격자가 몰래 만들어 둔 접근 통로이다."},{"id":"pc-0212","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"개발자가 서버와 운영체제를 직접 관리하지 않고 애플리케이션을 개발·배포할 수 있는 환경을 제공하는 클라우드 서비스 형태는?","options":["SaaS","IaaS","온프레미스","PaaS"],"answer":3,"explain":"PaaS는 개발·실행 플랫폼을 제공한다. SaaS는 완성된 소프트웨어를, IaaS는 가상 인프라를 제공한다."},{"id":"pc-0213","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"이진 탐색에 관한 설명으로 옳은 것은?","options":["자료가 정렬되어 있지 않아도 곧바로 적용할 수 있는 탐색 방법이다","정렬된 자료에서 가운데 값과 비교하며 탐색 범위를 절반씩 줄인다","첫 번째 자료부터 마지막 자료까지 차례로 하나씩 비교해 나가는 방법이다","한 번 비교할 때마다 탐색 범위가 세 배씩 넓어져 가는 방법이다"],"answer":1,"explain":"이진 탐색은 정렬이 전제이며 순차 탐색보다 빠르다."},{"id":"pc-0214","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"1ms(밀리초)는 몇 μs(마이크로초)와 같은가?","options":["100μs","10,000μs","1,000μs","1,000,000μs"],"answer":2,"explain":"밀리초는 10의 -3제곱 초, 마이크로초는 10의 -6제곱 초이므로 1ms=1,000μs이다."},{"id":"pc-0215","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"1초에 몇 백만 개의 명령어를 실행하는지로 CPU 성능을 나타내는 단위는?","options":["FLOPS","CPI","RPM","MIPS"],"answer":3,"explain":"MIPS는 초당 백만 명령어 수이다. FLOPS는 초당 부동 소수점 연산 수, CPI는 명령어당 클럭 수이다."},{"id":"pc-0216","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"프로젝터나 보조 모니터를 연결했을 때 [PC 화면만]·[복제]·[확장]·[두 번째 화면만] 중에서 고르는 창을 여는 바로 가기 키는?","options":["Win+P","Win+K","Win+S","Win+T"],"answer":0,"explain":"Win+P가 화면 투영 방식을 고르는 창을 연다. Win+K는 무선 디스플레이 연결, Win+S는 검색, Win+T는 작업 표시줄 앱 선택이다."},{"id":"pc-0217","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"GPU에 관한 설명으로 옳은 것은?","options":["프로그램의 실행 순서를 해석하고 제어하는 CPU 내부의 제어 회로 일부이다","전원이 꺼져도 데이터를 계속 보관하는 대용량 보조기억장치의 한 종류이다","수많은 연산을 병렬로 처리하는 구조라 그래픽 처리와 AI 학습에 널리 쓰인다","서로 다른 네트워크를 연결하여 패킷이 갈 경로를 선택해 주는 네트워크 장비이다"],"answer":2,"explain":"GPU는 단순한 연산을 대량으로 동시에 처리하는 데 강하다."},{"id":"pc-0218","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[전원 옵션]의 [빠른 시작 켜기]에 관한 설명으로 옳은 것은?","options":["종료할 때 커널 세션과 드라이버 상태를 최대 절전 파일에 저장해 다음 부팅을 빠르게 한다","종료할 때 열려 있던 앱의 작업을 모두 저장했다가 다음 부팅에서 그대로 복원한다","[다시 시작]을 선택해도 언제나 적용되어 부팅 시간을 줄여 준다","물리 메모리(RAM)의 용량을 늘려 주어 프로그램 실행 속도를 높여 준다"],"answer":0,"explain":"빠른 시작은 사용자 세션은 닫고 커널 상태만 저장해 부팅을 빠르게 한다. [다시 시작]을 선택하면 일반 부팅을 한다."},{"id":"pc-0219","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"문자 코드에 관한 설명으로 옳지 않은 것은?","options":["ASCII 코드는 7비트로 128가지 문자를 표현한다","EBCDIC 코드는 8비트로 구성되며 대형 컴퓨터에서 쓰였다","유니코드는 전 세계의 문자를 하나의 체계로 표현한다","BCD 코드는 8비트로 256가지 문자를 표현한다"],"answer":3,"explain":"BCD 코드는 6비트로 64가지를 표현한다."},{"id":"pc-0220","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"컴퓨터와 모니터를 연결하는 인터페이스 중 아날로그 영상 신호를 전송하는 것은?","options":["HDMI","VGA(D-Sub)","DisplayPort","DVI-D"],"answer":1,"explain":"VGA는 아날로그 방식이다. HDMI·DisplayPort·DVI-D는 디지털 신호를 쓴다."},{"id":"pc-0221","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"하드 디스크의 회전 속도(RPM)가 빨라질 때 직접 줄어드는 것은?","options":["회전 지연 시간","플래터 수","디스크 전체 용량","트랙 수"],"answer":0,"explain":"원판이 빨리 돌수록 원하는 섹터가 헤드 아래로 오는 시간이 짧아진다."},{"id":"pc-0222","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"항공기 예약이나 원자로 제어처럼 정해진 시간 안에 처리 결과를 내야 하는 운영 방식은?","options":["실시간 처리 시스템","일괄 처리 시스템","시분할 시스템","다중 프로그래밍 시스템"],"answer":0,"explain":"실시간 처리는 마감 시간 안의 응답이 중요하다. 일괄 처리는 응답 시간을 따지지 않는다."},{"id":"pc-0223","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"광 디스크의 저장 용량을 작은 것부터 큰 것 순서로 나열한 것은?","options":["CD → DVD → 블루레이","DVD → CD → 블루레이","블루레이 → DVD → CD","CD → 블루레이 → DVD"],"answer":0,"explain":"일반적으로 CD는 약 700MB, DVD는 4.7GB, 블루레이는 25GB(단층)이다."},{"id":"pc-0224","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"프로토콜과 기본 포트 번호의 연결로 옳은 것은?","options":["FTP - 23","SMTP - 25","DNS - 110","Telnet - 22"],"answer":1,"explain":"SMTP는 25, FTP는 21, DNS는 53, Telnet은 23이다. 110은 POP3, 22는 SSH의 포트이다."},{"id":"pc-0225","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"절전 모드와 최대 절전 모드의 비교로 옳지 않은 것은?","options":["절전 모드는 작업 상태를 메모리에 두고 최소한의 전력만 쓴다","최대 절전 모드는 전원이 꺼져도 이전 작업 상태로 복원할 수 있다","절전 모드는 작업 내용을 디스크에 저장한 뒤 전원을 완전히 끈다","절전 모드 중 전원이 끊기면 저장하지 않은 작업을 잃을 수 있다"],"answer":2,"explain":"작업을 디스크에 저장하고 전원을 끄는 쪽이 최대 절전 모드이다. 절전 모드는 메모리에 전력이 계속 필요하다."},{"id":"pc-0226","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 11의 설치 요구 사항에 해당하는 것은?","options":["32비트 프로세서","레거시 BIOS 방식 부팅만 되는 PC","TPM 2.0 지원","2GB RAM"],"answer":2,"explain":"Windows 11은 64비트 프로세서, UEFI(보안 부팅 지원), TPM 2.0, RAM 4GB 이상 등을 요구한다."},{"id":"pc-0227","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"운영체제·프로그램·설정·파일을 포함한 드라이브 전체의 복사본을 만들어 두었다가 시스템이 완전히 망가졌을 때 통째로 되살리는 백업 방식은?","options":["파일 히스토리(개인 파일 백업)","시스템 이미지 백업","복원 지점(앱·설정 복원)","디스크 정리(불필요 파일 삭제)"],"answer":1,"explain":"시스템 이미지는 드라이브 전체를 통째로 복원한다. 복원 지점은 개인 파일을 대상으로 하지 않는다."},{"id":"pc-0228","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"손가락의 정전기(전기적 특성)를 감지하며 멀티 터치가 가능하여 스마트폰에 널리 쓰이는 터치스크린 방식은?","options":["감압식","적외선식","저항막식","정전식"],"answer":3,"explain":"정전식은 신체의 전기적 특성을 이용하여 가볍게 닿기만 해도 인식한다. 감압식은 누르는 압력으로 인식한다."},{"id":"pc-0229","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"10진수 0.625를 2진수로 바꾼 값은?","options":["0.011","0.101","0.110","0.1001"],"answer":1,"explain":"0.625에 2를 곱해 정수 부분을 취하면 1, 0, 1이 나와 0.101(2)이다. 0.5+0.125=0.625로 확인된다."},{"id":"pc-0230","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"악성 코드에 감염되어 공격자의 원격 명령에 따라 움직이는 '좀비 PC'들이 이룬 네트워크는?","options":["봇넷","허니넷","인트라넷","VPN"],"answer":0,"explain":"봇넷은 DDoS 공격이나 스팸 발송에 동원된다. 허니넷은 공격자를 유인하기 위해 만든 가짜 네트워크이다."},{"id":"pc-0231","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"정보 보안 요소 중 인가된 사용자가 필요할 때 언제든 정보와 시스템을 이용할 수 있게 하는 것은?","options":["기밀성","가용성","무결성","부인 방지"],"answer":1,"explain":"가용성은 필요할 때 쓸 수 있는 성질이다. DDoS 공격은 가용성을 침해한다."},{"id":"pc-0232","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"서브넷 마스크가 255.255.255.192(/26)일 때 하나의 서브넷에서 호스트에 할당할 수 있는 주소 수는?","options":["64개","30개","62개","126개"],"answer":2,"explain":"호스트 비트가 6비트이므로 2의 6제곱 64개에서 네트워크 주소와 브로드캐스트 주소 2개를 뺀 62개이다."},{"id":"pc-0233","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"저작권이 소멸되었거나 저작자가 권리를 포기하여 누구나 자유롭게 사용·수정·배포할 수 있는 소프트웨어는?","options":["프리웨어(무료이나 저작권 유지)","셰어웨어(일정 기간 뒤 구입 요구)","애드웨어(광고 노출 조건)","공개(퍼블릭 도메인) 소프트웨어"],"answer":3,"explain":"퍼블릭 도메인은 저작권이 없는 상태이다. 프리웨어는 무료일 뿐 저작권 제한이 남아 있다."},{"id":"pc-0234","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"Python에 관한 설명으로 옳은 것은?","options":["컴파일을 거쳐 만들어진 실행 파일만 실행할 수 있어 소스 파일은 직접 실행할 수 없다","기계어에 가까워 하드웨어를 직접 제어하는 데 쓰이는 저급 언어에 해당한다","인터프리터 방식의 고급 언어로 문법이 간결하며 데이터 분석과 AI에 널리 쓰인다","웹 문서의 구조와 요소를 태그로 정의하는 마크업 언어에 해당한다"],"answer":2,"explain":"Python은 한 줄씩 실행하는 인터프리터 방식의 범용 고급 언어이다."},{"id":"pc-0235","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"색 모델에 관한 설명으로 옳은 것은?","options":["CMYK는 빛을 더하는 가산 혼합 방식이며 모니터 화면 표현에 주로 쓰인다","RGB는 잉크를 섞어 색을 만드는 감산 혼합 방식이며 인쇄에 주로 쓰인다","RGB는 빛의 삼원색을 더해 색을 만드는 가산 혼합이며 모니터에 쓰인다","CMYK에서 K는 파란색(Blue)을 뜻하며 청록·자홍·노랑과 함께 쓰인다"],"answer":2,"explain":"RGB는 가산 혼합(모니터), CMYK는 감산 혼합(인쇄)이다. K는 검정(Key)이다."},{"id":"pc-0236","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[설정]-[개인 설정]에서 할 수 있는 작업이 아닌 것은?","options":["사용자 계정의 로그인 암호 변경","바탕 화면 배경 변경","잠금 화면 이미지 변경","테마와 색 변경"],"answer":0,"explain":"로그인 암호와 PIN은 [계정]-[로그인 옵션]에서 바꾼다. [개인 설정]은 화면의 겉모습을 꾸미는 곳이다."},{"id":"pc-0237","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[성능 옵션]-[고급]-[가상 메모리] 설정에 관한 설명으로 옳은 것은?","options":["가상 메모리를 늘리면 물리 RAM이 실제로 늘어나 RAM과 같은 속도로 동작한다","SSD에는 가상 메모리를 설정할 수 없고 하드 디스크에서만 설정할 수 있다","페이징 파일의 위치와 크기를 지정하며 RAM이 부족할 때 디스크 일부를 메모리처럼 쓴다","가상 메모리는 CPU 안의 캐시 메모리 용량을 키워 주는 설정이다"],"answer":2,"explain":"가상 메모리는 디스크를 보조로 쓰는 것이라 RAM보다 훨씬 느리다. 크기와 위치는 직접 지정하거나 시스템이 자동 관리하게 할 수 있다."},{"id":"pc-0238","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"CPU가 명령어 하나를 처리하는 단계의 순서로 알맞은 것은?","options":["인출 → 해독 → 실행 → 저장","해독 → 인출 → 실행 → 저장","인출 → 실행 → 해독 → 저장","실행 → 인출 → 해독 → 저장"],"answer":0,"explain":"명령어를 가져와 해석한 뒤 실행하고 결과를 저장한다."},{"id":"pc-0239","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"사람이 반복하는 컴퓨터 업무를 소프트웨어 로봇이 대신 수행하게 하는 업무 자동화 기술은?","options":["IoT","5G","RPA","NFC"],"answer":2,"explain":"RPA(Robotic Process Automation)는 정해진 규칙의 업무를 자동으로 처리한다."},{"id":"pc-0240","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"알고리즘의 조건에 해당하지 않는 것은?","options":["유한성","명확성","모호성","출력"],"answer":2,"explain":"알고리즘은 입력·출력이 있고 단계가 명확하며 유한한 시간 안에 끝나야 한다. 모호한 지시는 허용되지 않는다."},{"id":"pc-0241","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"여러 대의 컴퓨터를 연결하는 장치로, 한 포트로 들어온 데이터를 나머지 모든 포트로 내보내는 것은?","options":["허브","스위치","라우터","게이트웨이"],"answer":0,"explain":"허브는 받은 신호를 모든 포트로 뿌린다. 스위치는 MAC 주소를 보고 해당 포트로만 보낸다."},{"id":"pc-0242","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"네트워크 규모에 따른 분류에서 도시 규모(MAN)보다 넓어 국가나 대륙 간을 연결하는 것은?","options":["LAN","WAN","MAN","PAN"],"answer":1,"explain":"LAN < MAN < WAN 순으로 넓어진다. PAN은 개인 주변의 매우 좁은 범위이다."},{"id":"pc-0243","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"OSI 7계층 중 MAC 주소를 사용해 프레임 단위로 인접한 노드 사이의 전송과 오류 검출을 담당하는 계층은?","options":["물리 계층(비트 신호 전송)","네트워크 계층(IP 주소·경로 선택)","전송 계층(종단 간 신뢰성)","데이터 링크 계층"],"answer":3,"explain":"데이터 링크 계층은 프레임을 다루며 MAC 주소를 쓴다. 물리 계층은 비트 신호를, 네트워크 계층은 IP 주소를 다룬다."},{"id":"pc-0244","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"파일 압축에 관한 설명으로 옳지 않은 것은?","options":["압축하면 저장 공간이 줄고 전송 시간이 짧아진다","이미 압축된 JPEG 파일은 다시 압축해도 크기가 크게 줄지 않는다","무손실 압축을 한 파일은 압축을 풀어도 일부 정보가 손실된다","ZIP·7z·RAR 등 여러 압축 형식이 있다"],"answer":2,"explain":"무손실 압축은 압축을 풀면 원본과 똑같이 복원된다. 일부 정보가 사라지는 것은 손실 압축이다."},{"id":"pc-0245","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"USB Type-C 커넥터에 관한 설명으로 옳은 것은?","options":["Type-A 커넥터보다 크기가 커서 얇은 노트북에는 장착하기 어려운 규격이다","데이터 전송만 가능하고 기기를 충전하는 용도로는 사용할 수 없는 규격이다","위아래 구분 없이 꽂으며 데이터 전송·충전·영상 출력을 지원할 수 있다","USB 2.0 수준의 낮은 전송 속도만 낼 수 있어 영상 출력은 불가능하다"],"answer":2,"explain":"Type-C는 작고 방향이 없으며 규격에 따라 고속 전송·전력 공급·영상 출력을 지원한다."},{"id":"pc-0246","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"3차원 모델에 조명·재질·그림자 등을 계산해 사실적인 2차원 이미지로 만드는 과정은?","options":["디더링","모핑","샘플링","렌더링"],"answer":3,"explain":"렌더링은 3D 데이터를 화면 이미지로 만든다. 모핑은 이미지가 다른 이미지로 변하는 기법이다."},{"id":"pc-0247","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"프로그래밍 언어와 주된 용도의 연결로 옳지 않은 것은?","options":["HTML - 데이터베이스에 질의하고 데이터를 조작","FORTRAN - 과학·공학 계산","COBOL - 사무 처리","C - 운영체제 등 시스템 소프트웨어 개발"],"answer":0,"explain":"데이터베이스 질의에는 SQL을 쓴다. HTML은 웹 문서의 구조를 나타내는 마크업 언어이다."},{"id":"pc-0248","subject":"computer","levels":["c1"],"topic":"운영체제","q":"교착 상태(Deadlock)가 발생하기 위한 필요 조건이 아닌 것은?","options":["상호 배제(Mutual Exclusion)","선점(Preemption)","점유와 대기(Hold and Wait)","환형 대기(Circular Wait)"],"answer":1,"explain":"교착 상태의 네 조건은 상호 배제·점유와 대기·비선점·환형 대기이다. 선점이 가능하면 자원을 빼앗아 교착을 풀 수 있다."},{"id":"pc-0249","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"방대한 데이터에서 숨은 패턴이나 규칙, 관계를 찾아내는 분석 기법은?","options":["데이터 마이닝","데이터 백업","데이터 암호화","데이터 압축"],"answer":0,"explain":"데이터 마이닝은 대용량 데이터에서 유용한 지식을 발굴한다."},{"id":"pc-0250","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"웹 문서의 글꼴·색·배치 같은 표현 방식을 정의하는 스타일 시트 언어는?","options":["HTML","CSS","XML","PHP"],"answer":1,"explain":"CSS는 웹 문서의 모양을 꾸민다. HTML은 구조, PHP는 서버에서 실행되는 스크립트이다."},{"id":"pc-0251","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"현실의 사물·공정·도시를 가상 공간에 똑같이 만들어 놓고 시뮬레이션과 분석을 하는 기술은?","options":["디지털 트윈","블록체인","엣지 컴퓨팅","핀테크"],"answer":0,"explain":"디지털 트윈은 현실의 쌍둥이를 가상에 두고 시험해 본다."},{"id":"pc-0252","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"증강 현실(AR)에 관한 설명으로 옳은 것은?","options":["사용자를 완전히 가상의 세계에 몰입시킨다","현실 세계의 화면 위에 가상의 정보를 겹쳐 보여 준다","모든 정보를 텍스트로만 보여 준다","센서나 카메라 없이 동작한다"],"answer":1,"explain":"AR은 현실에 가상 정보를 덧씌운다. 완전한 가상 세계는 VR이다."},{"id":"pc-0253","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"문서 파일에 포함된 매크로를 통해 감염되고 확산하는 바이러스는?","options":["부트 바이러스","파일 감염 바이러스","웜","매크로 바이러스"],"answer":3,"explain":"매크로 바이러스는 워드·엑셀 문서의 매크로를 이용한다. 부트 바이러스는 부트 섹터를 감염시킨다."},{"id":"pc-0254","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"아날로그 소리를 디지털 데이터로 바꾸는 과정의 순서로 옳은 것은?","options":["양자화 → 표본화 → 부호화","표본화 → 부호화 → 양자화","표본화 → 양자화 → 부호화","부호화 → 표본화 → 양자화"],"answer":2,"explain":"일정 간격으로 값을 뽑고(표본화), 값을 정해진 단계로 나눈 뒤(양자화), 2진 부호로 바꾼다(부호화)."},{"id":"pc-0255","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 표시줄의 왼쪽에서 세 번째에 고정된 앱을 실행하거나 그 앱의 창으로 전환하는 바로 가기 키는?","options":["Alt+3","Ctrl+3","Shift+3","Win+3"],"answer":3,"explain":"Win+숫자는 작업 표시줄에서 그 순서에 놓인 앱을 연다."},{"id":"pc-0256","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"명령어 형식에서 수행할 연산의 종류를 나타내는 부분은?","options":["오퍼랜드(Operand)","연산 코드(OP Code)","프로그램 카운터","상태 레지스터"],"answer":1,"explain":"연산 코드는 무슨 연산을 할지, 오퍼랜드는 대상 데이터나 그 주소를 나타낸다."},{"id":"pc-0257","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"빈 스택에 A, B, C를 차례로 삽입(push)한 뒤 삭제(pop)를 두 번 했을 때 스택에 남아 있는 데이터는?","options":["B","C","A","남는 데이터 없음"],"answer":2,"explain":"스택은 나중에 들어온 것이 먼저 나온다. C와 B가 차례로 삭제되어 A만 남는다."},{"id":"pc-0258","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"안드로이드(Android) 운영체제에 관한 설명으로 옳은 것은?","options":["Apple이 개발하여 자사 기기에만 쓰도록 만든 폐쇄형 운영체제이다","Windows 커널을 바탕으로 만든 데스크톱용 운영체제이다","Linux 커널을 기반으로 하는 모바일 운영체제이다","아이폰에만 설치할 수 있는 운영체제로 안드로이드폰에서는 쓸 수 없다"],"answer":2,"explain":"안드로이드는 Linux 커널 기반이며 Google이 주도해 만든 모바일 운영체제이다. 아이폰의 운영체제는 Apple의 iOS이다."},{"id":"pc-0259","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"서버에 주로 쓰이며 메모리에서 생긴 1비트 오류를 검출하고 정정하는 기능을 갖춘 메모리는?","options":["ECC 메모리","ROM","캐시 메모리","플래시 메모리"],"answer":0,"explain":"ECC(Error Correcting Code) 메모리는 오류 정정 코드를 함께 저장한다."},{"id":"pc-0260","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"UTF-8 인코딩에 관한 설명으로 옳은 것은?","options":["모든 문자를 항상 2바이트의 고정된 길이로 나타내는 방식으로 용량이 일정하다","한글을 2바이트 완성형으로만 나타내는 방식이며 영문자는 표현하지 못한다","ASCII 코드와 호환되지 않아 영문 문서도 별도의 변환을 거쳐야 읽을 수 있다","영문자는 1바이트, 한글은 보통 3바이트로 나타내는 가변 길이 방식이다"],"answer":3,"explain":"UTF-8은 글자에 따라 1~4바이트를 쓰며 ASCII 문자는 같은 1바이트 값을 갖는다."},{"id":"pc-0261","subject":"computer","levels":["c1"],"topic":"운영체제","q":"프로세스 스케줄링 방식 중 선점(Preemptive) 방식에 해당하는 것은?","options":["FCFS(선입 선출)","SJF(최단 작업 우선)","HRN(응답률 우선)","라운드 로빈(RR)"],"answer":3,"explain":"라운드 로빈은 시간 할당량이 끝나면 CPU를 빼앗는 선점 방식이다. FCFS·SJF·HRN은 실행 중인 프로세스를 중단시키지 않는 비선점 방식이다."},{"id":"pc-0262","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"메인보드의 CMOS에 관한 설명으로 옳은 것은?","options":["별도의 전원 공급이 없어도 내용이 영구히 유지되는 읽기 전용 메모리이다","운영체제 파일과 사용자의 문서가 저장되는 대용량 보조기억장치이다","CPU가 계산한 연산 결과를 임시로 보관하는 CPU 내부 기억 장소이다","날짜·시간·부팅 순서 같은 BIOS 설정값을 저장하며 전지로 내용을 유지한다"],"answer":3,"explain":"CMOS 메모리는 휘발성이라 메인보드의 작은 전지가 설정값을 유지한다. 전지가 방전되면 시간이 초기화된다."},{"id":"pc-0263","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"암호 알고리즘 중 비대칭키(공개키) 방식은?","options":["DES","RSA","AES","SEED"],"answer":1,"explain":"RSA는 공개키 방식이다. DES·AES·SEED는 대칭키 방식이다."},{"id":"pc-0264","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"사설(Private) IP 주소 대역에 해당하는 것은?","options":["192.168.10.5","8.8.8.8","172.32.0.1","203.0.113.5"],"answer":0,"explain":"사설 대역은 10.x.x.x, 172.16~172.31.x.x, 192.168.x.x이다. 172.32.0.1은 이 범위 밖이다."},{"id":"pc-0265","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 11의 변화로 옳은 것은?","options":["시작 메뉴에서 앱을 타일 형태로 보여 주는 라이브 타일을 계속 쓸 수 있다","작업 표시줄을 화면 위쪽이나 양옆으로 자유롭게 옮겨 놓을 수 있다","제어판이 모든 기능과 함께 완전히 없어지고 설정 앱만 남았다","작업 표시줄의 시작 단추와 앱 아이콘이 기본으로 가운데에 놓인다"],"answer":3,"explain":"Windows 11은 작업 표시줄을 가운데 정렬로 시작하며 위·옆 배치와 라이브 타일은 지원하지 않는다. 제어판은 일부가 남아 있다."},{"id":"pc-0266","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기 키와 기능의 연결로 옳지 않은 것은?","options":["F5: 현재 폴더의 내용을 새로 고침","Alt+Enter: 선택 항목의 이름 바꾸기","Alt+↑: 현재 폴더의 상위 폴더로 이동","Alt+←: 이전에 보았던 위치로 이동"],"answer":1,"explain":"Alt+Enter는 선택 항목의 [속성] 창을 연다. 이름 바꾸기는 F2이다."},{"id":"pc-0267","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[설정]의 [계정]에서 설정하는 항목으로 옳은 것은?","options":["화면 해상도와 디스플레이 배율을 바꾸는 항목 (디스플레이)","파일 형식별로 기본으로 열 프로그램을 지정하는 항목 (기본 앱)","로그인 옵션(PIN·지문·얼굴 인식 등 Windows Hello)","날짜와 시간의 표시 형식 및 입력 언어를 정하는 항목 (시간 및 언어)"],"answer":2,"explain":"[계정]에서는 로그인 방법과 사용자 추가를 관리한다. 해상도는 [디스플레이], 기본 앱은 [앱]에서 설정한다."},{"id":"pc-0268","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"TCP 연결을 설정하는 3-way handshake 과정의 순서로 옳은 것은?","options":["SYN → ACK → SYN+ACK","ACK → SYN → SYN+ACK","SYN+ACK → SYN → ACK","SYN → SYN+ACK → ACK"],"answer":3,"explain":"클라이언트가 SYN을 보내고 서버가 SYN+ACK로 답하면 클라이언트가 ACK를 보내 연결이 성립한다."},{"id":"pc-0269","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"OLED 디스플레이에 관한 설명으로 옳은 것은?","options":["액정 뒤의 백라이트가 항상 켜져 있어야만 화면을 볼 수 있는 방식이다","외부 빛을 반사하는 방식이라서 어두운 곳에서는 화면이 보이지 않는다","화소가 스스로 빛을 내므로 백라이트가 필요 없고 검은색 표현이 우수하다","주로 잉크와 토너를 이용하여 종이 위에 문자와 그림을 인쇄하는 방식이다"],"answer":2,"explain":"OLED는 자체 발광 소자이다. 백라이트가 필요한 것은 LCD 계열이다."},{"id":"pc-0270","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"도메인 이름에 해당하는 IP 주소를 DNS 서버에 조회하는 명령은?","options":["ipconfig","netstat","tracert","nslookup"],"answer":3,"explain":"nslookup은 DNS 조회 도구이다. netstat은 열린 연결과 포트를 보여 준다."},{"id":"pc-0271","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"네트워크 프로필을 [공용 네트워크]로 설정했을 때의 특징은?","options":["같은 네트워크에 있는 다른 PC의 공유 폴더와 프린터를 자동으로 검색해 준다","같은 네트워크의 다른 장치가 이 PC를 검색하지 못해 보안이 엄격하다","인터넷 연결은 차단되고 같은 네트워크 안의 내부 통신만 허용된다","공용 네트워크에 연결하면 VPN 연결이 자동으로 시작되어 통신이 암호화된다"],"answer":1,"explain":"카페·공항 같은 신뢰할 수 없는 네트워크에는 공용을 쓴다. 가정·회사처럼 믿을 수 있는 곳에는 [개인 네트워크]를 쓴다."},{"id":"pc-0272","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"언어 번역 프로그램에 해당하지 않는 것은?","options":["로더(Loader)","컴파일러(Compiler)","인터프리터(Interpreter)","어셈블러(Assembler)"],"answer":0,"explain":"로더는 실행 파일을 주기억장치에 올리는 프로그램이다. 번역 프로그램은 컴파일러·인터프리터·어셈블러이다."},{"id":"pc-0273","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"웹 브라우저의 시크릿(InPrivate) 모드에 관한 설명으로 옳은 것은?","options":["방문한 웹 사이트나 인터넷 서비스 제공업체도 사용자의 활동을 알아볼 수 없다","시크릿 창에서 내려받은 파일도 창을 닫을 때 함께 자동으로 삭제된다","창을 닫으면 방문 기록·쿠키·입력 정보가 이 기기에 남지 않는다","내 컴퓨터의 IP 주소가 숨겨져 접속한 사이트가 위치를 알 수 없게 된다"],"answer":2,"explain":"시크릿 모드는 이 기기에 기록을 남기지 않을 뿐 네트워크 상의 활동까지 숨기지는 않는다. 내려받은 파일은 남는다."},{"id":"pc-0274","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"2진수 11010110을 16진수로 바꾼 값은?","options":["D3","6D","D6","B6"],"answer":2,"explain":"4비트씩 묶으면 1101=D, 0110=6이므로 D6이다."},{"id":"pc-0275","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"양쪽 방향으로 동시에 통신할 수 있는 전송 방식으로 전화기가 대표적인 것은?","options":["단방향 방식","반이중 방식","전이중 방식","동기식"],"answer":2,"explain":"전이중은 송수신을 동시에, 반이중은 번갈아 한다(무전기). 단방향은 한쪽으로만 보낸다(라디오)."},{"id":"pc-0276","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"웹 입력란에 악의적인 SQL 구문을 넣어 데이터베이스를 조작하거나 정보를 빼내는 공격은?","options":["SQL 삽입(SQL Injection)","XSS(크로스 사이트 스크립팅)","DDoS","세션 하이재킹"],"answer":0,"explain":"SQL 삽입은 입력값 검증이 부족한 쿼리를 노린다. XSS는 악성 스크립트를 삽입하는 공격이다."},{"id":"pc-0277","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"공장의 설비와 공정을 IoT·AI로 연결하여 자동 제어하고 최적화하는 지능형 공장은?","options":["스마트 그리드","스마트 시티","스마트 워크","스마트 팩토리"],"answer":3,"explain":"스마트 팩토리는 생산 현장을 데이터로 제어한다. 스마트 그리드는 전력망을 지능화한 것이다."},{"id":"pc-0278","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"기술적 해킹 대신 사람의 심리와 신뢰를 이용해 비밀번호나 정보를 얻어 내는 수법은?","options":["사회 공학 기법","무차별 대입 공격","버퍼 오버플로","포트 스캐닝"],"answer":0,"explain":"사회 공학은 사람을 속이는 방식이다. 전화·메일로 담당자를 사칭하는 것이 예이다."},{"id":"pc-0279","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"전자 우편 프로토콜에 관한 설명으로 옳은 것은?","options":["SMTP는 메일을 보내거나 메일 서버끼리 전달할 때 쓴다","IMAP은 메일 송신 전용 프로토콜이다","POP3는 메일을 보내는 데 쓰는 프로토콜이다","SMTP는 수신 서버에서 메일을 내려받는 프로토콜이다"],"answer":0,"explain":"송신은 SMTP, 수신은 POP3나 IMAP이 맡는다."},{"id":"pc-0280","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"광고를 보여 주는 조건으로 무료로 제공하거나 광고가 포함된 채 배포되는 소프트웨어는?","options":["번들","베타 버전","패치","애드웨어"],"answer":3,"explain":"애드웨어는 광고 수익으로 무료 사용을 허용한다. 번들은 다른 제품과 함께 제공되는 소프트웨어이다."},{"id":"pc-0281","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"저작권에 관한 설명으로 옳은 것은?","options":["창작한 때부터 발생하며 별도의 등록 절차가 필요 없다","등록을 해야만 권리가 발생한다","저작재산권은 다른 사람에게 양도할 수 없다","공표된 저작물만 보호된다"],"answer":0,"explain":"저작권은 창작과 동시에 발생한다(무방식주의). 저작재산권은 양도·상속이 가능하다."},{"id":"pc-0282","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"순서도에서 조건을 비교하여 '예/아니오'로 갈라지는 판단 동작을 나타내는 기호의 모양은?","options":["사각형","평행사변형","마름모","타원"],"answer":2,"explain":"판단은 마름모, 처리는 사각형, 입출력은 평행사변형, 시작·끝은 타원으로 나타낸다."},{"id":"pc-0283","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"데이터 구성 단위를 작은 것부터 큰 것 순서로 나열한 것은?","options":["비트 → 필드 → 바이트 → 레코드 → 파일 → 데이터베이스","바이트 → 비트 → 필드 → 파일 → 레코드 → 데이터베이스","비트 → 바이트 → 레코드 → 필드 → 파일 → 데이터베이스","비트 → 바이트 → 필드 → 레코드 → 파일 → 데이터베이스"],"answer":3,"explain":"필드가 모여 레코드, 레코드가 모여 파일, 파일이 모여 데이터베이스가 된다."},{"id":"pc-0284","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"소프트웨어의 취약점이 알려지거나 패치가 나오기 전에 그 취약점을 악용하는 공격은?","options":["사전 공격","제로데이 공격","스피어 피싱","서비스 거부 공격"],"answer":1,"explain":"제로데이는 대응할 시간이 하루도 없는 취약점 공격이라는 뜻이다."},{"id":"pc-0285","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"현재 PC의 IP 주소·서브넷 마스크·기본 게이트웨이를 확인하는 명령은?","options":["ping","ipconfig","tracert","nslookup"],"answer":1,"explain":"ipconfig는 네트워크 설정을 보여 준다. ping은 연결 확인, tracert는 경로 추적, nslookup은 DNS 조회이다."},{"id":"pc-0286","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"통신하는 두 당사자 사이에 끼어들어 주고받는 내용을 엿보거나 변조하는 공격은?","options":["중간자 공격(MITM)","무차별 대입 공격","랜섬웨어","스미싱"],"answer":0,"explain":"중간자 공격은 통신 경로 중간에서 가로채는 공격이다."},{"id":"pc-0287","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[야간 모드]에 관한 설명으로 옳은 것은?","options":["화면의 청색광을 줄여 따뜻한 색으로 바꾸어 눈의 피로를 줄인다","화면 밝기를 시간에 상관없이 자동으로 최대치까지 올려 주는 기능이다","화면 해상도를 낮추어 전력 소모를 줄이는 절전 기능이다","앱과 창의 배경을 어두운 색으로 바꾸는 어둡게 모드와 같은 기능이다"],"answer":0,"explain":"야간 모드는 색 온도를 조절하는 기능이다. 어두운 배경은 [색] 설정의 어둡게 모드이다."},{"id":"pc-0288","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"우리나라 저작권법에서 저작재산권의 일반적인 보호 기간은?","options":["저작자의 사망 후 30년","저작자의 사망 후 50년","저작자의 생존 기간과 사망 후 70년","저작물 공표 후 100년"],"answer":2,"explain":"2013년부터 저작자 사후 70년으로 늘었다."},{"id":"pc-0289","subject":"computer","levels":["c1"],"topic":"운영체제","q":"운영체제의 성능 평가 기준 중 일정 시간 동안 시스템이 처리하는 일의 양을 뜻하는 것은?","options":["응답 시간(Response Time)","처리 능력(Throughput)","사용 가능도(Availability)","신뢰도(Reliability)"],"answer":1,"explain":"처리 능력은 단위 시간당 처리량이다. 응답 시간은 요청 뒤 첫 응답까지 걸린 시간이다."},{"id":"pc-0290","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"하나의 통신 회선(버스)에 모든 노드가 연결되어 설치가 쉽고 비용이 적게 들지만 회선에 장애가 생기면 전체에 영향을 주는 네트워크 형태는?","options":["링형(Ring)","성형(Star)","버스형(Bus)","망형(Mesh)"],"answer":2,"explain":"버스형은 한 줄의 공통 회선을 공유한다. 링형은 원형으로, 성형은 중앙 장치를 중심으로 연결한다."},{"id":"pc-0291","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"하나의 물리 컴퓨터에서 여러 개의 가상 머신을 동시에 실행할 수 있도록 자원을 나누어 주는 소프트웨어는?","options":["하이퍼바이저","컴파일러","미들웨어","디바이스 드라이버"],"answer":0,"explain":"하이퍼바이저는 CPU·메모리 같은 자원을 가상 머신에 배분한다. Hyper-V와 VMware가 대표적이다."},{"id":"pc-0292","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"CISC 방식 프로세서에 관한 설명으로 옳은 것은?","options":["명령어 수가 적고 길이가 고정되어 있어 파이프라인 처리에 유리한 구조이다","스마트폰에 널리 쓰이는 ARM 프로세서가 대표적인 CISC 방식 프로세서이다","명령어 종류가 많고 복잡해 한 명령으로 복잡한 동작을 하며 x86이 대표적이다","명령어 해독이 단순하여 모든 프로세서 방식 중 전력 소모가 가장 적다"],"answer":2,"explain":"CISC는 복잡한 명령어 집합을 가진 방식이다. 단순한 고정 길이 명령어를 쓰는 쪽이 RISC이다."},{"id":"pc-0293","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"개인정보 보호법에서 '정보주체'는 누구를 가리키는가?","options":["개인정보를 수집하고 이를 업무에 이용하여 처리하는 사업자나 기관","처리되는 개인정보에 의하여 알아볼 수 있는 사람","개인정보 처리 업무를 맡아서 위탁받아 처리해 주는 업체","개인정보 보호 정책을 심의하고 의결하는 개인정보 보호위원회의 위원"],"answer":1,"explain":"정보주체는 개인정보의 주인인 당사자이다. 수집·처리하는 쪽은 개인정보처리자이다."},{"id":"pc-0294","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"최소 3개의 디스크가 필요하며 패리티를 분산 저장하여 디스크 한 개가 고장 나도 데이터를 복구할 수 있는 RAID 방식은?","options":["RAID 5","RAID 0","RAID 1","JBOD"],"answer":0,"explain":"RAID 5는 패리티 분산으로 성능과 안전성을 함께 얻는다. JBOD는 디스크를 단순히 이어 붙이는 방식이다."},{"id":"pc-0295","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"10진수 200을 8진수로 바꾼 값은?","options":["301","310","320","130"],"answer":1,"explain":"200을 8로 나누면 25 나머지 0, 25를 8로 나누면 3 나머지 1이므로 310이다."},{"id":"pc-0296","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"사용자가 키보드로 입력한 내용을 몰래 기록하여 비밀번호 등을 훔치는 악성 프로그램은?","options":["애드웨어","키로거","매크로 바이러스","웜"],"answer":1,"explain":"키로거는 키 입력을 기록해 공격자에게 보낸다. 애드웨어는 광고를 보여 준다."},{"id":"pc-0297","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"OSI 7계층의 계층과 데이터 단위의 연결로 옳은 것은?","options":["네트워크 계층 - 패킷","데이터 링크 계층 - 패킷","전송 계층 - 프레임","물리 계층 - 세그먼트"],"answer":0,"explain":"전송 계층은 세그먼트, 네트워크 계층은 패킷, 데이터 링크 계층은 프레임, 물리 계층은 비트를 다룬다."},{"id":"pc-0298","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"네트워크 트래픽을 감시하다가 침입이 의심되면 자동으로 차단까지 수행하는 보안 시스템은?","options":["IDS(침입 탐지 시스템)","IPS(침입 방지 시스템)","허니팟","VPN"],"answer":1,"explain":"IPS는 탐지와 차단을 함께 한다. IDS는 탐지하고 경고를 보낸다."},{"id":"pc-0299","subject":"computer","levels":["c1"],"topic":"운영체제","q":"손상된 Windows 시스템 파일을 검사하여 복구하는 명령은?","options":["chkdsk /f","ipconfig /renew","tasklist","sfc /scannow"],"answer":3,"explain":"sfc는 시스템 파일 검사기이다. chkdsk는 디스크 오류 검사, ipconfig /renew는 IP 주소 갱신, tasklist는 프로세스 목록 표시이다."},{"id":"pc-0300","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"부호를 포함하여 10진수 1234를 팩(Packed) 10진 형식으로 저장할 때 필요한 최소 바이트 수는?","options":["2바이트","3바이트","4바이트","5바이트"],"answer":1,"explain":"팩 형식은 한 자리를 4비트로 나타내고 마지막에 부호 4비트를 붙이므로 4자리+부호=5니블, 즉 3바이트이다."},{"id":"pc-0301","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"IEEE 754 단정도(32비트) 부동 소수점 형식의 구성은?","options":["부호 1비트, 지수 11비트, 가수 52비트","부호 1비트, 지수 7비트, 가수 24비트","부호 1비트, 지수 8비트, 가수 23비트","부호 1비트, 지수 15비트, 가수 16비트"],"answer":2,"explain":"단정도는 1+8+23=32비트이다. 11비트 지수와 52비트 가수는 배정도(64비트)이다."},{"id":"pc-0302","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"숫자 5, 3, 8, 1을 오름차순으로 버블 정렬할 때 첫 번째 패스를 끝낸 결과는?","options":["1, 3, 5, 8","3, 5, 1, 8","1, 3, 8, 5","3, 5, 8, 1"],"answer":1,"explain":"이웃한 두 수를 비교해 큰 수를 뒤로 보내면 5와 3이 바뀌고, 8과 1이 바뀌어 3, 5, 1, 8이 된다. 1, 3, 8, 5는 선택 정렬의 첫 단계이다."},{"id":"pc-0303","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"인터넷 같은 공중망에 암호화된 가상의 터널을 만들어 사설망처럼 안전하게 통신하게 하는 기술은?","options":["프록시 서버","VPN","방화벽","DHCP"],"answer":1,"explain":"VPN은 공중망 위에 암호화 통로를 만든다. 프록시 서버는 요청을 대신 전달하는 중계 서버이다."},{"id":"pc-0304","subject":"computer","levels":["c1"],"topic":"시스템 설정","q":"DirectX 진단 도구를 열어 디스플레이·사운드 장치 정보를 확인할 때 [실행] 창에 입력하는 명령은?","options":["winver","regedit","dxdiag","msconfig"],"answer":2,"explain":"dxdiag는 DirectX 진단 도구이다. winver는 Windows 버전, regedit는 레지스트리 편집기, msconfig는 시스템 구성을 연다."},{"id":"pc-0305","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"파일 확장자와 파일 종류의 연결로 옳지 않은 것은?","options":[".zip - 압축 파일",".exe - 실행 파일",".hwp - 한글 문서 파일",".bmp - 압축된 동영상 파일"],"answer":3,"explain":".bmp는 압축하지 않은 비트맵 이미지 형식이다."},{"id":"pc-0306","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"텍스트·이미지·음악 등 새로운 콘텐츠를 만들어 내는 인공지능은?","options":["RPA","생성형 AI","엣지 컴퓨팅","블록체인"],"answer":1,"explain":"생성형 AI는 학습한 패턴을 바탕으로 새 결과물을 만든다. RPA는 반복 업무를 자동화하는 소프트웨어 로봇이다."},{"id":"pc-0307","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"컨테이너 가상화(예: Docker)에 관한 설명으로 옳은 것은?","options":["호스트 운영체제의 커널을 공유하면서 앱의 실행 환경만 격리하여 가볍게 실행한다","가상 머신처럼 컨테이너마다 별도의 게스트 운영체제를 완전히 설치해야 실행된다","하드웨어 전체를 에뮬레이션하여 BIOS까지 가상으로 만들어 주는 방식이다","물리 서버 한 대에서는 한 번에 하나의 컨테이너만 실행할 수 있는 방식이다"],"answer":0,"explain":"컨테이너는 커널을 공유하므로 가상 머신보다 가볍고 빠르게 시작한다."},{"id":"pc-0308","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"TCP/IP 4계층 모델에서 TCP가 속하는 계층은?","options":["인터넷 계층","네트워크 접근 계층","응용 계층","전송 계층"],"answer":3,"explain":"TCP와 UDP는 전송 계층, IP는 인터넷 계층에 속한다."},{"id":"pc-0309","subject":"computer","levels":["c1"],"topic":"멀티미디어","q":"해상도 1024×768, 24비트 트루컬러의 비압축 이미지가 차지하는 용량은?","options":["2,359,296바이트","786,432바이트","18,874,368바이트","4,718,592바이트"],"answer":0,"explain":"1024×768=786,432화소에 화소당 3바이트(24비트)를 곱하면 2,359,296바이트이다."},{"id":"pc-0310","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"자기 자신을 가리키는 루프백 주소로 자신의 TCP/IP 설정을 점검할 때 쓰는 IPv4 주소는?","options":["127.0.0.1","0.0.0.0","255.255.255.255","192.168.0.1"],"answer":0,"explain":"127.0.0.1은 루프백 주소이다. 255.255.255.255는 제한된 브로드캐스트 주소이다."},{"id":"pc-0311","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"휴지통에 관한 설명으로 옳은 것은?","options":["휴지통이 가득 차면 새로 삭제하는 파일은 휴지통으로 가지 못하고 삭제가 중단된다","네트워크 드라이브에서 삭제한 파일도 휴지통으로 이동하여 나중에 복원할 수 있다","휴지통에 들어 있는 파일은 디스크 공간을 차지하지 않으므로 용량 확보에 도움이 된다","Shift+Delete 로 삭제한 파일은 휴지통을 거치지 않고 바로 지워진다"],"answer":3,"explain":"Shift+Delete 는 휴지통을 거치지 않고 영구 삭제한다. 휴지통이 가득 차면 오래된 파일부터 자동으로 지워지고, 네트워크 드라이브의 파일은 휴지통을 거치지 않으며, 휴지통 안의 파일도 디스크 공간을 차지한다."},{"id":"pc-0312","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"현재 로그인한 계정의 열린 앱과 작업을 그대로 둔 채 다른 사용자 계정으로 로그인하는 기능은?","options":["로그아웃(앱 종료)","사용자 전환","잠금(Win+L)","다시 시작(재부팅)"],"answer":1,"explain":"사용자 전환은 현재 계정의 세션을 유지한다. 로그아웃은 현재 계정의 앱을 모두 종료한다."},{"id":"pc-0313","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"수표나 어음 아래쪽에 자성 잉크로 인쇄된 숫자·기호를 읽어 들이는 입력 장치는?","options":["OCR(광학 문자 판독기)","바코드 판독기","디지타이저(좌표 입력 장치)","MICR(자기 잉크 문자 판독기)"],"answer":3,"explain":"MICR은 자성 잉크 문자를 읽어 금융 업무에 쓴다. OCR은 인쇄·필기된 문자를 빛으로 읽는다."},{"id":"pc-0314","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"정답(레이블)이 있는 데이터를 학습시켜 새로운 데이터의 결과를 예측하는 머신러닝 방식은?","options":["비지도 학습","강화 학습","지도 학습","전이 학습"],"answer":2,"explain":"지도 학습은 입력과 정답 쌍으로 학습한다. 비지도 학습은 정답 없이 구조를 찾는다."},{"id":"pc-0315","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"그래픽 카드나 확장 카드를 메인보드에 꽂는 고속 직렬 확장 슬롯 규격은?","options":["PCI Express","DIMM(메모리 슬롯)","SATA(저장 장치 인터페이스)","PS/2(키보드·마우스 포트)"],"answer":0,"explain":"PCI Express(PCIe)는 확장 카드용 슬롯이다. DIMM은 메모리 슬롯이다."},{"id":"pc-0316","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"프린터 해상도 단위인 DPI의 의미는?","options":["1분당 인쇄되는 쪽수","1인치당 인쇄되는 점(Dot)의 수","1초당 인쇄되는 글자 수","이미지의 가로와 세로 비율"],"answer":1,"explain":"DPI는 점의 밀도로 클수록 선명하다. 1분당 쪽수는 PPM이다."},{"id":"pc-0317","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"[빠른 포맷]에 관한 설명으로 옳은 것은?","options":["디스크 표면 검사 없이 파일 시스템 구조만 새로 만들어 빨리 끝난다","디스크의 모든 섹터를 하나하나 검사하므로 시간이 오래 걸린다","포맷하는 동안에는 파일 시스템의 종류를 다른 것으로 바꿀 수 없다","사용 중인 시스템 드라이브(C:)도 Windows 실행 중에 곧바로 포맷할 수 있다"],"answer":0,"explain":"빠른 포맷은 배드 섹터 검사를 생략한다. 모든 섹터를 검사하는 것은 빠른 포맷 옵션을 끈 포맷이며, 실행 중인 시스템 드라이브는 포맷할 수 없다."},{"id":"pc-0318","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"DDR SDRAM에 관한 설명으로 옳은 것은?","options":["클럭의 상승·하강 구간 모두에서 데이터를 전송해 SDR보다 전송량이 두 배이다","클럭 신호가 한 번 뛸 때마다 데이터를 한 번씩만 전송하는 방식이다","전원이 꺼져도 저장된 내용이 지워지지 않고 계속 유지되는 비휘발성 메모리이다","SRAM 계열의 메모리여서 주기적인 재충전 없이도 내용이 유지된다"],"answer":0,"explain":"DDR은 Double Data Rate의 약자로 클럭 한 주기에 두 번 전송한다. SDRAM은 DRAM 계열이라 전원이 꺼지면 내용이 사라진다."},{"id":"pc-0319","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"창 맞춤·배치 관련 바로 가기 키의 설명으로 옳지 않은 것은?","options":["Win+↓: 선택한 창을 최대화한다","Win+↑: 창을 최대화한다","Win+←: 창을 화면 왼쪽 절반에 맞춘다","Win+Home: 활성 창만 남기고 나머지 창을 최소화한다"],"answer":0,"explain":"Win+↓는 최대화된 창을 원래 크기로 되돌리고, 한 번 더 누르면 최소화한다. 최대화는 Win+↑이다."},{"id":"pc-0320","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"가상 현실(VR), 증강 현실(AR), 혼합 현실(MR)을 아우르는 용어는?","options":["XR(확장 현실)","IoT(사물 인터넷)","ICT(정보 통신 기술)","NFT(대체 불가능 토큰)"],"answer":0,"explain":"XR은 현실과 가상을 섞는 기술의 총칭이다."},{"id":"pc-0321","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"[디스크 관리]에서 기존 볼륨의 남는 공간을 줄여 새 파티션을 만들 수 있는 '할당되지 않은 공간'을 확보하는 기능은?","options":["볼륨 삭제","볼륨 확장","볼륨 축소","드라이브 문자 및 경로 변경"],"answer":2,"explain":"볼륨 축소는 데이터를 유지한 채 볼륨 크기를 줄인다. 볼륨 삭제는 데이터가 사라진다."},{"id":"pc-0322","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"다음 중 손실 압축 방식의 오디오 형식은?","options":["MP3","WAV","FLAC","AIFF"],"answer":0,"explain":"MP3는 사람이 듣기 어려운 소리를 덜어 내는 손실 압축이다. WAV·AIFF는 비압축, FLAC은 무손실 압축이다."},{"id":"pc-0323","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"화면 전체를 캡처하여 [사진] 폴더 아래 [스크린샷] 폴더에 PNG 파일로 곧바로 저장하는 바로 가기 키는?","options":["Win+PrtSc","Alt+PrtSc","Ctrl+PrtSc","Shift+PrtSc"],"answer":0,"explain":"Win+PrtSc는 파일로 저장한다. PrtSc 단독이나 Alt+PrtSc(활성 창)는 클립보드에만 복사한다."},{"id":"pc-0324","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"16진수 A5를 2진수로 바꾼 값은?","options":["10100110","01011010","10100101","11000101"],"answer":2,"explain":"A=1010, 5=0101이므로 10100101이다."},{"id":"pc-0325","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"버스에 관한 설명으로 옳지 않은 것은?","options":["주소 버스는 CPU와 메모리 사이에서 양방향으로 주소를 전달한다","데이터 버스는 데이터를 양방향으로 전송한다","제어 버스는 읽기·쓰기나 인터럽트 같은 제어 신호를 전달한다","데이터 버스의 폭이 넓을수록 한 번에 더 많은 데이터를 보낼 수 있다"],"answer":0,"explain":"주소는 CPU가 메모리로 내보내기만 하므로 주소 버스는 단방향이다."},{"id":"pc-0326","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows의 파일 이름에 관한 설명으로 옳은 것은?","options":["대소문자를 그대로 보존해 저장하지만 같은 폴더에 대소문자만 다른 이름은 만들 수 없다","이름에 공백 문자를 포함할 수 없으며 공백 대신 밑줄을 써야 한다","이름에 마침표(.)는 한 번만 사용할 수 있으며 두 번째부터는 오류가 난다","확장자가 서로 달라도 같은 폴더 안에서는 이름이 같은 파일을 둘 수 없다"],"answer":0,"explain":"기본 설정에서 Windows는 대소문자를 보존하되 구분하지는 않는다. 공백과 여러 개의 마침표는 쓸 수 있고, 확장자가 다르면 이름이 같아도 된다."},{"id":"pc-0327","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"전자 서명 방식에 관한 설명으로 옳은 것은?","options":["송신자가 자신의 공개키로 서명하고 수신자가 송신자의 개인키로 검증한다","송신자가 수신자의 공개키로 서명하고 수신자가 자신의 개인키로 검증한다","송신자와 수신자가 같은 대칭키 하나로 서명하고 같은 키로 검증한다","송신자가 자신의 개인키로 서명하고 수신자는 송신자의 공개키로 검증한다"],"answer":3,"explain":"서명은 본인만 가진 개인키로 하고 누구나 가진 공개키로 검증하므로 부인 방지가 된다."},{"id":"pc-0328","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"생성형 AI에 원하는 결과를 얻기 위해 입력하는 질문이나 지시문을 무엇이라 하는가?","options":["펌웨어","파라미터","프롬프트","캐시"],"answer":2,"explain":"프롬프트는 AI에게 주는 지시이다. 표현을 구체적으로 쓸수록 원하는 결과에 가까워진다."},{"id":"pc-0329","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"화면의 텍스트와 요소를 소리 내어 읽어 주어 시각 장애인이 컴퓨터를 쓸 수 있게 돕는 접근성 기능은?","options":["돋보기","내레이터","화상 키보드","고대비"],"answer":1,"explain":"내레이터는 화면 읽기 기능이다. 돋보기는 확대, 화상 키보드는 마우스나 터치로 글자를 입력하는 기능이다."},{"id":"pc-0330","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"논리 연산 XOR(배타적 논리합)에 관한 설명으로 옳은 것은?","options":["두 입력이 모두 1일 때만 결과가 1이다","두 입력이 같을 때만 결과가 1이다","두 입력이 서로 다를 때만 결과가 1이다","입력 하나를 반대로 바꾼다"],"answer":2,"explain":"XOR은 서로 다르면 1이다. 모두 1일 때만 1인 것은 AND, 같을 때 1인 것은 XNOR, 반대로 바꾸는 것은 NOT이다."},{"id":"pc-0331","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"하드 디스크의 접근 시간을 구성하는 요소를 바르게 나타낸 것은?","options":["탐색 시간 + 대기 시간 + 반환 시간 + 응답 시간","회전 지연 시간 + 클럭 시간 + 인출 시간","탐색 시간 + 인출 시간 + 해독 시간 + 실행 시간","탐색 시간 + 회전 지연 시간 + 데이터 전송 시간"],"answer":3,"explain":"헤드를 옮기고(탐색), 원판이 돌아 섹터가 오기를 기다린 뒤(회전 지연), 데이터를 읽어 전송한다."},{"id":"pc-0332","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"RAID 0에 관한 설명으로 옳은 것은?","options":["패리티 정보를 여러 디스크에 분산 저장하여 디스크 한 개가 고장 나도 데이터를 복구할 수 있다","같은 데이터를 두 개의 디스크에 똑같이 기록하여 한쪽이 고장 나도 다른 쪽으로 계속 사용한다","여러 디스크에 나누어 기록해 속도는 빠르지만 중복이 없어 디스크 하나가 고장 나면 데이터를 잃는다","디스크 두 개가 동시에 고장 나더라도 남은 디스크의 정보로 데이터를 복구할 수 있다"],"answer":2,"explain":"RAID 0은 스트라이핑으로 성능을 높이는 대신 안전성이 없다. 이중 기록은 RAID 1, 패리티 분산은 RAID 5이다."},{"id":"pc-0333","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"클라이언트를 대신하여 인터넷 요청을 전달하고 응답을 보관(캐시)하거나 접근을 통제하는 중계 서버는?","options":["DNS 서버","DHCP 서버","웹 서버","프록시 서버"],"answer":3,"explain":"프록시 서버는 클라이언트와 목적지 사이에서 중계한다."},{"id":"pc-0334","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"전원 공급 장치(파워 서플라이)의 역할로 옳은 것은?","options":["직류 전원을 교류 전원으로 바꾸어 PC 안의 각 부품에 공급하는 장치이다","부품에서 발생하는 열을 흡수하여 케이스 밖으로 내보내는 냉각 장치이다","교류(AC) 전원을 PC 부품에 맞는 직류(DC) 전압으로 바꾸어 공급한다","정전이 되면 작업 중인 데이터를 디스크에 자동으로 백업해 주는 장치이다"],"answer":2,"explain":"컴퓨터 부품은 직류로 동작하므로 파워 서플라이가 변환한다. 열을 식히는 것은 쿨러의 일이다."},{"id":"pc-0335","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"생성형 AI가 사실이 아닌 내용을 그럴듯하게 만들어 내는 현상을 가리키는 용어는?","options":["과적합(Overfitting)","환각(Hallucination)","병목 현상","스푸핑"],"answer":1,"explain":"환각은 사실과 다른 답을 자신 있게 내놓는 현상이다. 과적합은 학습 데이터에만 지나치게 맞춰지는 현상이다."},{"id":"pc-0336","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"캐시 메모리의 효과를 뒷받침하는 '지역성'에 관한 설명으로 옳은 것은?","options":["공간 지역성은 서로 멀리 떨어진 주소를 번갈아 가며 접근하는 경향을 뜻한다","시간 지역성은 접근 시간이 짧은 메모리 장치만 골라서 접근하는 경향을 뜻한다","지역성은 사용자가 지리적으로 가까운 곳에 있는 서버에 접속하는 경향을 뜻한다","시간 지역성은 한 번 접근한 데이터를 가까운 시간 안에 다시 접근하는 경향이다"],"answer":3,"explain":"시간 지역성과 공간 지역성(가까운 주소를 이어서 접근) 덕분에 자주 쓰는 데이터를 캐시에 두면 효과가 크다."},{"id":"pc-0337","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"해시 함수에 관한 설명으로 옳은 것은?","options":["임의 길이 입력을 고정 길이 값으로 바꾸는 일방향 함수로 무결성 검증에 쓰인다","키를 이용하면 해시값으로부터 원래의 입력 내용을 그대로 복원할 수 있다","입력 내용이 조금 바뀌어도 해시값은 항상 같게 나오므로 변조를 알 수 없다","공개키와 개인키 한 쌍을 사용하여 암호화하고 복호화하는 방식이다"],"answer":0,"explain":"해시는 되돌릴 수 없고 입력이 달라지면 값이 크게 달라져 위·변조를 확인할 수 있다."},{"id":"pc-0338","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"도메인 이름 www.mois.go.kr에서 'go.kr'이 나타내는 것은?","options":["대학 등 교육 기관","영리 기업","정부 기관","네트워크 서비스 기관"],"answer":2,"explain":"go.kr은 정부 기관, ac.kr은 대학, co.kr은 기업이다."},{"id":"pc-0339","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows 11 [설정] 앱에서 Wi-Fi·이더넷·VPN·모바일 핫스팟·비행기 모드를 설정하는 범주는?","options":["시스템","네트워크 및 인터넷","Bluetooth 및 장치","개인 설정"],"answer":1,"explain":"연결 방식과 관련된 설정은 [네트워크 및 인터넷]에 모여 있다. [Bluetooth 및 장치]는 프린터·마우스·Bluetooth 장치를 다룬다."},{"id":"pc-0340","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"가능한 모든 비밀번호 조합을 차례로 시도하여 암호를 알아내려는 공격은?","options":["스니핑(Sniffing, 패킷 엿보기)","스푸핑(Spoofing, 주소 위조)","파밍(Pharming, 가짜 사이트 유도)","무차별 대입 공격(Brute Force)"],"answer":3,"explain":"무차별 대입은 조합을 모두 시도한다. 계정 잠금과 긴 비밀번호가 대응책이다."},{"id":"pc-0341","subject":"computer","levels":["c1"],"topic":"소프트웨어","q":"객체의 데이터와 이를 처리하는 메서드를 하나로 묶고 내부 구현을 감추는 객체 지향의 특징은?","options":["상속","다형성","캡슐화","모듈화"],"answer":2,"explain":"캡슐화는 묶고 숨긴다. 상속은 상위 클래스의 속성·메서드를 물려받는 것이고, 다형성은 같은 이름의 메서드가 다르게 동작하는 것이다."},{"id":"pc-0342","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"특정 프로세스의 우선 순위를 바꾸거나 사용할 CPU 코어를 지정(선호도 설정)할 수 있는 작업 관리자의 탭은?","options":["성능(사용률 그래프)","세부 정보","앱 기록(누적 사용량)","사용자(계정별 사용량)"],"answer":1,"explain":"[세부 정보] 탭에서 PID를 확인하고 프로세스를 마우스 오른쪽 단추로 눌러 우선 순위와 선호도를 설정한다."},{"id":"pc-0343","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"소리를 디지털로 바꿀 때 샘플링 주파수를 높이면 나타나는 변화로 옳은 것은?","options":["음질은 나빠지고 파일 용량은 오히려 더 커지게 된다","원음에 가까운 음질을 얻지만 파일 용량이 커진다","파일 용량은 줄어들지만 음질은 원음에 가까워져 좋아진다","파일 용량은 변하지 않으며 음질만 원음보다 나빠지게 된다"],"answer":1,"explain":"1초에 더 많이 표본을 뽑을수록 원음에 가깝지만 데이터 양도 늘어난다."},{"id":"pc-0344","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"여러 사용자가 CPU 시간을 아주 짧은 단위로 나누어 번갈아 쓰게 하여 각자 컴퓨터를 독점하는 것처럼 느끼게 하는 운영 방식은?","options":["일괄 처리 시스템","실시간 처리 시스템","시분할 시스템","분산 처리 시스템"],"answer":2,"explain":"시분할 시스템은 CPU를 시간 조각(Time Slice)으로 나눠 쓴다. 일괄 처리는 모아 두었다가 한꺼번에 처리하는 방식이다."},{"id":"pc-0345","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"앱이 카메라·마이크·위치 정보에 접근하는 것을 허용하거나 차단하는 [설정] 범주는?","options":["접근성 (화면 읽기·돋보기 설정)","앱 (기본 앱·시작 프로그램 설정)","시스템 (알림·전원 설정)","개인 정보 및 보안"],"answer":3,"explain":"앱 권한은 [개인 정보 및 보안](Windows 10은 [개인 정보])에서 항목별로 관리한다."},{"id":"pc-0346","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"레이저 프린터에 관한 설명으로 옳은 것은?","options":["미세한 노즐로 잉크를 종이에 분사하는 방식으로 인쇄하는 비충격식 프린터이다","감광 드럼에 토너를 정전기로 붙인 뒤 열로 정착시켜 한 페이지씩 인쇄한다","핀이 잉크 리본을 두드려 인쇄하므로 먹지를 이용한 복사 전표 인쇄에 적합하다","열을 가하면 색이 변하는 감열지를 사용하여 영수증 출력에 주로 쓰인다"],"answer":1,"explain":"레이저 프린터는 드럼·토너·정착 과정을 쓰는 페이지 프린터이다. 노즐 분사는 잉크젯, 핀 타격은 도트 매트릭스 프린터이다."},{"id":"pc-0347","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 보기(Task View)를 열어 실행 중인 창과 가상 데스크톱을 한눈에 보여 주는 바로 가기 키는?","options":["Alt+Esc","Ctrl+Esc","Win+Home","Win+Tab"],"answer":3,"explain":"Win+Tab이 작업 보기를 연다. Alt+Esc는 창을 순서대로 전환할 뿐 축소판을 보여 주지 않고, Ctrl+Esc는 시작 메뉴를 연다."},{"id":"pc-0348","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 11에서 Wi-Fi·Bluetooth·밝기·소리를 빠르게 켜고 끄는 빠른 설정 패널을 여는 바로 가기 키는?","options":["Win+N","Win+W","Win+S","Win+A"],"answer":3,"explain":"Win+A가 빠른 설정을 연다. Win+N은 알림 센터, Win+W는 위젯, Win+S는 검색이다."},{"id":"pc-0349","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"양자 컴퓨터에서 0과 1을 동시에 가질 수 있는(중첩) 정보의 기본 단위는?","options":["비트(Bit)","큐비트(Qubit)","바이트(Byte)","니블(Nibble)"],"answer":1,"explain":"큐비트는 중첩과 얽힘을 이용한다. 비트는 0 또는 1 중 하나만 가진다."},{"id":"pc-0350","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 관리자에서 앱별로 일정 기간 누적된 CPU 시간과 네트워크 사용량을 확인할 수 있는 탭은?","options":["프로세스","앱 기록","시작 앱","서비스"],"answer":1,"explain":"[앱 기록] 탭은 기록이 시작된 뒤의 누적 사용량을 보여 준다. [프로세스] 탭은 현재 사용률을 보여 준다."},{"id":"pc-0351","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"HTTP 응답 상태 코드 404의 의미는?","options":["요청이 성공적으로 처리됨","요청한 페이지를 찾을 수 없음","서버 내부에서 오류가 발생함","접근 권한이 없어 거부됨"],"answer":1,"explain":"404는 Not Found이다. 200은 성공, 500은 서버 내부 오류, 403은 접근 거부이다."},{"id":"pc-0352","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"저작권은 개발자가 가지고 있지만 누구나 무료로 사용할 수 있도록 배포되는 소프트웨어는?","options":["셰어웨어","상용 소프트웨어","프리웨어","데모 버전"],"answer":2,"explain":"프리웨어는 무료이나 저작권은 유지된다. 셰어웨어는 일정 기간 뒤 구입을 요구한다."},{"id":"pc-0353","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"활성 창의 조절 메뉴(복원·이동·크기 조정·최소화·최대화·닫기)를 여는 바로 가기 키는?","options":["Alt+Space","Ctrl+Esc","Win+Space","Alt+Esc"],"answer":0,"explain":"Alt+Space가 창 조절 메뉴를 연다. Win+Space는 입력 언어 전환, Ctrl+Esc는 시작 메뉴이다."},{"id":"pc-0354","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[설정]-[시스템]-[저장소]의 저장소 센스 기능은?","options":["드라이브에 흩어진 파일 조각을 모아 읽기 속도를 높여 주는 기능이다","개인 파일을 외부 드라이브에 주기적으로 백업해 주는 기능이다","컴퓨터를 검사하여 악성 코드를 찾아 치료해 주는 보안 기능이다","임시 파일과 휴지통 파일을 자동으로 정리해 저장 공간을 확보한다"],"answer":3,"explain":"저장소 센스는 불필요한 파일을 자동으로 지우는 기능이다. 조각 모음은 [드라이브 최적화]의 역할이다."},{"id":"pc-0355","subject":"computer","levels":["c2","c1"],"topic":"자료 표현","q":"2진수 1100과 1010을 AND 연산한 결과는?","options":["1000","1110","0110","0011"],"answer":0,"explain":"AND는 두 비트가 모두 1일 때만 1이므로 1000이다. 1110은 OR, 0110은 XOR의 결과이다."},{"id":"pc-0356","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"컴파일러에 관한 설명으로 옳지 않은 것은?","options":["원시 프로그램 전체를 한꺼번에 번역하여 목적 프로그램을 생성하는 번역기이다","한 번 번역해 둔 목적 프로그램은 다시 번역하지 않고 반복해서 실행할 수 있다","C, C++ 등의 언어가 대표적으로 이 방식으로 번역되어 실행 파일이 만들어진다","프로그램을 한 줄씩 번역하며 바로 실행하므로 오류가 있는 줄에서 멈춘다"],"answer":3,"explain":"한 줄씩 번역하며 실행하는 것은 인터프리터이다. 컴파일러는 번역과 실행이 분리되어 있다."},{"id":"pc-0357","subject":"computer","levels":["c1"],"topic":"운영체제","q":"페이지 프레임이 3개이고 페이지 참조 순서가 1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5일 때 FIFO 교체 방식에서 발생하는 페이지 부재(Page Fault) 횟수는?","options":["7회","9회","8회","10회"],"answer":1,"explain":"FIFO로 따라가 보면 부재는 1,2,3,4,1,2,5,3,4(9번째)에서 발생하며 모두 9회이다."},{"id":"pc-0358","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"주소 버스가 32비트인 CPU가 직접 지정할 수 있는 최대 메모리 주소 공간은?","options":["2GB","8GB","4GB","16GB"],"answer":2,"explain":"2의 32제곱 바이트는 4GB이다. 이 한계 때문에 4GB를 넘는 RAM을 쓰려면 64비트 환경이 필요하다."},{"id":"pc-0359","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"접근성 기능에 관한 설명으로 옳은 것은?","options":["고정 키는 키를 길게 눌러도 반복 입력이 되지 않게 한다","필터 키는 짧거나 반복되는 키 입력을 무시하도록 한다","내레이터는 화면의 일부를 확대해 보여 주는 기능이다","고대비는 마우스를 움직일 때 소리가 나게 한다"],"answer":1,"explain":"필터 키가 짧은 입력과 반복 입력을 무시한다. 고정 키는 Ctrl·Alt·Shift를 한 번에 하나씩 눌러도 조합이 되게 하는 기능이다."},{"id":"pc-0360","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 복구 설정의 [이 PC 초기화]에 관한 설명으로 옳은 것은?","options":["복원 지점을 골라 설치된 앱과 레지스트리를 이전 상태로 되돌리되 개인 파일은 건드리지 않는다","외부 드라이브에 개인 파일의 이전 버전을 주기적으로 백업하여 필요할 때 되돌린다","개인 파일을 유지하거나 모두 제거하는 옵션을 골라 Windows를 다시 설치할 수 있다","BIOS·UEFI 설정을 공장 출하 때의 초기값으로 되돌리고 부팅 순서를 다시 정한다"],"answer":2,"explain":"이 PC 초기화는 Windows를 새로 설치하는 기능이다. 복원 지점은 시스템 복원, 이전 버전 백업은 파일 히스토리의 역할이다."},{"id":"pc-0361","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"웹 서버에서 실행되어 그 결과를 HTML로 만들어 브라우저에 보내는 서버 측 스크립트 언어는?","options":["CSS","HTML","XML","PHP"],"answer":3,"explain":"PHP·JSP·ASP는 서버에서 실행된다. CSS·HTML·XML은 문서의 표현이나 구조를 기술하는 언어이다."},{"id":"pc-0362","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"운영체제의 기능으로 옳지 않은 것은?","options":["CPU·메모리·입출력 장치 같은 자원을 관리한다","사용자와 하드웨어 사이의 인터페이스를 제공한다","사용자가 작성한 원시 프로그램을 기계어로 번역한다","파일과 디렉터리를 관리한다"],"answer":2,"explain":"원시 프로그램을 기계어로 번역하는 것은 컴파일러 같은 언어 번역 프로그램의 일이다."},{"id":"pc-0363","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기에서 현재 선택된 항목은 해제하고, 선택되지 않은 항목은 선택하는 기능은?","options":["모두 선택(전체 선택)","선택 안 함(선택 해제)","선택 영역 반전","항목 확인란(체크박스 표시)"],"answer":2,"explain":"선택 영역 반전은 선택 상태를 뒤집는다. 모두 선택은 전부 선택하고, 선택 안 함은 전부 해제한다."},{"id":"pc-0364","subject":"computer","levels":["c1"],"topic":"운영체제","q":"MBR과 GPT 파티션 방식에 관한 설명으로 옳지 않은 것은?","options":["MBR 방식은 2TB를 넘는 영역을 쓸 수 없다","UEFI 방식 부팅은 GPT 디스크와 함께 쓴다","GPT는 파티션 정보의 복사본을 디스크 끝에도 두어 손상에 강하다","GPT 디스크는 기본 파티션을 최대 4개까지만 만들 수 있다"],"answer":3,"explain":"기본 파티션이 4개로 제한되는 쪽은 MBR이다. Windows는 GPT에서 최대 128개의 파티션을 지원한다."},{"id":"pc-0365","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"8비트 2의 보수 방식으로 표현할 수 있는 수의 범위는?","options":["-127 ~ +127","-128 ~ +127","-128 ~ +128","0 ~ 255"],"answer":1,"explain":"2의 보수는 음수 쪽에 하나 더 표현할 수 있다. 부호와 절대치 방식이나 1의 보수는 -127~+127이다."},{"id":"pc-0366","subject":"computer","levels":["c2","c1"],"topic":"정보 보안","q":"비밀번호(지식)와 휴대폰으로 받은 OTP(소유)처럼 서로 다른 종류의 인증 수단을 둘 이상 조합하는 인증 방식은?","options":["단일 로그인(SSO, Single Sign-On)","생체 인증(지문·홍채 등)","전자 서명(공개키 기반)","다중 요소 인증(MFA)"],"answer":3,"explain":"다중 요소 인증은 지식·소유·생체 중 서로 다른 요소를 조합한다. SSO는 한 번 로그인으로 여러 서비스를 이용하는 방식이다."},{"id":"pc-0367","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일 탐색기에서 파일을 열지 않고 선택한 파일의 내용을 오른쪽에 보여 주는 미리 보기 창을 켜고 끄는 바로 가기 키는?","options":["Alt+Shift+P","Ctrl+P","Alt+Enter","Alt+P"],"answer":3,"explain":"Alt+P는 미리 보기 창, Alt+Shift+P는 세부 정보 창이다. Ctrl+P는 인쇄, Alt+Enter는 속성이다."},{"id":"pc-0368","subject":"computer","levels":["c1"],"topic":"운영체제","q":"프로세스가 실제 작업보다 페이지 교체에 더 많은 시간을 써서 시스템 성능이 급격히 떨어지는 현상은?","options":["단편화(Fragmentation)","교착 상태(Deadlock)","스래싱(Thrashing)","오버플로(Overflow)"],"answer":2,"explain":"스래싱은 페이지 부재가 지나치게 잦아 CPU가 놀게 되는 현상이다. 단편화는 메모리가 조각나 낭비되는 현상이다."},{"id":"pc-0369","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows 11에서 알림 배너와 소리를 일시적으로 끄는 기능의 이름은?","options":["방해 금지","비행기 모드","야간 모드","절전 모드"],"answer":0,"explain":"방해 금지(Windows 10의 집중 지원)는 발표나 집중이 필요할 때 알림을 숨긴다. 비행기 모드는 무선 통신을 끈다."},{"id":"pc-0370","subject":"computer","levels":["c1"],"topic":"운영체제","q":"UNIX 운영체제에 관한 설명으로 옳지 않은 것은?","options":["다중 사용자·다중 작업을 지원한다","대부분 C 언어로 작성되어 이식성이 높다","특정 하드웨어에서만 동작하도록 어셈블리어로만 작성되었다","파일을 계층 구조(트리)로 관리한다"],"answer":2,"explain":"UNIX는 대부분 C 언어로 다시 작성되어 여러 하드웨어로 옮기기 쉽다."},{"id":"pc-0371","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"불 대수식 A + A·B를 간단히 한 결과는?","options":["B","A·B","A","A + B"],"answer":2,"explain":"흡수 법칙에 따라 A+A·B = A·(1+B) = A이다."},{"id":"pc-0372","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"Windows 11 파일 탐색기에서 즐겨찾기·최근 파일을 보여 주는 첫 화면의 이름은?","options":["내 PC","홈","라이브러리","네트워크"],"answer":1,"explain":"Windows 11은 예전의 빠른 액세스 자리에 [홈]을 둔다. [내 PC]는 드라이브와 장치를 보여 준다."},{"id":"pc-0373","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"명령 프롬프트(cmd)의 명령과 기능의 연결로 옳지 않은 것은?","options":["dir: 현재 폴더의 파일과 폴더 목록 표시","cls: 현재 폴더의 파일과 폴더 목록 표시","md(mkdir): 새 폴더 만들기","ren: 파일 이름 바꾸기"],"answer":1,"explain":"cls는 화면을 지우는 명령이다. 목록을 보여 주는 명령은 dir이다."},{"id":"pc-0374","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"가상 데스크톱에서 새 데스크톱을 만들고 곧바로 그 데스크톱으로 전환하는 바로 가기 키는?","options":["Win+Ctrl+N","Win+Alt+D","Win+Ctrl+D","Win+Ctrl+Enter"],"answer":2,"explain":"Win+Ctrl+D는 새 가상 데스크톱을 만든다. Win+Ctrl+Enter는 내레이터를 켜는 키이다."},{"id":"pc-0375","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[제어판]의 항목과 기능의 연결로 옳지 않은 것은?","options":["프로그램 및 기능 - 마우스 포인터의 속도 변경","프로그램 및 기능 - 설치된 프로그램의 제거와 변경","장치 및 프린터 - 프린터 추가와 기본 프린터 지정","네트워크 및 공유 센터 - 네트워크 상태 확인과 어댑터 설정 변경"],"answer":0,"explain":"마우스 포인터 속도는 [마우스] 항목에서 바꾼다."},{"id":"pc-0376","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"기능이나 사용 기간을 제한하여 제품을 체험·홍보하려고 배포하는 소프트웨어 버전은?","options":["알파 버전(개발사 내부 시험용)","업그레이드(상위 버전 교체)","패치(오류 수정 파일)","데모(체험판) 버전"],"answer":3,"explain":"데모 버전은 일부 기능이나 기간을 제한한 체험용이다. 알파 버전은 개발사 내부 시험용이다."},{"id":"pc-0377","subject":"computer","levels":["c2","c1"],"topic":"소프트웨어","q":"운영체제가 하드웨어 장치를 제어할 수 있도록 장치별로 설치하는 소프트웨어는?","options":["장치 드라이버","유틸리티(편의 프로그램)","미들웨어(중간 연결)","그룹웨어(협업 프로그램)"],"answer":0,"explain":"장치 드라이버는 운영체제와 장치 사이의 통역 역할을 한다. 유틸리티는 컴퓨터 사용을 돕는 작은 프로그램이다."},{"id":"pc-0378","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"무선 랜 보안 방식 중 보안성이 가장 낮아 더 이상 권장되지 않는 것은?","options":["WEP","WPA","WPA2","WPA3"],"answer":0,"explain":"WEP는 암호가 쉽게 풀린다. 보안성은 WEP < WPA < WPA2 < WPA3 순이다."},{"id":"pc-0379","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"8비트 1의 보수 방식에서 10진수 -6을 나타낸 것은?","options":["11111001","11111010","10000110","00000110"],"answer":0,"explain":"+6은 00000110이고 각 비트를 뒤집으면 11111001이다. 11111010은 2의 보수, 10000110은 부호와 절대치 표현이다."},{"id":"pc-0380","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"화면 해상도가 1920×1080일 때 전체 화소(픽셀) 수는?","options":["2,592,000개","2,073,600개","1,555,200개","3,686,400개"],"answer":1,"explain":"1920×1080 = 2,073,600이다. 3,686,400은 2560×1440(QHD)의 화소 수이다."},{"id":"pc-0381","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"서버나 클라우드를 거치지 않고 스마트폰 같은 기기 자체에서 AI 연산을 처리하는 방식은?","options":["클라우드 AI(서버에서 연산)","온디바이스 AI","그리드 컴퓨팅(분산 연산)","분산 원장(블록체인)"],"answer":1,"explain":"온디바이스 AI는 기기 안에서 처리하므로 응답이 빠르고 데이터가 밖으로 나가지 않는다."},{"id":"pc-0382","subject":"computer","levels":["c1"],"topic":"운영체제","q":"HRN 스케줄링의 우선순위는 (대기 시간 + 서비스 시간) ÷ 서비스 시간이다. 프로세스 A(대기 6, 서비스 2), B(대기 10, 서비스 5), C(대기 4, 서비스 1), D(대기 9, 서비스 3) 중 가장 먼저 실행되는 것은?","options":["A","B","C","D"],"answer":2,"explain":"우선순위는 A=4, B=3, C=5, D=4이므로 값이 가장 큰 C가 먼저 실행된다."},{"id":"pc-0383","subject":"computer","levels":["c2","c1"],"topic":"하드웨어","q":"다음 중 입력 장치가 아닌 것은?","options":["스캐너","디지타이저","플로터","터치 패드"],"answer":2,"explain":"플로터는 도면을 출력하는 출력 장치이다. 디지타이저는 좌표를 입력하는 장치이다."},{"id":"pc-0384","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"여러 모니터를 쓸 때 활성 창을 다른 모니터로 옮기는 바로 가기 키는?","options":["Win+Shift+←/→","Win+Ctrl+←/→","Win+Tab (작업 보기)","Win+P (화면 투영)"],"answer":0,"explain":"Win+Shift+←/→가 창을 옆 모니터로 보낸다. Win+Ctrl+←/→는 가상 데스크톱 전환, Win+P는 화면 투영 방식 선택이다."},{"id":"pc-0385","subject":"computer","levels":["c1"],"topic":"운영체제","q":"여러 대의 컴퓨터를 네트워크로 연결해 작업을 나누어 처리하고 결과를 합치는 운영 방식은?","options":["다중 처리 시스템","다중 프로그래밍 시스템","일괄 처리 시스템","분산 처리 시스템"],"answer":3,"explain":"분산 처리는 여러 컴퓨터에 작업을 나눈다. 다중 처리는 한 시스템 안에 CPU가 여러 개 있는 구조이다."},{"id":"pc-0386","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"작업 관리자의 [성능] 탭에서 확인할 수 있는 정보로 옳지 않은 것은?","options":["로그인할 때 자동 실행되는 앱의 목록과 사용 안 함 설정","CPU의 사용률과 현재 클럭 속도, 코어 수 같은 프로세서 정보","메모리의 사용량과 사용 가능한 용량, 속도 같은 메모리 정보","디스크와 이더넷(네트워크)의 사용률과 전송 속도 같은 장치 정보"],"answer":0,"explain":"시작 프로그램의 사용 여부는 [시작 앱] 탭(Windows 10은 [시작프로그램] 탭)에서 관리한다. [성능] 탭은 CPU·메모리·디스크·네트워크·GPU 사용 현황을 보여 준다."},{"id":"pc-0387","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"원격 컴퓨터에 접속할 때 통신 내용을 암호화하여 Telnet의 보안 약점을 보완한 프로토콜은?","options":["Telnet","SSH","FTP","SMTP"],"answer":1,"explain":"SSH는 22번 포트를 쓰며 원격 접속 구간을 암호화한다. Telnet은 평문으로 주고받는다."},{"id":"pc-0388","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"추가 정보 없이는 특정 개인을 알아볼 수 없도록 개인정보의 일부를 다른 값으로 대체하는 처리는?","options":["파기(복구할 수 없게 삭제)","가명 처리","열람(조회)","위탁(처리를 맡김)"],"answer":1,"explain":"가명 처리는 별도 정보를 결합해야 식별할 수 있게 하는 처리이다. 통계·연구 목적에 활용할 수 있다."},{"id":"pc-0389","subject":"computer","levels":["c2","c1"],"topic":"최신 기술","q":"5G 이동통신의 특징으로 옳은 것은?","options":["4G LTE보다 속도는 느리지만 통신 가능 지역이 훨씬 넓다는 점이 특징이다","지연 시간이 4G보다 길어 원격 수술 같은 실시간 서비스에는 불리하다","음성 통화만 지원하며 데이터 통신 서비스는 제공하지 않는 규격이다","초고속·초저지연·초연결이 특징이며 이론상 최대 20Gbps의 속도를 낸다"],"answer":3,"explain":"5G는 4G보다 빠르고 지연이 짧으며 많은 기기를 동시에 연결한다."},{"id":"pc-0390","subject":"computer","levels":["c2","c1"],"topic":"멀티미디어","q":"동영상에서 1초 동안 보여 주는 정지 화면(프레임)의 수를 나타내는 단위는?","options":["fps","dpi","bps","ppm"],"answer":0,"explain":"fps는 초당 프레임 수이다. dpi는 인치당 점 수, bps는 초당 비트 수, ppm은 분당 인쇄 쪽수이다."},{"id":"pc-0391","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"IPv4 주소의 첫 번째 옥텟이 128~191이고 기본 서브넷 마스크가 255.255.0.0인 주소 클래스는?","options":["B 클래스","A 클래스","C 클래스","D 클래스"],"answer":0,"explain":"A 클래스는 1~126, B 클래스는 128~191, C 클래스는 192~223이다. D 클래스는 멀티캐스트용이다."},{"id":"pc-0392","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"Windows 업데이트에 관한 설명으로 옳지 않은 것은?","options":["보안 취약점을 고치는 품질 업데이트가 정기적으로 제공된다","업데이트를 설치하려면 기존 앱과 파일을 모두 삭제해야 한다","활동 시간을 지정하면 그 시간 동안은 자동으로 다시 시작되지 않는다","업데이트를 일정 기간 일시 중지할 수 있다"],"answer":1,"explain":"업데이트는 기존 앱과 파일을 유지한 채 설치된다."},{"id":"pc-0393","subject":"computer","levels":["c2","c1"],"topic":"네트워크·인터넷","q":"가정용 공유기가 하나의 공인 IP 주소로 여러 기기를 인터넷에 연결할 수 있게 사설 IP를 공인 IP로 바꾸어 주는 기술은?","options":["DHCP","NAT","DNS","VPN"],"answer":1,"explain":"NAT는 주소 변환 기술이다. DHCP는 IP 주소를 자동 할당하는 프로토콜이다."},{"id":"pc-0394","subject":"computer","levels":["c2","c1"],"topic":"시스템 설정","q":"[설정]-[시스템]-[디스플레이]에서 배율을 125%로 바꾸었을 때의 변화로 옳은 것은?","options":["해상도가 낮아져 모니터가 실제로 표시하는 화소 수가 줄어든다","모니터의 재생률이 높아져 화면의 깜빡임이 줄어든다","화면이 가로 방향에서 세로 방향으로 회전하여 표시된다","해상도는 그대로이며 텍스트·앱·아이콘이 더 크게 표시된다"],"answer":3,"explain":"배율은 표시 크기만 키우고 해상도는 바꾸지 않는다. 화면 방향은 별도의 [디스플레이 방향] 항목이다."},{"id":"pc-0395","subject":"computer","levels":["c1"],"topic":"네트워크·인터넷","q":"OSI 7계층 중 통신 장치 사이의 대화(세션)를 설정·유지·종료하고 동기화 지점을 관리하는 계층은?","options":["전송 계층","표현 계층","응용 계층","세션 계층"],"answer":3,"explain":"세션 계층은 통신 세션을 관리한다. 전송 계층은 종단 간 신뢰성, 표현 계층은 형식 변환·암호화를 맡는다."},{"id":"pc-0396","subject":"computer","levels":["c1"],"topic":"최신 기술","q":"블록체인에 기록되어 대체 불가능한 고유한 값을 가지며 디지털 자산의 소유권을 증명하는 토큰은?","options":["비트코인","QR 코드","OTP","NFT"],"answer":3,"explain":"NFT는 서로 교환할 수 없는 고유 토큰이다. 비트코인은 같은 단위끼리 대체할 수 있는 암호화폐이다."},{"id":"pc-0397","subject":"computer","levels":["c1"],"topic":"하드웨어","q":"명령어를 여러 단계로 나누어 서로 다른 명령어의 단계를 겹쳐 처리함으로써 처리량을 높이는 CPU 기법은?","options":["가상 메모리","파이프라이닝","스풀링","인터리빙"],"answer":1,"explain":"파이프라이닝은 조립 라인처럼 명령어 단계를 동시에 진행한다. 스풀링은 입출력 장치의 속도 차이를 줄이는 기법이다."},{"id":"pc-0398","subject":"computer","levels":["c1"],"topic":"정보 보안","q":"게시판 등에 악성 스크립트를 심어 다른 방문자의 브라우저에서 실행되게 하는 공격은?","options":["SQL 삽입(데이터베이스 질의 조작)","스푸핑(주소 위조)","XSS(크로스 사이트 스크립팅)","버퍼 오버플로(메모리 넘침)"],"answer":2,"explain":"XSS는 웹 페이지를 통해 방문자의 브라우저에서 스크립트를 실행시킨다."},{"id":"pc-0399","subject":"computer","levels":["c2","c1"],"topic":"운영체제","q":"파일이나 폴더의 속성에 관한 설명으로 옳지 않은 것은?","options":["읽기 전용 속성의 파일은 내용을 열어 볼 수 없다","숨김 속성의 파일은 기본 설정에서 파일 탐색기에 보이지 않는다","[속성] 대화 상자의 [일반] 탭에서 읽기 전용·숨김 속성을 바꿀 수 있다","폴더의 [속성]에서 보이는 크기는 하위 폴더의 파일까지 합한 크기이다"],"answer":0,"explain":"읽기 전용은 내용을 볼 수는 있고 수정·저장이 제한될 뿐이다."},{"id":"pc-0400","subject":"computer","levels":["c1"],"topic":"자료 표현","q":"인접한 두 값이 항상 1비트만 다르도록 만든 코드로 회전 센서나 아날로그-디지털 변환에 쓰이는 것은?","options":["그레이 코드","해밍 코드","패리티 코드","BCD 코드"],"answer":0,"explain":"그레이 코드는 한 칸 이동할 때 한 비트만 바뀌어 오류가 적다. 해밍 코드는 오류 정정용이다."},{"id":"db-0002","subject":"database","levels":["c1"],"topic":"DB 개념","q":"DBMS의 필수 기능 중 제어 기능에 해당하지 않는 것은?","options":["무결성이 유지되도록 데이터를 검사한다","여러 사용자가 동시에 쓸 때 병행 수행을 관리한다","데이터의 논리적·물리적 구조를 정의한다","권한 없는 사용자의 접근을 막는다"],"answer":2,"explain":"구조를 정의하는 것은 정의 기능이다. 제어 기능은 무결성·보안·권한 검사·병행 제어를 담당한다."},{"id":"db-0005","subject":"database","levels":["c1"],"topic":"DB 개념","q":"레코드의 물리적 저장 형식, 인덱스, 저장 장치에서의 배치 방법 등을 정의하는 스키마는?","options":["서브 스키마","외부 스키마","내부 스키마","개념 스키마"],"answer":2,"explain":"물리적 저장 구조는 내부 스키마가 정의한다. 서브 스키마는 외부 스키마의 다른 이름이다."},{"id":"db-0007","subject":"database","levels":["c1"],"topic":"DB 개념","q":"개념 스키마를 변경하더라도 외부 스키마나 응용 프로그램은 영향을 받지 않는 성질은?","options":["데이터 무결성","논리적 데이터 독립성","물리적 데이터 독립성","데이터 일관성"],"answer":1,"explain":"개념 스키마 변경이 외부 스키마에 영향을 주지 않는 것이 논리적 독립성이다. 내부 스키마 변경이 개념 스키마에 영향을 주지 않는 것은 물리적 독립성이다."},{"id":"db-0008","subject":"database","levels":["c1"],"topic":"DB 개념","q":"저장 장치를 바꾸거나 인덱스를 새로 만드는 등 내부 스키마를 변경해도 개념 스키마에 영향이 없는 성질은?","options":["데이터 종속성","물리적 데이터 독립성","참조 무결성","논리적 데이터 독립성"],"answer":1,"explain":"내부(물리) 구조 변경으로부터 개념 스키마를 보호하는 것이 물리적 독립성이다. 논리적 독립성은 개념 스키마와 외부 스키마 사이의 독립성이다."},{"id":"db-0013","subject":"database","levels":["c1"],"topic":"DB 개념","q":"E-R 다이어그램에서 사용하는 기호와 의미의 연결이 옳지 않은 것은?","options":["사각형 - 개체","마름모 - 속성","타원 - 속성","밑줄 그은 타원 - 기본키 속성"],"answer":1,"explain":"마름모는 관계(relationship)를 나타낸다. 속성은 타원, 개체는 사각형, 기본키 속성은 밑줄 그은 타원이다."},{"id":"db-0016","subject":"database","levels":["c1"],"topic":"DB 개념","q":"데이터베이스 설계 과정 중 논리적 설계 단계에서 하는 작업으로 가장 알맞은 것은?","options":["레코드 저장 방식과 접근 경로를 결정한다","E-R 다이어그램을 릴레이션 스키마로 바꾸고 정규화한다","완성된 스키마로 실제 데이터베이스를 만든다","사용자 인터뷰로 필요한 업무 데이터를 조사한다"],"answer":1,"explain":"논리적 설계는 목표 DBMS의 데이터 모델에 맞게 스키마를 만들고 정규화한다. 저장 방식·접근 경로는 물리적 설계, 인터뷰는 요구 분석 단계이다."},{"id":"db-0017","subject":"database","levels":["c1"],"topic":"DB 개념","q":"하나의 튜플을 삭제했을 때 원하지 않던 다른 정보까지 함께 사라지는 현상은?","options":["삽입 이상","삭제 이상","갱신 이상","종속 이상"],"answer":1,"explain":"정규화가 덜 된 릴레이션에서 생기는 삭제 이상이다. 삽입 이상은 불필요한 값까지 넣어야 하는 문제, 갱신 이상은 일부만 수정되어 불일치가 생기는 문제이다."},{"id":"db-0019","subject":"database","levels":["c1"],"topic":"DB 개념","q":"제1정규형을 만족하는 릴레이션에서 기본키에 대한 부분 함수 종속을 제거하면 어떤 정규형이 되는가?","options":["제4정규형","제3정규형","BCNF","제2정규형"],"answer":3,"explain":"부분 함수 종속 제거 → 2NF, 이행적 함수 종속 제거 → 3NF, 결정자이면서 후보키가 아닌 것 제거 → BCNF이다."},{"id":"db-0021","subject":"database","levels":["c1"],"topic":"DB 개념","q":"BCNF(보이스-코드 정규형)의 조건으로 옳은 것은?","options":["모든 조인 종속이 후보키를 통해서만 성립한다","모든 결정자가 후보키이다","모든 속성이 기본키에 부분 종속된다","다치 종속이 하나도 없다"],"answer":1,"explain":"BCNF는 결정자가 모두 후보키여야 한다. 다치 종속 제거는 4NF, 조인 종속은 5NF의 조건이다."},{"id":"db-0024","subject":"database","levels":["c1"],"topic":"DB 개념","q":"트랜잭션의 특성(ACID)에 대한 설명으로 옳지 않은 것은?","options":["일관성: 트랜잭션이 끝나면 데이터베이스는 일관된 상태를 유지한다","격리성: 동시에 실행되는 트랜잭션은 서로 간섭하지 않는다","지속성: 실행 중인 트랜잭션의 중간 결과를 다른 트랜잭션이 참조할 수 있다","원자성: 트랜잭션의 연산은 전부 실행되거나 전부 취소된다"],"answer":2,"explain":"지속성은 커밋된 결과가 장애가 나도 영구히 유지된다는 뜻이다. 중간 결과를 남이 볼 수 없게 하는 것은 격리성이다."},{"id":"db-0026","subject":"database","levels":["c1"],"topic":"관계·키","q":"후보키가 갖추어야 할 성질을 바르게 묶은 것은?","options":["최소성, 종속성","유일성, 중복성","원자성, 중복성","유일성, 최소성"],"answer":3,"explain":"후보키는 튜플을 유일하게 식별하고(유일성) 꼭 필요한 속성만으로 구성(최소성)되어야 한다. 슈퍼키는 유일성만 만족한다."},{"id":"db-0027","subject":"database","levels":["c1"],"topic":"관계·키","q":"유일성은 만족하지만 최소성은 만족하지 않을 수 있는 키는?","options":["대체키","후보키","기본키","슈퍼키"],"answer":3,"explain":"슈퍼키는 튜플을 식별할 수만 있으면 되므로 불필요한 속성이 섞여 있어도 된다. 후보키·기본키·대체키는 최소성까지 만족한다."},{"id":"db-0032","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access에서 두 테이블 사이에 참조 무결성을 설정하기 위한 조건으로 옳지 않은 것은?","options":["관련 필드끼리 데이터 형식이 같아야 한다","기본 테이블의 관련 필드는 기본키이거나 고유 인덱스가 있어야 한다","두 테이블의 관련 필드 이름이 반드시 같아야 한다","두 테이블이 같은 Access 데이터베이스에 있어야 한다"],"answer":2,"explain":"관련 필드는 이름이 달라도 데이터 형식만 맞으면 된다(일련 번호 필드는 숫자 정수(Long)와 연결 가능)."},{"id":"db-0035","subject":"database","levels":["c1"],"topic":"관계·키","q":"일대다 관계에 참조 무결성만 설정하고 연쇄 업데이트·연쇄 삭제는 선택하지 않았다. 다음 중 할 수 있는 작업은?","options":["관련 레코드가 있는 기본 테이블의 레코드를 삭제한다","관련 테이블(다 쪽)의 레코드를 삭제한다","기본 테이블에 없는 값을 관련 테이블의 외래키에 입력한다","관련 레코드가 있는 기본 테이블의 기본키 값을 바꾼다"],"answer":1,"explain":"다 쪽 레코드 삭제는 참조 관계를 깨지 않으므로 가능하다. 나머지는 외래키가 존재하지 않는 기본키를 가리키게 되므로 거부된다."},{"id":"db-0041","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access 테이블의 기본키에 대한 설명으로 옳지 않은 것은?","options":["기본키 필드에는 Null 값을 입력할 수 없다","기본키를 지정하지 않으면 테이블을 저장할 수 없다","여러 필드를 함께 선택해 하나의 기본키로 지정할 수 있다","기본키로 지정한 필드에는 중복 불가능 인덱스가 자동 설정된다"],"answer":1,"explain":"기본키 없이도 테이블을 저장할 수 있다(저장할 때 기본키를 만들지 묻기만 한다). 복합 기본키는 Ctrl로 여러 필드를 선택해 지정한다."},{"id":"db-0042","subject":"database","levels":["c1"],"topic":"관계·키","q":"다른 테이블과의 관계에 사용 중인 필드의 기본키를 해제하려고 할 때 먼저 해야 하는 일은?","options":["해당 필드의 인덱스 속성을 \"예(중복 가능)\"로 바꾼다","관련 테이블의 레코드를 모두 삭제한다","[관계] 창에서 해당 관계를 삭제한다","해당 필드의 데이터 형식을 짧은 텍스트로 바꾼다"],"answer":2,"explain":"관계에 쓰이는 기본키는 바로 해제할 수 없어 먼저 관계를 지워야 한다. 레코드 삭제나 형식 변경으로는 해결되지 않는다."},{"id":"db-0049","subject":"database","levels":["c1"],"topic":"테이블","q":"Yes/No 데이터 형식에 대한 설명으로 옳은 것은?","options":["Yes는 1, No는 0으로 저장된다","Yes는 1, No는 -1로 저장된다","Yes는 -1, No는 0으로 저장된다","Yes는 0, No는 -1로 저장된다"],"answer":2,"explain":"Access의 Yes/No(True/False)는 내부적으로 -1과 0이다. 1로 착각하기 쉽다."},{"id":"db-0052","subject":"database","levels":["c1"],"topic":"테이블","q":"Excel 워크시트나 Word 문서 같은 다른 프로그램의 개체를 연결하거나 포함하는 데이터 형식은?","options":["계산","긴 텍스트","OLE 개체","조회 마법사"],"answer":2,"explain":"OLE 개체 형식이 개체 연결·포함(Object Linking and Embedding)을 지원한다."},{"id":"db-0060","subject":"database","levels":["c1"],"topic":"테이블","q":"필드 속성 중 형식(Format)과 입력 마스크에 대한 설명으로 옳은 것은?","options":["형식을 지정하면 저장된 값도 형식에 맞게 바뀐다","형식은 표시되는 모양만 바꾸고 저장된 값은 바꾸지 않는다","형식을 지정한 필드에는 입력 마스크를 지정할 수 없다","형식은 데이터를 입력할 때만 적용되고 표시에는 쓰이지 않는다"],"answer":1,"explain":"형식은 표시 방식만 정하고, 입력 마스크는 입력 형태를 제한한다. 한 필드에 둘 다 지정할 수 있다."},{"id":"db-0062","subject":"database","levels":["c1"],"topic":"테이블","q":"필드 속성 중 유효성 검사 규칙에 맞지 않는 값을 입력했을 때 나타낼 메시지를 지정하는 것은?","options":["캡션","입력 마스크","유효성 검사 텍스트","기본값"],"answer":2,"explain":"규칙은 유효성 검사 규칙에, 위반 시 보여 줄 문구는 유효성 검사 텍스트에 쓴다."},{"id":"db-0064","subject":"database","levels":["c1"],"topic":"테이블","q":"인덱스에 대한 설명으로 옳지 않은 것은?","options":["인덱스를 설정하면 검색과 정렬 속도가 빨라질 수 있다","기본키로 지정한 필드에는 인덱스가 자동으로 설정된다","인덱스를 많이 설정할수록 레코드 추가·수정 속도도 빨라진다","\"예(중복 불가능)\"으로 지정하면 같은 값을 두 번 입력할 수 없다"],"answer":2,"explain":"인덱스는 조회를 빠르게 하지만 레코드를 추가·수정할 때마다 인덱스도 갱신해야 해서 그 작업은 느려진다."},{"id":"db-0065","subject":"database","levels":["c1"],"topic":"테이블","q":"필드 속성 중 새 레코드를 추가할 때 자동으로 입력될 값을 지정하는 것은?","options":["형식","유효성 검사 텍스트","기본값","캡션"],"answer":2,"explain":"기본값에 =Date() 등을 지정하면 새 레코드에 자동으로 들어간다. 사용자가 바꿔 입력할 수도 있다."},{"id":"db-0066","subject":"database","levels":["c1"],"topic":"테이블","q":"필드의 \"캡션\" 속성에 대한 설명으로 옳은 것은?","options":["데이터시트 보기의 열 머리글 등에 필드 이름 대신 표시할 이름이다","필드 이름 자체를 다른 이름으로 바꾸는 속성이다","입력할 수 있는 값의 범위를 제한하는 속성이다","필드 값이 표시되는 숫자 모양을 정하는 속성이다"],"answer":0,"explain":"캡션은 표시용 이름일 뿐 실제 필드 이름은 바뀌지 않으므로 쿼리·식에서는 원래 필드 이름을 써야 한다."},{"id":"db-0067","subject":"database","levels":["c1"],"topic":"테이블","q":"Access 테이블의 필드 이름으로 사용할 수 없는 것은?","options":["단가(원)","단가_원","단가.원","단가 원"],"answer":2,"explain":"필드 이름에는 마침표(.)·느낌표(!)·억음 악센트(`)·대괄호([ ])를 쓸 수 없다. 괄호·밑줄·중간 공백은 쓸 수 있다."},{"id":"db-0068","subject":"database","levels":["c1"],"topic":"테이블","q":"외부 데이터를 연결(링크) 테이블로 만들었을 때의 설명으로 옳지 않은 것은?","options":["원본 데이터가 바뀌면 연결 테이블에도 바뀐 내용이 반영된다","연결 테이블에서는 필드 추가 같은 구조 변경을 할 수 없다","탐색 창에서 연결 테이블은 일반 테이블과 다른 아이콘으로 표시된다","연결 테이블을 삭제하면 원본 데이터 파일도 함께 삭제된다"],"answer":3,"explain":"연결 테이블을 지우면 연결 정보만 사라지고 원본 파일은 그대로 남는다."},{"id":"db-0073","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT 부서 FROM 사원 GROUP BY 부서 HAVING COUNT(*) >= 2; 의 결과 행 수는?","options":["2","1","3","5"],"answer":0,"explain":"부서별 인원은 영업 2·총무 1·개발 2이므로 영업·개발 2행이다. COUNT(*)는 급여가 Null인 행도 센다."},{"id":"db-0075","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT 이름 FROM 사원 WHERE 급여 > (SELECT AVG(급여) FROM 사원); 의 결과로 옳은 것은?","options":["박다온, 최라희","박다온, 최라희, 정마루","박다온","김가람, 박다온, 최라희"],"answer":0,"explain":"하위 쿼리 평균은 325이므로 400인 박다온과 350인 최라희가 나온다. 정마루는 Null이라 비교에서 빠진다."},{"id":"db-0077","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT DISTINCT 부서 FROM 사원; 의 결과 행 수는?","options":["5","2","4","3"],"answer":3,"explain":"DISTINCT는 중복을 없애므로 영업·총무·개발 3행이다."},{"id":"db-0081","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT 이름 FROM 사원 WHERE 급여 IS NULL; 의 결과는?","options":["결과 없음","최라희, 정마루","이나래","정마루"],"answer":3,"explain":"Null 여부는 = Null이 아니라 IS NULL로 검사한다. 급여가 비어 있는 사람은 정마루뿐이다."},{"id":"db-0085","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"SQL에서 WHERE 절과 HAVING 절에 대한 설명으로 옳은 것은?","options":["WHERE 절은 그룹을 만든 뒤 그룹에 조건을 적용한다","HAVING 절은 GROUP BY 절 없이 단독으로만 쓸 수 있다","HAVING 절은 반드시 ORDER BY 절 뒤에 와야 한다","SUM, COUNT 같은 집계 함수를 이용한 조건은 HAVING 절에 쓴다"],"answer":3,"explain":"WHERE는 그룹화 전에 행을 거르고, HAVING은 그룹화 후 그룹을 거른다. 집계 함수 조건은 HAVING에 쓴다."},{"id":"db-0091","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"크로스탭 쿼리에 대한 설명으로 옳지 않은 것은?","options":["값으로는 하나의 필드만 지정하며 합계·평균 등 집계를 계산한다","열 머리글로 여러 개의 필드를 지정할 수 있다","데이터를 행과 열이 교차하는 표 형태로 요약해 보여 준다","행 머리글로는 여러 개의 필드를 지정할 수 있다"],"answer":1,"explain":"크로스탭 쿼리의 열 머리글과 값은 하나씩만 지정할 수 있다. 행 머리글은 여러 개 둘 수 있다(마법사는 최대 3개)."},{"id":"db-0093","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"한 번도 주문하지 않은 고객처럼, 다른 테이블에 관련 레코드가 없는 레코드를 찾을 때 쓰는 쿼리 마법사는?","options":["단순 쿼리 마법사","중복 데이터 검색 쿼리 마법사","크로스탭 쿼리 마법사","불일치 검색 쿼리 마법사"],"answer":3,"explain":"불일치 검색은 두 테이블을 비교해 짝이 없는 레코드를 찾는다. 중복 데이터 검색은 한 테이블 안에서 같은 값을 가진 레코드를 찾는다."},{"id":"db-0098","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금의 조건 입력에 대한 설명으로 옳은 것은?","options":["같은 조건 행에 입력한 조건들은 AND로 연결된다","같은 조건 행에 입력한 조건들은 OR로 연결된다","한 필드에는 조건을 하나만 입력할 수 있다","\"또는\" 행에 입력한 조건은 위 조건과 AND로 연결된다"],"answer":0,"explain":"한 행 안의 조건은 모두 만족해야 하는 AND, 서로 다른 행(조건·또는)의 조건은 OR로 결합된다."},{"id":"db-0099","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금의 필드 행에 [수량]과 [단가]를 곱한 값을 \"금액\"이라는 이름으로 표시하려 한다. 바르게 입력한 것은?","options":["[수량]*[단가]: 금액","금액 = [수량]*[단가]","=금액([수량]*[단가])","금액: [수량]*[단가]"],"answer":3,"explain":"쿼리 계산 필드는 \"별칭: 식\" 형식으로, 콜론 앞이 새 이름이다(SQL 로는 [수량]*[단가] AS 금액). 식과 이름의 순서를 바꾸거나 = 를 쓰면 안 된다."},{"id":"db-0102","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[고객](고객번호, 이름)과 [주문](주문번호, 고객번호)이 있다. 주문한 적이 없는 고객의 이름을 구하는 SQL로 옳은 것은?","options":["SELECT 이름 FROM 주문 WHERE 고객번호 NOT IN (SELECT 고객번호 FROM 고객);","SELECT 이름 FROM 고객 WHERE 고객번호 IN (SELECT 고객번호 FROM 주문);","SELECT 이름 FROM 고객 WHERE 고객번호 NOT IN (SELECT 고객번호 FROM 주문);","SELECT 이름 FROM 고객 WHERE 고객번호 <> (SELECT 주문번호 FROM 주문);"],"answer":2,"explain":"하위 쿼리로 주문한 고객번호 목록을 구하고 NOT IN으로 그 목록에 없는 고객을 고른다. IN을 쓰면 주문한 고객이 나온다."},{"id":"db-0105","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Access 쿼리의 식 [성] & [이름] 에서 [성]이 \"김\", [이름]이 Null일 때 결과는?","options":["#오류","김Null","김","Null"],"answer":2,"explain":"& 연산자는 Null을 빈 문자열처럼 처리해 \"김\"이 된다. + 연산자로 연결하면 결과가 Null이 된다."},{"id":"db-0106","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 보기 형식 중 실제 데이터를 보면서 컨트롤의 크기와 위치를 조정할 수 있는 것은?","options":["디자인 보기","레이아웃 보기","폼 보기","데이터시트 보기"],"answer":1,"explain":"레이아웃 보기는 데이터를 표시한 상태로 모양을 고칠 수 있다. 디자인 보기는 데이터를 보여 주지 않는다."},{"id":"db-0108","subject":"database","levels":["c1"],"topic":"폼","q":"텍스트 상자의 컨트롤 원본에 =[수량]*[단가]를 입력한 컨트롤의 종류는?","options":["계산 컨트롤","하위 폼 컨트롤","언바운드 컨트롤","바운드 컨트롤"],"answer":0,"explain":"=로 시작하는 식이 원본이면 계산 컨트롤이다. 필드 이름만 쓰면 바운드, 비워 두면 언바운드 컨트롤이다."},{"id":"db-0109","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 \"레코드 원본\" 속성으로 지정할 수 없는 것은?","options":["쿼리 이름","보고서 이름","SELECT로 시작하는 SQL 문","테이블 이름"],"answer":1,"explain":"폼의 레코드 원본은 테이블·쿼리·SQL 문이다. 보고서는 데이터 원본이 될 수 없다."},{"id":"db-0115","subject":"database","levels":["c1"],"topic":"폼","q":"하위 폼 컨트롤에서 기본 폼과 하위 폼을 연결하는 데 쓰는 속성을 바르게 묶은 것은?","options":["탭 정지, 탭 인덱스","기본 필드 연결, 하위 필드 연결","행 원본, 바운드 열","레코드 원본, 컨트롤 원본"],"answer":1,"explain":"기본 필드 연결(기본 폼 쪽)과 하위 필드 연결(하위 폼 쪽)에 관련 필드를 지정한다."},{"id":"db-0116","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 탭 순서에 대한 설명으로 옳지 않은 것은?","options":["레이블 컨트롤에도 탭 순서를 지정해 Tab 키로 이동할 수 있다","\"탭 인덱스\" 속성 값으로 순서를 직접 바꿀 수 있다","[탭 순서] 대화 상자에서 \"자동 순서\"를 누르면 위치에 따라 순서가 정해진다","컨트롤의 \"탭 정지\" 속성을 아니요로 하면 Tab 키로 그 컨트롤에 이동하지 않는다"],"answer":0,"explain":"레이블은 포커스를 받지 않으므로 탭 순서에 들어가지 않는다."},{"id":"db-0123","subject":"database","levels":["c1"],"topic":"폼","q":"폼 속성 중 \"모달\"을 예로 지정했을 때의 결과로 옳은 것은?","options":["그 폼을 닫기 전에는 다른 개체 창으로 포커스를 옮길 수 없다","그 폼은 새 레코드 입력 화면으로만 열린다","그 폼을 다른 창보다 항상 위에 떠 있는 팝업 창으로만 표시한다","그 폼은 데이터시트 보기로만 열 수 있게 된다"],"answer":0,"explain":"모달은 폼을 닫을 때까지 다른 창 작업을 막는다. 다른 창 위에 떠 있게 하는 것은 팝업 속성이다."},{"id":"db-0124","subject":"database","levels":["c1"],"topic":"폼","q":"폼 바닥글에 레코드 원본의 [금액] 필드 합계를 표시하는 텍스트 상자의 컨트롤 원본으로 옳은 것은?","options":["=Total([금액])","=Sum([금액])","=Sum[금액]","Sum([금액])="],"answer":1,"explain":"집계 계산 컨트롤은 =Sum([필드]) 처럼 등호로 시작하고 필드 이름을 대괄호로 감싼다."},{"id":"db-0128","subject":"database","levels":["c1"],"topic":"보고서","q":"지점별로 그룹화한 보고서에서 지점마다 판매 금액 합계를 표시하려 할 때 =Sum([금액]) 텍스트 상자를 둘 구역으로 알맞은 것은?","options":["페이지 머리글","보고서 머리글","그룹 바닥글","본문"],"answer":2,"explain":"그룹 머리글·바닥글에 둔 집계 함수는 그 그룹 범위로 계산된다. 보고서 머리글·바닥글에 두면 전체 합계가 된다."},{"id":"db-0129","subject":"database","levels":["c1"],"topic":"보고서","q":"전체 10페이지인 보고서의 3페이지에서 =[Page] & \"/\" & [Pages] 식의 결과는?","options":["10/3","3/10페이지","3","3/10"],"answer":3,"explain":"[Page]는 현재 페이지, [Pages]는 전체 페이지 수이며 &로 연결된다."},{"id":"db-0131","subject":"database","levels":["c1"],"topic":"보고서","q":"텍스트 상자의 \"누적 합계\" 속성을 \"그룹\"으로 지정했을 때의 결과로 옳은 것은?","options":["보고서 전체에 걸쳐 그룹이 바뀌어도 계속 누적한다","그룹마다 레코드 수를 세어 표시한다","그룹 안에서 값을 누적하다가 새 그룹이 시작되면 다시 처음부터 누적한다","각 그룹의 마지막 값만 그룹 바닥글에 표시한다"],"answer":2,"explain":"누적 합계는 아니요·그룹·모두 중 고르며, \"모두\"가 보고서 전체에 걸쳐 누적한다."},{"id":"db-0132","subject":"database","levels":["c1"],"topic":"보고서","q":"그룹별로 레코드에 1, 2, 3 … 순번을 매기려 한다. 본문 텍스트 상자의 설정으로 옳은 것은?","options":["컨트롤 원본 =[Page], 누적 합계 \"모두\"","컨트롤 원본 =1, 누적 합계 \"그룹\"","컨트롤 원본 =Count(*), 누적 합계 \"아니요\"","컨트롤 원본 =1, 누적 합계 \"아니요\""],"answer":1,"explain":"레코드마다 1을 누적하면 순번이 되고, \"그룹\"이면 그룹마다 1부터 다시 시작한다. \"모두\"면 전체 일련번호가 된다."},{"id":"db-0142","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"데이터베이스 파일을 열 때 자동으로 실행되도록 하려면 매크로 이름을 무엇으로 저장해야 하는가?","options":["AutoOpen","AutoExec","AutoStart","Startup"],"answer":1,"explain":"AutoExec 매크로는 DB를 열면 자동 실행된다. Shift 키를 누른 채 열면 실행되지 않는다."},{"id":"db-0146","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). DCount(\"*\", \"사원\", \"부서 = '개발'\")와 DSum(\"급여\", \"사원\", \"부서 = '개발'\")의 결과를 순서대로 나타낸 것은?","options":["1, 350","1, 175","2, 350","2, 700"],"answer":2,"explain":"DCount(\"*\")는 Null 급여 행도 세어 2이고, DSum은 Null을 빼고 더해 350이다."},{"id":"db-0147","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"Nz([할인], 0)에서 [할인] 필드가 Null일 때의 결과는?","options":["0","#오류","Null","빈 문자열"],"answer":0,"explain":"Nz(값, 대체값)은 값이 Null이면 대체값을, 아니면 원래 값을 돌려준다."},{"id":"db-0001","subject":"database","levels":["c1"],"topic":"DB 개념","q":"데이터베이스의 특징으로 옳지 않은 것은?","options":["삽입·삭제·갱신으로 내용이 계속 변한다","질의에 대해 실시간으로 처리하고 응답한다","데이터를 찾을 때 저장된 물리적 주소로만 참조한다","여러 사용자가 같은 데이터를 동시에 공유한다"],"answer":2,"explain":"데이터베이스는 주소가 아니라 데이터의 내용(값)으로 찾는 내용에 의한 참조를 한다. 실시간 접근·계속적 변화·동시 공용은 모두 특징이다."},{"id":"db-0004","subject":"database","levels":["c1"],"topic":"DB 개념","q":"스키마 3단계 중 개별 사용자나 응용 프로그램 입장에서 본 데이터베이스의 논리적 구조로, 서브 스키마라고도 하는 것은?","options":["외부 스키마","관계 스키마","개념 스키마","내부 스키마"],"answer":0,"explain":"외부 스키마는 사용자마다 다를 수 있는 서브 스키마이다. 개념 스키마는 조직 전체 관점, 내부 스키마는 물리적 저장 관점이다."},{"id":"db-0006","subject":"database","levels":["c1"],"topic":"DB 개념","q":"개념 스키마에 대한 설명으로 옳지 않은 것은?","options":["사용자마다 서로 다른 개념 스키마가 여러 개 존재한다","개체 간의 관계와 제약 조건을 포함한다","조직 전체 관점에서 본 데이터베이스의 논리적 구조이다","접근 권한과 무결성 규칙에 관한 정의를 포함한다"],"answer":0,"explain":"개념 스키마는 데이터베이스 하나에 하나만 존재한다. 사용자마다 여러 개가 있을 수 있는 것은 외부 스키마이다."},{"id":"db-0009","subject":"database","levels":["c1"],"topic":"DB 개념","q":"데이터 모델에 대한 설명으로 옳은 것은?","options":["망형 모델은 그래프 구조로 다대다 관계를 표현할 수 있다","관계형 모델은 데이터를 트리 구조로만 표현한다","계층형 모델은 오너와 멤버를 그래프로 연결한다","계층형 모델은 다대다 관계를 직접 표현하기 쉽다"],"answer":0,"explain":"망형(네트워크) 모델은 그래프 구조라 N:M 관계를 표현할 수 있다. 계층형은 트리(1:N) 구조이고, 관계형은 2차원 테이블로 표현한다."},{"id":"db-0010","subject":"database","levels":["c1"],"topic":"DB 개념","q":"속성이 5개이고 튜플이 8개인 릴레이션의 차수(degree)와 카디널리티(cardinality)를 순서대로 바르게 나타낸 것은?","options":["8, 5","5, 40","5, 8","13, 8"],"answer":2,"explain":"차수는 속성(열)의 수, 카디널리티는 튜플(행)의 수이다. 두 값을 바꿔 쓰는 것이 흔한 함정이다."},{"id":"db-0011","subject":"database","levels":["c1"],"topic":"DB 개념","q":"관계형 데이터베이스에서 하나의 속성이 가질 수 있는 같은 형식의 원자값들의 집합을 무엇이라 하는가?","options":["튜플","차수","도메인","인스턴스"],"answer":2,"explain":"도메인은 속성이 취할 수 있는 값의 범위(집합)이다. 튜플은 행, 차수는 속성의 수, 인스턴스는 어느 시점의 실제 데이터이다."},{"id":"db-0015","subject":"database","levels":["c1"],"topic":"DB 개념","q":"데이터베이스 설계 단계를 순서대로 바르게 나열한 것은?","options":["요구 조건 분석 → 물리적 설계 → 논리적 설계 → 개념적 설계 → 구현","개념적 설계 → 요구 조건 분석 → 물리적 설계 → 논리적 설계 → 구현","요구 조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현","요구 조건 분석 → 논리적 설계 → 개념적 설계 → 물리적 설계 → 구현"],"answer":2,"explain":"현실 요구를 분석한 뒤 E-R 등 개념 모델 → DBMS 데이터 모델(릴레이션) → 저장 구조 순으로 구체화한다."},{"id":"db-0018","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션의 모든 속성 값이 원자값으로만 이루어진 정규형은?","options":["제2정규형","제1정규형","BCNF","제3정규형"],"answer":1,"explain":"반복 그룹이나 다중값을 없애 원자값만 남기면 1NF이다. 2NF 이상은 함수 종속을 기준으로 한다."},{"id":"db-0022","subject":"database","levels":["c1"],"topic":"DB 개념","q":"정규화에 대한 설명으로 옳지 않은 것은?","options":["정규화를 하면 조회할 때 조인이 줄어 검색 속도가 항상 빨라진다","분해할 때 정보 손실이 없어야 한다","릴레이션을 더 작은 릴레이션으로 분해하는 과정이다","데이터 중복을 줄여 이상 현상을 막는다"],"answer":0,"explain":"정규화로 테이블이 나뉘면 조회할 때 조인이 늘어 오히려 느려질 수 있다. 그래서 성능을 위해 반정규화를 하기도 한다."},{"id":"db-0023","subject":"database","levels":["c1"],"topic":"DB 개념","q":"트랜잭션의 연산이 모두 반영되거나 하나도 반영되지 않아야 한다는 성질은?","options":["격리성","지속성","일관성","원자성"],"answer":3,"explain":"All or Nothing이 원자성(Atomicity)이다. 격리성은 동시 실행 트랜잭션이 서로 간섭하지 않는 것, 지속성은 완료된 결과가 영구히 남는 것이다."},{"id":"db-0030","subject":"database","levels":["c1"],"topic":"관계·키","q":"기본키를 구성하는 속성은 Null 값을 가질 수 없고 중복될 수도 없다는 규칙은?","options":["도메인 무결성","사용자 정의 무결성","개체 무결성","참조 무결성"],"answer":2,"explain":"개체 무결성은 기본키에 관한 규칙이다. 참조 무결성은 외래키 값이 참조 대상 기본키 값이거나 Null이어야 한다는 규칙이다."},{"id":"db-0031","subject":"database","levels":["c1"],"topic":"관계·키","q":"참조 무결성에 대한 설명으로 옳은 것은?","options":["속성 값은 정해진 도메인 범위 안에 있어야 한다","외래키 값은 반드시 중복 없이 하나씩만 입력해야 한다","기본키 값은 Null이 될 수 없고 중복될 수 없어야 한다","외래키 값은 참조하는 테이블의 기본키 값 중 하나이거나 Null이어야 한다"],"answer":3,"explain":"참조 무결성은 외래키에 관한 규칙이다. 기본키 Null·중복 금지는 개체 무결성, 도메인 범위는 도메인 무결성이며 외래키는 중복될 수 있다."},{"id":"db-0033","subject":"database","levels":["c1"],"topic":"관계·키","q":"[관계 편집] 대화 상자에서 참조 무결성과 함께 \"관련 필드 모두 업데이트\"를 선택했을 때의 동작은?","options":["관련 테이블의 외래키 값을 바꾸면 기본 테이블의 기본키 값도 자동으로 바뀐다","기본 테이블의 기본키 값을 바꾸면 관련 테이블의 외래키 값도 자동으로 바뀐다","관련 테이블에 새 레코드를 넣으면 기본 테이블에 같은 레코드가 추가된다","기본 테이블의 레코드를 지우면 관련 테이블의 레코드도 자동으로 지워진다"],"answer":1,"explain":"연쇄 업데이트는 일 쪽(기본 테이블)의 기본키 변경을 다 쪽에 전파한다. 레코드 삭제 전파는 \"관련 레코드 모두 삭제\" 옵션이다."},{"id":"db-0034","subject":"database","levels":["c1"],"topic":"관계·키","q":"[고객]과 [주문]이 일대다 관계이고 참조 무결성과 \"관련 레코드 모두 삭제\"가 설정되어 있다. [고객]에서 주문이 3건 있는 고객 레코드를 삭제하면?","options":["고객 레코드와 그 고객의 주문 3건이 함께 삭제된다","고객 레코드만 삭제되고 주문 3건의 고객번호는 Null로 바뀐다","고객 레코드만 삭제되고 주문 3건의 고객번호는 그대로 남는다","주문이 있으므로 고객 레코드를 삭제할 수 없다"],"answer":0,"explain":"연쇄 삭제가 켜져 있으면 관련 레코드도 함께 지워진다. 이 옵션이 없으면 관련 레코드가 있는 고객은 삭제할 수 없다."},{"id":"db-0037","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access에서 두 테이블의 관계를 일대일로 만들려면 관련 필드가 어떤 조건을 갖추어야 하는가?","options":["한쪽 필드만 기본키이고 다른 쪽은 중복 가능 인덱스여야 한다","양쪽 관련 필드가 모두 인덱스 없이 Null을 허용해야 한다","양쪽 관련 필드가 모두 기본키이거나 중복 불가능 인덱스여야 한다","양쪽 관련 필드가 모두 일련 번호 형식이어야 한다"],"answer":2,"explain":"양쪽이 모두 고유하면 1:1, 한쪽만 고유하면 1:N 관계가 만들어진다."},{"id":"db-0045","subject":"database","levels":["c1"],"topic":"관계·키","q":"속성 값이 그 속성에 정의된 범위·형식에 맞아야 한다는 무결성으로, Access에서는 유효성 검사 규칙으로 구현하는 것은?","options":["개체 무결성","도메인 무결성","키 무결성","참조 무결성"],"answer":1,"explain":"값의 범위·형식 제약은 도메인 무결성이다. 개체 무결성은 기본키, 참조 무결성은 외래키에 관한 규칙이다."},{"id":"db-0047","subject":"database","levels":["c1"],"topic":"테이블","q":"숫자 데이터 형식의 필드 크기 중 0부터 255까지의 정수만 저장할 수 있는 것은?","options":["바이트","정수","정수(Long)","실수(Single)"],"answer":0,"explain":"바이트는 1바이트로 0~255이다. 정수는 -32,768~32,767, 정수(Long)는 약 ±21억 범위이다."},{"id":"db-0053","subject":"database","levels":["c1"],"topic":"테이블","q":"계산 데이터 형식에 대한 설명으로 옳지 않은 것은?","options":["사용자가 값을 직접 입력할 수 없다","식에서 참조하는 필드가 바뀌면 결과도 다시 계산된다","같은 테이블에 있는 다른 필드를 이용한 식으로 값이 정해진다","다른 테이블의 필드도 식에서 직접 참조할 수 있다"],"answer":3,"explain":"계산 필드의 식은 같은 테이블의 필드만 참조할 수 있다. 다른 테이블 값이 필요하면 쿼리에서 계산한다."},{"id":"db-0055","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 기호에 대한 설명으로 옳지 않은 것은?","options":["L : 문자(영문·한글)를 반드시 입력해야 한다","9 : 0~9 숫자를 반드시 입력해야 한다","& : 모든 문자나 공백을 반드시 입력해야 한다","0 : 0~9 숫자를 반드시 입력해야 한다"],"answer":1,"explain":"9는 숫자나 공백을 선택적으로 입력하는 기호이다. 반드시 숫자를 넣어야 하는 기호는 0이다."},{"id":"db-0069","subject":"database","levels":["c1"],"topic":"테이블","q":"Access의 [외부 데이터] 탭에서 테이블로 가져오기를 할 수 있는 원본 형식이 아닌 것은?","options":["Excel 통합 문서","텍스트 파일","PowerPoint 프레젠테이션 파일","XML 파일"],"answer":2,"explain":"Excel·텍스트·XML·HTML·다른 Access DB·ODBC 데이터베이스 등은 가져올 수 있지만 PowerPoint 파일은 원본이 될 수 없다."},{"id":"db-0071","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT COUNT(급여) FROM 사원; 의 결과는?","options":["4","1300","5","3"],"answer":0,"explain":"COUNT(필드)는 Null을 세지 않으므로 정마루를 뺀 4이다. COUNT(*)였다면 5이다."},{"id":"db-0082","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Access 쿼리의 조건에 Like \"?나*\"를 지정했을 때 찾을 수 있는 값은?","options":["나리나","김가나","이나래","나래"],"answer":2,"explain":"?는 정확히 한 글자, *는 0개 이상의 글자이므로 두 번째 글자가 \"나\"인 값만 해당한다. 김가나(가)·나래(래)·나리나(리)는 두 번째 글자가 \"나\"가 아니다."},{"id":"db-0084","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"SELECT 문의 절을 작성 순서대로 바르게 나열한 것은?","options":["SELECT - FROM - GROUP BY - WHERE - ORDER BY - HAVING","SELECT - WHERE - FROM - GROUP BY - HAVING - ORDER BY","SELECT - FROM - WHERE - HAVING - GROUP BY - ORDER BY","SELECT - FROM - WHERE - GROUP BY - HAVING - ORDER BY"],"answer":3,"explain":"WHERE는 그룹 전 행 조건, HAVING은 GROUP BY 뒤 그룹 조건, ORDER BY는 맨 마지막에 쓴다."},{"id":"db-0086","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"ORDER BY 절에 대한 설명으로 옳지 않은 것은?","options":["SELECT 문의 마지막 절로 쓴다","정렬 방식을 생략하면 내림차순(DESC)으로 정렬된다","ASC는 오름차순, DESC는 내림차순을 뜻한다","여러 필드를 쉼표로 나열해 정렬 기준을 여러 개 둘 수 있다"],"answer":1,"explain":"ASC/DESC를 생략하면 오름차순(ASC)이 기본이다."},{"id":"db-0087","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[주문]과 [고객] 테이블을 고객번호로 연결해 양쪽에 모두 있는 레코드만 조회하는 SQL로 옳은 것은?","options":["SELECT * FROM 주문 INNER JOIN 고객 ON 주문.고객번호 = 고객.고객번호;","SELECT * FROM 주문 INNER JOIN 고객 WHERE 주문.고객번호 = 고객.고객번호;","SELECT * FROM 주문 JOIN ON 고객 주문.고객번호 = 고객.고객번호;","SELECT * FROM 주문 LEFT JOIN 고객 ON 주문.고객번호 = 고객.고객번호;"],"answer":0,"explain":"INNER JOIN 뒤에는 ON으로 조인 조건을 쓴다. LEFT JOIN은 주문 쪽 레코드를 모두 포함하는 외부 조인이다."},{"id":"db-0088","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블에서 퇴사(Yes/No) 필드가 Yes인 레코드를 모두 지우는 SQL로 옳은 것은?","options":["DELETE FROM 사원 WHERE 퇴사 = True;","REMOVE FROM 사원 WHERE 퇴사 = True;","DELETE 사원 SET 퇴사 = True;","DROP FROM 사원 WHERE 퇴사 = True;"],"answer":0,"explain":"레코드 삭제는 DELETE FROM ~ WHERE이다. DROP은 테이블 같은 개체 자체를 지우는 DDL이다."},{"id":"db-0089","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블에 사번 6, 이름 '한별'인 레코드를 추가하는 SQL로 옳은 것은?","options":["INSERT 사원 SET 사번 = 6, 이름 = '한별';","UPDATE 사원 VALUES (6, '한별');","INSERT INTO 사원 (사번, 이름) VALUES (6, '한별');","INSERT INTO 사원 VALUE 사번 = 6, 이름 = '한별';"],"answer":2,"explain":"INSERT INTO 테이블(필드 목록) VALUES(값 목록) 형식이다. SET은 UPDATE 문에서 쓴다."},{"id":"db-0090","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블에 짧은 텍스트 20자의 [연락처] 필드를 추가하는 SQL로 옳은 것은?","options":["ALTER TABLE 사원 ADD COLUMN 연락처 TEXT(20);","INSERT INTO 사원 ADD COLUMN 연락처 TEXT(20);","CREATE TABLE 사원 ADD COLUMN 연락처 TEXT(20);","UPDATE TABLE 사원 ADD COLUMN 연락처 TEXT(20);"],"answer":0,"explain":"테이블 구조 변경은 DDL인 ALTER TABLE이다. INSERT·UPDATE는 레코드를 다루는 DML이다."},{"id":"db-0095","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Access의 실행 쿼리에 해당하지 않는 것은?","options":["업데이트 쿼리","테이블 만들기 쿼리","추가 쿼리","크로스탭 쿼리"],"answer":3,"explain":"실행 쿼리는 데이터를 바꾸는 테이블 만들기·추가·업데이트·삭제 쿼리이다. 크로스탭은 데이터를 요약해 보여 주기만 한다."},{"id":"db-0096","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"조회 결과로 새 테이블 [우수고객]을 만드는 테이블 만들기 쿼리의 SQL로 옳은 것은?","options":["INSERT INTO 우수고객 FROM 고객 WHERE 등급 = \"A\";","SELECT * INTO 우수고객 FROM 고객 WHERE 등급 = \"A\";","CREATE TABLE 우수고객 FROM 고객 WHERE 등급 = \"A\";","SELECT * FROM 고객 INTO 우수고객 WHERE 등급 = \"A\";"],"answer":1,"explain":"테이블 만들기 쿼리는 SELECT ~ INTO 새테이블 FROM ~ 형식이다. 이미 있는 테이블에 넣는 것은 INSERT INTO ~ SELECT(추가 쿼리)이다."},{"id":"db-0097","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"실행 쿼리에 대한 설명으로 옳은 것은?","options":["실행하면 테이블의 데이터가 바뀌며 Ctrl+Z로 되돌릴 수 없다","크로스탭 쿼리와 선택 쿼리도 실행 쿼리에 포함된다","데이터시트 보기로 열면 결과만 보여 주고 데이터는 바뀌지 않는 쿼리이다","실행해도 확인 메시지 없이 항상 미리 보기만 표시된다"],"answer":0,"explain":"실행 쿼리는 데이터를 실제로 바꾸고 실행 취소가 되지 않으므로 실행 전에 확인 메시지가 나온다. 선택·크로스탭은 실행 쿼리가 아니다."},{"id":"db-0104","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[학생] 테이블(이름, 점수)에서 SELECT 이름, IIf([점수] >= 60, \"합격\", \"불합격\") AS 결과 FROM 학생; 을 실행했다. 점수가 60인 학생의 결과는?","options":["True","60","합격","불합격"],"answer":2,"explain":"IIf(조건, 참일 때, 거짓일 때)이고 60 >= 60은 참이므로 \"합격\"이다. 경계값에서 >=와 >를 혼동하기 쉽다."},{"id":"db-0107","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 컨트롤에 대한 설명으로 옳지 않은 것은?","options":["계산 컨트롤은 폼 보기에서 값을 직접 입력해 수정할 수 있다","언바운드 컨트롤은 컨트롤 원본이 비어 있어 데이터 원본과 연결되지 않는다","바운드 컨트롤은 컨트롤 원본에 테이블이나 쿼리의 필드가 연결된다","계산 컨트롤은 컨트롤 원본이 등호(=)로 시작하는 식이다"],"answer":0,"explain":"계산 컨트롤은 식의 결과를 보여 줄 뿐이라 값을 직접 고칠 수 없다."},{"id":"db-0111","subject":"database","levels":["c1"],"topic":"폼","q":"한 화면 위쪽(또는 아래쪽)에는 폼 보기, 다른 쪽에는 데이터시트 보기가 함께 표시되어 동기화되는 폼은?","options":["탐색 폼","분할 표시 폼","모달 대화 상자","연속 폼"],"answer":1,"explain":"분할 표시 폼은 두 보기를 동시에 보여 주며 한쪽에서 선택한 레코드가 다른 쪽에도 선택된다."},{"id":"db-0112","subject":"database","levels":["c1"],"topic":"폼","q":"폼 속성 중 \"데이터 입력\"을 예로 지정했을 때의 동작은?","options":["기존 레코드는 표시하지 않고 새 레코드 입력 화면만 열린다","기존 레코드를 수정할 수 있지만 새 레코드는 추가할 수 없다","레코드를 삭제할 수 없고 조회만 할 수 있다","폼이 열리면 레코드 원본의 모든 레코드가 삭제된다"],"answer":0,"explain":"데이터 입력=예는 새 레코드 입력 전용 폼으로 만든다. 수정·삭제 제한은 편집 가능·삭제 가능 속성으로 정한다."},{"id":"db-0113","subject":"database","levels":["c1"],"topic":"폼","q":"폼에서 기존 레코드를 볼 수는 있지만 값을 고치지 못하게 하려면 어떤 폼 속성을 아니요로 지정해야 하는가?","options":["편집 가능","추가 가능","데이터 입력","삭제 가능"],"answer":0,"explain":"편집 가능=아니요는 기존 레코드 수정만 막는다. 추가 가능·삭제 가능은 각각 새 레코드 추가·삭제를 제어한다."},{"id":"db-0118","subject":"database","levels":["c1"],"topic":"폼","q":"콤보 상자의 \"바운드 열\" 속성에 대한 설명으로 옳은 것은?","options":["목록의 원본이 테이블인지 값 목록인지 정하는 값이다","항목을 선택했을 때 필드에 저장될 값이 들어 있는 열 번호이다","목록에 표시할 열의 너비를 차례로 지정하는 값이다","목록을 펼쳤을 때 한 번에 보이는 행의 개수이다"],"answer":1,"explain":"바운드 열은 저장되는 열이다. 보이는 행 수는 목록 행 수, 너비는 열 너비, 원본 종류는 행 원본 유형이다."},{"id":"db-0119","subject":"database","levels":["c1"],"topic":"폼","q":"콤보 상자의 열 개수가 2이고 \"열 너비\"가 0cm;3cm일 때의 결과로 옳은 것은?","options":["두 번째 열은 숨겨지고 첫 번째 열만 목록에 보인다","열 너비에 0을 쓸 수 없어 오류가 난다","두 열이 모두 3cm 너비로 표시된다","첫 번째 열은 숨겨지고 두 번째 열만 목록에 보인다"],"answer":3,"explain":"너비 0은 그 열을 숨긴다. 코드 열을 숨기고 이름만 보이게 하면서 저장은 코드로 할 때 쓴다."},{"id":"db-0125","subject":"database","levels":["c1"],"topic":"폼","q":"옵션 그룹에 대한 설명으로 옳은 것은?","options":["옵션 단추의 레이블 글자가 필드에 그대로 저장된다","그룹 안에서 여러 옵션을 동시에 선택해 쉼표로 이어 저장한다","그룹 안에서 하나만 선택할 수 있고 선택한 옵션의 \"옵션 값\"(숫자)이 저장된다","옵션 그룹은 짧은 텍스트 필드에만 연결할 수 있다"],"answer":2,"explain":"옵션 그룹은 단일 선택이며 각 옵션의 옵션 값(숫자)이 그룹의 값이 된다."},{"id":"db-0127","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 구역에 대한 설명으로 옳지 않은 것은?","options":["본문은 레코드 원본의 레코드마다 반복해서 표시된다","그룹 바닥글은 각 그룹이 끝나는 곳에 표시된다","보고서 바닥글은 페이지마다 맨 아래에 반복해서 표시된다","페이지 머리글은 페이지마다 맨 위에 표시된다"],"answer":2,"explain":"보고서 바닥글은 마지막 페이지에 한 번만 나온다. 페이지마다 아래에 나오는 것은 페이지 바닥글이다."},{"id":"db-0133","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 보기 형식에 대한 설명으로 옳은 것은?","options":["인쇄 미리 보기는 실제 인쇄될 모양을 페이지 단위로 보여 준다","보고서 보기에서는 데이터를 직접 수정해 테이블에 저장할 수 있다","디자인 보기에서는 실제 데이터가 채워진 모양을 확인할 수 있다","레이아웃 보기에서는 컨트롤의 크기나 위치를 바꿀 수 없다"],"answer":0,"explain":"보고서는 데이터를 수정할 수 없다. 디자인 보기는 데이터를 표시하지 않고, 레이아웃 보기에서는 데이터를 보며 모양을 고칠 수 있다."},{"id":"db-0134","subject":"database","levels":["c1"],"topic":"보고서","q":"우편 발송용으로 주소를 일정한 크기의 라벨 용지에 여러 개씩 인쇄하는 보고서를 만드는 도구는?","options":["새 보고서","레이블","보고서 마법사","보고서 디자인"],"answer":1,"explain":"[만들기]-[보고서] 그룹의 레이블 마법사로 라벨 규격을 골라 만든다."},{"id":"db-0135","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서에서 그룹 하나가 두 페이지에 나뉘어 인쇄되지 않도록 하려면 [그룹, 정렬 및 요약] 창에서 어떻게 지정해야 하는가?","options":["그룹 머리글 구역을 표시하지 않도록 지정한다","그룹 요약에서 합계를 표시하도록 지정한다","그룹 정렬 기준을 내림차순으로 바꾼다","그룹 전체를 같은 페이지에 표시하도록 지정한다"],"answer":3,"explain":"그룹의 페이지 유지(Keep Together) 옵션을 그룹 전체를 같은 페이지에 표시하도록 바꾸면 그룹이 나뉘지 않는다."},{"id":"db-0137","subject":"database","levels":["c1"],"topic":"보고서","q":"지점 그룹이 끝날 때마다 새 페이지에서 다음 지점이 시작되게 하려면 지점 그룹 바닥글 구역의 어떤 속성을 바꾸는가?","options":["누적 합계를 \"그룹\"으로 지정한다","확장 가능을 \"예\"로 지정한다","페이지 바꿈을 \"구역 후\"로 지정한다","반복 실행 구역을 \"예\"로 지정한다"],"answer":2,"explain":"구역의 페이지 바꿈 속성(없음·구역 전·구역 후·구역 전/후)으로 페이지를 나눈다."},{"id":"db-0138","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서에 대한 설명으로 옳지 않은 것은?","options":["하위 보고서를 넣어 관련 데이터를 함께 보여 줄 수 있다","보고서 보기에서 데이터를 입력하면 원본 테이블에 저장된다","테이블, 쿼리, SQL 문을 레코드 원본으로 쓸 수 있다","그룹화와 정렬을 지정해 데이터를 요약할 수 있다"],"answer":1,"explain":"보고서는 출력 전용 개체라 데이터를 입력·수정할 수 없다. 입력은 폼이나 데이터시트에서 한다."},{"id":"db-0140","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 머리글에 오늘 날짜를 표시하려 한다. 텍스트 상자의 컨트롤 원본으로 옳은 것은?","options":["=[Date]","=Day()","=Date()","=Today()"],"answer":2,"explain":"Access에서 오늘 날짜는 Date() 함수이다. Today()는 Excel 함수이고 Access에는 없다."},{"id":"db-0143","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"컨트롤의 데이터가 바뀐 뒤 레코드에 반영되기 직전에 발생하여, 값을 검사하고 업데이트를 취소할 수 있는 이벤트는?","options":["업데이트 전(BeforeUpdate)","포커스 얻음(GotFocus)","업데이트 후(AfterUpdate)","클릭(Click)"],"answer":0,"explain":"BeforeUpdate는 저장 전에 발생해 Cancel로 취소할 수 있다. AfterUpdate는 이미 반영된 뒤에 발생한다."},{"id":"db-0144","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"VBA에서 [매출현황] 보고서를 인쇄 미리 보기로 여는 문장으로 옳은 것은?","options":["DoCmd.OpenReport \"매출현황\", acViewPreview","DoCmd.OpenForm \"매출현황\", acViewPreview","Report.Open \"매출현황\", acViewPreview","DoCmd.RunReport \"매출현황\", acPreview"],"answer":0,"explain":"보고서는 DoCmd 개체의 OpenReport 메서드로 열고 보기 형식 acViewPreview를 지정한다."},{"id":"db-0149","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"Format(#2026-10-04#, \"yyyy-mm\")의 결과는?","options":["26-10","2026-10","2026-04","2026-10-04"],"answer":1,"explain":"yyyy는 네 자리 연도, mm은 두 자리 월을 뜻한다. 날짜(dd)는 지정하지 않았으므로 표시되지 않는다."},{"id":"db-0150","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"다음 VBA 코드를 실행했을 때 MsgBox에 표시되는 값은? Dim s As Integer, i As Integer : s = 0 : For i = 1 To 10 Step 3 : s = s + i : Next i : MsgBox s","options":["22","12","15","55"],"answer":0,"explain":"i는 1, 4, 7, 10으로 바뀌므로 합은 22이다. Step을 무시하면 55가 된다."},{"id":"db-0003","subject":"database","levels":["c1"],"topic":"DB 개념","q":"DBMS를 사용할 때의 단점으로 가장 알맞은 것은?","options":["데이터 일관성이 떨어진다","백업과 회복 절차가 복잡해진다","데이터 중복이 늘어난다","데이터 공유가 어려워진다"],"answer":1,"explain":"DBMS는 운영비 증가·전문 인력 필요·백업과 회복의 복잡함이 단점이다. 중복 감소·일관성·공유는 오히려 장점이다."},{"id":"db-0012","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션의 특징으로 옳지 않은 것은?","options":["한 릴레이션에 똑같은 튜플이 두 개 이상 존재하지 않는다","각 속성의 값은 더 나눌 수 없는 원자값이다","튜플 사이에는 입력한 순서대로 의미 있는 순서가 있다","속성의 순서가 바뀌어도 같은 릴레이션이다"],"answer":2,"explain":"릴레이션의 튜플과 속성에는 순서가 없다. 중복 튜플 없음·원자값은 릴레이션의 특징이다."},{"id":"db-0014","subject":"database","levels":["c1"],"topic":"DB 개념","q":"E-R 모델에 대한 설명으로 옳은 것은?","options":["특정 DBMS에 맞춰 레코드의 물리적 저장 위치를 정한다","정규화를 거친 뒤 인덱스 구조를 설계하는 도구이다","테이블을 만든 뒤 SQL 문을 자동으로 만들어 주는 도구이다","개념적 설계 단계에서 개체와 개체 간의 관계를 표현하는 데 쓰인다"],"answer":3,"explain":"E-R 모델(피터 첸)은 현실 세계를 개체·속성·관계로 표현하는 개념적 설계 도구이다. 물리적 저장·인덱스는 물리적 설계에서 다룬다."},{"id":"db-0020","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션 (학번, 학과코드, 학과명)에서 학번 → 학과코드, 학과코드 → 학과명이 성립한다. 이를 분해하여 해결하는 정규화 단계는?","options":["제4정규형","제1정규형","제3정규형","제2정규형"],"answer":2,"explain":"학번 → 학과코드 → 학과명은 이행적 함수 종속이며, 이를 제거하는 단계가 3NF이다. 기본키가 단일 속성이라 부분 종속은 없다."},{"id":"db-0025","subject":"database","levels":["c1"],"topic":"DB 개념","q":"SQL 명령어와 분류의 연결이 옳지 않은 것은?","options":["GRANT - 데이터 조작어(DML)","CREATE - 데이터 정의어(DDL)","ROLLBACK - 데이터 제어어(DCL)","UPDATE - 데이터 조작어(DML)"],"answer":0,"explain":"GRANT·REVOKE는 권한을 다루는 데이터 제어어(DCL)이다. COMMIT·ROLLBACK도 DCL로 분류하며, CREATE·ALTER·DROP은 DDL이다."},{"id":"db-0028","subject":"database","levels":["c1"],"topic":"관계·키","q":"후보키 중에서 기본키로 선택되지 않은 나머지 키를 무엇이라 하는가?","options":["외래키","복합키","슈퍼키","대체키"],"answer":3,"explain":"기본키로 뽑히지 않은 후보키가 대체키(보조키)이다. 외래키는 다른 테이블의 기본키를 참조하는 키이다."},{"id":"db-0029","subject":"database","levels":["c1"],"topic":"관계·키","q":"다른 릴레이션의 기본키를 참조하여 두 릴레이션의 관계를 맺어 주는 속성은?","options":["대체키","외래키","슈퍼키","후보키"],"answer":1,"explain":"외래키는 참조하는 테이블 쪽에 있으며 참조되는 테이블의 기본키 값과 연결된다."},{"id":"db-0036","subject":"database","levels":["c1"],"topic":"관계·키","q":"[학생]과 [과목]은 한 학생이 여러 과목을 듣고 한 과목을 여러 학생이 듣는 관계이다. Access에서 이 관계를 구현하는 방법으로 가장 알맞은 것은?","options":["[관계] 창에서 관계 종류를 \"다대다\"로 바로 선택한다","[수강] 테이블을 만들어 두 테이블과 각각 일대다 관계를 맺는다","[학생]의 기본키를 [과목]의 기본키로도 지정하여 일대일 관계를 맺는다","[과목] 테이블에 학번 필드를 여러 개 추가하여 직접 연결한다"],"answer":1,"explain":"M:N 관계는 두 기본키를 외래키로 갖는 연결(교차) 테이블을 두어 1:N 두 개로 나눈다. 관계 창에는 다대다 종류가 따로 없다."},{"id":"db-0038","subject":"database","levels":["c1"],"topic":"관계·키","q":"[관계] 창에서 참조 무결성이 설정된 일대다 관계선 양 끝에 표시되는 기호로 옳은 것은?","options":["일 쪽에 1, 다 쪽에 ∞","양쪽 모두 1","일 쪽에 ∞, 다 쪽에 1","양쪽 모두 ∞"],"answer":0,"explain":"참조 무결성을 설정하면 관계선에 1과 ∞(무한대)가 표시된다. ∞가 외래키가 있는 다 쪽이다."},{"id":"db-0039","subject":"database","levels":["c1"],"topic":"관계·키","q":"[조인 속성] 대화 상자에서 \"왼쪽 테이블의 레코드는 모두 포함하고 오른쪽 테이블에서는 조인된 필드가 같은 레코드만 포함\"을 선택했을 때 해당하는 조인은?","options":["LEFT JOIN","INNER JOIN","CROSS JOIN","RIGHT JOIN"],"answer":0,"explain":"왼쪽 테이블 전체를 유지하는 외부 조인이 LEFT JOIN이다. [조인 속성] 대화 상자의 첫 번째 항목(두 테이블에서 조인된 필드가 같은 행만 포함)이 INNER JOIN이다."},{"id":"db-0040","subject":"database","levels":["c1"],"topic":"관계·키","q":"[고객](고객번호, 이름)에 (1, 가온) (2, 나리) (3, 다솜), [주문](주문번호, 고객번호)에 (101, 1) (102, 1) (103, 2)가 있다. SELECT 고객.이름, 주문.주문번호 FROM 고객 LEFT JOIN 주문 ON 고객.고객번호 = 주문.고객번호; 의 결과 행 수는?","options":["3","2","6","4"],"answer":3,"explain":"가온 2행, 나리 1행에 주문이 없는 다솜도 주문번호 Null로 1행 포함되어 4행이다. INNER JOIN이었다면 3행이다."},{"id":"db-0043","subject":"database","levels":["c1"],"topic":"관계·키","q":"릴레이션 (학번, 주민번호, 이름, 학과)에서 학번과 주민번호는 각각 모든 학생을 유일하게 구별하며 학번을 기본키로 정했다. 옳지 않은 것은?","options":["{학번, 이름}은 유일성과 최소성을 모두 만족하므로 후보키이다","학번과 주민번호는 모두 후보키이다","{학번, 이름}은 슈퍼키이다","주민번호는 대체키이다"],"answer":0,"explain":"{학번, 이름}은 학번만으로도 식별되므로 최소성이 없어 슈퍼키일 뿐 후보키가 아니다."},{"id":"db-0044","subject":"database","levels":["c1"],"topic":"관계·키","q":"외래키에 대한 설명으로 옳은 것은?","options":["한 테이블에는 외래키를 하나만 둘 수 있다","외래키 필드에는 같은 값이 여러 번 나올 수 있다","외래키는 반드시 해당 테이블의 기본키여야 한다","외래키에는 어떤 경우에도 Null을 입력할 수 없다"],"answer":1,"explain":"일대다의 다 쪽 외래키는 중복될 수 있고 Null도 허용될 수 있다. 한 테이블에 여러 외래키를 둘 수도 있다."},{"id":"db-0046","subject":"database","levels":["c1"],"topic":"테이블","q":"Access의 짧은 텍스트 데이터 형식에서 필드 크기로 지정할 수 있는 최대 글자 수는?","options":["1,024","65,535","127","255"],"answer":3,"explain":"짧은 텍스트는 최대 255자(기본값도 255)이다. 더 긴 내용은 긴 텍스트 형식을 쓴다."},{"id":"db-0048","subject":"database","levels":["c1"],"topic":"테이블","q":"일련 번호 데이터 형식에 대한 설명으로 옳지 않은 것은?","options":["새 값을 1씩 증가 또는 임의 값으로 정할 수 있다","레코드를 삭제하면 남은 레코드의 번호가 자동으로 다시 매겨진다","새 레코드를 추가하면 Access가 고유한 번호를 자동으로 넣는다","사용자가 값을 직접 입력하거나 수정할 수 없다"],"answer":1,"explain":"삭제된 일련 번호는 다시 쓰이지 않고 남은 번호도 바뀌지 않는다."},{"id":"db-0050","subject":"database","levels":["c1"],"topic":"테이블","q":"통화 데이터 형식에 대한 설명으로 옳은 것은?","options":["소수점 왼쪽 15자리, 오른쪽 4자리까지 정확하게 저장한다","소수점 왼쪽 10자리, 오른쪽 2자리까지 정확하게 저장한다","소수점 왼쪽 28자리, 오른쪽 8자리까지 정확하게 저장한다","소수점 아래 값은 저장하지 않고 정수만 저장한다"],"answer":0,"explain":"통화 형식은 8바이트로 정수부 15자리·소수부 4자리까지 반올림 오차 없이 계산한다."},{"id":"db-0051","subject":"database","levels":["c1"],"topic":"테이블","q":"한 레코드의 한 필드에 이미지·문서 등 여러 개의 파일을 함께 저장할 수 있는 데이터 형식은?","options":["OLE 개체","하이퍼링크","긴 텍스트","첨부 파일"],"answer":3,"explain":"첨부 파일 형식은 한 필드에 여러 파일을 넣을 수 있다. OLE 개체는 한 필드에 개체 하나만 연결·포함한다."},{"id":"db-0054","subject":"database","levels":["c1"],"topic":"테이블","q":"필드에 값을 입력할 때 다른 테이블·쿼리의 값이나 직접 입력한 값 목록에서 골라 넣을 수 있도록 만들어 주는 것은?","options":["캡션 속성","유효성 검사 규칙","입력 마스크 마법사","조회 마법사"],"answer":3,"explain":"조회 마법사는 콤보 상자 형태의 목록을 만들어 준다. 입력 마스크는 입력 형식, 유효성 검사 규칙은 값 범위를 제한한다."},{"id":"db-0056","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크가 \"LL00\"인 필드에 입력할 수 있는 값은?","options":["AB12","AB1","A123","1B23"],"answer":0,"explain":"L은 문자 필수, 0은 숫자 필수이므로 문자 2개 + 숫자 2개가 모두 있어야 한다. \"AB1\"은 숫자가 하나 모자라다."},{"id":"db-0057","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 기호 중 영문자와 숫자 중 하나를 반드시 입력해야 하는 것은?","options":["?","A","C","a"],"answer":1,"explain":"A는 문자·숫자 필수, a는 문자·숫자 선택, ?는 문자 선택, C는 모든 문자·공백 선택이다."},{"id":"db-0058","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 기호 중 입력한 영문자를 모두 대문자로 바꾸어 주는 것은?","options":["\\","!","<",">"],"answer":3,"explain":"> 다음 문자는 대문자, < 다음 문자는 소문자로 바뀐다. !는 오른쪽부터 채우기, \\는 다음 문자를 그대로 표시한다."},{"id":"db-0059","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크를 \"000-0000;0;#\"으로 지정했다. 설명으로 옳은 것은?","options":["하이픈(-)도 함께 저장되고 입력 자리는 0으로 표시된다","숫자를 선택 입력할 수 있고 입력 자리는 _로 표시된다","하이픈(-)은 저장되지 않고 입력 자리는 #으로 표시된다","하이픈(-)도 함께 저장되고 입력 자리는 #으로 표시된다"],"answer":3,"explain":"두 번째 구역 0은 리터럴 문자를 함께 저장, 1이나 생략은 저장하지 않음을 뜻한다. 세 번째 구역은 자리 표시자 문자이다."},{"id":"db-0061","subject":"database","levels":["c1"],"topic":"테이블","q":"[성별] 필드에 \"남\" 또는 \"여\"만 입력되도록 하는 유효성 검사 규칙으로 옳은 것은?","options":["Like(\"남\",\"여\")","Is \"남\" Or \"여\"","In(\"남\",\"여\")","Between \"남\" And \"여\""],"answer":2,"explain":"In(값 목록)은 목록 중 하나만 허용한다. Between \"남\" And \"여\"는 문자열 범위 비교라 다른 글자도 통과할 수 있다."},{"id":"db-0063","subject":"database","levels":["c1"],"topic":"테이블","q":"짧은 텍스트 필드의 \"필수\"를 예, \"빈 문자열 허용\"을 예로 지정했다. 옳은 것은?","options":["빈 문자열(\"\")은 입력할 수 없지만 Null은 입력할 수 있다","빈 문자열(\"\")과 Null 모두 입력할 수 있다","빈 문자열(\"\")과 Null 모두 입력할 수 없다","빈 문자열(\"\")은 입력할 수 있지만 Null로 비워 둘 수는 없다"],"answer":3,"explain":"필수=예는 Null을 막고, 빈 문자열 허용=예는 길이 0 문자열을 허용한다. 둘은 서로 다른 값이다."},{"id":"db-0070","subject":"database","levels":["c1"],"topic":"테이블","q":"데이터가 들어 있는 짧은 텍스트 필드의 필드 크기를 50에서 10으로 줄이고 저장했을 때의 결과로 옳은 것은?","options":["10자를 넘는 값은 앞 10자만 남고 나머지는 잘린다","10자를 넘는 값이 있는 레코드는 모두 삭제된다","10자를 넘는 값이 있으면 필드 크기를 바꿀 수 없다","이미 입력된 값은 그대로 두고 새 값만 10자로 제한된다"],"answer":0,"explain":"필드 크기를 줄이면 데이터가 잘려 손실될 수 있다는 경고가 나오고, 계속하면 넘는 부분이 잘린다."},{"id":"db-0072","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT AVG(급여) FROM 사원; 의 결과는?","options":["260","300","350","325"],"answer":3,"explain":"AVG는 Null을 제외한 300·250·400·350의 평균 1300/4 = 325이다. Null을 0으로 보고 5로 나누면 260이 된다."},{"id":"db-0074","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT 이름 FROM 사원 WHERE 급여 BETWEEN 300 AND 400; 의 결과 행 수는?","options":["2","4","1","3"],"answer":3,"explain":"BETWEEN은 양 끝 값을 포함하므로 300·400·350인 3명이다. Null은 비교 결과가 참이 아니라 제외된다."},{"id":"db-0076","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT TOP 2 이름 FROM 사원 ORDER BY 급여 DESC; 의 결과로 옳은 것은?","options":["박다온, 최라희","김가람, 이나래","박다온, 김가람","이나래, 김가람"],"answer":0,"explain":"급여 내림차순으로 400(박다온), 350(최라희) 순이며 TOP 2는 앞 2행이다. 오름차순으로 착각하면 이나래·김가람을 고르게 된다."},{"id":"db-0078","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT 이름 FROM 사원 WHERE 부서 = '영업' OR 급여 >= 350; 의 결과 행 수는?","options":["3","4","2","1"],"answer":0,"explain":"영업인 김가람·박다온에 급여 350 이상인 최라희가 더해져 3명이다(박다온은 두 조건 모두지만 한 번만 나온다). AND였다면 1명이다."},{"id":"db-0079","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). UPDATE 사원 SET 급여 = 급여 * 1.1 WHERE 부서 = '개발'; 을 실행한 뒤의 결과로 옳은 것은?","options":["최라희는 385가 되고 정마루는 0이 된다","모든 사원의 급여가 10% 오른다","최라희는 385가 되고 정마루는 Null 그대로이다","최라희와 정마루 모두 385가 된다"],"answer":2,"explain":"Null에 어떤 수를 곱해도 Null이다. WHERE 조건 때문에 개발 부서만 바뀐다."},{"id":"db-0080","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). SELECT SUM(급여) FROM 사원 WHERE 부서 IN ('영업', '총무'); 의 결과는?","options":["650","1300","700","950"],"answer":3,"explain":"영업 300+400과 총무 250을 더해 950이다."},{"id":"db-0083","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Access 쿼리의 조건 Like \"A#*\"에 해당하는 값은?","options":["BA1","AB1","A1B","A"],"answer":2,"explain":"#은 숫자 한 자리를 뜻하므로 A 다음에 숫자가 와야 한다. *는 그 뒤 글자가 없어도 된다."},{"id":"db-0092","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리를 실행할 때마다 검색할 이름의 일부를 입력받아 그 글자가 들어 있는 레코드를 찾으려 한다. [이름] 필드의 조건으로 옳은 것은?","options":["In (\"*\", [이름 일부 입력], \"*\")","= \"*\" & [이름 일부 입력] & \"*\"","Like \"*[이름 일부 입력]*\"","Like \"*\" & [이름 일부 입력] & \"*\""],"answer":3,"explain":"매개 변수는 대괄호로 쓰고 &로 와일드카드와 연결해 Like로 비교한다. 따옴표 안에 넣으면 매개 변수가 아닌 글자로 취급된다."},{"id":"db-0094","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"한 테이블에서 같은 거래처명이 두 번 이상 입력된 레코드를 찾을 때 쓰는 쿼리 마법사는?","options":["크로스탭 쿼리 마법사","불일치 검색 쿼리 마법사","추가 쿼리 마법사","중복 데이터 검색 쿼리 마법사"],"answer":3,"explain":"같은 필드 값이 반복되는 레코드는 중복 데이터 검색 쿼리로 찾는다. 불일치 검색은 두 테이블 사이에서 짝 없는 레코드를 찾는다."},{"id":"db-0100","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Access 쿼리에서 입사일이 2026년 1월 1일 이후인 레코드를 찾는 조건으로 옳은 것은?","options":[">= \"2026-01-01\"#",">= [2026-01-01]",">= {2026-01-01}",">= #2026-01-01#"],"answer":3,"explain":"Access에서 날짜 상수는 #으로 감싼다. 대괄호는 필드·매개 변수 이름에 쓴다."},{"id":"db-0101","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[판매] 테이블(지점, 금액)에 (강남, 200) (강북, 300) (강남, 350) (서초, 100) (강북, 150) (서초, 500)이 있다. SELECT 지점 FROM 판매 GROUP BY 지점 HAVING SUM(금액) >= 500; 의 결과로 옳은 것은?","options":["서초","강남","강남, 서초","강남, 강북, 서초"],"answer":2,"explain":"지점별 합계는 강남 550, 강북 450, 서초 600이므로 500 이상인 강남·서초가 나온다."},{"id":"db-0103","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금(QBE)에서는 만들 수 없고 SQL 보기에서 직접 작성해야 하는 쿼리는?","options":["매개 변수 쿼리","업데이트 쿼리","크로스탭 쿼리","통합(UNION) 쿼리"],"answer":3,"explain":"통합·전달·데이터 정의 쿼리는 SQL 전용 쿼리이다. 매개 변수·업데이트·크로스탭은 디자인 눈금에서 만들 수 있다."},{"id":"db-0110","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 \"기본 보기\" 속성 중 여러 레코드를 폼 형식 그대로 한 화면에 이어서 표시하는 것은?","options":["분할 표시 폼","단일 폼","연속 폼","데이터시트"],"answer":2,"explain":"연속 폼은 레코드마다 같은 폼 모양을 반복한다. 단일 폼은 한 번에 한 레코드만 보여 준다."},{"id":"db-0114","subject":"database","levels":["c1"],"topic":"폼","q":"하위 폼에 대한 설명으로 옳지 않은 것은?","options":["하위 폼은 데이터시트나 연속 폼 형식으로 표시하는 경우가 많다","기본 폼은 다 쪽, 하위 폼은 일 쪽 테이블을 원본으로 하는 것이 일반적이다","일대다 관계의 데이터를 함께 보여 줄 때 주로 쓴다","\"기본 필드 연결\"과 \"하위 필드 연결\" 속성으로 두 폼을 연결한다"],"answer":1,"explain":"기본 폼이 일 쪽(예: 고객), 하위 폼이 다 쪽(예: 주문)이다. 연결 필드로 기본 폼의 현재 레코드와 관련된 것만 보여 준다."},{"id":"db-0117","subject":"database","levels":["c1"],"topic":"폼","q":"콤보 상자에서 목록에 없는 값을 사용자가 직접 입력하지 못하게 하려면 어떤 속성을 예로 지정해야 하는가?","options":["목록 행 수","바운드 열","열 개수","목록 값만 허용"],"answer":3,"explain":"목록 값만 허용=예이면 목록 밖 값 입력이 거부된다. 목록 행 수는 펼쳤을 때 보이는 줄 수이다."},{"id":"db-0120","subject":"database","levels":["c1"],"topic":"폼","q":"콤보 상자와 목록 상자에 대한 설명으로 옳은 것은?","options":["콤보 상자는 목록에 없는 값을 어떤 경우에도 입력할 수 없다","목록 상자는 공간을 아끼려고 평소에는 한 줄만 표시된다","콤보 상자에는 행 원본 속성을 지정할 수 없다","목록 상자는 목록에 있는 값만 고를 수 있고 직접 입력할 수 없다"],"answer":3,"explain":"목록 상자는 항상 펼쳐져 있으며 입력란이 없다. 콤보 상자는 접혀 있다가 펼치며, 목록 값만 허용이 아니요이면 직접 입력도 된다."},{"id":"db-0121","subject":"database","levels":["c1"],"topic":"폼","q":"컨트롤의 \"사용 가능\" 속성을 아니요로 지정했을 때의 결과로 옳은 것은?","options":["컨트롤이 정상으로 표시되고 포커스는 받지만 값은 고칠 수 없다","컨트롤이 폼 보기에서 화면에 표시되지 않는다","컨트롤의 값이 저장될 때 Null로 바뀐다","컨트롤이 흐리게 표시되고 포커스를 받을 수 없다"],"answer":3,"explain":"사용 가능=아니요는 흐리게 바뀌고 선택도 안 된다. 포커스는 받되 수정만 막는 것은 잠금=예, 숨기는 것은 표시=아니요이다."},{"id":"db-0122","subject":"database","levels":["c1"],"topic":"폼","q":"[만들기] 탭의 [폼] 그룹에서 바로 만들 수 있는 항목이 아닌 것은?","options":["레이블","폼 마법사","폼 디자인","탐색"],"answer":0,"explain":"레이블(우편물 레이블)은 [보고서] 그룹에 있다. [폼] 그룹에는 폼·폼 디자인·새 폼·폼 마법사·탐색·기타 폼이 있다."},{"id":"db-0126","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서의 구역 중 보고서 첫 페이지 맨 위에 한 번만 표시되는 것은?","options":["그룹 머리글","보고서 머리글","페이지 머리글","본문"],"answer":1,"explain":"보고서 머리글은 첫 페이지에 한 번만 나온다. 페이지 머리글은 페이지마다 위쪽에 나온다."},{"id":"db-0130","subject":"database","levels":["c1"],"topic":"보고서","q":"전체 5페이지인 보고서의 2페이지에서 =\"Page \" & [Page] & \" of \" & [Pages] 식의 결과는?","options":["2 of 5","Page 2/5","Page 5 of 2","Page 2 of 5"],"answer":3,"explain":"문자열과 [Page], [Pages]가 순서대로 연결된다. 따옴표 안의 공백도 그대로 출력된다."},{"id":"db-0136","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 본문의 [지점] 텍스트 상자에서 바로 위 레코드와 값이 같으면 표시하지 않게 하는 속성은?","options":["중복 내용 숨기기","확장 가능","표시","누적 합계"],"answer":0,"explain":"중복 내용 숨기기=예이면 이전 레코드와 같은 값은 비워서 보여 준다. 표시=아니요는 항상 숨긴다."},{"id":"db-0139","subject":"database","levels":["c1"],"topic":"보고서","q":"부서별로 그룹화한 보고서의 그룹 머리글에 =Count(*)를 넣었을 때 표시되는 값은?","options":["해당 부서에 속한 레코드 수","현재 페이지에 인쇄된 레코드 수","부서 그룹의 개수","보고서 전체 레코드 수"],"answer":0,"explain":"그룹 머리글·바닥글의 집계 함수는 그 그룹 범위로 계산되므로 그 부서의 레코드 수가 나온다."},{"id":"db-0141","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"매크로 함수와 기능의 연결이 옳지 않은 것은?","options":["OpenForm - 폼을 연다","ApplyFilter - 현재 레코드를 삭제한다","MessageBox - 메시지 상자를 표시한다","RunSQL - SQL 문으로 실행 쿼리를 실행한다"],"answer":1,"explain":"ApplyFilter는 폼·보고서에 필터나 조건을 적용해 레코드를 거른다. 레코드 삭제와는 관계가 없다."},{"id":"db-0145","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"[사원] 테이블(사번, 이름, 부서, 급여)에 다음 5개 레코드가 있다. (1, 김가람, 영업, 300) (2, 이나래, 총무, 250) (3, 박다온, 영업, 400) (4, 최라희, 개발, 350) (5, 정마루, 개발, Null). DLookup(\"이름\", \"사원\", \"사번 = 3\")의 결과는?","options":["최라희","박다온","이나래","3"],"answer":1,"explain":"DLookup(필드, 도메인, 조건)은 조건에 맞는 레코드의 필드 값을 돌려준다. 사번 3은 박다온이다."},{"id":"db-0148","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"DateDiff(\"d\", #2026-10-01#, #2026-10-04#)의 결과는?","options":["1","3","4","-3"],"answer":1,"explain":"DateDiff는 두 번째 날짜에서 첫 번째 날짜를 뺀 간격을 구하므로 4일 - 1일 = 3이다. 순서를 바꾸면 -3이 된다."},{"id":"db-0151","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 마법사를 사용할 수 있는 데이터 형식은?","options":["숫자와 통화","짧은 텍스트와 날짜/시간","일련 번호와 Yes/No","긴 텍스트와 OLE 개체"],"answer":1,"explain":"입력 마스크 마법사는 짧은 텍스트와 날짜/시간 형식의 필드에서 제공된다. 숫자·통화는 마법사 없이 직접 입력 마스크를 쓴다."},{"id":"db-0152","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 속성에서 암호(Password)를 선택했을 때의 효과로 옳은 것은?","options":["저장되는 값이 암호화되며 데이터베이스 파일을 열 때마다 비밀번호를 묻는다","입력한 값은 저장되지 않고 한 번 쓴 뒤 사라진다","입력하는 문자는 *로 표시되지만 저장되는 값은 입력한 그대로이다","레코드를 보려면 데이터시트에서 별도 암호를 입력해야 한다"],"answer":2,"explain":"암호 마스크는 화면 표시만 가린다. 데이터가 암호화되는 것은 아니다."},{"id":"db-0153","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 구역에 대한 설명으로 옳은 것은?","options":["폼 바닥글은 레코드마다 한 번씩 반복되어 표시된다","본문 구역은 폼에 한 번만 나타나며 레코드 수에 관계없이 항상 하나의 레코드만 보여 준다","폼 머리글은 폼 보기에서 위쪽에 고정되어 보이고 인쇄하면 첫 페이지 맨 위에만 나온다","페이지 머리글은 폼 보기 화면에서도 모든 레코드 위에 항상 표시된다"],"answer":2,"explain":"폼 머리글·바닥글은 폼당 한 번씩 나타난다. 본문은 레코드를 표시하고, 페이지 머리글·바닥글은 인쇄할 때만 적용된다."},{"id":"db-0154","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"InStr(4, \"abcabc\", \"c\")의 결과는?","options":["6","3","4","0"],"answer":0,"explain":"4번째 글자부터 \"c\"를 찾으므로 처음 만나는 c는 6번째 위치이다."},{"id":"db-0155","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금의 [요약] 행에서 선택할 수 없는 항목은?","options":["표준 편차","처음","중앙값","식"],"answer":2,"explain":"[요약] 행에는 그룹화, 합계, 평균, 최소, 최대, 개수, 표준 편차, 분산, 처음, 마지막, 식, 조건이 있다."},{"id":"db-0156","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"다음 중 데이터시트에서 결과를 직접 수정할 수 없는 쿼리는?","options":["한 테이블에서 조건만 지정한 선택 쿼리","기본키가 포함된 한 테이블을 정렬해 보여 주는 선택 쿼리","일대일 관계의 두 테이블을 조인한 선택 쿼리","지점별 합계와 평균을 구하는 요약(집계) 쿼리"],"answer":3,"explain":"요약 쿼리의 결과는 여러 레코드가 합쳐진 값이므로 수정할 수 없다. 단일 테이블 선택 쿼리와 일대일 조인 쿼리는 수정할 수 있다."},{"id":"db-0157","subject":"database","levels":["c1"],"topic":"테이블","q":"텍스트 파일 가져오기 마법사의 [구분]과 [고정 너비]에 대한 설명으로 옳은 것은?","options":["구분은 글자 위치(열 경계선)로 필드를 나누고 고정 너비는 쉼표 같은 구분 기호로 필드를 나눈다","구분은 한 열짜리 파일에, 고정 너비는 여러 열 파일에만 쓸 수 있다","구분은 첫 행을 필드 이름으로 쓸 수 있으나 고정 너비는 쓸 수 없다","구분은 쉼표·탭 같은 구분 기호로 필드를 나누고 고정 너비는 열 위치로 필드를 나눈다"],"answer":3,"explain":"구분 방식은 구분 기호, 고정 너비 방식은 글자 위치(열 경계선)로 필드를 구분한다."},{"id":"db-0158","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[성적] 테이블\n이름 | 반 | 점수\n가 | 1 | 80\n나 | 2 | 90\n다 | 1 | 90\n라 | 2 | 80\n마 | 1 | 70\n\nSELECT 이름 FROM 성적 ORDER BY 반 ASC, 점수 DESC; 의 결과 순서는?","options":["다, 가, 마, 나, 라","마, 가, 다, 라, 나","다, 나, 가, 라, 마","나, 라, 다, 가, 마"],"answer":0,"explain":"먼저 반 오름차순으로 묶고 같은 반 안에서 점수 내림차순으로 정렬한다. 1반은 다(90), 가(80), 마(70), 2반은 나(90), 라(80)이다."},{"id":"db-0159","subject":"database","levels":["c1"],"topic":"관계·키","q":"후보키가 {회원번호}, {주민번호}, {이메일} 세 개이고 회원번호를 기본키로 정했다. 대체키는 몇 개이며 무엇인가?","options":["3개 - 회원번호, 주민번호, 이메일","1개 - 회원번호","0개 - 기본키가 정해지면 대체키는 없어진다","2개 - 주민번호, 이메일"],"answer":3,"explain":"후보키 중 기본키로 선택되지 않은 나머지가 대체키이다."},{"id":"db-0160","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[고객] 테이블\n이름 | 이메일\n가 | a@x.kr\n나 | Null\n다 | c@x.kr\n라 | Null\n마 | Null\n\nSELECT COUNT(*), COUNT(이메일), COUNT(*)-COUNT(이메일) FROM 고객; 의 결과를 차례로 나타낸 것은?","options":["5, 5, 0","5, 2, 3","2, 2, 0","3, 2, 1"],"answer":1,"explain":"COUNT(*)는 모든 행, COUNT(이메일)은 Null이 아닌 값만 센다. 둘의 차이 3은 이메일이 비어 있는 행 수이다."},{"id":"db-0161","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"값이 Apple, Berry, Cabin, Dove, Axe인 필드에 Like \"[AB]*\" 조건을 지정했을 때 조회되는 값의 개수는?","options":["2","4","3","5"],"answer":2,"explain":"대괄호 안의 문자 중 하나로 시작하는 값에 일치한다. A로 시작하는 Apple, Axe와 B로 시작하는 Berry, 모두 3개이다."},{"id":"db-0162","subject":"database","levels":["c1"],"topic":"보고서","q":"[그룹, 정렬 및 요약] 창에서 그룹 기준 [지점](오름차순) 다음에 정렬 기준 [금액](내림차순)을 이 순서로 지정했다. 결과로 옳은 것은?","options":["전체가 금액 내림차순으로 정렬되어 나오고 같은 금액끼리는 지점 오름차순으로 나온다","지점별로 묶여 지점 오름차순으로 나오고, 같은 지점 안에서 금액이 큰 순서로 나온다","지점은 오름차순이지만 지점 안의 정렬 순서는 정해지지 않는다","지점별 그룹은 만들어지지만 금액 정렬은 적용되지 않는다"],"answer":1,"explain":"창의 위쪽 항목이 우선이다. 먼저 지점으로 그룹을 만들고 그 안에서 금액으로 다시 정렬한다."},{"id":"db-0163","subject":"database","levels":["c1"],"topic":"DB 개념","q":"분산 데이터베이스에서 사용자가 데이터가 실제로 어느 컴퓨터에 저장되어 있는지 몰라도 접근하게 해 주는 투명성은?","options":["분할 투명성","복제 투명성","위치 투명성","장애 투명성"],"answer":2,"explain":"위치 투명성은 저장 장소를 숨기고, 분할 투명성은 데이터가 쪼개져 있음을, 복제 투명성은 복사본이 있음을, 장애 투명성은 장애가 있어도 일관되게 보이게 한다."},{"id":"db-0164","subject":"database","levels":["c1"],"topic":"폼","q":"탭 컨트롤에 대한 설명으로 옳은 것은?","options":["탭마다 별도의 폼 개체가 만들어져 따로 저장된다","탭 페이지는 최대 3개까지만 추가할 수 있다","탭마다 레코드 원본을 서로 다르게 지정해 탭별로 다른 데이터를 보여 줄 수 있다","한 폼 안에 여러 페이지를 만들어 컨트롤을 탭별로 나누어 배치할 수 있다"],"answer":3,"explain":"탭 컨트롤은 한 폼의 화면 공간을 여러 페이지로 나누는 도구이다. 폼의 레코드 원본은 하나이다."},{"id":"db-0165","subject":"database","levels":["c1"],"topic":"보고서","q":"[페이지 설정] 대화 상자의 [인쇄 옵션] 탭에서 지정하는 항목은?","options":["여백과 데이터만 인쇄","용지 방향과 용지 크기","열 개수와 열 간격","머리글과 바닥글의 반복 여부"],"answer":0,"explain":"[인쇄 옵션]에서는 여백과 데이터만 인쇄를, [페이지] 탭에서는 용지 방향·크기를, [열] 탭에서는 열 설정을 지정한다."},{"id":"db-0166","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"다음 VBA 코드를 실행했을 때 MsgBox에 표시되는 값은?\nDim n As Integer, r As String\nn = 72\nSelect Case n\n  Case 90 To 100: r = \"A\"\n  Case 70 To 89: r = \"B\"\n  Case 60 To 89: r = \"C\"\n  Case Else: r = \"D\"\nEnd Select\nMsgBox r","options":["C","D","B","오류가 발생한다"],"answer":2,"explain":"Select Case는 처음으로 일치하는 Case만 실행하고 끝낸다. 72는 70 To 89에 먼저 해당하므로 B이다."},{"id":"db-0167","subject":"database","levels":["c1"],"topic":"테이블","q":"계산 데이터 형식으로 만든 필드의 값을 데이터시트에서 직접 고치려 하면 어떻게 되는가?","options":["값을 고치면 식이 지워지고 입력한 값으로 바뀐다","수정은 가능하지만 저장하는 순간 식의 결과로 다시 되돌아가서 원래 값이 된다","식으로 계산되는 값이므로 직접 입력하거나 수정할 수 없다","시스템 관리자 권한이 있을 때만 수정할 수 있다"],"answer":2,"explain":"계산 필드는 식의 결과가 표시될 뿐이어서 직접 편집이 불가능하다. 값을 바꾸려면 식에 쓰인 필드를 고친다."},{"id":"db-0168","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\nSELECT 상품명 FROM 상품 WHERE 단가 > ALL (SELECT 단가 FROM 상품 WHERE 분류 = \"문구\"); 의 결과로 옳은 것은?","options":["마우스, 키보드, 파일","마우스, 키보드","노트, 마우스, 키보드, 파일","결과가 없다"],"answer":0,"explain":"> ALL은 하위 쿼리 값 모두(800, 1500)보다 커야 하므로 1500 초과인 마우스, 키보드, 파일이다. ANY였다면 800 초과인 노트까지 포함된다."},{"id":"db-0169","subject":"database","levels":["c1"],"topic":"테이블","q":"일련 번호 필드의 [새 값] 속성을 [임의]로 지정하면?","options":["1부터 시작해 1씩 증가하는 값이 부여된다","새 레코드마다 임의의 정수가 부여된다","삭제된 레코드의 번호가 있으면 그 번호를 다시 사용한다","임의의 영문자로 이루어진 문자열이 부여된다"],"answer":1,"explain":"새 값은 증가 또는 임의 중에서 고른다. 임의를 선택하면 무작위 정수가 부여된다."},{"id":"db-0170","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access에서 두 테이블의 관련 필드 데이터 형식에 대한 설명으로 옳은 것은?","options":["일 쪽이 일련 번호이면 다 쪽도 일련 번호여야 연결된다","숫자 형식은 필드 크기(바이트와 긴 정수 등)가 달라도 참조 무결성을 설정할 수 있다","일 쪽이 짧은 텍스트여도 다 쪽을 숫자로 두면 참조 무결성을 설정할 수 있다","일 쪽이 일련 번호이면 다 쪽은 필드 크기가 긴 정수인 숫자 형식으로 만들 수 있다"],"answer":3,"explain":"관련 필드는 데이터 형식이 같아야 한다. 단, 일련 번호는 필드 크기가 긴 정수인 숫자와 짝지을 수 있다."},{"id":"db-0171","subject":"database","levels":["c1"],"topic":"관계·키","q":"학생과 과목의 다대다 관계를 위해 만든 [수강](학번, 과목코드, 점수)의 기본키로 가장 알맞은 것은?","options":["학번과 과목코드를 묶은 복합키","점수 필드 하나만 기본키로 지정","학번 필드 하나만 기본키로 지정","과목코드 필드 하나만 기본키로 지정"],"answer":0,"explain":"한 학생이 여러 과목을 듣고 한 과목을 여러 학생이 들으므로 학번과 과목코드의 조합이 레코드를 유일하게 구별한다."},{"id":"db-0172","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[성]이 \"김\", [이름]이 Null일 때 [성] + [이름]과 [성] & [이름]의 결과를 차례로 나타낸 것은?","options":["김, 김","Null, Null","김, Null","Null, 김"],"answer":3,"explain":"+ 연산자는 한쪽이 Null이면 결과가 Null이고, & 연산자는 Null을 빈 문자열처럼 취급해 \"김\"이 된다."},{"id":"db-0173","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[비고] 필드에 빈 문자열(\"\")이 저장된 레코드와 Null인 레코드가 섞여 있다. 비어 있는 레코드를 모두 찾는 조건으로 옳은 것은?","options":["Is Null And \"\"","Is Null Or \"\"","= \"\" Or Is Not Null","Like \"*\""],"answer":1,"explain":"Null과 빈 문자열은 서로 다른 값이라 둘을 함께 찾으려면 Is Null Or \"\"처럼 둘 다 지정해야 한다."},{"id":"db-0174","subject":"database","levels":["c1"],"topic":"테이블","q":"하이퍼링크 데이터 형식에 대한 설명으로 옳은 것은?","options":["여러 개의 파일을 한 필드에 묶어 압축 저장한다","웹 주소나 파일 경로를 저장하며 클릭하면 해당 대상으로 연결된다","다른 테이블의 값 목록에서 항목을 고르는 콤보 상자를 자동으로 만들어 준다","다른 필드의 값을 이용해 식을 계산하고 결과를 저장한다"],"answer":1,"explain":"하이퍼링크는 URL이나 파일 경로를 저장해 클릭하면 열리는 형식이다. 여러 파일 저장은 첨부 파일, 계산은 계산 형식이다."},{"id":"db-0175","subject":"database","levels":["c1"],"topic":"DB 개념","q":"Access 데이터베이스에 암호를 설정하려면 파일을 어떤 방식으로 열어야 하는가?","options":["[열기] 대화 상자에서 [읽기 전용으로 열기]를 선택한다","파일을 신뢰할 수 있는 위치로 복사한 뒤 더블클릭하는 일반적인 방법으로 열어 매크로를 허용한다","[열기] 대화 상자에서 [열기] 단추의 목록을 펼쳐 [단독으로 열기]를 선택한다","[콘텐츠 사용]을 누르지 않고 보안 경고가 있는 채로 연다"],"answer":2,"explain":"암호 설정은 파일을 단독(독점)으로 열어야 가능하다. 다른 사용자가 쓰고 있으면 설정할 수 없다."},{"id":"db-0176","subject":"database","levels":["c1"],"topic":"보고서","q":"그룹 머리글 구역의 [반복 실행 구역] 속성을 예로 지정하면?","options":["그룹마다 머리글이 두 번씩 인쇄된다","그룹 머리글이 해당 그룹의 마지막 페이지 머리글 위치로 옮겨져서 한 번만 인쇄된다","그룹이 다음 페이지로 이어지면 새 페이지 위에도 그룹 머리글이 다시 인쇄된다","그룹 머리글의 내용이 레코드마다 반복해서 인쇄된다"],"answer":2,"explain":"반복 실행 구역은 한 그룹이 페이지를 넘길 때 새 페이지에서도 그룹 머리글을 다시 표시한다."},{"id":"db-0177","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션 R(차수 3, 카디널리티 4)과 S(차수 2, 카디널리티 5)의 카티션 프로덕트 R × S 결과의 차수와 카디널리티를 차례로 나타낸 것은?","options":["5, 20","5, 9","6, 20","6, 9"],"answer":0,"explain":"카티션 프로덕트의 차수는 두 차수의 합(3+2=5), 카디널리티는 두 카디널리티의 곱(4×5=20)이다."},{"id":"db-0178","subject":"database","levels":["c1"],"topic":"DB 개념","q":"Access의 [데이터베이스 압축 및 복구]에 대한 설명으로 옳은 것은?","options":["여러 사용자가 동시에 쓰도록 테이블과 나머지 개체를 서로 다른 두 개의 파일로 나누어 각각 따로 저장한다","파일에 암호를 설정하고 내용을 암호화해 허가되지 않은 열람을 막는다","삭제로 생긴 빈 공간을 정리해 파일 크기를 줄이고 손상된 파일을 고치는 기능이다","중복 데이터가 있는 테이블을 분석해 관련 있는 여러 테이블로 나누어 준다"],"answer":2,"explain":"압축 및 복구는 파일의 단편화를 없애고 오류를 복구한다. 파일 나누기는 데이터베이스 분할, 암호 설정은 별도 기능이다."},{"id":"db-0179","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 [팝업] 속성을 예로 지정했을 때의 설명으로 옳은 것은?","options":["폼을 닫기 전에는 다른 개체 창이나 폼으로 포커스를 옮길 수 없고 모든 작업이 중단된다","폼이 읽기 전용으로 열려 데이터를 수정할 수 없다","다른 창 위에 항상 떠 있는 창으로 열리지만 다른 개체 사용은 막지 않는다","폼이 항상 최대화된 상태로만 열린다"],"answer":2,"explain":"팝업은 항상 위에 있는 창이고, 포커스 이동을 막는 것은 모달 속성이다."},{"id":"db-0180","subject":"database","levels":["c1"],"topic":"테이블","q":"데이터시트의 필터 기능에 대한 설명으로 옳은 것은?","options":["조건에 맞지 않는 레코드는 테이블에서 영구히 삭제된다","필터는 쿼리 개체로 자동 저장되어 탐색 창에 나타난다","여러 필드에 필터를 걸면 조건이 OR로 연결되어 하나라도 맞는 레코드가 모두 표시된다","조건에 맞지 않는 레코드를 삭제하지 않고 일시적으로 숨기며 해제하면 다시 나타난다"],"answer":3,"explain":"필터는 보기 방식일 뿐 데이터를 지우지 않는다. 여러 필드의 필터 조건은 AND로 연결된다."},{"id":"db-0181","subject":"database","levels":["c1"],"topic":"DB 개념","q":"로그 기반 회복에서 체크포인트를 사용한다. 장애 시점에 T1은 체크포인트 이전에 완료, T2는 체크포인트 이후에 완료, T3은 장애 때까지 미완료 상태였다. 회복 처리를 바르게 나타낸 것은?","options":["T1은 처리하지 않고, T2는 REDO, T3은 UNDO한다","T1은 REDO, T2는 REDO, T3은 UNDO한다","T1은 처리하지 않고, T2는 UNDO, T3은 REDO한다","T1은 UNDO, T2는 처리하지 않고, T3은 UNDO한다"],"answer":0,"explain":"체크포인트 이전에 완료된 T1은 이미 디스크에 반영되어 있어 제외한다. 이후 완료된 T2는 REDO, 미완료 T3은 UNDO한다."},{"id":"db-0182","subject":"database","levels":["c1"],"topic":"DB 개념","q":"교착상태(Deadlock)에 대한 설명으로 옳은 것은?","options":["한 트랜잭션이 실패해 롤백된 뒤 다른 트랜잭션이 처음부터 다시 실행되는 상태이다","여러 트랜잭션이 같은 데이터를 읽기만 하면서 공유 로크를 함께 가지고 서로 방해하지 않고 진행하는 상태이다","트랜잭션이 끝나기 전에 변경 결과가 다른 트랜잭션에게 그대로 보이는 상태이다","둘 이상의 트랜잭션이 서로 상대가 잡은 로크가 풀리기를 기다리며 더 진행하지 못하는 상태이다"],"answer":3,"explain":"교착상태는 서로의 로크 해제를 기다리는 순환 대기이다. 공유 로크를 함께 갖는 것은 정상 동작이다."},{"id":"db-0183","subject":"database","levels":["c1"],"topic":"테이블","q":"[점수] 필드에 0 이상 100 이하의 값만 입력되도록 하는 유효성 검사 규칙으로 옳은 것은?","options":["Between 0 And 100","In(0, 100)",">=0 Or <=100",">0 And <100 And Is Not Null"],"answer":0,"explain":"Between 0 And 100은 경계 값을 포함한다. In(0, 100)은 0과 100만, Or는 모든 숫자를, >0 And <100은 경계를 제외한다."},{"id":"db-0184","subject":"database","levels":["c1"],"topic":"DB 개념","q":"E-R 다이어그램에서 다중 값 속성과 기본키 속성을 나타내는 방법을 바르게 짝지은 것은?","options":["다중 값 속성은 점선 타원, 기본키 속성은 굵은 선으로 그린 이중 타원","다중 값 속성은 이중 타원, 기본키 속성은 밑줄 친 이름의 타원","다중 값 속성은 밑줄 친 타원, 기본키 속성은 점선 타원","다중 값 속성은 마름모, 기본키 속성은 이중 사각형"],"answer":1,"explain":"다중 값 속성은 이중 타원, 키 속성은 밑줄로 나타낸다. 점선 타원은 유도 속성, 이중 사각형은 약한 개체이다."},{"id":"db-0185","subject":"database","levels":["c1"],"topic":"DB 개념","q":"SQL의 COMMIT 명령에 대한 설명으로 옳은 것은?","options":["트랜잭션이 바꾼 내용을 모두 취소하고 트랜잭션을 시작하기 전의 상태로 데이터베이스를 완전히 되돌린다","트랜잭션이 바꾼 내용을 영구히 확정하며, 이후에는 ROLLBACK으로 되돌릴 수 없다","다른 사용자에게 특정 테이블에 대한 사용 권한을 나누어 준다","트랜잭션 중간에 부분적으로 되돌아갈 저장 지점을 만들어 둔다"],"answer":1,"explain":"COMMIT은 변경을 확정한다. 변경 취소는 ROLLBACK, 권한 부여는 GRANT, 중간 지점 설정은 SAVEPOINT의 일이다."},{"id":"db-0186","subject":"database","levels":["c1"],"topic":"테이블","q":"짧은 텍스트 필드의 형식 속성을 >로 지정하고 abc를 입력했을 때의 결과는?","options":["ABC로 바뀌어 저장되고 표시도 ABC이다","화면에는 abc 그대로 보이지만 저장되는 값은 모두 대문자 ABC로 바뀐다","첫 글자만 대문자인 Abc로 표시된다","화면에는 ABC로 보이지만 저장된 값은 abc 그대로이다"],"answer":3,"explain":"형식 속성은 표시 모양만 바꾼다. >는 대문자로 표시하며 저장되는 값은 입력한 그대로이다."},{"id":"db-0187","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\n[주문] 테이블\n번호 | 상품 | 수량\n1 | A1 | 10\n2 | A3 | 2\n3 | A1 | 5\n4 | A4 | 1\n5 | A2 | 20\n6 | A3 | 1\n\nSELECT 상품.분류, SUM(주문.수량*상품.단가) AS 금액 FROM 주문 INNER JOIN 상품 ON 주문.상품 = 상품.코드 GROUP BY 상품.분류 HAVING SUM(주문.수량*상품.단가) >= 50000; 의 결과는?","options":["문구 | 38500","문구 | 38500, 전자 | 61000","전자 | 61000","결과가 없다"],"answer":2,"explain":"전자는 3×12000+25000=61000이고 문구는 15×1500+20×800=38500이어서 HAVING 조건(50000 이상)은 전자만 만족한다."},{"id":"db-0188","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 디자인 보기에서 [날짜 및 시간] 단추로 삽입했을 때 만들어지는 컨트롤의 컨트롤 원본은?","options":["=Date()와 =Time()","=Now()와 =Today()","=Date와 [Time] 필드","[Date]와 [Time] 필드"],"answer":0,"explain":"날짜 및 시간 삽입은 =Date()와 =Time()을 컨트롤 원본으로 하는 텍스트 상자를 만든다."},{"id":"db-0189","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"포함 매크로와 독립 매크로의 차이로 옳은 것은?","options":["포함 매크로는 별도 매크로 개체로 탐색 창에 나타나며 여러 폼과 보고서가 함께 공유하여 호출해 쓴다","포함 매크로는 개체의 이벤트 속성에 저장되어 그 개체와 함께 이동·복사되며 매크로 목록에는 나타나지 않는다","포함 매크로는 데이터시트 보기에서만 쓸 수 있는 매크로이다","포함 매크로는 VBA로 자동 변환된 뒤에만 저장된다"],"answer":1,"explain":"포함 매크로는 개체의 일부로 저장된다. 독립 매크로는 별도 개체로 만들어 여러 곳에서 호출한다."},{"id":"db-0190","subject":"database","levels":["c1"],"topic":"DB 개념","q":"2단계 로킹 규약(2PL)에 대한 설명으로 옳은 것은?","options":["로크를 푼 뒤에도 새 로크를 다시 얻을 수 있어 대기 시간이 줄고 교착상태가 생기지 않는다","모든 트랜잭션이 읽기 로크만 사용하도록 제한해 갱신 충돌이 처음부터 일어나지 않게 한다","로크를 얻기만 하는 확장 단계와 풀기만 하는 축소 단계로 나뉘며 직렬 가능성이 보장된다","트랜잭션이 끝나기 전에 로크를 전부 풀도록 강제해 교착상태를 완전히 막는다"],"answer":2,"explain":"2PL은 확장·축소 두 단계로 직렬 가능성을 보장하지만 교착상태를 막지는 못한다."},{"id":"db-0191","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"크로스탭 쿼리의 열 머리글을 사용자가 정한 항목과 순서로 고정하려고 설정하는 쿼리 속성은?","options":["열 머리글","고유 값","출력 필드","상위 값"],"answer":0,"explain":"쿼리 속성 시트의 [열 머리글]에 값을 쉼표로 지정하면 해당 열만 지정한 순서로 표시된다."},{"id":"db-0192","subject":"database","levels":["c1"],"topic":"관계·키","q":"[고객](고객번호: 1, 2, 3)과 [주문]이 일대다 관계이고 참조 무결성이 설정되어 있다. [주문]에 고객번호가 7인 레코드를 추가하려 하면?","options":["[고객]에 7번 레코드가 자동으로 만들어지고 주문이 저장된다","고객번호가 Null로 바뀌어 주문이 저장된다","경고 메시지가 나타난 뒤 관계가 해제되고 주문이 그대로 저장된다","[고객]에 7번이 없으므로 추가가 거부되고 오류 메시지가 나타난다"],"answer":3,"explain":"참조 무결성은 외래키 값이 일 쪽 기본키에 있어야 함을 보장한다. 일 쪽에 없는 값은 입력이 거부된다."},{"id":"db-0193","subject":"database","levels":["c1"],"topic":"테이블","q":"다음 중 인덱스를 설정할 수 없는 데이터 형식은?","options":["짧은 텍스트","숫자","긴 텍스트","날짜/시간"],"answer":2,"explain":"긴 텍스트, OLE 개체, 첨부 파일 형식은 인덱스를 지정할 수 없다."},{"id":"db-0194","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"VBA의 Round 함수로 Round(2.5)와 Round(3.5)를 계산한 결과를 차례로 나타낸 것은?","options":["2, 4","3, 4","2, 3","3, 3"],"answer":0,"explain":"Round는 .5를 가장 가까운 짝수로 맞추는 은행가 반올림을 한다. 2.5는 2, 3.5는 4가 된다."},{"id":"db-0195","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"17 Mod 5와 17 \\ 5의 결과를 차례로 나타낸 것은?","options":["2, 3","3, 2","2, 4","3, 3"],"answer":0,"explain":"Mod는 나머지(2), 정수 나누기 \\는 몫의 정수 부분(3)을 구한다."},{"id":"db-0196","subject":"database","levels":["c1"],"topic":"DB 개념","q":"데이터 사전(Data Dictionary)에 대한 설명으로 옳은 것은?","options":["데이터의 이름, 형식, 길이, 의미 같은 정의 정보를 모아 둔 메타데이터 저장소이다","사용자가 입력한 실제 업무 데이터를 모아 응용 프로그램이 직접 수정하는 저장소이다","데이터가 놓인 물리적 위치만 기록하고 속성의 정의는 담지 않는 파일이다","트랜잭션의 변경 내역을 순서대로 기록해 장애 때 회복에 쓰는 파일이다"],"answer":0,"explain":"데이터 사전은 데이터에 관한 데이터(메타데이터)를 담는다. 데이터의 물리적 위치 정보는 데이터 디렉터리가, 변경 내역은 로그가 담당한다."},{"id":"db-0197","subject":"database","levels":["c1"],"topic":"보고서","q":"본문의 [금액] 값이 보고서 전체 합계에서 차지하는 비율을 표시하는 텍스트 상자의 컨트롤 원본으로 옳은 것은?","options":["=[금액]/[Sum]","=Sum([금액])/[금액]","=[금액]/Count([금액])","=[금액]/Sum([금액])"],"answer":3,"explain":"본문에서 Sum([금액])은 보고서 전체의 합계이므로 각 레코드 금액을 나누면 비율이 된다. 표시 형식은 백분율로 지정한다."},{"id":"db-0198","subject":"database","levels":["c1"],"topic":"DB 개념","q":"관계형 데이터 모델의 용어와 Access의 용어를 짝지은 것 중 옳지 않은 것은?","options":["릴레이션 - 테이블","도메인 - 레코드","속성 - 필드","튜플 - 레코드"],"answer":1,"explain":"도메인은 속성이 가질 수 있는 값의 집합으로, 필드에 입력 가능한 값의 범위에 해당한다. 레코드는 튜플에 해당한다."},{"id":"db-0199","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"다음 매크로 함수와 그 기능의 연결 중 옳지 않은 것은?","options":["RunMacro - 컨트롤의 속성 값을 바꾼다","GoToRecord - 지정한 레코드로 이동한다","QuitAccess - Access를 종료한다","CloseWindow - 지정한 개체 창을 닫는다"],"answer":0,"explain":"RunMacro는 다른 매크로를 실행한다. 컨트롤 속성 변경은 SetProperty가 맡는다."},{"id":"db-0200","subject":"database","levels":["c1"],"topic":"테이블","q":"Access의 필드 이름에 대한 설명으로 옳은 것은?","options":["최대 64자까지 쓸 수 있고 공백을 포함할 수 있다","최대 255자까지 쓸 수 있으나 공백은 쓸 수 없다","마침표(.)와 느낌표(!)를 쓸 수 있으나 공백은 쓸 수 없다","공백으로 시작할 수 있고 대괄호([ ])도 쓸 수 있다"],"answer":0,"explain":"필드 이름은 64자 이내이며 공백은 가능하다. 마침표, 느낌표, 대괄호, 선행 공백은 쓸 수 없다."},{"id":"db-0201","subject":"database","levels":["c1"],"topic":"관계·키","q":"참조 무결성이 설정된 일대다 관계에서 다 쪽 외래키 필드가 Null인 레코드에 대한 설명으로 옳은 것은?","options":["외래키가 Null이면 참조 무결성 위반이므로 저장할 수 없다","일 쪽 기본키가 Null인 레코드와 자동으로 연결된다","저장되지만 일 쪽 레코드를 지울 때 함께 삭제된다","관련된 일 쪽 레코드가 없어도 저장할 수 있다"],"answer":3,"explain":"외래키는 일 쪽 기본키 값과 같거나 Null이어야 한다. Null은 아직 연결된 일 쪽 레코드가 없음을 뜻하며 허용된다."},{"id":"db-0202","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"OpenForm 매크로 함수의 [Where 조건문] 인수의 역할로 옳은 것은?","options":["폼을 열 때 조건에 맞는 레코드만 표시하도록 WHERE 형식의 식을 지정한다","폼을 열기 전에 먼저 실행해야 할 다른 매크로의 이름과 실행 순서를 함께 지정한다","폼이 열릴 때의 창 크기와 위치를 지정한다","폼의 레코드 원본을 다른 테이블로 바꾼다"],"answer":0,"explain":"Where 조건문은 폼에 표시할 레코드를 거르는 SQL WHERE 형식 조건이다. 예: [고객번호]=3."},{"id":"db-0203","subject":"database","levels":["c1"],"topic":"관계·키","q":"[관계] 창에서 두 테이블 사이의 관계를 삭제하는 방법으로 옳은 것은?","options":["[관계] 창에서 테이블을 숨기면 그 테이블의 관계도 함께 삭제된다","[관계 편집] 대화 상자에서 [새로 만들기]를 누르면 기존 관계가 지워지고 새 관계가 시작된다","관계선을 더블클릭하면 확인 없이 즉시 삭제된다","관계선을 클릭해 선택한 뒤 Delete 키를 누르거나 바로 가기 메뉴에서 [삭제]를 선택한다"],"answer":3,"explain":"관계선을 선택해 삭제한다. 테이블을 숨기는 것은 표시만 감추는 것이고, 더블클릭은 [관계 편집] 대화 상자를 연다."},{"id":"db-0204","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션에서 A → B이고 B → C일 때 A → C가 간접적으로 성립하는 종속을 무엇이라 하는가?","options":["기본키의 부분 함수 종속","이행적 함수 종속","완전 함수 종속","다치 종속"],"answer":1,"explain":"이행적 종속을 제거하면 제3정규형이 된다. 부분 종속은 기본키의 일부에 대한 종속이다."},{"id":"db-0205","subject":"database","levels":["c1"],"topic":"DB 개념","q":"릴레이션 주문(주문번호, 상품코드, 상품명, 수량)의 기본키는 (주문번호, 상품코드)이고 상품코드 → 상품명이 성립한다. 이 릴레이션의 정규형 상태로 옳은 것은?","options":["제2정규형이지만 이행 종속이 남아 있어 제3정규형은 되지 못한다","제3정규형이며 모든 결정자가 후보키이다","원자값이 아닌 속성이 있어 제1정규형도 아니다","제1정규형이지만 부분 함수 종속이 있어 제2정규형은 아니다"],"answer":3,"explain":"상품명이 기본키의 일부(상품코드)에만 종속되므로 제2정규형 위반이다. 속성은 모두 원자값이라 제1정규형은 만족한다."},{"id":"db-0206","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[거래처] 테이블(코드: 짧은 텍스트 5자 기본키, 상호: 짧은 텍스트 30자)을 만드는 Access SQL로 옳은 것은?","options":["CREATE TABLE 거래처 (코드 TEXT(5) KEY PRIMARY, 상호 TEXT(30));","CREATE 거래처 TABLE (코드 TEXT(5) PRIMARY KEY, 상호 TEXT(30));","CREATE TABLE 거래처 코드 TEXT(5) PRIMARY KEY, 상호 TEXT(30);","CREATE TABLE 거래처 (코드 TEXT(5) PRIMARY KEY, 상호 TEXT(30));"],"answer":3,"explain":"구문은 CREATE TABLE 테이블명 (필드명 형식 [제약], ...) 이다. 키워드는 PRIMARY KEY 순서이고 필드 정의 전체를 괄호로 묶어야 한다."},{"id":"db-0207","subject":"database","levels":["c1"],"topic":"DB 개념","q":"두 릴레이션 R과 S에 합집합(∪) 연산을 하려면 갖추어야 할 조건은?","options":["차수가 같고 대응하는 속성들의 도메인이 같아야 한다","카디널리티가 같고 두 릴레이션에 같은 튜플이 없어야 한다","기본키 이름이 같아야 하며 나머지 속성의 이름은 모두 달라야 한다","한 릴레이션의 속성 집합이 다른 릴레이션 속성 집합의 부분집합이어야 한다"],"answer":0,"explain":"합집합은 합병 가능(차수와 대응 도메인이 같음)한 릴레이션끼리만 가능하다. 카디널리티는 같을 필요가 없다."},{"id":"db-0208","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[수량]이 Null이고 [단가]가 1000인 레코드에서 Nz([수량], 1)*[단가]와 [수량]*[단가]의 결과를 차례로 나타낸 것은?","options":["1000, Null","1000, 0","0, Null","Null, 1000"],"answer":0,"explain":"Nz는 Null을 지정한 값(1)으로 바꾸므로 1000이 된다. Null이 포함된 곱셈은 결과가 Null이다."},{"id":"db-0209","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"날짜/시간 형식의 값 #2026-02-20#에 15를 더한 결과는? (2026년 2월은 28일까지)","options":["2026-03-08","2026-03-07","2026-03-06","2026-02-35"],"answer":1,"explain":"날짜에 숫자를 더하면 일수가 더해진다. 2월 20일에서 8일 뒤가 2월 28일이므로 나머지 7일을 더해 3월 7일이 된다."},{"id":"db-0210","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"VBA에서 DoCmd.SetWarnings False의 의미로 옳은 것은?","options":["오류가 발생해도 코드가 중단되지 않게 한다","매크로 보안 경고(콘텐츠 사용 알림)를 열 때마다 숨겨서 표시하지 않는다","실행 쿼리를 실행할 때 나타나는 확인 메시지를 표시하지 않는다","컴파일 경고 메시지를 표시하지 않는다"],"answer":2,"explain":"SetWarnings False는 추가·삭제·업데이트 쿼리의 확인 대화 상자를 생략한다. 사용 후 True로 되돌리는 것이 좋다."},{"id":"db-0211","subject":"database","levels":["c1"],"topic":"폼","q":"목록 상자의 [다중 선택] 속성 중 Ctrl 키 없이 항목을 클릭할 때마다 선택·해제가 번갈아 되는 방식은?","options":["없음","확장","단순","전체"],"answer":2,"explain":"단순은 클릭할 때마다 선택이 토글된다. 확장은 Shift·Ctrl 키로 범위나 개별 항목을 선택하며 없음은 하나만 선택된다."},{"id":"db-0212","subject":"database","levels":["c1"],"topic":"테이블","q":"Excel 통합 문서를 연결 테이블로 만든 뒤 Access에서 할 수 없는 작업은?","options":["필드를 추가하거나 삭제하는 구조 변경","기존 레코드의 값을 수정하는 작업","새 레코드를 추가하는 작업","연결 테이블을 쿼리의 원본으로 사용하는 작업"],"answer":0,"explain":"연결된 Excel 테이블의 구조는 Access에서 바꿀 수 없다. 값 수정, 레코드 추가와 쿼리 원본 사용은 가능하다."},{"id":"db-0213","subject":"database","levels":["c1"],"topic":"관계·키","q":"[부서](부서코드, 부서명)에 (D1, 영업), (D2, 총무), (D3, 연구)가 있고 [직원](이름, 부서코드)에 (가, D1), (나, D1), (다, D2), (라, Null)이 있다. SELECT 부서.부서명, 직원.이름 FROM 직원 RIGHT JOIN 부서 ON 직원.부서코드 = 부서.부서코드; 의 결과 행 수는?","options":["3","4","5","6"],"answer":1,"explain":"RIGHT JOIN은 [부서] 레코드를 모두 포함한다. 영업 2행, 총무 1행, 연구 1행(이름 Null)이고 부서코드가 Null인 라는 짝이 없어 제외된다."},{"id":"db-0214","subject":"database","levels":["c1"],"topic":"폼","q":"폼 속성에서 [탐색 단추]를 아니요로 지정하면?","options":["PageDown 키로도 다음 레코드로 이동할 수 없게 된다","폼 왼쪽의 레코드 선택기가 사라진다","폼에 놓인 명령 단추가 모두 비활성화된다","폼 아래쪽의 레코드 탐색 단추 줄이 표시되지 않는다"],"answer":3,"explain":"탐색 단추는 폼 하단의 레코드 이동 줄이다. 숨겨도 키보드로 레코드를 이동하거나 별도 명령 단추를 만들어 쓸 수 있다."},{"id":"db-0215","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 첫 페이지에서 보고서 머리글과 페이지 머리글이 인쇄되는 위치로 옳은 것은?","options":["페이지 머리글이 위에, 보고서 머리글은 그 아래에 인쇄된다","보고서 머리글이 위에, 페이지 머리글은 그 아래에 인쇄된다","첫 페이지에는 페이지 머리글이 인쇄되지 않는다","두 구역이 같은 위치에 겹쳐 인쇄된다"],"answer":1,"explain":"보고서 머리글은 첫 페이지 맨 위에 한 번 인쇄되고 그 아래에 페이지 머리글이 이어진다."},{"id":"db-0216","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금의 필드 행에 금액: Sum([수량]*[단가])를 직접 입력할 때 [요약] 행에 지정해야 하는 항목은?","options":["합계","그룹화","조건","식"],"answer":3,"explain":"필드 행에 이미 집계 함수를 썼으므로 [요약] 행은 식으로 둔다. 합계를 또 지정하면 집계 함수가 중복되어 오류가 난다."},{"id":"db-0217","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"모듈 맨 위에 Option Explicit를 선언하면 어떻게 되는가?","options":["모든 변수가 자동으로 Variant 형식으로 바뀌어 저장된다","프로시저 이름이 중복되지 않는지 검사한다","선언하지 않은 변수를 사용하면 컴파일 오류가 발생한다","모듈의 변수가 다른 프로젝트에서도 공유된다"],"answer":2,"explain":"Option Explicit는 변수 선언을 강제해 오타로 새 변수가 만들어지는 실수를 막는다."},{"id":"db-0218","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[주문] 테이블\n번호 | 상품 | 수량\n1 | A1 | 10\n2 | A3 | 2\n3 | A1 | 5\n4 | A4 | 1\n5 | A2 | 20\n6 | A3 | 1\n\nAccess에서 주문된 서로 다른 상품 수를 구하려고 SELECT COUNT(DISTINCT 상품) FROM 주문; 을 실행했다. 설명으로 옳은 것은?","options":["4가 반환되며 서로 다른 상품 코드 A1, A2, A3, A4가 정상적으로 계산된다","구문 오류가 발생하며 하위 쿼리로 DISTINCT 값을 먼저 구한 뒤 COUNT를 써야 한다","6이 반환되며 COUNT 안에 쓴 DISTINCT는 무시되고 전체 행을 센다","3이 반환되며 Null이 아닌 값만 세어 서로 다른 상품 수가 줄어든다"],"answer":1,"explain":"Access(ACE) SQL은 COUNT(DISTINCT ...)를 지원하지 않는다. SELECT COUNT(*) FROM (SELECT DISTINCT 상품 FROM 주문) 형태로 우회하며 그 값은 4이다."},{"id":"db-0219","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Int(-3.7)과 Fix(-3.7)의 결과를 차례로 나타낸 것은?","options":["-3, -4","-4, -3","-4, -4","-3, -3"],"answer":1,"explain":"Int는 작거나 같은 정수로 내림해 -4, Fix는 소수 부분을 버려 -3이 된다. 양수에서는 둘의 결과가 같다."},{"id":"db-0220","subject":"database","levels":["c1"],"topic":"테이블","q":"[주문일] 필드에 오늘 이후의 날짜만 입력되도록 하는 유효성 검사 규칙으로 옳은 것은?","options":["<=Date()","Like Date()",">=Date()","In(Date())"],"answer":2,"explain":"Date()는 오늘 날짜를 돌려주므로 >=Date()는 오늘 및 이후만 허용한다. 나머지는 오늘 이전이거나 오늘 하루만 허용한다."},{"id":"db-0221","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"Right(Left(\"ABCDEFG\", 5), 3)의 결과는?","options":["EFG","CDEFG","BCD","CDE"],"answer":3,"explain":"Left(\"ABCDEFG\", 5)는 ABCDE이고 그 오른쪽 3글자는 CDE이다."},{"id":"db-0222","subject":"database","levels":["c1"],"topic":"테이블","q":"[입력일] 필드의 기본값 속성에 Date()를 지정했을 때의 설명으로 옳은 것은?","options":["테이블을 열 때마다 이미 저장된 모든 레코드의 값이 그날의 오늘 날짜로 새로 바뀐다","오늘 날짜가 아닌 값은 입력할 수 없게 된다","이미 저장된 기존 레코드에도 소급하여 오늘 날짜가 채워진다","새 레코드를 만들 때 오늘 날짜가 자동으로 채워지며 필요하면 다른 날짜로 고칠 수 있다"],"answer":3,"explain":"기본값은 새 레코드에만 미리 채워 주는 값이다. 입력을 제한하는 것은 유효성 검사 규칙의 역할이다."},{"id":"db-0223","subject":"database","levels":["c1"],"topic":"보고서","q":"텍스트 상자의 [늘림] 속성을 예로 지정하면?","options":["내용이 길면 인쇄할 때 컨트롤 높이가 늘어나 모든 내용이 표시된다","내용이 길면 글꼴 크기가 자동으로 줄어든다","컨트롤이 페이지 너비까지 가로로 늘어난다","구역 높이가 고정된 채 넘친 내용은 다음 레코드가 인쇄되는 위치로 이어서 인쇄된다"],"answer":0,"explain":"늘림은 내용에 맞춰 세로로 확장하고, 줄임은 내용이 짧을 때 높이를 줄인다."},{"id":"db-0224","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"테이블의 [삽입 후], [업데이트 후] 같은 이벤트에 연결해 데이터가 바뀔 때 실행되는 매크로는?","options":["AutoExec 매크로","데이터 매크로","포함 매크로","매크로 그룹"],"answer":1,"explain":"데이터 매크로는 Access 2010부터 제공되며 테이블 이벤트에 연결되어 폼이나 쿼리를 거치지 않고도 동작한다."},{"id":"db-0225","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\nUPDATE 상품 SET 단가 = 단가 * 0.9 WHERE 분류 = \"전자\"; 를 실행한 뒤 [키보드]와 [파일]의 단가를 차례로 나타낸 것은?","options":["22500, 1800","22500, 2000","25000, 2000","22500, Null"],"answer":1,"explain":"분류가 전자인 마우스와 키보드만 10% 인하된다. 분류가 Null인 파일은 WHERE 조건을 만족하지 않아 그대로 2000이다."},{"id":"db-0226","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\n[주문] 테이블\n번호 | 상품 | 수량\n1 | A1 | 10\n2 | A3 | 2\n3 | A1 | 5\n4 | A4 | 1\n5 | A2 | 20\n6 | A3 | 1\n\nUPDATE 주문 INNER JOIN 상품 ON 주문.상품 = 상품.코드 SET 주문.수량 = 0 WHERE 상품.분류 = \"전자\"; 를 실행하면 수량이 0으로 바뀌는 주문 번호는?","options":["2, 3, 6","2, 4, 6","1, 3, 5","2, 4, 5, 6"],"answer":1,"explain":"분류가 전자인 상품은 A3, A4이다. 이 상품을 주문한 번호 2, 4, 6의 수량만 0이 된다."},{"id":"db-0227","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access SQL은 FULL OUTER JOIN을 지원하지 않는다. 두 테이블의 레코드를 짝이 없는 것까지 모두 포함하는 결과를 얻는 방법은?","options":["INNER JOIN 쿼리 두 개를 UNION ALL로 합친다","두 테이블을 조인하지 않고 쿼리에 나란히 추가한 뒤 DISTINCT를 지정한다","[조인 속성]에서 양쪽 모두 포함 옵션이 있는 네 번째 항목을 선택한다","LEFT JOIN 쿼리와 RIGHT JOIN 쿼리를 UNION으로 합친다"],"answer":3,"explain":"[조인 속성]에는 1~3번 옵션만 있다. LEFT JOIN과 RIGHT JOIN 결과를 UNION으로 합치면 전체 외부 조인과 같은 효과를 낸다."},{"id":"db-0228","subject":"database","levels":["c1"],"topic":"DB 개념","q":"자연 조인(Natural Join)에 대한 설명으로 옳은 것은?","options":["공통 속성의 값이 같은 튜플끼리 연결하고 결과에서 공통 속성은 한 번만 나타낸다","조인 조건으로 부등호만 사용할 수 있으며 결과에는 공통 속성이 양쪽에서 가져온 두 열로 모두 나타난다","한쪽 릴레이션의 튜플을 모두 남기고 짝이 없으면 Null로 채워 보여 준다","두 릴레이션의 모든 튜플을 짝지어 카디널리티가 두 값의 곱이 되게 한다"],"answer":0,"explain":"자연 조인은 같은 이름의 속성 값이 같은 튜플을 연결하고 중복 속성을 제거한다. 짝이 없는 튜플을 남기는 것은 외부 조인, 모든 조합은 카티션 프로덕트이다."},{"id":"db-0229","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 속성의 [고유 값]과 [고유 레코드]에 대한 설명으로 옳은 것은?","options":["고유 값은 원본 레코드 전체가 같은 경우에만 걸러 내고, 고유 레코드는 출력 필드 값이 같은 행을 한 번만 보여 준다","고유 값은 테이블에서 중복 레코드를 삭제하고 고유 레코드는 중복 레코드를 숨기기만 한다","고유 값은 출력 필드의 값이 같은 행을 한 번만 보여 주고, 고유 레코드는 원본 레코드 전체가 같은 경우만 걸러 낸다","두 속성은 이름만 다를 뿐 결과가 항상 같다"],"answer":2,"explain":"고유 값은 SELECT DISTINCT, 고유 레코드는 DISTINCTROW에 해당한다. 두 속성 모두 원본 데이터는 삭제하지 않는다."},{"id":"db-0230","subject":"database","levels":["c1"],"topic":"보고서","q":"3페이지짜리 보고서의 페이지 바닥글 텍스트 상자에 =IIf([Page]=1, \"\", [Page]) 를 입력했다. 1, 2, 3페이지에 표시되는 값은?","options":["1, 2, 3","(빈 칸), (빈 칸), 3","(빈 칸), 2, 3","(빈 칸), 2, 2"],"answer":2,"explain":"[Page]가 1이면 빈 문자열을, 그 밖에는 현재 페이지 번호를 돌려준다. 첫 페이지에만 번호를 감출 때 쓰는 방법이다."},{"id":"db-0231","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"폼 모듈의 VBA에서 Me 키워드가 가리키는 것은?","options":["현재 열려 있는 데이터베이스 파일 전체","Access 응용 프로그램 전체","현재 선택된 레코드 하나","실행 중인 현재 폼(또는 보고서) 개체"],"answer":3,"explain":"Me.txt이름처럼 같은 폼의 컨트롤이나 속성을 짧게 참조할 때 쓴다."},{"id":"db-0232","subject":"database","levels":["c1"],"topic":"DB 개념","q":"반정규화(Denormalization)를 하는 이유로 가장 알맞은 것은?","options":["중복을 완전히 없애 저장 공간을 최대한 줄이려고 한다","갱신 이상을 막으려고 릴레이션을 더 잘게 나누려고 한다","조인을 줄여 조회 성능을 높이려고 일부 중복을 허용한다","모든 함수적 종속을 제거해 이론적으로 완벽한 설계를 만들려고 한다"],"answer":2,"explain":"반정규화는 성능을 위해 정규화된 구조에 중복이나 통합을 허용하는 것이다. 그 대가로 갱신 이상 위험이 생긴다."},{"id":"db-0233","subject":"database","levels":["c1"],"topic":"테이블","q":"데이터시트 보기에서 [홈] 탭의 [합계](Σ)를 눌러 표시되는 요약 행에 대한 설명으로 옳은 것은?","options":["합계·평균·개수·최대·최소 등을 필드마다 골라 표시하며 형식에 따라 목록이 다르다","테이블에 새 필드가 추가되어 레코드마다 합계가 저장된다","모든 필드에서 데이터 형식과 관계없이 합계 한 가지 함수만 선택해 표시할 수 있다","합계 행의 값은 쿼리에 저장되어 다른 쿼리에서 재사용된다"],"answer":0,"explain":"요약 행은 화면에 요약을 보여 줄 뿐 데이터를 바꾸거나 저장하지 않는다. 숫자 필드는 합계·평균 등을, 텍스트 필드는 개수만 선택할 수 있는 식으로 형식에 따라 목록이 다르다."},{"id":"db-0234","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[점수]가 각각 80, 95, 79인 레코드에 IIf([점수]>=90, \"A\", IIf([점수]>=80, \"B\", \"C\")) 식을 적용한 결과를 차례로 나타낸 것은?","options":["B, B, C","B, A, C","A, B, C","B, A, B"],"answer":1,"explain":"95는 90 이상이라 A, 80은 두 번째 조건에서 B, 79는 둘 다 만족하지 못해 C가 된다."},{"id":"db-0235","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[사원] 테이블에서 [연락처] 필드를 삭제하는 Access SQL로 옳은 것은?","options":["ALTER TABLE 사원 REMOVE COLUMN 연락처;","DELETE COLUMN 연락처 FROM 사원;","ALTER TABLE 사원 DROP COLUMN 연락처;","ALTER TABLE 사원 DELETE 연락처;"],"answer":2,"explain":"필드 삭제는 ALTER TABLE 테이블 DROP COLUMN 필드 구문을 쓴다."},{"id":"db-0236","subject":"database","levels":["c1"],"topic":"보고서","q":"하위 보고서에 대한 설명으로 옳은 것은?","options":["기본 보고서와 같은 테이블을 레코드 원본으로 사용하는 경우에만 서로 연결할 수 있다","기본 보고서에 삽입해 관련 레코드를 함께 인쇄하며 기본 필드와 하위 필드로 연결한다","기본 보고서의 페이지 머리글에만 삽입할 수 있다","하위 보고서 안에는 다른 하위 보고서를 넣을 수 없다"],"answer":1,"explain":"하위 보고서는 일대다 관계의 다 쪽 데이터를 기본 보고서와 함께 보여 줄 때 쓴다. 하위 보고서 안에 하위 보고서를 중첩할 수도 있다."},{"id":"db-0237","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"DAO Recordset rs의 레코드를 처음부터 끝까지 차례로 처리하는 반복 구조로 옳은 것은? (rs는 첫 레코드에 위치함)","options":["Do While Not rs.EOF : (처리) : rs.MoveNext : Loop","Do While rs.EOF : (처리) : rs.MoveNext : Loop","Do Until Not rs.BOF : (처리) : rs.MoveNext : Loop","Do While Not rs.EOF : (처리) : Loop"],"answer":0,"explain":"EOF가 True가 될 때까지 처리하고 MoveNext로 다음 레코드로 이동한다. MoveNext가 없으면 무한 반복된다."},{"id":"db-0238","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\n[주문] 테이블\n번호 | 상품 | 수량\n1 | A1 | 10\n2 | A3 | 2\n3 | A1 | 5\n4 | A4 | 1\n5 | A2 | 20\n6 | A3 | 1\n\nSELECT 상품명 FROM 상품 WHERE EXISTS (SELECT * FROM 주문 WHERE 주문.상품 = 상품.코드 AND 주문.수량 >= 2); 의 결과로 옳은 것은?","options":["노트, 볼펜, 마우스, 키보드","노트, 볼펜","노트, 볼펜, 마우스","마우스, 키보드"],"answer":2,"explain":"수량 2 이상인 주문이 있는 상품은 노트(10, 5), 볼펜(20), 마우스(2)이다. 키보드는 주문이 수량 1건뿐이라 제외된다."},{"id":"db-0239","subject":"database","levels":["c1"],"topic":"테이블","q":"이미 중복된 값이 들어 있는 필드의 인덱스를 [예(중복 불가능)]로 지정하고 저장하면?","options":["중복된 데이터 때문에 인덱스를 만들 수 없다는 오류가 나타나 설정이 되지 않는다","중복된 값 중 첫 레코드만 남고 나머지는 자동으로 삭제된다","기존 중복 값은 그대로 허용하고 앞으로 새로 입력하는 값에만 중복 불가능이 적용된다","중복된 값 뒤에 일련번호가 자동으로 붙어 구별된다"],"answer":0,"explain":"중복 불가능 인덱스는 기존 데이터에도 중복이 없어야 만들 수 있다. 먼저 중복을 정리해야 한다."},{"id":"db-0240","subject":"database","levels":["c1"],"topic":"DB 개념","q":"두 트랜잭션이 같은 데이터를 읽은 뒤 각각 수정해 저장했더니 먼저 저장한 결과가 사라지는 병행 수행 문제는?","options":["연쇄 복귀","갱신 분실","모순성","교착상태"],"answer":1,"explain":"두 트랜잭션이 같은 값을 읽고 덮어써서 앞선 갱신이 사라지는 것이 갱신 분실이다. 로킹 같은 병행 제어로 막는다."},{"id":"db-0241","subject":"database","levels":["c1"],"topic":"테이블","q":"필드 크기가 Double인 숫자 필드의 형식 속성을 #,##0으로 지정하고 1234.567을 입력했을 때 표시되는 값은?","options":["1,234.567","1,234","1234.57","1,235"],"answer":3,"explain":"#,##0은 천 단위 구분 기호와 정수 표시 형식이다. 소수점 이하는 반올림되어 표시될 뿐 저장된 값은 1234.567 그대로이다."},{"id":"db-0242","subject":"database","levels":["c1"],"topic":"보고서","q":"본문의 텍스트 상자에서 컨트롤 원본을 =[금액], [누적 합계]를 모두로 지정했다. [금액]이 차례로 100, 200, 50인 세 레코드에 표시되는 값은?","options":["100, 200, 50","100, 300, 350","350, 350, 350","100, 300, 300"],"answer":1,"explain":"누적 합계 모두는 보고서 전체에서 값을 이어서 더한다. 100, 100+200=300, 300+50=350이 된다."},{"id":"db-0243","subject":"database","levels":["c1"],"topic":"보고서","q":"보고서 마법사의 [요약 옵션] 단계에서 지정할 수 있는 것은?","options":["필드별 글꼴 크기와 배경색 지정","문자 필드의 개수와 중앙값","숫자 필드의 합계·평균·최소·최대","페이지 번호의 위치"],"answer":2,"explain":"요약 옵션은 숫자 필드에 대한 합계·평균·최소·최대와 세부 정보 표시 여부를 정한다."},{"id":"db-0244","subject":"database","levels":["c1"],"topic":"폼","q":"컨트롤의 [잠금] 속성을 예로 지정하면?","options":["컨트롤이 흐리게 표시되고 포커스를 받을 수 없다","폼 보기에서 컨트롤이 보이지 않는다","입력은 되지만 저장할 때 원본 필드에 반영되지 않는다","컨트롤에 포커스는 둘 수 있지만 값을 수정할 수 없다"],"answer":3,"explain":"잠금은 읽기 전용으로 만든다. 흐려지고 포커스를 못 받는 것은 사용 가능=아니요일 때이다."},{"id":"db-0245","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리를 실행할 때마다 시작일과 종료일을 입력받아 그 사이의 주문만 조회하려 한다. [주문일] 필드의 조건으로 옳은 것은?","options":["Between \"시작일 입력\" And \"종료일 입력\"","Between (시작일 입력) And (종료일 입력)","Between ?시작일 And ?종료일","Between [시작일 입력] And [종료일 입력]"],"answer":3,"explain":"필드 이름이 아닌 대괄호 문자열은 매개 변수로 인식되어 입력 대화 상자가 나타난다. 따옴표 문자열은 단순한 텍스트로 취급된다."},{"id":"db-0246","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[주문보관] 테이블에 [주문]의 번호, 상품, 수량 중 수량이 10 이상인 레코드를 복사하는 SQL로 옳은 것은?","options":["INSERT INTO 주문보관 (번호, 상품, 수량) VALUES SELECT 번호, 상품, 수량 FROM 주문 WHERE 수량 >= 10;","SELECT 번호, 상품, 수량 INTO 주문보관 FROM 주문 WHERE 수량 >= 10 AND 번호 IS NOT NULL;","UPDATE 주문보관 SET 번호, 상품, 수량 = SELECT 번호, 상품, 수량 FROM 주문 WHERE 수량 >= 10;","INSERT INTO 주문보관 (번호, 상품, 수량) SELECT 번호, 상품, 수량 FROM 주문 WHERE 수량 >= 10;"],"answer":3,"explain":"추가 쿼리는 INSERT INTO ... SELECT 구문이다. VALUES 뒤에는 SELECT를 쓸 수 없고, SELECT ... INTO는 새 테이블을 만드는 구문이다."},{"id":"db-0247","subject":"database","levels":["c1"],"topic":"테이블","q":"[부서] 테이블의 부서코드와 부서명 두 열을 목록에 보이되 부서코드는 숨기고 부서코드를 저장하려 한다. 조회 속성 설정으로 옳은 것은?","options":["열 개수 2, 바운드 열 1, 열 너비 0cm;3cm","열 개수 2, 바운드 열 2, 열 너비 0cm;3cm","열 개수 1, 바운드 열 1, 열 너비 3cm","열 개수 2, 바운드 열 1, 열 너비 3cm;0cm"],"answer":0,"explain":"저장할 값은 바운드 열(1번 열)이고 첫 열의 너비를 0으로 하면 숨겨진다. 바운드 열이 2이면 부서명이 저장된다."},{"id":"db-0248","subject":"database","levels":["c1"],"topic":"관계·키","q":"Access 테이블 디자인 보기에서 두 필드를 합쳐 하나의 기본키로 지정하는 방법으로 옳은 것은?","options":["Ctrl 키로 두 필드의 행 선택기를 함께 선택한 뒤 [기본 키]를 클릭한다","첫 필드에 [기본 키]를 지정한 뒤 둘째 필드에도 같은 방법으로 지정하면 두 필드가 합쳐진다","두 필드의 인덱스를 모두 예(중복 불가능)로 지정하면 복합키로 자동 인식된다","[관계] 창에서 두 필드를 선으로 연결하면 복합키가 만들어진다"],"answer":0,"explain":"여러 필드를 선택한 상태에서 [기본 키]를 누르면 복합 기본키가 된다. 필드를 하나씩 지정하면 앞선 지정이 바뀐다."},{"id":"db-0249","subject":"database","levels":["c1"],"topic":"테이블","q":"필드의 필수 속성을 예로 지정했을 때의 설명으로 옳은 것은?","options":["그 필드를 Null로 비워 둔 채 레코드를 저장할 수 없다","그 필드가 기본키로 자동 지정된다","그 필드에는 중복된 값을 입력할 수 없다","그 필드에 인덱스가 자동으로 만들어져 검색 속도가 빨라지고 정렬이 쉬워진다"],"answer":0,"explain":"필수는 Null 입력을 막을 뿐이며 중복 방지는 인덱스(중복 불가능)로, 유일 식별은 기본키로 한다."},{"id":"db-0250","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"다음 VBA 코드를 실행했을 때 MsgBox에 표시되는 값은?\nDim i As Integer, t As Integer\ni = 1: t = 0\nDo While i <= 5\n  If i Mod 2 = 0 Then t = t + i\n  i = i + 1\nLoop\nMsgBox t","options":["6","9","15","12"],"answer":0,"explain":"1~5 중 짝수 2와 4만 더해 6이 된다. 홀수의 합은 9, 전체 합은 15이다."},{"id":"db-0251","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"DateAdd(\"m\", 1, #2026-01-31#)의 결과는?","options":["2026-02-28","2026-03-03","2026-03-01","2026-02-31"],"answer":0,"explain":"DateAdd는 월을 더한 뒤 그 달에 없는 날짜이면 말일로 맞춘다. 2026년 2월은 28일까지이다."},{"id":"db-0252","subject":"database","levels":["c1"],"topic":"보고서","q":"[그룹, 정렬 및 요약] 창의 [그룹 추가]와 [정렬 추가]의 차이로 옳은 것은?","options":["그룹 추가는 그룹 머리글·바닥글 구역을 만들 수 있고, 정렬 추가는 구역 없이 정렬만 지정한다","정렬 추가는 그룹 머리글·바닥글 구역을 만들 수 있고, 그룹 추가는 구역 없이 정렬 순서만 지정한다","둘 다 구역을 만들지만 정렬 추가는 오름차순만 지정할 수 있다","그룹 추가를 하면 하위 보고서가 자동으로 함께 만들어진다"],"answer":0,"explain":"그룹은 구역과 요약을 둘 수 있고, 정렬은 단순히 순서만 정한다."},{"id":"db-0253","subject":"database","levels":["c1"],"topic":"테이블","q":"입력 마스크 기호 !의 기능으로 옳은 것은?","options":["바로 뒤에 오는 문자를 그대로 표시한다","입력하는 문자를 오른쪽에서 왼쪽으로 채워 넣는다","입력한 영문자를 모두 소문자로 바꾼다","입력할 때 영문자나 공백을 선택적으로 입력할 수 있게 해 준다"],"answer":1,"explain":"!는 오른쪽에서 왼쪽으로 입력하게 한다. 뒤 문자를 그대로 표시하는 것은 \\, 소문자 변환은 <, 선택적 문자는 ?이다."},{"id":"db-0254","subject":"database","levels":["c1"],"topic":"테이블","q":"여러 필드를 묶어 하나의 인덱스로 설정할 때 사용하는 도구는?","options":["[관계] 창","[인덱스] 창","[테이블 분석] 마법사","입력 마스크 마법사"],"answer":1,"explain":"[인덱스] 창에서 인덱스 이름 아래에 여러 필드를 나열하면 다중 필드 인덱스가 된다."},{"id":"db-0255","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\n쿼리 디자인 눈금에서 [분류] 필드의 조건 행에 \"문구\"를, [단가] 필드의 또는 행에 >=10000을 입력했다. 조회되는 상품명은?","options":["노트, 볼펜, 마우스, 키보드","노트, 볼펜, 마우스, 키보드, 파일","마우스, 키보드","결과가 없다"],"answer":0,"explain":"서로 다른 행의 조건은 OR로 연결된다. 분류가 문구인 노트·볼펜과 단가가 10000 이상인 마우스·키보드가 조회된다."},{"id":"db-0256","subject":"database","levels":["c1"],"topic":"DB 개념","q":"Access 데이터베이스를 분할했을 때 만들어지는 구성으로 옳은 것은?","options":["테이블마다 별도 파일이 만들어지고 각각이 서로 독립된 데이터베이스가 된다","백업용 복사본이 만들어지고 원본과 자동으로 동기화된다","테이블만 담은 백엔드 파일과, 쿼리·폼·보고서를 담고 테이블을 연결해 쓰는 프런트엔드 파일","읽기 전용 파일과 쓰기 전용 파일로 나뉘어 한 번에 한 명의 사용자만 데이터를 입력하고 수정할 수 있다"],"answer":2,"explain":"분할하면 백엔드(테이블)와 프런트엔드(나머지 개체, 연결 테이블)로 나뉘어 여러 사용자가 각자 프런트엔드를 쓰며 같은 데이터를 공유한다."},{"id":"db-0257","subject":"database","levels":["c1"],"topic":"DB 개념","q":"뷰(View)에 대한 설명으로 옳지 않은 것은?","options":["하나 이상의 테이블에서 유도된 가상 테이블로 논리적으로만 존재한다","뷰는 자체 인덱스를 가지며 원본 테이블과 별개로 데이터를 따로 저장한다","필요한 열과 행만 보여 주어 민감한 데이터를 감추는 보안 수단으로 활용할 수 있다","뷰를 삭제해도 원본 테이블에 저장된 데이터는 삭제되지 않는다"],"answer":1,"explain":"뷰는 정의만 저장되는 가상 테이블이다. 데이터를 따로 저장하지 않으며 삭제해도 기본 테이블은 그대로이다."},{"id":"db-0258","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[고객](고객번호, 이름), [주문](주문번호, 고객번호, 상품코드), [상품](코드, 상품명) 세 테이블을 INNER JOIN으로 연결해 이름과 상품명을 조회하는 Access SQL로 옳은 것은?","options":["SELECT 고객.이름, 상품.상품명 FROM 고객 INNER JOIN 주문 ON 고객.고객번호 = 주문.고객번호 INNER JOIN 상품 ON 주문.상품코드 = 상품.코드;","SELECT 고객.이름, 상품.상품명 FROM 고객 INNER JOIN 주문 INNER JOIN 상품 ON 고객.고객번호 = 주문.고객번호 AND 주문.상품코드 = 상품.코드;","SELECT 고객.이름, 상품.상품명 FROM 고객, 주문, 상품 ON 고객.고객번호 = 주문.고객번호 AND 주문.상품코드 = 상품.코드;","SELECT 고객.이름, 상품.상품명 FROM (고객 INNER JOIN 주문 ON 고객.고객번호 = 주문.고객번호) INNER JOIN 상품 ON 주문.상품코드 = 상품.코드;"],"answer":3,"explain":"Access는 조인이 둘 이상이면 먼저 수행할 조인을 괄호로 묶어 중첩해야 한다. 괄호가 없으면 구문 오류가 난다."},{"id":"db-0259","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"DROP TABLE 주문;과 DELETE FROM 주문;의 차이로 옳은 것은?","options":["DROP TABLE은 테이블의 레코드만 삭제하고 구조는 남기며, DELETE FROM은 테이블 구조까지 완전히 삭제한다","두 명령 모두 구조까지 삭제하지만 DELETE FROM은 실행 후 되돌릴 수 있다","DROP TABLE은 테이블 구조까지 삭제하고 DELETE FROM은 구조는 남긴 채 모든 레코드만 삭제한다","DROP TABLE은 삭제한 레코드를 휴지통으로 옮겨 나중에 복구할 수 있다"],"answer":2,"explain":"DROP은 개체(테이블) 자체를 없애는 DDL이고 DELETE는 레코드를 지우는 DML이다. Access 실행 쿼리는 둘 다 되돌릴 수 없다."},{"id":"db-0260","subject":"database","levels":["c1"],"topic":"폼","q":"폼을 닫을 때 이벤트가 발생하는 순서로 옳은 것은?","options":["Close → Unload → Deactivate","Deactivate → Unload → Close","Unload → Close → Deactivate","Unload → Deactivate → Close"],"answer":3,"explain":"닫을 때는 Unload, Deactivate, Close 순이다. Unload에서 Cancel을 설정하면 폼 닫기를 취소할 수 있다."},{"id":"db-0261","subject":"database","levels":["c1"],"topic":"테이블","q":"조회 속성에서 컨트롤 표시를 콤보 상자로 하고 목록 항목을 직접 입력하려 한다. 설정으로 옳은 것은?","options":["행 원본 유형을 테이블/쿼리로 하고 행 원본에 서울;부산;대구를 입력한다","행 원본 유형을 필드 목록으로 하고 행 원본에 항목을 세미콜론으로 구분해 직접 입력해 둔다","행 원본 유형을 값 목록으로 하고 행 원본에 \"서울\";\"부산\";\"대구\"처럼 세미콜론으로 구분해 입력한다","행 원본 유형을 값 목록으로 하고 행 원본에 항목을 공백으로만 구분해 입력한다"],"answer":2,"explain":"값 목록은 항목을 세미콜론으로 구분해 직접 입력한다. 테이블/쿼리는 개체 이름이나 SQL을, 필드 목록은 테이블 필드 이름을 원본으로 쓴다."},{"id":"db-0262","subject":"database","levels":["c1"],"topic":"DB 개념","q":"수강(학번, 과목, 학과, 학과장)에서 같은 학과의 학과장 이름이 여러 튜플에 중복되어 있다. 학과장이 바뀌어 일부 튜플만 고치면 데이터가 서로 어긋나는 현상은?","options":["갱신 이상","삽입 이상","삭제 이상","참조 이상"],"answer":0,"explain":"중복 저장된 값을 일부만 수정해 모순이 생기는 것이 갱신 이상이다. 정규화로 중복을 없애 방지한다."},{"id":"db-0263","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 [스크롤 막대] 속성에서 세로 스크롤 막대만 표시하려면 어떤 값을 지정해야 하는가?","options":["가로만","양쪽 모두","없음","세로만"],"answer":3,"explain":"스크롤 막대는 없음, 가로만, 세로만, 양쪽 모두 중에서 고른다."},{"id":"db-0264","subject":"database","levels":["c1"],"topic":"DB 개념","q":"E-R 다이어그램을 관계형 스키마로 바꾸는 규칙으로 옳은 것은?","options":["일대다 관계는 다 쪽 릴레이션에 일 쪽의 기본키를 외래키로 넣어 표현할 수 있다","다대다 관계는 어느 한쪽 릴레이션에 외래키 하나만 더하면 표현된다","다중 값 속성은 별도 릴레이션으로 나누지 않고 같은 릴레이션의 한 열에 쉼표로 구분해 모두 저장한다","약한 개체는 소유 개체의 기본키와 무관한 독립 기본키만으로 식별한다"],"answer":0,"explain":"일대다는 다 쪽에 외래키를 두면 된다. 다대다는 별도 릴레이션이 필요하고, 다중 값 속성은 원자성을 위해 분리하며, 약한 개체는 소유 개체 키를 포함해 식별한다."},{"id":"db-0265","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"폼이나 보고서에 만든 이벤트 프로시저가 저장되는 모듈은?","options":["표준 모듈","클래스 모듈","데이터 모듈","시스템 모듈"],"answer":1,"explain":"폼·보고서 모듈은 클래스 모듈의 한 종류이다. 여러 곳에서 공유하는 프로시저는 표준 모듈에 둔다."},{"id":"db-0266","subject":"database","levels":["c1"],"topic":"폼","q":"폼을 열 때 이벤트가 발생하는 순서로 옳은 것은?","options":["Load → Open → Activate → Resize → Current","Open → Activate → Load → Current → Resize","Current → Open → Load → Resize → Activate","Open → Load → Resize → Activate → Current"],"answer":3,"explain":"폼은 Open, Load, Resize, Activate, Current 순으로 이벤트가 발생한다."},{"id":"db-0267","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[성적] 테이블\n이름 | 점수\n가 | 95\n나 | 90\n다 | 90\n라 | 80\n\nAccess에서 SELECT TOP 2 이름 FROM 성적 ORDER BY 점수 DESC; 를 실행했을 때 결과로 옳은 것은?","options":["2행: 가, 나","2행: 가, 다","4행: 가, 나, 다, 라","3행: 가, 나, 다"],"answer":3,"explain":"Access의 TOP은 정렬 기준 값이 같은 행(동점)을 모두 포함한다. 공동 2위인 나와 다가 함께 나와 3행이 된다."},{"id":"db-0268","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[판매] 테이블\n지점 | 분기 | 금액\n강남 | 1 | 100\n강남 | 1 | 50\n강남 | 2 | 70\n강북 | 2 | 30\n\n행 머리글을 지점, 열 머리글을 분기, 값을 금액의 합계로 지정한 크로스탭 쿼리의 결과로 옳은 것은?","options":["강남은 1분기 100·2분기 70, 강북은 1분기 비어 있고 2분기 30","강남은 1분기 150·2분기 70, 강북은 1분기 0이고 2분기 30","강남은 1분기 150·2분기 70, 강북은 1분기 비어 있고 2분기 30","강남은 1분기 2·2분기 1, 강북은 1분기 비어 있고 2분기 1"],"answer":2,"explain":"크로스탭은 같은 행·열 조합의 값을 집계한다. 강남 1분기는 100+50=150이고, 해당 조합이 없는 강북 1분기는 Null(빈 칸)이다."},{"id":"db-0269","subject":"database","levels":["c1"],"topic":"관계·키","q":"[직원](사번, 이름, 상사사번)에서 직원 이름과 그 상사의 이름을 한 줄에 보려 한다. 알맞은 방법은?","options":["상사사번 필드를 기본키로 지정해 일대일 관계를 만든다","UNION 쿼리로 직원 테이블을 두 번 읽어 나온 결과를 세로로 이어 붙여 상사 정보를 만든다","같은 테이블을 별칭을 달리해 두 번 사용하고 상사사번 = 사번으로 조인한다","크로스탭 쿼리에서 상사사번을 열 머리글로 지정한다"],"answer":2,"explain":"자기 조인은 같은 테이블을 별칭으로 두 번 가져와 서로 연결하는 방법이다."},{"id":"db-0270","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[갑조](이름)에 김, 이, 박이 있고 [을조](이름)에 이, 박, 최가 있다. SELECT 이름 FROM 갑조 UNION SELECT 이름 FROM 을조; 의 결과 행 수와 UNION ALL로 바꾸었을 때의 행 수를 차례로 나타낸 것은?","options":["6, 4","4, 6","4, 4","6, 6"],"answer":1,"explain":"UNION은 중복을 제거해 김·이·박·최 4행, UNION ALL은 중복을 포함해 6행이다."},{"id":"db-0271","subject":"database","levels":["c1"],"topic":"테이블","q":"필드 크기가 실수(Double)이고 형식은 고정, 소수 자릿수는 2로 지정한 필드에 3.14159를 입력하면?","options":["3.14로 반올림되어 저장되고 표시도 3.14이다","3.14로 표시되지만 저장된 값은 3.14159 그대로이다","3.14159로 표시되며 소수 자릿수 속성은 무시된다","소수 자릿수를 초과했다는 오류 메시지가 나타나면서 입력이 거부된다"],"answer":1,"explain":"소수 자릿수는 형식을 지정했을 때 표시되는 자릿수를 정할 뿐이다. 저장된 값은 바뀌지 않는다."},{"id":"db-0272","subject":"database","levels":["c1"],"topic":"테이블","q":"[데이터베이스 도구] 탭의 [테이블 분석]에 대한 설명으로 옳은 것은?","options":["중복 데이터가 있는 테이블을 분석해 관련된 여러 테이블로 나누어 준다","테이블의 인덱스를 자동으로 최적화하고 쓰지 않는 필드를 찾아 삭제해 준다","쿼리 실행 시간을 측정해 느린 쿼리를 찾아 알려 준다","데이터 형식 오류를 찾아 올바른 형식으로 자동 변환한다"],"answer":0,"explain":"테이블 분석 마법사는 중복을 줄이도록 테이블을 분할해 준다. 성능 문제는 [성능 분석]이 다룬다."},{"id":"db-0273","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"값이 Apple, Berry, Cabin, Dove, Fig인 필드에 Like \"[!A-C]*\" 조건을 지정했을 때 조회되는 값은?","options":["Apple, Berry, Cabin","Dove, Fig","Dove","Apple, Dove, Fig"],"answer":1,"explain":"[!A-C]는 A부터 C까지의 문자를 제외한 문자 하나를 뜻한다. 따라서 A·B·C로 시작하지 않는 Dove와 Fig만 조회된다."},{"id":"db-0274","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\nSELECT 상품명 FROM 상품 WHERE 분류 <> \"문구\"; 의 결과 행 수는?","options":["3","2","4","5"],"answer":1,"explain":"분류가 Null인 파일은 Null <> \"문구\"의 결과가 Null이어서 조건을 만족하지 못한다. 마우스와 키보드 2행만 조회된다."},{"id":"db-0275","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"[상품] 테이블\n코드 | 상품명 | 분류 | 단가\nA1 | 노트 | 문구 | 1500\nA2 | 볼펜 | 문구 | 800\nA3 | 마우스 | 전자 | 12000\nA4 | 키보드 | 전자 | 25000\nA5 | 파일 | Null | 2000\n\n[주문] 테이블\n번호 | 상품 | 수량\n1 | A1 | 10\n2 | A3 | 2\n3 | A1 | 5\n4 | A4 | 1\n5 | A2 | 20\n6 | A3 | 1\n\nSELECT 상품명 FROM 상품 WHERE 코드 IN (SELECT 상품 FROM 주문 WHERE 수량 >= 5); 의 결과로 옳은 것은?","options":["노트, 볼펜, 마우스","마우스, 키보드, 파일","노트, 볼펜, 파일","노트, 볼펜"],"answer":3,"explain":"수량이 5 이상인 주문의 상품은 A1(10, 5)과 A2(20)이므로 노트와 볼펜이 조회된다."},{"id":"db-0276","subject":"database","levels":["c1"],"topic":"관계·키","q":"일대일 관계를 만드는 이유로 가장 알맞은 것은?","options":["여러 레코드가 하나의 레코드를 공유하도록 같은 데이터를 중복해 두려고","자주 쓰지 않거나 보안이 필요한 필드를 별도 테이블로 분리해 관리하려고","다대다 관계를 중간 테이블을 만들지 않고 곧바로 구현할 수 있게 하려고","기본키 없이도 두 테이블을 연결할 수 있게 하려고"],"answer":1,"explain":"일대일 관계는 한 테이블의 일부 필드를 따로 떼어 접근을 제한하거나 테이블을 가볍게 하려는 목적으로 쓴다."},{"id":"db-0277","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"다음 중 ADO 방식으로 현재 데이터베이스에 연결할 때 사용하는 것은?","options":["CurrentDb.OpenRecordset","DBEngine.Workspaces(0).Databases(0)","CurrentProject.Connection","DoCmd.OpenDatabase"],"answer":2,"explain":"CurrentProject.Connection은 ADO 연결이고, CurrentDb와 DBEngine은 DAO 개체이다."},{"id":"db-0278","subject":"database","levels":["c1"],"topic":"DB 개념","q":"인덱스에 대한 설명으로 옳은 것은?","options":["클러스터드 인덱스는 필드 수만큼 여러 개를 한 테이블에 동시에 만들 수 있다","데이터의 물리적 정렬 순서와 인덱스 순서가 같은 클러스터드 인덱스는 테이블당 하나만 만들 수 있다","비클러스터드 인덱스는 레코드를 물리적으로 정렬해 저장하므로 삽입이 가장 빠르고 테이블당 한 개만 만들 수 있다","인덱스는 별도 구조가 아니라 각 레코드 안에 포함되어 저장된다"],"answer":1,"explain":"클러스터드 인덱스는 레코드 자체의 저장 순서를 결정하므로 하나뿐이다. 비클러스터드 인덱스는 별도 구조로 저장된다."},{"id":"db-0279","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"VBA의 On Error Resume Next에 대한 설명으로 옳은 것은?","options":["오류가 발생하면 프로시저를 즉시 종료한다","오류가 발생하면 프로시저를 처음부터 다시 실행한다","오류가 발생하면 지정한 레이블로 이동하고 오류 메시지를 표시한다","오류가 발생한 문장은 건너뛰고 바로 다음 문장부터 계속 실행한다"],"answer":3,"explain":"Resume Next는 오류를 무시하고 진행한다. 레이블로 이동하는 것은 On Error GoTo 레이블이다."},{"id":"db-0280","subject":"database","levels":["c1"],"topic":"DB 개념","q":"관계 대수에서 릴레이션의 조건에 맞는 튜플(행)을 고르는 연산자와 원하는 속성(열)을 고르는 연산자를 차례로 나타낸 것은?","options":["π(프로젝트), σ(셀렉트)","⋈(조인), ÷(디비전)","σ(셀렉트), π(프로젝트)","∪(합집합), ∩(교집합)"],"answer":2,"explain":"σ는 행을 선택하고 π는 열을 선택한다. 둘 다 순수 관계 연산자이다."},{"id":"db-0281","subject":"database","levels":["c1"],"topic":"폼","q":"텍스트 상자에 글자를 한 자 입력할 때마다 발생하는 이벤트는?","options":["업데이트 후(AfterUpdate)","변경 시(Change)","포커스 받음(GotFocus)","현재 레코드(Current)"],"answer":1,"explain":"Change는 입력 내용이 바뀔 때마다 발생한다. AfterUpdate는 값을 확정하고 컨트롤을 벗어난 뒤에 발생한다."},{"id":"db-0282","subject":"database","levels":["c1"],"topic":"매크로·모듈","q":"VBA의 Sub 프로시저와 Function 프로시저의 차이로 옳은 것은?","options":["Sub만 인수를 받을 수 있고 Function은 인수를 받을 수 없다","Function은 폼 모듈에서만 만들 수 있고 Sub는 표준 모듈에서만 만들 수 있도록 제한된다","Function은 값을 반환할 수 있어 쿼리 식이나 컨트롤 원본에서 호출할 수 있다","Sub는 이벤트 프로시저로 사용할 수 없고 Function만 사용할 수 있다"],"answer":2,"explain":"Function은 반환값을 가지며 식에서 호출할 수 있다. Sub는 동작만 수행하며 이벤트 프로시저는 주로 Sub로 만든다."},{"id":"db-0283","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"DatePart(\"q\", #2026-11-20#)의 결과는?","options":["11","4","3","2"],"answer":1,"explain":"인수 \"q\"는 분기를 뜻한다. 11월은 4분기(10~12월)에 속한다."},{"id":"db-0284","subject":"database","levels":["c1"],"topic":"테이블","q":"숫자 데이터 형식의 필드 크기 중 정수(Integer)와 긴 정수(Long Integer)에 대한 설명으로 옳은 것은?","options":["정수는 2바이트로 -32,768~32,767, 긴 정수는 4바이트 범위의 정수를 저장한다","정수는 1바이트로 0~255, 긴 정수는 2바이트 범위의 정수를 저장한다","정수는 4바이트, 긴 정수는 8바이트이며 둘 다 소수점 이하의 값도 정확하게 저장할 수 있다","정수는 소수점 이하 7자리, 긴 정수는 15자리의 정밀도를 가진다"],"answer":0,"explain":"정수는 2바이트(-32,768~32,767), 긴 정수는 4바이트이다. 소수 자릿수가 필요하면 실수(Single, Double)를 쓴다."},{"id":"db-0285","subject":"database","levels":["c1"],"topic":"관계·키","q":"사원(사번, 이메일, 이름, 부서)에서 사번과 이메일은 각각 후보키이다. 슈퍼키가 될 수 없는 것은?","options":["{사번}","{이름, 부서}","{사번, 이름}","{이메일, 부서}"],"answer":1,"explain":"슈퍼키는 후보키를 포함해 유일성만 만족하면 된다. {이름, 부서}에는 후보키가 없어 동명이인이 같은 부서에 있으면 구별되지 않는다."},{"id":"db-0286","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"쿼리 디자인 눈금에서 [단가] 필드의 [표시] 확인란을 해제했을 때의 결과는?","options":["결과에는 나타나지 않지만 그 필드에 지정한 조건과 정렬은 그대로 적용된다","그 필드에 지정한 조건이 무시되고 결과에도 나타나지 않는다","필드가 쿼리 디자인에서 삭제되고 조건도 함께 지워진다","결과 열에는 그대로 나타나고 지정한 조건만 적용되며 정렬은 적용되지 않는다"],"answer":0,"explain":"표시 해제는 결과 열만 숨긴다. 조건과 정렬은 계속 적용되므로 보이지 않는 필드로 기준을 걸 때 유용하다."},{"id":"db-0287","subject":"database","levels":["c1"],"topic":"폼","q":"조건부 서식에 대한 설명으로 옳은 것은?","options":["조건을 만족하는 레코드의 필드 값을 지정해 둔 다른 값으로 자동으로 바꾸어 테이블에 저장한다","조건을 만족하는 레코드만 남기고 나머지는 폼에서 숨긴다","컨트롤에 표시되는 글꼴 색·배경색 같은 서식만 바꾸며 저장된 데이터는 변하지 않는다","조건을 만족하면 매크로를 실행해 새 레코드를 추가한다"],"answer":2,"explain":"조건부 서식은 표시 모양만 바꾼다. 데이터 수정은 쿼리나 이벤트로, 레코드 숨기기는 필터로 처리한다."},{"id":"db-0288","subject":"database","levels":["c1"],"topic":"폼","q":"기본 폼의 텍스트 상자에서 하위 폼 컨트롤(이름: 하위주문)에 있는 [합계] 텍스트 상자의 값을 참조하는 식으로 옳은 것은?","options":["=[하위주문]![합계]","=Forms![하위주문]![합계]","=[하위주문].Report![합계]","=[하위주문].Form![합계]"],"answer":3,"explain":"하위 폼 컨트롤의 Form 속성을 거쳐 그 안의 컨트롤을 참조한다. 보고서 하위 개체에는 Report 속성을 쓴다."},{"id":"db-0289","subject":"database","levels":["c1"],"topic":"관계·키","q":"(사번, 이름, 부서) 릴레이션의 현재 데이터에는 이름이 모두 다르다. 이름을 후보키로 볼 수 있는가?","options":["볼 수 없다. 후보키는 현재 값이 아니라 앞으로 어떤 데이터가 들어와도 유일성이 보장되는지로 판단한다","볼 수 있다. 현재 입력된 값이 모두 서로 달라 유일성을 만족하므로 후보키가 되고 기본키로도 쓸 수 있다","볼 수 있다. 다만 최소성을 만족하려면 사번과 함께 써야 한다","볼 수 없다. 후보키는 숫자 형식의 필드만 될 수 있기 때문이다"],"answer":0,"explain":"후보키는 속성의 의미상 중복이 생길 수 없어야 한다. 동명이인이 입사하면 이름은 중복될 수 있다."},{"id":"db-0290","subject":"database","levels":["c1"],"topic":"폼","q":"폼의 레이아웃에서 [스택형]과 [테이블형]의 차이로 옳은 것은?","options":["스택형은 레이블이 위쪽에 놓이고 컨트롤이 가로 줄로 배열되며, 테이블형은 레이블과 컨트롤이 세로로 쌓인다","스택형은 읽기 전용이고 테이블형만 데이터를 입력할 수 있다","스택형은 하위 폼에만, 테이블형은 보고서에만 사용할 수 있다","스택형은 레이블과 컨트롤이 세로로 쌓여 한 레코드를 보여 주고, 테이블형은 컨트롤이 가로 줄로 배열된다"],"answer":3,"explain":"스택형은 레코드 한 건을 세로로 배열하고 테이블형은 표처럼 가로로 배열한다. 둘 다 입력 가능한 폼에서 쓸 수 있다."},{"id":"db-0291","subject":"database","levels":["c1"],"topic":"DB 개념","q":"DBA(데이터베이스 관리자)의 역할로 옳지 않은 것은?","options":["스키마를 정의하고 구조가 바뀔 때 변경을 관리한다","개별 업무 프로그램의 화면 설계와 코딩을 도맡아 작성한다","사용자별 접근 권한과 보안 정책을 정해 시행한다","백업과 회복 절차를 마련하고 저장 공간과 시스템 성능을 주기적으로 점검한다"],"answer":1,"explain":"DBA는 스키마 정의, 저장 구조, 권한·보안, 백업·회복, 성능 관리를 맡는다. 응용 프로그램 개발은 응용 프로그래머의 몫이다."},{"id":"db-0292","subject":"database","levels":["c1"],"topic":"보고서","q":"본문의 텍스트 상자 [금액]의 컨트롤 원본이 =[수량]*[단가]이고 레코드 원본에 [금액] 필드는 없다. 보고서 바닥글에 =Sum([금액])을 쓰면 어떻게 되는가?","options":["컨트롤 이름이 필드처럼 인식되어 오류 없이 모든 레코드의 금액 합계가 정상적으로 표시된다","합계는 표시되지만 본문 첫 레코드의 값만 반영된다","계산 컨트롤은 합산할 수 없어 오류가 나므로 =Sum([수량]*[단가])로 써야 한다","오류 없이 0이 표시되고 레코드가 늘어도 변하지 않는다"],"answer":2,"explain":"집계 함수는 필드나 식을 대상으로 한다. 계산 컨트롤의 이름을 참조해 합산할 수 없으므로 계산식을 Sum 안에 직접 쓴다."},{"id":"db-0293","subject":"database","levels":["c1"],"topic":"DB 개념","q":"트랜잭션의 상태 변화에 대한 설명으로 옳지 않은 것은?","options":["활동(Active) 상태는 트랜잭션이 연산을 실행하고 있는 상태이다","부분 완료 상태는 마지막 연산까지 끝났으나 결과가 아직 확정되지 않은 상태이다","철회(Aborted) 상태는 실패한 트랜잭션이 취소되어 시작 이전 상태로 복구된 상태이다","완료(Committed) 상태는 실행 중 오류가 나서 ROLLBACK으로 취소된 상태이다"],"answer":3,"explain":"완료는 결과가 영구 반영(COMMIT)된 상태이다. 오류로 취소되어 원상 복구된 상태는 철회이다."},{"id":"db-0294","subject":"database","levels":["c1"],"topic":"보고서","q":"한 페이지에 레코드를 여러 열로 나누어 인쇄하는 다단 보고서를 만들 때 열 개수를 지정하는 곳은?","options":["[페이지 설정] 대화 상자의 [인쇄 옵션] 탭","[그룹, 정렬 및 요약] 창의 열 옵션","본문 구역 속성의 [여러 열] 항목","[페이지 설정] 대화 상자의 [열] 탭"],"answer":3,"explain":"열 개수, 열 간격, 열 크기는 [페이지 설정]의 [열] 탭에서 지정한다."},{"id":"db-0295","subject":"database","levels":["c1"],"topic":"관계·키","q":"일련 번호가 아닌 기본키 필드에 값을 입력하지 않은 채 새 레코드를 저장하려 하면 Access는 어떻게 동작하는가?","options":["빈 칸 그대로 저장되며 나중에 기본키 인덱스를 복구해야 다시 사용할 수 있다","바로 위 레코드의 값이 자동으로 복사되어 저장된다","Null 값을 허용하지 않는다는 오류 메시지가 나타나고 저장되지 않는다","Null로 저장되지만 [관계]를 설정할 때만 오류가 난다"],"answer":2,"explain":"개체 무결성에 따라 기본키는 Null일 수 없다. Access는 기본키에 Null을 넣고 저장하는 것을 막는다."},{"id":"db-0296","subject":"database","levels":["c1"],"topic":"폼","q":"명령 단추 마법사의 범주와 동작의 연결이 옳지 않은 것은?","options":["레코드 작업 - 레코드 저장","폼 작업 - 폼 닫기","레코드 탐색 - 레코드 삭제","보고서 작업 - 보고서 미리 보기"],"answer":2,"explain":"레코드 삭제·추가·저장은 레코드 작업 범주이다. 레코드 탐색은 첫째·마지막·다음·이전 레코드로 이동하는 동작이다."},{"id":"db-0297","subject":"database","levels":["c1"],"topic":"관계·키","q":"참조 무결성에서 [관련 필드 모두 업데이트]를 선택하는 것이 실제로 의미가 있는 경우는?","options":["일 쪽 기본키가 일련 번호일 때 가장 효과가 크다","다 쪽의 외래키가 모두 Null일 때만 동작한다","일대일 관계로 연결된 두 테이블에서만 선택할 수 있으며 일대다에서는 쓸 수 없다","일 쪽 기본키 값을 직접 고칠 수 있는 형식(짧은 텍스트, 숫자 등)일 때이다"],"answer":3,"explain":"일련 번호는 사용자가 값을 수정할 수 없으므로 연쇄 업데이트가 필요하지 않다. 직접 수정 가능한 기본키에서 의미가 있다."},{"id":"db-0298","subject":"database","levels":["c1"],"topic":"폼","q":"컨트롤의 [탭 정지] 속성을 아니요로 지정했을 때의 결과로 옳은 것은?","options":["컨트롤이 흐리게 표시되고 마우스로 클릭해도 선택하거나 입력할 수 없게 된다","Tab 키 이동에서는 건너뛰지만 마우스로 클릭해 선택할 수 있다","컨트롤이 폼 보기에서 보이지 않게 숨겨진다","컨트롤이 탭 순서 목록에서 삭제된다"],"answer":1,"explain":"탭 정지를 아니요로 하면 Tab 키 이동에서만 제외된다. 선택 불가는 사용 가능 속성, 숨김은 표시 속성의 일이다."},{"id":"db-0299","subject":"database","levels":["c1"],"topic":"보고서","q":"[그룹, 정렬 및 요약] 창에서 하나의 보고서에 지정할 수 있는 그룹 수준의 최대 개수는?","options":["10개","3개","5개","20개"],"answer":0,"explain":"Access 보고서는 정렬 및 그룹을 최대 10수준까지 지정할 수 있다."},{"id":"db-0300","subject":"database","levels":["c1"],"topic":"쿼리·SQL","q":"주문일 값이 2026-02-28, 2026-03-01, 2026-03-03, 2026-03-05, 2026-03-06인 5개 레코드에 Between #2026-03-01# And #2026-03-05# 조건을 지정하면 조회되는 레코드 수는?","options":["2","4","3","5"],"answer":2,"explain":"Between은 양쪽 경계를 포함한다. 3월 1일, 3일, 5일 레코드가 조회된다."},{"id":"ss-0001","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"VBA 매크로가 들어 있는 통합 문서를 매크로가 유지되도록 저장하려면 어떤 형식을 골라야 하는가?","options":["Excel 통합 문서(*.xlsx)","Excel 매크로 사용 통합 문서(*.xlsm)","Excel 서식 파일(*.xltx)","CSV UTF-8(쉼표로 분리)(*.csv)"],"answer":1,"explain":".xlsx로 저장하면 VBA 프로젝트가 빠진다는 경고가 나온다. .xltx는 매크로 없는 서식 파일, CSV는 값만 저장하는 텍스트 파일이다."},{"id":"ss-0002","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"통합 문서를 CSV(쉼표로 분리) 형식으로 저장할 때의 특징으로 옳지 않은 것은?","options":["통합 문서의 모든 시트가 하나의 CSV 파일에 함께 저장된다.","현재 활성 시트만 저장된다.","수식 대신 계산된 결과 값이 저장된다.","글꼴·채우기 색 같은 셀 서식은 저장되지 않는다."],"answer":0,"explain":"CSV는 텍스트 파일이라 활성 시트 하나의 값만 저장한다. 여러 시트를 한 CSV 파일에 담을 수 없다."},{"id":"ss-0003","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"C3 셀을 선택한 상태에서 [보기]-[틀 고정]-[틀 고정]을 실행했을 때 고정되는 영역은?","options":["1~3행과 A~C열","3행과 C열","1~2행만","1~2행과 A~B열"],"answer":3,"explain":"틀 고정은 선택한 셀의 위쪽 행과 왼쪽 열을 고정한다. C3이면 1~2행과 A~B열이 고정된다."},{"id":"ss-0004","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"창 나누기와 틀 고정에 대한 설명으로 옳지 않은 것은?","options":["창 나누기를 하면 한 시트를 최대 4개 창으로 나누어 볼 수 있다.","틀 고정을 해도 인쇄 결과에는 영향이 없다.","창 나누기를 한 상태로 인쇄하면 나뉜 창마다 다른 페이지로 인쇄된다.","틀 고정과 창 나누기는 [보기] 탭의 [창] 그룹에 있다."],"answer":2,"explain":"창 나누기·틀 고정은 화면 보기 기능일 뿐 인쇄에는 반영되지 않는다. 제목을 모든 페이지에 인쇄하려면 [인쇄 제목]을 쓴다."},{"id":"ss-0005","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[검토]-[통합 문서 보호]에서 '구조'를 보호했을 때 할 수 없는 작업은?","options":["셀 값 수정","셀 서식 변경","셀에 하이퍼링크 삽입","시트 이름 바꾸기"],"answer":3,"explain":"통합 문서 구조 보호는 시트 삽입·삭제·이름 바꾸기·이동·숨기기를 막는다. 셀 내용·서식 수정을 막는 것은 시트 보호다."},{"id":"ss-0006","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"시트 보호와 셀 잠금에 대한 설명으로 옳지 않은 것은?","options":["셀의 '잠금' 설정은 시트를 보호해야 효과가 나타난다.","새 통합 문서의 셀은 기본적으로 '잠금'이 해제되어 있다.","'숨김'을 설정하고 시트를 보호하면 수식 입력줄에 수식이 보이지 않는다.","시트를 보호할 때 사용자에게 허용할 작업을 골라 지정할 수 있다."],"answer":1,"explain":"모든 셀은 기본적으로 '잠금'이 설정되어 있다. 그래서 시트 보호 전에 입력을 허용할 셀만 잠금을 해제한다."},{"id":"ss-0007","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"새 워크시트를 삽입하는 바로 가기 키는?","options":["Shift+F11","F11","Ctrl+N","Ctrl+F4"],"answer":0,"explain":"Shift+F11은 새 워크시트 삽입이다. F11은 차트 시트 만들기, Ctrl+N은 새 통합 문서, Ctrl+F4는 통합 문서 창 닫기다."},{"id":"ss-0008","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"워크시트 이름에 대한 설명으로 옳지 않은 것은?","options":["시트 이름은 최대 31자까지 입력할 수 있다.","시트 이름에 공백을 넣을 수 있다.","시트 이름에 대괄호([ ])를 사용할 수 있다.","한 통합 문서에 이름이 같은 시트를 둘 수 없다."],"answer":2,"explain":"시트 이름에는 \\ / ? * [ ] : 를 쓸 수 없다. 공백은 쓸 수 있고 길이는 31자까지다."},{"id":"ss-0009","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"여러 시트를 그룹으로 선택했을 때의 설명으로 옳지 않은 것은?","options":["제목 표시줄의 파일 이름 뒤에 [그룹]이 표시된다.","그룹 상태에서는 셀에 데이터를 입력할 수 없다.","한 시트에 입력한 내용이 선택한 모든 시트의 같은 셀에 입력된다.","Ctrl을 누른 채 시트 탭을 클릭하면 떨어진 시트를 묶을 수 있다."],"answer":1,"explain":"그룹 상태에서도 입력할 수 있으며, 입력한 내용은 묶인 모든 시트의 같은 위치에 들어간다."},{"id":"ss-0010","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[파일]-[옵션]-[일반]에서 설정할 수 있는 항목은?","options":["자동 복구 정보 저장 간격","반복 계산 사용 여부","Enter 키를 누른 후 이동 방향","새 통합 문서에 포함할 시트 수"],"answer":3,"explain":"새 통합 문서의 시트 수·기본 글꼴은 [일반]에 있다. 자동 복구는 [저장], 반복 계산은 [수식], Enter 이동 방향은 [고급]이다."},{"id":"ss-0011","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"통합 문서를 열 때 암호를 묻도록 설정할 수 있는 곳은?","options":["[다른 이름으로 저장]의 [도구]-[일반 옵션]","[검토] 탭의 [시트 보호]","[파일]-[옵션]의 [보안 센터]","[데이터] 탭의 [데이터 유효성 검사]"],"answer":0,"explain":"[다른 이름으로 저장]-[도구]-[일반 옵션]에서 열기 암호와 쓰기 암호를 지정한다. 시트 보호 암호는 파일 열기를 막지 못한다."},{"id":"ss-0012","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"시트 숨기기에 대한 설명으로 옳지 않은 것은?","options":["숨긴 시트의 셀도 다른 시트의 수식에서 참조할 수 있다.","시트 탭 바로 가기 메뉴의 [숨기기 취소]로 다시 표시한다.","통합 문서의 모든 시트를 한꺼번에 숨길 수 있다.","통합 문서 구조를 보호하면 숨기기 취소를 할 수 없다."],"answer":2,"explain":"통합 문서에는 적어도 하나의 시트가 표시되어 있어야 하므로 모든 시트를 숨길 수는 없다."},{"id":"ss-0013","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"통합 문서를 다른 사람에게 보내기 전에 숨겨진 속성, 작성자 같은 개인 정보, 숨긴 행·시트 등을 찾아 제거할 수 있는 기능은?","options":["호환성 검사","접근성 검사","통합 문서 통계","문서 검사"],"answer":3,"explain":"[파일]-[정보]-[문제 확인]-[문서 검사]가 숨겨진 데이터와 개인 정보를 찾아 제거한다. 접근성 검사는 장애가 있는 사용자가 읽기 어려운 부분을 찾는다."},{"id":"ss-0014","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"[파일]-[옵션]-[고급]의 '이 워크시트의 표시 옵션'에서 설정할 수 있는 항목이 아닌 것은?","options":["눈금선 표시","0 값이 있는 셀에 0 표시","새 시트의 기본 글꼴","행 및 열 머리글 표시"],"answer":2,"explain":"눈금선·0 값·행/열 머리글 표시는 시트별 표시 옵션이다. 기본 글꼴은 [일반]의 '새 통합 문서 만들기'에서 정한다."},{"id":"ss-0015","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"[파일]-[옵션]-[수식]에서 설정할 수 있는 항목으로 옳지 않은 것은?","options":["통합 문서 계산을 자동 또는 수동으로 지정","셀에 노트가 있을 때 표시 방법","반복 계산 사용과 최대 반복 횟수","R1C1 참조 스타일 사용"],"answer":1,"explain":"계산 옵션·반복 계산·R1C1 참조 스타일은 [수식]에 있다. 노트·메모 표시 방법은 [고급]의 표시 항목이다."},{"id":"ss-0016","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"[보기]-[사용자 지정 보기]에 대한 설명으로 옳지 않은 것은?","options":["통합 문서에 표(Ctrl+T)가 있어도 사용자 지정 보기를 만들 수 있다.","숨긴 행·열과 필터 설정을 보기로 저장할 수 있다.","인쇄 설정을 보기에 함께 저장할 수 있다.","여러 보기를 이름으로 저장해 바꿔 가며 볼 수 있다."],"answer":0,"explain":"통합 문서에 표(Excel 표)가 하나라도 있으면 [사용자 지정 보기]가 비활성화된다."},{"id":"ss-0017","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"한 셀 안에서 줄을 바꾸어 두 줄로 입력하려면 누르는 키는?","options":["Ctrl+Enter","Alt+Enter","Shift+Enter","Tab"],"answer":1,"explain":"Alt+Enter가 셀 안 줄 바꿈이다. Ctrl+Enter는 선택한 여러 셀에 같은 값 입력, Shift+Enter는 입력 후 위 셀로 이동한다."},{"id":"ss-0018","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"오늘 날짜와 현재 시간을 입력하는 바로 가기 키를 차례로 짝지은 것은?","options":["Ctrl+; / Ctrl+Shift+;","Ctrl+Shift+; / Ctrl+;","Ctrl+: / Ctrl+;","Alt+; / Alt+Shift+;"],"answer":0,"explain":"Ctrl+;는 오늘 날짜, Ctrl+Shift+;(Ctrl+:)는 현재 시간이다. 둘을 바꿔 외우기 쉬우니 주의한다."},{"id":"ss-0019","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"A1에 10, A2에 13을 입력하고 A1:A2를 선택한 뒤 채우기 핸들을 A5까지 끌었을 때 A5의 값은?","options":["13","19","22","25"],"answer":2,"explain":"두 셀을 함께 끌면 차이(3)만큼 늘어난다. 10, 13, 16, 19, 22."},{"id":"ss-0020","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"A1에 날짜 2026-01-31을 입력하고 채우기 핸들로 A2까지 끈 뒤 [자동 채우기 옵션]에서 '월 단위 채우기'를 고르면 A2의 값은?","options":["2026-02-01","2026-03-03","2026-03-01","2026-02-28"],"answer":3,"explain":"월 단위 채우기는 날짜의 '일'을 유지하되 그 달에 없는 날이면 말일로 맞춘다. 그냥 끌면 일 단위로 늘어 2026-02-01이 된다."},{"id":"ss-0021","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"사용자 지정 목록에 대한 설명으로 옳지 않은 것은?","options":["[파일]-[옵션]-[고급]의 [사용자 지정 목록 편집]에서 만든다.","숫자로만 된 항목도 그대로 사용자 지정 목록으로 추가할 수 있다.","첫 항목을 입력하고 끌면 다음 항목이 차례로 채워진다.","정렬할 때 사용자 지정 목록의 순서를 기준으로 쓸 수 있다."],"answer":1,"explain":"사용자 지정 목록은 텍스트나 텍스트와 숫자가 섞인 항목으로 만든다. 숫자만으로 된 목록은 그대로는 만들 수 없다."},{"id":"ss-0022","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"날짜·시간 데이터에 대한 설명으로 옳지 않은 것은?","options":["시간은 1시간을 1로 하는 일련번호로 저장된다.","날짜는 1900-01-01을 1로 하는 일련번호로 저장된다.","날짜를 입력하면 기본적으로 셀의 오른쪽에 맞춰진다.","'10/4'처럼 연도를 빼고 입력하면 올해 날짜가 된다."],"answer":0,"explain":"시간은 하루(24시간)를 1로 한 소수로 저장된다. 예를 들어 12:00은 0.5다."},{"id":"ss-0023","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"Windows 기본 설정에서 셀에 '29/3/1'을 입력했을 때 입력되는 날짜는?","options":["1929-03-01","2026-03-29","2029-01-03","2029-03-01"],"answer":3,"explain":"두 자리 연도 00~29는 2000~2029년, 30~99는 1930~1999년으로 해석한다. 연/월/일 순서이므로 2029-03-01이다."},{"id":"ss-0024","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"데이터 입력에 대한 설명으로 옳지 않은 것은?","options":["분수 1/2은 '0 1/2'처럼 0과 공백을 먼저 입력한다.","15자리를 넘는 숫자는 16번째 자리부터 0으로 바뀐다.","숫자 앞에 작은따옴표(')를 붙이면 숫자로 인식되어 오른쪽에 맞춰진다.","문자 데이터는 기본적으로 셀의 왼쪽에 맞춰진다."],"answer":2,"explain":"작은따옴표를 붙이면 숫자도 텍스트로 입력되어 왼쪽에 맞춰진다. 0 없이 1/2을 입력하면 날짜(1월 2일)가 된다."},{"id":"ss-0025","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"[찾기 및 바꾸기]에서 별표(*) 문자 자체를 찾으려 할 때 '찾을 내용'에 입력할 값은?","options":["\\*","\"*\"","?*","~*"],"answer":3,"explain":"*와 ?는 와일드카드이므로 문자 자체를 찾으려면 앞에 물결표(~)를 붙인다."},{"id":"ss-0026","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"[찾기 및 바꾸기] 기능에 대한 설명으로 옳지 않은 것은?","options":["Ctrl+F는 [찾기] 탭, Ctrl+H는 [바꾸기] 탭을 연다.","바꾸기 기능으로는 셀 서식을 바꿀 수 없다.","범위를 '시트' 또는 '통합 문서'로 지정할 수 있다.","'전체 셀 내용 일치'는 셀 내용 전체가 같은 셀만 찾는다."],"answer":1,"explain":"[옵션]의 [서식] 단추로 찾을 서식과 바꿀 서식을 지정할 수 있다."},{"id":"ss-0027","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"B1 셀에 =A1*2가 입력되어 있다. B1을 복사하여 D3에 붙여 넣었을 때 D3의 수식은?","options":["=C3*2","=A1*2","=A3*2","=C1*2"],"answer":0,"explain":"상대 참조는 복사한 거리만큼 바뀐다. B1→D3은 2열·2행 이동이므로 A1이 C3이 된다."},{"id":"ss-0028","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"[선택하여 붙여넣기] 대화 상자의 '연산' 항목에 없는 것은?","options":["더하기","곱하기","평균","나누기"],"answer":2,"explain":"연산은 없음·더하기·빼기·곱하기·나누기 다섯 가지다. 예를 들어 1.1을 복사해 '곱하기'로 붙이면 값이 10% 오른다."},{"id":"ss-0029","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"Microsoft 365 Excel의 노트(이전 버전의 메모)에 대한 설명으로 옳지 않은 것은?","options":["노트가 있는 셀은 오른쪽 위 모서리에 빨간 삼각형이 표시된다.","셀을 선택하고 Delete 키를 누르면 셀 내용과 노트가 함께 지워진다.","데이터를 정렬하면 노트도 해당 셀과 함께 이동한다.","[검토] 탭에서 모든 노트를 한꺼번에 표시하거나 숨길 수 있다."],"answer":1,"explain":"Delete 키는 내용만 지운다. 노트는 바로 가기 메뉴의 [노트 삭제]나 [홈]-[지우기]에서 지운다."},{"id":"ss-0030","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"이름 정의 규칙에 대한 설명으로 옳지 않은 것은?","options":["첫 글자는 문자, 밑줄(_), 백슬래시(\\) 중 하나여야 한다.","'A1'처럼 셀 주소와 같은 이름은 쓸 수 없다.","이름에 공백을 넣어 '매출 합계'처럼 정의할 수 있다.","이름은 대소문자를 구분하지 않는다."],"answer":2,"explain":"이름에는 공백을 쓸 수 없으므로 '매출_합계'처럼 밑줄이나 마침표로 대신한다."},{"id":"ss-0031","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"셀 편집 관련 바로 가기 키 설명으로 옳지 않은 것은?","options":["Ctrl+R: 위쪽 셀의 내용을 선택 범위 아래로 복사","F2: 활성 셀을 편집 상태로 전환","Ctrl+D: 위쪽 셀의 내용을 선택 범위 아래로 복사","Ctrl+-: [삭제] 대화 상자 표시"],"answer":0,"explain":"Ctrl+R은 왼쪽 셀을 오른쪽으로 채운다. 위쪽 셀을 아래로 채우는 것은 Ctrl+D다."},{"id":"ss-0032","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"B열에 '홍길동(영업)' 형식의 데이터가 있고 C2에 '홍길동'만 입력했다. C열 나머지를 같은 패턴으로 한 번에 채우는 기능과 바로 가기 키는?","options":["자동 완성, Ctrl+E","빠른 채우기, Ctrl+D","자동 채우기, Ctrl+R","빠른 채우기, Ctrl+E"],"answer":3,"explain":"빠른 채우기(Ctrl+E)는 입력한 예시의 패턴을 읽어 나머지를 채운다. Ctrl+D는 위 셀 복사다."},{"id":"ss-0033","subject":"spreadsheet","levels":["c1"],"topic":"입력·편집","q":"Excel에서 숫자 1234567890123456789를 일반 숫자로 입력했을 때 셀에 저장되는 값은?","options":["1234567890123450000","1234567890123456789","1234567890123460000","#NUM!"],"answer":0,"explain":"Excel은 유효 숫자 15자리까지만 저장하므로 16번째 자리부터는 0으로 바뀐다(반올림하지 않음). 그대로 남기려면 텍스트로 입력한다."},{"id":"ss-0034","subject":"spreadsheet","levels":["c1"],"topic":"입력·편집","q":"복사한 범위에 빈 셀이 섞여 있을 때, 붙여 넣을 곳의 기존 값이 빈 셀 때문에 지워지지 않게 하려면 [선택하여 붙여넣기]에서 어떤 옵션을 고르는가?","options":["행/열 바꿈","연결하여 붙여넣기","유효성 검사","빈 셀 건너뛰기(Skip blanks)"],"answer":3,"explain":"'빈 셀 건너뛰기'는 원본의 빈 셀을 건너뛰어 대상 셀의 값을 그대로 둔다. 한국어 Excel에서는 '내용 있는 셀 제외'라는 이름으로 표시되기도 한다."},{"id":"ss-0035","subject":"spreadsheet","levels":["c1"],"topic":"입력·편집","q":"이름 관리자에서 범위를 'Sheet1'로 지정해 만든 이름 '세율'을 Sheet2의 수식에서 쓰려면 어떻게 쓰는가?","options":["=세율","=Sheet1!세율","=[Sheet1]세율","=Sheet1.세율"],"answer":1,"explain":"범위가 특정 시트인 이름은 다른 시트에서 '시트이름!이름'으로 참조한다. 범위가 '통합 문서'인 이름만 이름만으로 쓸 수 있다."},{"id":"ss-0036","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 1234567에 사용자 지정 표시 형식 #,##0, 을 적용했을 때 표시 결과는?","options":["1,234","1,234,567","1,235","1,235,000"],"answer":2,"explain":"형식 끝의 쉼표 하나는 천 단위를 생략하며 반올림한다. 1234.567 → 1,235."},{"id":"ss-0037","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 -2500에 표시 형식 #,##0;[빨강](#,##0)을 적용한 결과는?","options":["빨간색 -2,500","검은색 (2,500)","빨간색 (-2,500)","빨간색 (2,500)"],"answer":3,"explain":"두 번째 구역이 음수 서식이다. 구역을 따로 지정하면 음수 부호는 자동으로 붙지 않고 괄호와 빨강만 적용된다."},{"id":"ss-0038","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀에 '홍길동'이 입력되어 있고 표시 형식 @\"님\"을 적용했을 때 결과는?","options":["홍길동님","님홍길동","@님","홍길동"],"answer":0,"explain":"@는 입력한 텍스트 자리이고 큰따옴표 안 문자는 그대로 붙는다."},{"id":"ss-0039","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"사용자 지정 표시 형식 ;;; 을 적용한 셀에 대한 설명으로 옳은 것은?","options":["세미콜론 세 개가 표시된다.","셀에 값이 보이지 않는다.","숫자만 보이고 텍스트는 숨겨진다.","0만 빈칸으로 보인다."],"answer":1,"explain":"양수;음수;0;텍스트 네 구역을 모두 비웠으므로 어떤 값도 셀에 표시되지 않는다. 수식 입력줄에서는 값이 보인다."},{"id":"ss-0040","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 0에 표시 형식 #,###을 적용한 결과는?","options":["0","0,000","(빈칸)","#"],"answer":2,"explain":"#은 의미 없는 0을 표시하지 않으므로 0은 아무것도 보이지 않는다. 0을 보이게 하려면 #,##0을 쓴다."},{"id":"ss-0041","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"2026년 10월 4일(일요일) 날짜에 표시 형식 yyyy-mm-dd aaa를 적용한 결과는?","options":["2026-10-04 일","2026-10-04 일요일","2026-10-04 Sun","2026-10-04 Sunday"],"answer":0,"explain":"aaa는 한글 요일 한 글자, aaaa는 '일요일', ddd는 Sun, dddd는 Sunday로 표시한다."},{"id":"ss-0042","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 1.5에 표시 형식 [h]:mm을 적용한 결과는?","options":["12:00","1:30","1:50","36:00"],"answer":3,"explain":"1.5일은 36시간이다. [h]는 24를 넘는 시간을 누적해 표시한다. h:mm이었다면 12:00으로 보인다."},{"id":"ss-0043","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 1500에 사용자 지정 형식 [>=1000]#,##0,\"천\";0 을 적용한 결과는?","options":["1.5천","2천","1천","1,500"],"answer":1,"explain":"1500은 첫 조건(1000 이상)에 맞는다. 끝의 쉼표로 천 단위를 생략하며 소수 자릿수가 없으므로 1.5가 반올림되어 2천이 된다."},{"id":"ss-0044","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"사용자 지정 형식 [빨강][<=50]0;[파랑][>100]0;0 을 적용했을 때 셀 값 30, 80, 120의 표시 색으로 옳은 것은?","options":["30 빨강, 80 파랑, 120 파랑","30 기본색, 80 빨강, 120 파랑","30 빨강, 80 기본색, 120 파랑","30 빨강, 80 빨강, 120 파랑"],"answer":2,"explain":"첫 구역(50 이하)은 빨강, 둘째 구역(100 초과)은 파랑, 두 조건에 모두 맞지 않는 값은 세 번째 구역(색 지정 없음)으로 표시된다."},{"id":"ss-0045","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 3.75에 표시 형식 # ?/? 를 적용한 결과는?","options":["3 1/2","15/4","3.75","3 3/4"],"answer":3,"explain":"# ?/?는 정수 부분과 한 자리 분모의 분수로 표시한다. 0.75 = 3/4."},{"id":"ss-0046","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"사용자 지정 표시 형식에 대한 설명으로 옳지 않은 것은?","options":["구역은 세미콜론(;)으로 나누며 최대 4개까지 쓸 수 있다.","색은 [빨강]처럼 대괄호 안에 써서 구역 맨 앞에 둔다.","구역은 '음수;양수;0;텍스트' 순서로 지정한다.","#은 의미 없는 0을 숨기고, 0은 자릿수만큼 0을 채운다."],"answer":2,"explain":"구역의 순서는 '양수;음수;0;텍스트'다."},{"id":"ss-0047","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"A2:E20 범위에 조건부 서식을 적용해 C열 점수가 80 이상인 행 전체에 색을 채우려 한다. 규칙 수식으로 옳은 것은?","options":["=C$2>=80","=$C2>=80","=$C$2>=80","=C2>=80"],"answer":1,"explain":"열은 C로 고정하고(행 전체가 C열을 보게) 행은 상대 참조로 두어야 한다. =C2>=80이면 열마다 다른 셀을 보게 된다."},{"id":"ss-0048","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"조건부 서식에 대한 설명으로 옳지 않은 것은?","options":["한 셀에는 조건부 서식 규칙을 하나만 지정할 수 있다.","규칙이 여러 개면 [규칙 관리]에서 우선순위를 바꿀 수 있다.","데이터 막대·색조·아이콘 집합으로 값의 크기를 표현할 수 있다.","수식을 사용하는 규칙은 결과가 TRUE일 때 서식이 적용된다."],"answer":0,"explain":"한 셀에 여러 규칙을 지정할 수 있으며, 충돌하면 우선순위가 높은 규칙이 적용된다."},{"id":"ss-0049","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"A2:F50에 조건부 서식을 적용해 짝수 행마다 채우기 색을 넣으려 한다. 규칙 수식으로 옳은 것은?","options":["=MOD(COLUMN(),2)=0","=ROW()/2=0","=MOD(ROW(),2)=0","=MOD(ROW(),2)=1"],"answer":2,"explain":"ROW()는 현재 행 번호이고 MOD(행,2)=0이면 짝수 행이다. =1이면 홀수 행, COLUMN은 열 번호다."},{"id":"ss-0050","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"범위를 표로 변환(Ctrl+T)했을 때의 설명으로 옳지 않은 것은?","options":["표 바로 아래에 데이터를 입력하면 표 범위가 자동으로 늘어난다.","표 상태에서도 [데이터]-[부분합]을 바로 실행할 수 있다.","[표 디자인] 탭에서 요약 행을 표시할 수 있다.","수식에서 표1[매출]처럼 구조적 참조를 쓸 수 있다."],"answer":1,"explain":"표에서는 부분합이 비활성화된다. [범위로 변환]한 뒤 부분합을 실행한다."},{"id":"ss-0051","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"[셀 서식]-[맞춤] 탭에서 '셀에 맞춤'을 선택했을 때의 결과는?","options":["열 너비가 내용에 맞게 늘어난다.","텍스트가 여러 줄로 나뉘어 표시된다.","선택한 셀들이 하나로 병합된다.","글자 크기가 셀 너비에 맞게 줄어 보인다."],"answer":3,"explain":"'셀에 맞춤'은 열 너비는 그대로 두고 글자를 줄여 보이게 한다. 여러 줄 표시는 '텍스트 줄 바꿈'이다."},{"id":"ss-0052","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"서식 관련 바로 가기 키 연결이 옳지 않은 것은?","options":["Ctrl+5: 밑줄","Ctrl+B: 굵게","Ctrl+Shift+%: 백분율 형식","Ctrl+Shift+$: 통화 형식"],"answer":0,"explain":"Ctrl+5는 취소선이다. 밑줄은 Ctrl+U(또는 Ctrl+4)다."},{"id":"ss-0053","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 -0.5에 사용자 지정 형식 0.0;(0.0);\"영\" 을 적용한 결과는?","options":["(0.5)","-0.5","영","(-0.5)"],"answer":0,"explain":"음수이므로 두 번째 구역 (0.0)이 적용된다. 구역을 지정하면 음수 부호는 따로 붙지 않는다."},{"id":"ss-0054","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 2500000에 사용자 지정 형식 0.0,,\"백만\" 을 적용한 결과는?","options":["2500.0백만","2.5","3백만","2.5백만"],"answer":3,"explain":"쉼표 두 개는 백만 단위를 생략한다. 2,500,000 → 2.5, 형식이 0.0이므로 2.5백만이다."},{"id":"ss-0055","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 0.5에 표시 형식 h:mm AM/PM을 적용한 결과는?","options":["12:00 AM","12:00 PM","0:30 AM","0:00 PM"],"answer":1,"explain":"0.5일은 정오(12시)다. AM/PM 형식에서 정오는 12:00 PM으로 표시된다."},{"id":"ss-0056","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 -1234.5에 사용자 지정 형식 #,##0;[빨강]-#,##0;\"-\" 를 적용한 결과는?","options":["빨간색 -1,234","빨간색 (1,235)","빨간색 -1,235","-"],"answer":2,"explain":"음수 구역 [빨강]-#,##0이 적용되고 소수가 없으므로 반올림된다. '-' 문자는 값이 0일 때의 세 번째 구역이다."},{"id":"ss-0057","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"날짜 2026-07-09에 표시 형식 m/d(aaaa)를 적용한 결과는?","options":["07/09(목)","7/9(목요일)","7/9(목)","7/9(Thursday)"],"answer":1,"explain":"m과 d는 앞에 0을 붙이지 않는 월·일, aaaa는 '목요일'처럼 요일 전체를 한글로 표시한다."},{"id":"ss-0058","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"조건부 서식의 [셀 강조 규칙]에 있는 항목이 아닌 것은?","options":["상위 10개 항목","다음 값의 사이에 있음","텍스트 포함","중복 값"],"answer":0,"explain":"상위 10개 항목·평균 초과 등은 [상위/하위 규칙]에 있다. 셀 강조 규칙은 보다 큼·작음·사이·같음·텍스트 포함·발생 날짜·중복 값이다."},{"id":"ss-0059","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =2+3*2^2 의 결과는?","options":["20","38","64","14"],"answer":3,"explain":"거듭제곱(^) → 곱하기(*) → 더하기(+) 순서로 계산한다. 2^2=4, 3*4=12, 2+12=14."},{"id":"ss-0060","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =-2^2 의 결과는?","options":["-4","0","4","#VALUE!"],"answer":2,"explain":"Excel에서는 음수 부호(-)가 거듭제곱(^)보다 먼저 계산되어 (-2)^2=4가 된다. 수학식처럼 -4가 되지 않는 점이 함정이다."},{"id":"ss-0061","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =\"A\"&1+2 의 결과는?","options":["A12","#VALUE!","A1+2","A3"],"answer":3,"explain":"산술 연산(+)이 연결 연산(&)보다 먼저 계산되어 1+2=3이 된 뒤 \"A\"와 연결된다."},{"id":"ss-0062","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"Excel 연산자 %, ^, *, &, = 의 우선순위를 높은 것부터 바르게 나열한 것은?","options":["% → ^ → * → & → =","^ → % → * → = → &","* → ^ → % → & → =","% → * → ^ → = → &"],"answer":0,"explain":"우선순위는 참조 연산자 → 음수 부호 → % → ^ → *·/ → +·- → & → 비교 연산자 순서다."},{"id":"ss-0063","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"C1 셀에 =$A1*B$1이 입력되어 있다. C1을 복사하여 E4에 붙여 넣으면 E4의 수식은?","options":["=$A1*D$1","=$A4*B$4","=$A4*D$1","=$C4*D$1"],"answer":2,"explain":"C1→E4는 2열·3행 이동이다. $A1은 열 고정이라 행만 바뀌어 $A4, B$1은 행 고정이라 열만 바뀌어 D$1이 된다."},{"id":"ss-0064","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식을 입력하면서 A1 참조에 커서를 두고 F4 키를 세 번 누르면 참조는 어떻게 바뀌는가?","options":["A$1","$A1","$A$1","A1"],"answer":1,"explain":"F4를 누를 때마다 A1 → $A$1 → A$1 → $A1 → A1 순서로 바뀐다. 세 번이면 $A1이다."},{"id":"ss-0065","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"다른 통합 문서 '실적.xlsx'의 Sales 시트 B3 셀을 참조하는 형식으로 옳은 것은? (두 파일 모두 열려 있음)","options":["=실적.xlsx!Sales!B3","=[실적.xlsx]Sales!B3","=Sales[실적.xlsx]!B3","=[Sales]실적.xlsx!B3"],"answer":1,"explain":"외부 참조는 [파일 이름]시트 이름!셀 형식이다. 파일이 닫혀 있으면 앞에 전체 경로가 붙고 작은따옴표로 묶인다."},{"id":"ss-0066","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 오류 값과 그 의미의 연결이 옳지 않은 것은?","options":["#N/A: 찾는 값이 없거나 사용할 수 없을 때","#REF!: 참조한 셀이 삭제되어 참조가 잘못되었을 때","#NUM!: 숫자 인수가 잘못되었거나 결과가 너무 클 때","#NAME?: 수식에서 0으로 나누었을 때"],"answer":3,"explain":"0으로 나누면 #DIV/0!이다. #NAME?은 함수 이름·정의된 이름을 잘못 썼거나 텍스트를 따옴표 없이 썼을 때 나온다."},{"id":"ss-0067","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"=SUM(A1:A3 C1:C3)처럼 공백(교점 연산자)으로 이은 두 범위가 겹치지 않을 때 나타나는 오류는?","options":["#REF!","#VALUE!","#NULL!","#N/A"],"answer":2,"explain":"공백은 두 범위의 교차 영역을 뜻하는데, 교차하는 셀이 없으면 #NULL!이 된다."},{"id":"ss-0068","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =ROUND(1234.567,-2) 의 결과는?","options":["1200","1234.57","1300","1230"],"answer":0,"explain":"자릿수가 -2이면 십의 자리에서 반올림해 백의 자리까지 남긴다."},{"id":"ss-0069","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =ROUNDDOWN(-3.78,1) 의 결과는?","options":["-3.8","-3","-4","-3.7"],"answer":3,"explain":"ROUNDDOWN은 0에 가까운 쪽으로 자르므로 -3.78은 -3.7이 된다."},{"id":"ss-0070","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =INT(-3.2)+TRUNC(-3.2) 의 결과는?","options":["-6","-8","-7","-6.4"],"answer":2,"explain":"INT는 더 작은 정수로 내리므로 -4, TRUNC는 소수만 잘라 -3이다. 합은 -7."},{"id":"ss-0071","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =MOD(-7,3) 의 결과는?","options":["-1","2","1","-2"],"answer":1,"explain":"MOD의 결과 부호는 나누는 수(3)를 따른다. -7 = 3×(-3) + 2."},{"id":"ss-0072","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =SUMPRODUCT({1,2,3},{4,5,6}) 의 결과는?","options":["32","21","15","90"],"answer":0,"explain":"같은 위치끼리 곱해 더한다. 1×4+2×5+3×6 = 32."},{"id":"ss-0073","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =MID(\"2026-10-04\",6,2)&\"월\" 의 결과는?","options":["10월","-1월","6월","04월"],"answer":0,"explain":"6번째 글자부터 2글자를 꺼내면 \"10\"이다."},{"id":"ss-0074","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"=FIND(\"e\",\"Excel\")과 =SEARCH(\"e\",\"Excel\")의 결과를 차례로 쓴 것은?","options":["1, 4","1, 1","4, 4","4, 1"],"answer":3,"explain":"FIND는 대소문자를 구분해 소문자 e의 위치 4를, SEARCH는 구분하지 않아 첫 글자 E의 위치 1을 돌려준다."},{"id":"ss-0075","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =REPLACE(\"20261004\",5,0,\"-\") 의 결과는?","options":["2026-004","202-61004","2026-1004","20261004-"],"answer":2,"explain":"바꿀 글자 수가 0이면 아무것도 지우지 않고 5번째 자리 앞에 \"-\"를 끼워 넣는다."},{"id":"ss-0076","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =LEN(TRIM(\"  컴퓨터   활용  \")) 의 결과는?","options":["5","6","7","12"],"answer":1,"explain":"TRIM은 앞뒤 공백을 지우고 단어 사이 공백을 하나만 남긴다. \"컴퓨터 활용\"은 6글자다."},{"id":"ss-0077","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =DATE(2026,13,1) 의 결과로 표시되는 날짜는?","options":["2026-12-01","#NUM!","2027-01-01","2026-01-13"],"answer":2,"explain":"월이 12를 넘으면 다음 해로 넘어간다. 2026년 13월 = 2027년 1월."},{"id":"ss-0078","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"2026-10-04은 일요일이다. 수식 =WEEKDAY(\"2026-10-04\",2) 의 결과는?","options":["1","0","6","7"],"answer":3,"explain":"유형 2는 월요일=1 ~ 일요일=7이다. 유형 1(생략)이면 일요일=1, 유형 3이면 월요일=0이다."},{"id":"ss-0079","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =EDATE(\"2026-01-31\",1) 의 결과로 표시되는 날짜는?","options":["2026-03-03","2026-02-28","2026-02-01","2026-03-02"],"answer":1,"explain":"EDATE는 같은 일자의 1개월 뒤를 구하는데, 2월에는 31일이 없으므로 그 달 말일이 된다."},{"id":"ss-0080","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =DATEDIF(\"2026-01-15\",\"2026-10-04\",\"m\") 의 결과는?","options":["8","9","7","10"],"answer":0,"explain":"\"m\"은 다 채운 개월 수다. 1/15부터 9/15까지 8개월이고, 10/4는 10/15 전이므로 9개월을 채우지 못한다."},{"id":"ss-0081","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"2026-10-01은 목요일이다. 공휴일 인수를 생략한 수식 =NETWORKDAYS(\"2026-10-01\",\"2026-10-09\") 의 결과는?","options":["9","6","7","5"],"answer":2,"explain":"주말을 뺀 평일 수다. 10/1(목)·10/2(금), 10/5(월)~10/9(금) 5일로 모두 7일이며 시작일과 종료일을 포함한다."},{"id":"ss-0082","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"2026-10-02은 금요일이다. 공휴일 인수를 생략한 수식 =WORKDAY(\"2026-10-02\",3) 의 결과로 표시되는 날짜는?","options":["2026-10-05","2026-10-06","2026-10-08","2026-10-07"],"answer":3,"explain":"시작일 다음 평일부터 센다. 10/5(월)이 1일, 10/6이 2일, 10/7(수)이 3일째다."},{"id":"ss-0083","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =IF(AND(85>=80,70<60),\"합격\",IF(OR(85>=90,70>=70),\"보류\",\"불합격\")) 의 결과는?","options":["합격","보류","불합격","FALSE"],"answer":1,"explain":"70<60이 거짓이라 AND는 FALSE, 다음 IF의 OR은 70>=70이 참이므로 TRUE가 되어 \"보류\"다."},{"id":"ss-0084","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =VLOOKUP(\"박\",A2:D6,4,FALSE) 의 결과는?","options":["150","과장","90","#N/A"],"answer":0,"explain":"첫 열에서 \"박\"을 정확히 찾아 같은 행의 4번째 열(매출) 값을 돌려준다."},{"id":"ss-0085","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =INDEX(B2:B6,MATCH(MAX(D2:D6),D2:D6,0)) 의 결과는?","options":["박","150","과장","영업"],"answer":3,"explain":"매출 최댓값 150은 4행(범위 안 3번째)에 있고, 같은 위치의 부서는 \"영업\"이다."},{"id":"ss-0086","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =SUMIF(B2:B6,\"영업\",D2:D6) 의 결과는?","options":["270","330","210","3"],"answer":1,"explain":"부서가 영업인 행의 매출 120+150+60 = 330이다."},{"id":"ss-0087","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =COUNTIFS(B2:B6,\"영업\",D2:D6,\">=100\") 의 결과는?","options":["3","1","2","270"],"answer":2,"explain":"부서가 영업이면서 매출이 100 이상인 행은 김(120)과 박(150) 두 개다."},{"id":"ss-0088","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =RANK.EQ(D2,D2:D6,1) 의 결과는?","options":["4","2","1","5"],"answer":0,"explain":"세 번째 인수 1은 오름차순 순위다. 60, 80, 90, 120 순으로 120은 4위다. 생략(0)하면 내림차순 2위다."},{"id":"ss-0089","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"A1:A6에 차례로 10, '합격', (빈 셀), TRUE, 5, 0이 입력되어 있을 때 =COUNT(A1:A6)+COUNTA(A1:A6)+COUNTBLANK(A1:A6) 의 결과는?","options":["8","10","7","9"],"answer":3,"explain":"COUNT는 숫자 10·5·0으로 3, COUNTA는 빈 셀을 뺀 5, COUNTBLANK는 1이다. 범위 안의 TRUE는 COUNT에서 세지 않는다."},{"id":"ss-0090","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =MEDIAN(3,8,1,6)+MODE.SNGL(2,5,5,3,3,5) 의 결과는?","options":["8.5","10","9.5","7.5"],"answer":2,"explain":"MEDIAN은 정렬한 1,3,6,8의 가운데 두 값 평균 4.5, MODE.SNGL은 가장 많이 나온 5다. 4.5+5=9.5."},{"id":"ss-0091","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"A1=10, A2='없음'(텍스트), A3=(빈 셀), A4=20일 때 =AVERAGE(A1:A4)와 =AVERAGEA(A1:A4)의 결과를 차례로 쓴 것은?","options":["15, 10","15, 7.5","10, 10","7.5, 7.5"],"answer":0,"explain":"AVERAGE는 숫자만 평균해 (10+20)/2=15, AVERAGEA는 텍스트를 0으로 세어 (10+0+20)/3=10이다. 빈 셀은 둘 다 제외한다."},{"id":"ss-0092","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\nF1에 '직급', F2에 '대리'가 입력되어 있을 때 =DAVERAGE(A1:D6,\"매출\",F1:F2) 의 결과는?","options":["120","100","200","80"],"answer":1,"explain":"조건 범위(직급=대리)에 맞는 김(120)·최(80)의 매출 평균은 100이다."},{"id":"ss-0093","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"데이터베이스 함수(DSUM, DCOUNT 등)에 대한 설명으로 옳지 않은 것은?","options":["첫 번째 인수 범위에는 필드 이름 행이 포함되어야 한다.","필드 인수는 열 번호나 \"매출\" 같은 필드 이름으로 지정한다.","조건 범위에는 필드 이름 없이 조건 값만 입력한다.","조건을 같은 행에 쓰면 AND, 다른 행에 쓰면 OR로 결합된다."],"answer":2,"explain":"조건 범위는 필드 이름(머리글)과 그 아래 조건으로 이루어져야 한다."},{"id":"ss-0094","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 배열 수식 {=SUM((B2:B6=\"영업\")*(D2:D6>=100))} 의 결과는?","options":["270","2","3","1"],"answer":1,"explain":"두 조건 배열을 곱하면 둘 다 참인 행만 1이 된다. 영업이면서 100 이상인 행은 2개다."},{"id":"ss-0095","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 배열 수식 {=SUM(IF(C2:C6=\"대리\",D2:D6))} 의 결과는?","options":["200","2","100","120"],"answer":0,"explain":"직급이 대리인 행의 매출 120+80만 더해 200이다."},{"id":"ss-0096","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =SUMPRODUCT((B2:B6=\"영업\")*(C2:C6=\"과장\")*D2:D6) 의 결과는?","options":["240","1","330","150"],"answer":3,"explain":"영업이면서 과장인 행은 박 하나뿐이므로 매출 150이다."},{"id":"ss-0097","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 배열 수식 {=SUM(1/COUNTIF(B2:B6,B2:B6))} 의 결과는?","options":["3","5","1","2"],"answer":0,"explain":"각 값의 등장 횟수의 역수를 더하면 고유 값 개수가 된다. 영업(1/3×3)+총무(1)+기획(1) = 3."},{"id":"ss-0098","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"배열 수식에 대한 설명으로 옳지 않은 것은?","options":["이전 버전 방식에서는 Ctrl+Shift+Enter로 입력해 앞뒤에 중괄호가 붙는다.","배열 상수에서 열은 쉼표(,), 행은 세미콜론(;)으로 구분한다.","배열 수식을 둘러싼 중괄호({ })는 키보드로 직접 입력한다.","여러 셀에 걸친 배열 수식은 그중 한 셀만 따로 고칠 수 없다."],"answer":2,"explain":"배열 수식의 중괄호는 Ctrl+Shift+Enter로 입력할 때 Excel이 자동으로 붙인다. 직접 입력하면 텍스트로 인식된다. 배열 상수의 중괄호는 직접 입력한다."},{"id":"ss-0099","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =SUM({1,2;3,4}*{2;3}) 의 결과는?","options":["20","27","30","25"],"answer":1,"explain":"{2;3}은 2행 1열이므로 1행에는 2를, 2행에는 3을 곱한다. (1+2)×2 + (3+4)×3 = 6+21 = 27."},{"id":"ss-0100","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =SUM(LARGE({8,3,9,5,7},{1,2,3})) 의 결과는?","options":["9","21","17","24"],"answer":3,"explain":"LARGE에 {1,2,3}을 주면 1~3번째로 큰 값 9, 8, 7을 배열로 돌려주고 SUM이 더한다."},{"id":"ss-0101","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"연 6% 이율로 1,000만 원을 대출받아 3년 동안 매월 말에 같은 금액을 갚을 때, 월 상환액을 양수로 구하는 수식은?","options":["=PMT(6%,3,-10000000)","=PMT(6%/12,3,10000000)","=PMT(6%/12,3*12,-10000000)","=PMT(6%*12,3*12,-10000000)"],"answer":2,"explain":"월 단위로 맞춰 이율은 12로 나누고 기간은 개월 수(36)로 쓴다. 받은 원금을 음수로 넣어야 결과가 양수가 된다."},{"id":"ss-0102","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"매월 초에 20만 원씩 연 3% 이율로 2년 동안 적금할 때 만기 금액을 구하는 수식은?","options":["=FV(3%/12,24,-200000)","=FV(3%/12,24,-200000,,1)","=FV(3%,2,-200000,,1)","=PV(3%/12,24,-200000,,1)"],"answer":1,"explain":"미래 가치는 FV다. 월 이율 3%/12, 24개월, 납입액은 나가는 돈이라 음수, 매월 초 납입이므로 type=1이다."},{"id":"ss-0103","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"재무 함수에 대한 설명으로 옳지 않은 것은?","options":["PV는 앞으로 일정 금액을 받을 때 그 현재 가치를 구한다.","PMT의 type 인수가 1이면 매 기간 초에 납입한다고 보고 계산한다.","내는 돈은 음수, 받는 돈은 양수로 넣으면 결과 부호가 맞는다.","NPV는 첫 번째 현금 흐름이 현재 시점(0기)에 생긴다고 보고 계산한다."],"answer":3,"explain":"NPV는 첫 현금 흐름을 1기 말로 보고 할인한다. 현재 시점의 투자액은 NPV 밖에서 더한다."},{"id":"ss-0104","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =NPV(10%,110,121) 의 결과는?","options":["200","231","210","190.9"],"answer":0,"explain":"110/1.1 + 121/1.1^2 = 100 + 100 = 200이다. 첫 현금 흐름도 1기 말로 할인한다."},{"id":"ss-0105","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =FV(10%,2,0,-1000) 의 결과는?","options":["1210","1200","1100","-1210"],"answer":0,"explain":"현재 1,000을 맡기면(음수) 2년 뒤 1000×1.1^2 = 1,210을 받는다(양수)."},{"id":"ss-0106","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"VLOOKUP의 네 번째 인수를 TRUE로 하거나 생략할 때의 설명으로 옳은 것은?","options":["정확히 같은 값만 찾고 없으면 #N/A를 낸다.","첫 열이 내림차순이어야 근삿값을 바르게 찾는다.","대소문자를 구분해 같은 값을 찾는다.","첫 열이 오름차순이어야 근삿값을 바르게 찾는다."],"answer":3,"explain":"TRUE(생략)는 근삿값 찾기로, 찾는 값보다 작거나 같은 값 중 가장 큰 값을 찾으므로 첫 열이 오름차순이어야 한다."},{"id":"ss-0107","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D6\n이름 | 부서 | 직급 | 매출\n김 | 영업 | 대리 | 120\n이 | 총무 | 과장 | 90\n박 | 영업 | 과장 | 150\n최 | 기획 | 대리 | 80\n정 | 영업 | 사원 | 60\n위 표에서 수식 =INDEX(A1:D6,MATCH(\"최\",A1:A6,0),MATCH(\"직급\",A1:D1,0)) 의 결과는?","options":["기획","80","대리","최"],"answer":2,"explain":"\"최\"는 A1:A6의 5번째, \"직급\"은 A1:D1의 3번째이므로 5행 3열 값 \"대리\"다."},{"id":"ss-0108","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"SUMIF와 SUMIFS 함수의 인수 순서에 대한 설명으로 옳은 것은?","options":["SUMIF는 합계 범위를 맨 앞에 쓴다.","SUMIFS는 합계 범위를 맨 앞에 쓴다.","둘 다 합계 범위를 맨 앞에 쓴다.","둘 다 합계 범위를 맨 뒤에 쓴다."],"answer":1,"explain":"SUMIF(조건 범위, 조건, 합계 범위)와 달리 SUMIFS(합계 범위, 조건 범위1, 조건1, …)는 합계 범위가 먼저 온다."},{"id":"ss-0109","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =PV(5%,2,-1000) 의 결과를 소수 둘째 자리까지 나타낸 것은?","options":["2,000.00","1,904.76","1,859.41","1,814.06"],"answer":2,"explain":"매년 말 1,000씩 2년 받는 돈의 현재 가치다. 1000/1.05 + 1000/1.05^2 = 952.38 + 907.03 = 1,859.41."},{"id":"ss-0110","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =PMT(0%,10,-1000) 의 결과는?","options":["110","1000","#NUM!","100"],"answer":3,"explain":"이율이 0이면 원금을 기간 수로 나눈 값이 된다. 1000 ÷ 10 = 100."},{"id":"ss-0111","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"배열 수식 =FREQUENCY({55,70,85,90,62},{60,80}) 가 돌려주는 배열은?","options":["{1;2}","{1;2;2}","{2;2;1}","{1;3;1}"],"answer":1,"explain":"구간은 60 이하(55), 60 초과~80 이하(70, 62), 80 초과(85, 90)다. FREQUENCY는 구간 수보다 하나 많은 값을 세로 배열로 돌려준다."},{"id":"ss-0112","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"정렬에 대한 설명으로 옳지 않은 것은?","options":["내림차순으로 정렬하면 빈 셀이 맨 위에 온다.","오름차순 정렬은 숫자 → 문자 → 논리값 → 오류값 → 빈 셀 순이다.","셀 색이나 글꼴 색을 기준으로 정렬할 수 있다.","[정렬 옵션]에서 왼쪽에서 오른쪽 방향으로 정렬할 수 있다."],"answer":0,"explain":"빈 셀은 오름차순이든 내림차순이든 항상 맨 마지막에 놓인다."},{"id":"ss-0113","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"'월, 화, 수, 목, 금' 같은 요일 순서로 데이터를 정렬하려면 [정렬] 대화 상자에서 어떻게 하는가?","options":["정렬 기준을 '셀 색'으로 고른다.","[옵션]에서 '대/소문자 구분'을 고른다.","정렬 순서에서 '사용자 지정 목록'을 고른다.","[옵션]에서 '왼쪽에서 오른쪽'을 고른다."],"answer":2,"explain":"요일·월처럼 가나다순이 아닌 순서는 사용자 지정 목록으로 정렬한다."},{"id":"ss-0114","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"자동 필터에 대한 설명으로 옳지 않은 것은?","options":["한 열의 [사용자 지정 필터]에서는 두 조건을 AND나 OR로 묶을 수 있다.","서로 다른 두 열에 각각 조건을 지정하면 OR 조건으로 결합된다.","숫자 필드에서는 [상위 10]으로 상위·하위 항목을 추출할 수 있다.","필터 결과를 복사해 붙여 넣으면 화면에 보이는 행만 복사된다."],"answer":1,"explain":"여러 열에 지정한 자동 필터 조건은 모두 만족해야 하는 AND로 결합된다. 열끼리 OR가 필요하면 고급 필터를 쓴다."},{"id":"ss-0115","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"고급 필터의 조건 범위가 다음과 같을 때 추출되는 데이터는?\n부서 | 매출\n영업 | >=100\n총무 | (빈칸)","options":["영업부나 총무부 중 매출이 100 이상인 데이터","영업부이거나, 매출이 100 이상인 데이터","영업부와 총무부의 매출 100 이상인 데이터만","영업부 중 매출 100 이상이거나, 총무부인 데이터"],"answer":3,"explain":"같은 행의 조건은 AND, 다른 행의 조건은 OR다. 1행은 영업 AND 100 이상, 2행은 총무(매출 조건 없음)."},{"id":"ss-0116","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"고급 필터로 '나이가 30 이상 40 미만'인 데이터를 추출하려 한다. 조건 범위로 옳은 것은?","options":["나이 | 나이\n>=30 | <40","나이\n>=30\n<40","나이\n>=30 AND <40","나이 | 나이\n>=30 | (빈칸)\n(빈칸) | <40"],"answer":0,"explain":"같은 필드에 AND 조건을 걸려면 같은 필드 이름을 두 번 쓰고 조건을 같은 행에 둔다. 다른 행에 두면 OR가 된다."},{"id":"ss-0117","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"고급 필터에서 수식을 조건으로 쓸 때의 설명으로 옳지 않은 것은?","options":["수식의 결과는 TRUE 또는 FALSE가 되어야 한다.","수식은 목록의 첫 데이터 행을 상대 참조로 가리키게 쓴다.","조건 범위의 머리글은 반드시 원본 필드 이름과 같아야 한다.","조건 머리글은 비우거나 원본에 없는 이름으로 입력한다."],"answer":2,"explain":"수식 조건의 머리글은 원본 필드 이름과 달라야(또는 비워야) 한다. 같으면 수식이 아니라 그 필드의 값과 비교한다."},{"id":"ss-0118","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"A1:D6 목록(D열이 매출, D2부터 데이터)에서 매출이 매출 평균보다 큰 행만 고급 필터로 추출하려 한다. 조건 범위 F1:F2에 넣을 내용으로 옳은 것은?","options":["F1: 매출 / F2: =D2>AVERAGE($D$2:$D$6)","F1: 평균초과 / F2: =$D$2>AVERAGE(D2:D6)","F1: 평균초과 / F2: >AVERAGE(D2:D6)","F1: 평균초과 / F2: =D2>AVERAGE($D$2:$D$6)"],"answer":3,"explain":"수식 조건은 머리글을 원본과 다르게 하고, 비교할 셀은 첫 데이터 행 상대 참조(D2), 평균 범위는 절대 참조로 쓴다."},{"id":"ss-0119","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"고급 필터의 '동일한 레코드는 하나만' 옵션을 선택했을 때의 결과는?","options":["모든 필드가 같은 행은 하나만 표시한다.","조건에 맞지 않는 행을 원본에서 삭제한다.","열 이름이 같은 열은 하나만 남긴다.","조건에 맞는 첫 번째 행만 표시한다."],"answer":0,"explain":"중복된 레코드(행 전체가 같은 행)를 하나만 추출하는 옵션이며, 원본 데이터는 지우지 않는다."},{"id":"ss-0120","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[텍스트 나누기]에 대한 설명으로 옳지 않은 것은?","options":["탭·세미콜론·쉼표·공백 등 구분 기호로 나눌 수 있다.","여러 열을 한꺼번에 선택해 동시에 나눌 수 있다.","너비가 일정하면 구분선을 직접 지정해 나눌 수 있다.","나눌 열마다 일반·텍스트·날짜 등 데이터 서식을 정할 수 있다."],"answer":1,"explain":"텍스트 나누기는 한 번에 한 열만 선택해 실행할 수 있다."},{"id":"ss-0121","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[데이터]-[중복된 항목 제거]에 대한 설명으로 옳은 것은?","options":["중복된 행을 모두 지워 하나도 남기지 않는다.","고른 열의 값이 같은 행 중 첫 행만 남긴다.","중복 값이 있는 셀에 색을 칠해 표시만 한다.","모든 열을 기준으로만 중복을 판단한다."],"answer":1,"explain":"기준 열을 골라 그 값이 같은 행 중 첫 번째 행을 남기고 나머지를 지운다. 색 표시는 조건부 서식의 '중복 값'이다."},{"id":"ss-0122","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"데이터 유효성 검사의 '제한 대상'에 없는 것은?","options":["정수","목록","문자 서식","텍스트 길이"],"answer":2,"explain":"제한 대상은 모든 값·정수·소수점·목록·날짜·시간·텍스트 길이·사용자 지정이다."},{"id":"ss-0123","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"데이터 유효성 검사에 대한 설명으로 옳지 않은 것은?","options":["'목록'의 원본은 쉼표(,)로 구분해 직접 입력할 수 있다.","오류 메시지 스타일은 중지·경고·정보 세 가지다.","[잘못된 데이터]에 동그라미로 기존 오류 값을 확인할 수 있다.","설정하면 이미 입력되어 있던 잘못된 값이 자동으로 지워진다."],"answer":3,"explain":"유효성 검사는 새로 입력하는 값만 검사한다. 이미 있던 값은 [잘못된 데이터]로 표시만 할 수 있다."},{"id":"ss-0124","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"데이터 유효성 검사의 오류 메시지 스타일 중 규칙에 맞지 않는 값을 아예 입력할 수 없게 하는 것은?","options":["중지","경고","정보","확인"],"answer":0,"explain":"'중지'는 다시 시도하거나 취소만 할 수 있다. '경고'와 '정보'는 사용자가 확인하면 잘못된 값도 입력된다."},{"id":"ss-0125","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"B2:B100에 같은 사번을 두 번 입력하지 못하도록 데이터 유효성 검사의 '사용자 지정' 수식을 쓰려 한다. 옳은 수식은? (B2:B100 선택, 활성 셀 B2)","options":["=COUNTIF(B2:B100,B2)=1","=COUNTIF($B$2:$B$100,$B$2)=1","=COUNTIF($B$2:$B$100,B2)>1","=COUNTIF($B$2:$B$100,B2)=1"],"answer":3,"explain":"검사 범위는 절대 참조로 고정하고 검사할 셀은 상대 참조(B2)로 둔다. 결과가 TRUE일 때만 입력이 허용되므로 =1이어야 한다."},{"id":"ss-0126","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[데이터]-[데이터 가져오기]로 가져올 수 있는 원본이 아닌 것은?","options":["텍스트/CSV 파일","한글(.hwp) 문서","Access 데이터베이스","웹 페이지"],"answer":1,"explain":"텍스트/CSV·웹·Access·SQL Server·XML·JSON 등을 가져올 수 있지만 한글 문서는 원본으로 지원하지 않는다."},{"id":"ss-0127","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"외부 데이터를 쿼리로 가져온 뒤 원본 파일의 내용이 바뀌었을 때 Excel의 데이터에 반영하는 방법은?","options":["[수식]-[지금 계산]","[검토]-[변경 내용 추적]","[데이터]-[모두 새로 고침]","[데이터]-[통합]"],"answer":2,"explain":"가져온 데이터와 피벗 테이블은 [모두 새로 고침](Ctrl+Alt+F5)으로 갱신한다. [지금 계산](F9)은 수식만 다시 계산한다."},{"id":"ss-0128","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"고급 필터의 조건 범위에서 '이름' 필드 아래에 김 이라고만 입력했을 때 추출되는 데이터는?","options":["'김'으로 시작하는 모든 이름","이름이 정확히 '김'인 데이터만","'김'이 들어 있는 모든 이름","'김'으로 끝나는 모든 이름"],"answer":0,"explain":"고급 필터의 텍스트 조건은 그 글자로 시작하는 값을 모두 찾는다. 정확히 일치시키려면 =\"=김\"처럼 입력한다."},{"id":"ss-0129","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"부분합을 실행하기 전에 반드시 해야 하는 작업은?","options":["범위를 표로 변환(Ctrl+T)","그룹으로 묶을 필드를 기준으로 정렬","자동 필터 설정","피벗 테이블 만들기"],"answer":1,"explain":"부분합은 같은 값이 연속된 행을 한 그룹으로 묶으므로 그룹 기준 필드로 먼저 정렬해야 한다."},{"id":"ss-0130","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"부분합에 대한 설명으로 옳지 않은 것은?","options":["부분합을 중첩하려면 '새로운 값으로 대치'를 선택해야 한다.","'그룹 사이에서 페이지 나누기'로 그룹별로 나눠 인쇄할 수 있다.","[모두 제거]를 누르면 부분합과 윤곽이 함께 제거된다.","'데이터 아래에 요약 표시'를 해제하면 요약이 그룹 위에 표시된다."],"answer":0,"explain":"중첩 부분합을 만들려면 '새로운 값으로 대치'를 해제해야 한다. 선택하면 기존 부분합이 새 것으로 바뀐다."},{"id":"ss-0131","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"부분합 대화 상자의 '사용할 함수'에 없는 것은?","options":["곱","숫자 개수","중앙값","최대"],"answer":2,"explain":"부분합 함수는 합계·개수·평균·최대·최소·곱·숫자 개수·표준 편차·분산 등이며 중앙값은 없다."},{"id":"ss-0132","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"피벗 테이블에 대한 설명으로 옳지 않은 것은?","options":["피벗 차트를 만들면 피벗 테이블도 함께 만들어진다.","값 필드의 요약 기준을 합계에서 평균 등으로 바꿀 수 있다.","날짜 필드는 월·분기·연 단위로 그룹화할 수 있다.","원본 데이터를 수정하면 피벗 테이블에 자동으로 반영된다."],"answer":3,"explain":"원본을 바꾼 뒤에는 [새로 고침](Alt+F5)을 해야 피벗 테이블에 반영된다."},{"id":"ss-0133","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"피벗 테이블을 삭제하면 그 피벗 테이블로 만든 피벗 차트는 어떻게 되는가?","options":["피벗 테이블과 함께 삭제된다.","빈 차트 영역만 남는다.","삭제할 수 없다는 메시지가 나온다.","일반 차트로 바뀌어 남는다."],"answer":3,"explain":"연결된 피벗 테이블이 없어지면 피벗 차트는 필드 단추가 없는 일반 차트가 되어 남는다."},{"id":"ss-0134","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"[피벗 테이블 필드] 창에서 필드를 끌어 놓을 수 있는 영역이 아닌 것은?","options":["정렬","필터","행","값"],"answer":0,"explain":"필드를 놓는 영역은 필터·열·행·값 네 가지다."},{"id":"ss-0135","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 테이블 값 필드의 [값 표시 형식]으로 고를 수 없는 것은?","options":["총합계 비율","열 합계 비율","원본 셀의 채우기 색","누계"],"answer":2,"explain":"값 표시 형식에는 총합계·열 합계·행 합계 비율, 기준값 대비 차이, 누계, 순위 지정 등이 있다. 색은 서식 기능이다."},{"id":"ss-0136","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 테이블 [보고서 레이아웃] 형식이 아닌 것은?","options":["압축 형식","요약 형식","개요 형식","테이블 형식"],"answer":1,"explain":"보고서 레이아웃은 압축·개요·테이블 형식 세 가지다."},{"id":"ss-0137","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 테이블의 '계산 필드'에 대한 설명으로 옳은 것은?","options":["원본 데이터에 새 열이 실제로 추가된다.","기존 필드로 만든 수식을 새 필드로 추가한다.","행 레이블의 항목끼리만 계산할 수 있다.","값 영역에는 넣을 수 없고 필터에만 쓴다."],"answer":1,"explain":"계산 필드는 '=매출-원가'처럼 다른 필드로 수식을 만들어 피벗 테이블 안에만 추가한다. 원본 데이터는 바뀌지 않는다."},{"id":"ss-0138","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"목표값 찾기에 대한 설명으로 옳지 않은 것은?","options":["'수식 셀'에는 원하는 결과가 나와야 할 수식 셀을 지정한다.","값을 바꿀 셀은 하나만 지정할 수 있다.","'값을 바꿀 셀'에는 수식이 들어 있는 셀을 지정해야 한다.","[데이터]-[가상 분석]에서 실행한다."],"answer":2,"explain":"'값을 바꿀 셀'은 수식 셀이 참조하는 값(상수) 셀이어야 한다. 수식이 들어 있으면 오류가 난다."},{"id":"ss-0139","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"판매 이익(D10, 수식)이 500만 원이 되려면 판매 수량(B3)이 얼마여야 하는지 알고 싶다. 가장 알맞은 기능은?","options":["목표값 찾기","시나리오 관리자","데이터 표","통합"],"answer":0,"explain":"결과 값을 정해 두고 입력 값 하나를 거꾸로 찾는 기능이 목표값 찾기다."},{"id":"ss-0140","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"시나리오에 대한 설명으로 옳지 않은 것은?","options":["한 시나리오에 변경 셀을 최대 32개까지 지정할 수 있다.","결과를 시나리오 요약이나 피벗 테이블 보고서로 만들 수 있다.","변경 셀에 이름을 정의해 두면 요약 보고서에 그 이름이 나온다.","시나리오 요약 보고서는 원본 값을 바꾸면 자동으로 다시 계산된다."],"answer":3,"explain":"시나리오 요약 보고서는 만들 때의 값으로 고정되므로 원본이 바뀌면 보고서를 다시 만들어야 한다."},{"id":"ss-0141","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"데이터 표에 대한 설명으로 옳지 않은 것은?","options":["변수가 하나 또는 두 개일 때 쓸 수 있다.","결과 범위의 셀 하나만 골라 값을 고칠 수 있다.","결과 셀에는 {=TABLE(행 입력 셀,열 입력 셀)} 형태의 수식이 생긴다.","입력 값이 바뀌면 결과가 자동으로 다시 계산된다."],"answer":1,"explain":"데이터 표 결과는 배열 수식이라 일부 셀만 수정하거나 지울 수 없다."},{"id":"ss-0142","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"이자율 후보를 C5:C10에 세로로 적고 D4에 월 상환액 수식(이자율은 B2 참조)을 넣은 뒤 C4:D10을 선택해 데이터 표를 만들려 한다. [데이터 표] 대화 상자의 입력으로 옳은 것은?","options":["행 입력 셀에 B2","열 입력 셀에 D4","열 입력 셀에 B2","행 입력 셀에 C5"],"answer":2,"explain":"대입할 값이 한 열(세로)로 나열되어 있으므로 '열 입력 셀'에 수식이 참조하는 원래 셀 B2를 지정한다."},{"id":"ss-0143","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"데이터 통합에 대한 설명으로 옳지 않은 것은?","options":["합계·평균·개수·최대·최소 등의 함수를 쓸 수 있다.","'첫 행'과 '왼쪽 열'을 쓰면 이름을 기준으로 통합한다.","'원본 데이터에 연결'을 고르면 원본 변경이 결과에 반영된다.","통합할 데이터는 반드시 같은 시트에 있어야 한다."],"answer":3,"explain":"통합은 여러 시트나 다른 통합 문서에 있는 데이터도 한곳에 모아 요약할 수 있다."},{"id":"ss-0144","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"데이터 통합의 '원본 데이터에 연결' 옵션에 대한 설명으로 옳은 것은?","options":["원본과 결과가 같은 시트에 있으면 쓸 수 없다.","원본이 다른 통합 문서에 있으면 쓸 수 없다.","고르면 결과가 피벗 테이블로 만들어진다.","고르면 원본 데이터가 결과 위치로 옮겨진다."],"answer":0,"explain":"원본 연결은 원본과 대상이 같은 시트일 때는 만들 수 없다. 연결하면 결과에 윤곽이 생기고 원본 변경이 반영된다."},{"id":"ss-0145","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"예측 시트에 대한 설명으로 옳지 않은 것은?","options":["날짜·시간 열 없이 값 열만 있어도 예측 시트를 만들 수 있다.","시계열 데이터로 미래 값을 예측하는 표와 차트를 새 시트에 만든다.","예측 차트는 꺾은선형이나 세로 막대형 중에서 고를 수 있다.","예측 결과에 신뢰 구간을 함께 표시할 수 있다."],"answer":0,"explain":"예측 시트는 일정한 간격의 날짜·시간 열과 그에 대응하는 값 열이 함께 있어야 만들 수 있다."},{"id":"ss-0146","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"목표값 찾기·시나리오 관리자·데이터 표를 실행하는 메뉴 위치는?","options":["[수식]-[수식 분석]-[가상 분석]","[데이터]-[데이터 도구]-[통합]","[검토]-[데이터 분석]","[데이터]-[예측]-[가상 분석]"],"answer":3,"explain":"세 기능은 [데이터] 탭 [예측] 그룹의 [가상 분석]에 모여 있다."},{"id":"ss-0147","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"해 찾기에 대한 설명으로 옳지 않은 것은?","options":["목표 셀을 최대값·최소값·지정값 중 하나로 맞출 수 있다.","변수 셀에 정수 같은 제한 조건을 추가할 수 있다.","변수 셀은 하나만 지정할 수 있다.","처음 쓸 때는 Excel 추가 기능에서 활성화해야 한다."],"answer":2,"explain":"해 찾기는 여러 변수 셀과 제한 조건을 함께 다룬다. 변수가 하나뿐인 경우에 쓰는 것은 목표값 찾기다."},{"id":"ss-0148","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"슬라이서에 대한 설명으로 옳지 않은 것은?","options":["단추를 눌러 피벗 테이블을 빠르게 필터링한다.","슬라이서는 피벗 테이블에만 쓸 수 있고 표(Ctrl+T)에는 쓸 수 없다.","슬라이서 하나를 여러 피벗 테이블에 연결할 수 있다.","시간 표시 막대는 날짜 필드를 기간 단위로 필터링한다."],"answer":1,"explain":"슬라이서는 피벗 테이블뿐 아니라 표에도 삽입할 수 있다."},{"id":"ss-0149","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"원형 차트에 대한 설명으로 옳은 것은?","options":["가로 축과 세로 축이 모두 있다.","여러 계열의 추세 비교에 알맞다.","데이터 계열을 하나만 표시할 수 있다.","추세선을 추가할 수 있다."],"answer":2,"explain":"원형 차트는 한 계열의 항목별 비율을 보여 준다. 축이 없고 추세선도 넣을 수 없다."},{"id":"ss-0150","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"가로 축과 세로 축이 모두 값 축이어서 과학·공학 데이터처럼 두 수치 사이의 관계를 보기에 알맞은 차트는?","options":["분산형(XY)","꺾은선형","영역형","방사형"],"answer":0,"explain":"분산형은 두 값의 상관 관계를 점으로 나타낸다. 꺾은선형의 가로 축은 항목 축이다."},{"id":"ss-0151","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"주식형 차트 중 '고가-저가-종가'를 만들 때 데이터 열의 순서로 옳은 것은?","options":["종가, 고가, 저가","저가, 고가, 종가","시가, 종가, 고가","고가, 저가, 종가"],"answer":3,"explain":"주식형 차트는 차트 이름에 적힌 순서대로 데이터를 배치해야 만들 수 있다."},{"id":"ss-0152","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"추세선을 추가할 수 없는 차트는?","options":["2차원 꺾은선형","3차원 세로 막대형","분산형","2차원 세로 막대형"],"answer":1,"explain":"추세선은 3차원·원형·도넛형·방사형·누적형 차트에는 추가할 수 없다."},{"id":"ss-0153","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트를 만드는 바로 가기 키에 대한 설명으로 옳은 것은?","options":["Alt+F1: 기본 차트를 새 차트 시트에 만든다.","F11: 기본 차트를 현재 시트에 만든다.","F11: 기본 차트를 새 차트 시트에 만든다.","Ctrl+F1: 기본 차트를 현재 시트에 만든다."],"answer":2,"explain":"F11은 별도 차트 시트, Alt+F1은 현재 워크시트에 기본 차트를 만든다."},{"id":"ss-0154","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"값의 크기가 크게 다른 두 계열(매출액과 증가율)을 한 차트에서 보기 좋게 표시하는 방법은?","options":["증가율 계열을 범례에서 삭제한다.","가로 축의 항목 간격을 넓힌다.","두 계열을 원형 차트로 바꾼다.","증가율 계열을 보조 세로 축에 표시한다."],"answer":3,"explain":"단위가 다른 계열은 보조 축으로 보내고, 필요하면 계열 차트 종류를 꺾은선형 등으로 바꿔 콤보 차트로 만든다."},{"id":"ss-0155","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"스파크라인에 대한 설명으로 옳지 않은 것은?","options":["꺾은선형·열·승패 세 종류가 있다.","스파크라인이 있는 셀에서 Delete 키를 누르면 스파크라인이 지워진다.","셀 안에 표시되는 작은 차트다.","높은 점·낮은 점 등 특정 표식을 강조할 수 있다."],"answer":1,"explain":"스파크라인은 Delete 키로 지워지지 않고 [스파크라인]-[지우기]로 지운다."},{"id":"ss-0156","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트에 대한 설명으로 옳지 않은 것은?","options":["원본 데이터의 행을 숨겨도 숨긴 데이터가 차트에 그대로 표시된다.","원본 데이터 값을 바꾸면 차트에 자동으로 반영된다.","[행/열 전환]으로 범례 항목과 가로 축 항목을 바꿀 수 있다.","차트를 서식 파일(.crtx)로 저장해 다시 쓸 수 있다."],"answer":0,"explain":"기본 설정에서는 숨긴 행·열의 데이터는 차트에 표시되지 않는다. [숨겨진 셀/빈 셀] 설정으로 바꿀 수 있다."},{"id":"ss-0157","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"계층 구조 데이터를 사각형의 크기와 색으로 비교해 보여 주는 차트는?","options":["도넛형","방사형","히스토그램","트리맵"],"answer":3,"explain":"트리맵은 계층을 사각형 크기로, 선버스트는 고리 모양으로 보여 준다."},{"id":"ss-0158","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"각 항목을 중심에서 뻗은 축 위에 나타내 여러 계열의 값을 비교하는 차트는?","options":["방사형","거품형","표면형","폭포"],"answer":0,"explain":"방사형은 항목마다 축이 중심점에서 뻗어 나가며, 같은 계열의 값을 선으로 잇는다."},{"id":"ss-0159","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"오차 막대를 추가할 수 없는 차트는?","options":["2차원 꺾은선형","분산형","원형","2차원 가로 막대형"],"answer":2,"explain":"오차 막대는 2차원 영역형·가로 막대형·세로 막대형·꺾은선형·분산형·거품형에 쓸 수 있고, 원형·3차원 차트에는 쓸 수 없다."},{"id":"ss-0160","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"시작 값에서 늘고 준 값이 차례로 쌓여 최종 값이 되는 과정(손익 흐름 등)을 보여 주기에 알맞은 차트는?","options":["선버스트","폭포","깔때기형","상자 수염"],"answer":1,"explain":"폭포 차트는 양수·음수 변화를 누적해 보여 준다. 깔때기형은 단계별로 줄어드는 값을 보여 준다."},{"id":"ss-0161","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"차트에 추가할 수 있는 추세선 종류가 아닌 것은?","options":["지수","로그","계단형","이동 평균"],"answer":2,"explain":"추세선은 지수·선형·로그·다항식·거듭제곱·이동 평균 여섯 가지다."},{"id":"ss-0162","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트 구성 요소에 대한 설명으로 옳지 않은 것은?","options":["데이터 레이블로 각 요소의 값을 표시할 수 있다.","범례는 위치만 바꿀 수 있고 삭제할 수 없다.","차트 제목과 축 제목은 [차트 요소] 단추로 추가한다.","그림 영역은 실제 데이터 계열이 그려지는 부분이다."],"answer":1,"explain":"범례는 선택하고 Delete 키를 누르거나 [차트 요소]에서 해제해 지울 수 있다."},{"id":"ss-0163","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"세로 막대형 차트의 [데이터 계열 서식]에서 '계열 겹치기'와 '간격 너비'에 대한 설명으로 옳은 것은?","options":["간격 너비를 0%로 하면 항목 사이 간격이 없어진다.","계열 겹치기를 100%로 하면 막대 사이가 가장 벌어진다.","간격 너비는 막대의 높이를 바꾸는 값이다.","계열 겹치기는 -100%~0% 사이만 지정할 수 있다."],"answer":0,"explain":"간격 너비(0~500%)는 항목 묶음 사이의 간격, 계열 겹치기(-100~100%)는 같은 항목 안 막대끼리 겹치는 정도다. 100%면 완전히 겹친다."},{"id":"ss-0164","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"꺾은선형 차트의 [숨겨진 셀/빈 셀] 설정에서 빈 셀을 표시하는 방법으로 고를 수 없는 것은?","options":["간격","0으로","선으로 데이터 요소 연결","평균값으로 채우기"],"answer":3,"explain":"빈 셀은 간격·0으로·선으로 데이터 요소 연결 중에서 골라 표시한다."},{"id":"ss-0165","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"바닥글에 '현재 페이지/전체 페이지'를 '1/5'처럼 표시하는 코드는?","options":["&[전체 페이지 수]/&[페이지 번호]","&[페이지]/&[총 페이지]","&[페이지 번호]/&[전체 페이지 수]","#[페이지 번호]/#[전체 페이지 수]"],"answer":2,"explain":"현재 페이지는 &[페이지 번호], 전체 페이지는 &[전체 페이지 수]다."},{"id":"ss-0166","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"머리글/바닥글에 시트 이름을 표시하는 코드는?","options":["&[탭]","&[파일]","&[경로]","&[시트]"],"answer":0,"explain":"&[탭]은 시트 이름, &[파일]은 파일 이름, &[경로]는 파일 경로를 넣는다."},{"id":"ss-0167","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"머리글/바닥글 설정에 대한 설명으로 옳지 않은 것은?","options":["첫 페이지를 다르게 지정할 수 있다.","머리글은 왼쪽·오른쪽 두 구역으로만 나뉜다.","짝수와 홀수 페이지를 다르게 지정할 수 있다.","[페이지 레이아웃] 보기에서 직접 클릭해 입력할 수 있다."],"answer":1,"explain":"머리글과 바닥글은 왼쪽·가운데·오른쪽 세 구역으로 나뉜다."},{"id":"ss-0168","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"여러 페이지에 걸친 표를 인쇄할 때 1행의 제목을 모든 페이지에 반복하려면?","options":["[보기]-[틀 고정]으로 1행 고정","[페이지 설정]-[머리글/바닥글]에 1행 내용 입력","[인쇄 영역 설정]으로 1행만 지정","[페이지 설정]-[시트]의 '반복할 행'에 $1:$1 지정"],"answer":3,"explain":"인쇄 제목의 '반복할 행'으로 지정한다. 틀 고정은 화면에서만 동작한다."},{"id":"ss-0169","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[시트] 탭에서 설정할 수 없는 것은?","options":["용지 방향","눈금선 인쇄","행/열 머리글 인쇄","페이지 순서"],"answer":0,"explain":"용지 방향은 [페이지] 탭에서 정한다. [시트] 탭에는 인쇄 영역·인쇄 제목·눈금선·흑백·간단하게 인쇄·행/열 머리글·메모·셀 오류 표시·페이지 순서가 있다."},{"id":"ss-0170","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[페이지] 탭에 대한 설명으로 옳지 않은 것은?","options":["'자동 맞춤'으로 용지 너비와 높이를 페이지 수로 지정한다.","용지 방향을 세로 또는 가로로 정할 수 있다.","확대/축소 배율은 10%~500% 범위로 지정한다.","인쇄 품질과 시작 페이지 번호를 정할 수 있다."],"answer":2,"explain":"인쇄 배율은 10%~400%다."},{"id":"ss-0171","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"페이지 나누기 미리 보기에 대한 설명으로 옳지 않은 것은?","options":["구분선을 마우스로 끌어 페이지를 나누는 위치를 바꿀 수 있다.","인쇄되지 않는 영역은 회색으로 표시된다.","이 보기에서도 데이터를 입력하고 편집할 수 있다.","자동 페이지 나누기는 실선, 수동 페이지 나누기는 파선으로 표시된다."],"answer":3,"explain":"자동 페이지 나누기는 파선, 사용자가 지정한 수동 페이지 나누기는 실선으로 표시된다."},{"id":"ss-0172","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[시트]의 '셀 오류 표시' 옵션으로 고를 수 없는 것은?","options":["표시된 대로","0","<공백>","--"],"answer":1,"explain":"셀 오류 표시는 표시된 대로·<공백>·--·#N/A 네 가지다."},{"id":"ss-0173","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"인쇄 영역에 대한 설명으로 옳지 않은 것은?","options":["인쇄 영역을 지정하면 그 범위만 인쇄된다.","떨어진 여러 범위를 인쇄 영역으로 지정하면 한 페이지에 모아 인쇄된다.","[페이지 레이아웃]-[인쇄 영역]-[인쇄 영역 해제]로 해제한다.","인쇄 영역은 Print_Area라는 이름으로 정의된다."],"answer":1,"explain":"떨어진 범위를 인쇄 영역으로 지정하면 범위마다 다른 페이지에 인쇄된다."},{"id":"ss-0174","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[시트] 탭에서 노트(메모)를 인쇄하는 위치로 고를 수 있는 것은?","options":["시트 끝","각 페이지 머리글","새 통합 문서","셀 왼쪽 여백"],"answer":0,"explain":"노트는 '(없음)', '시트 끝', '시트에 표시된 대로' 중에서 골라 인쇄한다."},{"id":"ss-0175","subject":"spreadsheet","levels":["c1"],"topic":"출력","q":"[페이지 설정]-[시트]의 '간단하게 인쇄'를 선택했을 때의 결과는?","options":["흑백으로 바꾸되 그래픽은 그대로 인쇄한다.","눈금선과 행/열 머리글을 함께 인쇄한다.","한 페이지에 맞게 축소하여 인쇄한다.","눈금선과 대부분의 그래픽을 빼고 인쇄한다."],"answer":3,"explain":"'간단하게 인쇄'는 눈금선과 대부분의 그래픽을 생략해 빠르게 인쇄한다. 색만 빼는 것은 '흑백으로'다."},{"id":"ss-0176","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[파일]-[인쇄]의 설정에서 고를 수 있는 인쇄 대상이 아닌 것은?","options":["활성 시트 인쇄","전체 통합 문서 인쇄","차트의 원본 데이터만 인쇄","선택 영역 인쇄"],"answer":2,"explain":"인쇄 대상은 활성 시트·전체 통합 문서·선택 영역(표가 있으면 선택한 표)이다."},{"id":"ss-0177","subject":"spreadsheet","levels":["c1"],"topic":"출력","q":"가로·세로로 모두 여러 페이지가 되는 데이터를 인쇄할 때 '페이지 순서'를 '행 우선'으로 지정하면?","options":["오른쪽 페이지를 먼저 인쇄한 뒤 아래로 내려간다.","아래쪽 페이지를 먼저 인쇄한 뒤 오른쪽으로 간다.","홀수 페이지를 모두 인쇄한 뒤 짝수 페이지를 인쇄한다.","모든 페이지에 행 머리글이 인쇄된다."],"answer":0,"explain":"'행 우선'은 왼쪽에서 오른쪽으로 먼저, '열 우선'(기본)은 위에서 아래로 먼저 인쇄한다."},{"id":"ss-0178","subject":"spreadsheet","levels":["c1"],"topic":"출력","q":"머리글/바닥글에 넣는 코드와 의미의 연결이 옳지 않은 것은?","options":["&[날짜]: 인쇄하는 날의 날짜","&[경로]&[파일]: 파일 경로와 이름","&[그림]: 삽입한 그림","&[시간]: 파일을 만든 시간"],"answer":3,"explain":"&[시간]은 파일을 만든 시간이 아니라 인쇄할 때의 현재 시간이다."},{"id":"ss-0179","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"매크로 이름 규칙에 대한 설명으로 옳지 않은 것은?","options":["첫 글자는 문자여야 한다.","매크로 이름에 공백을 넣을 수 있다.","이름 중간에 밑줄(_)을 쓸 수 있다.","셀 주소와 같은 이름(예: A1)은 쓸 수 없다."],"answer":1,"explain":"매크로 이름에는 공백을 쓸 수 없으므로 밑줄로 대신한다."},{"id":"ss-0180","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"매크로를 기록할 때 지정하는 바로 가기 키에 대한 설명으로 옳지 않은 것은?","options":["Ctrl과 함께 누를 영문자를 지정한다.","대문자로 입력하면 Ctrl+Shift 조합이 된다.","숫자나 특수 문자도 바로 가기 키로 지정할 수 있다.","Excel 기본 바로 가기 키와 겹치면 매크로 키가 우선한다."],"answer":2,"explain":"바로 가기 키에는 영문자만 지정할 수 있다."},{"id":"ss-0181","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"기록한 매크로를 모든 통합 문서에서 쓰려고 할 때 '매크로 저장 위치'로 고를 것은?","options":["현재 통합 문서","새 통합 문서","개인용 매크로 통합 문서","공유 통합 문서"],"answer":2,"explain":"개인용 매크로 통합 문서(PERSONAL.XLSB)는 XLSTART 폴더에 저장되어 Excel을 시작할 때마다 숨겨진 채 열린다."},{"id":"ss-0182","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"매크로 관련 바로 가기 키의 연결로 옳은 것은?","options":["Alt+F11: [매크로] 대화 상자","Alt+F8: Visual Basic 편집기","Ctrl+F8: 매크로 기록 시작","Alt+F8: [매크로] 대화 상자"],"answer":3,"explain":"Alt+F8은 매크로 목록(실행·편집·삭제), Alt+F11은 Visual Basic 편집기다."},{"id":"ss-0183","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"매크로 기록에 대한 설명으로 옳지 않은 것은?","options":["[상대 참조로 기록]을 켜면 활성 셀 기준 위치로 기록된다.","기록 중 마우스로 리본 명령을 실행한 동작은 기록되지 않는다.","기록한 매크로는 VBA 코드로 저장되어 편집기에서 고칠 수 있다.","[개발 도구] 탭이나 [보기]-[매크로]에서 기록을 시작한다."],"answer":1,"explain":"리본 명령 실행·셀 선택처럼 마우스로 한 작업도 VBA 코드로 기록된다."},{"id":"ss-0184","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 합계()\n    s = 0\n    For i = 1 To 10 Step 3\n        s = s + i\n    Next i\n    MsgBox s\nEnd Sub","options":["22","55","12","10"],"answer":0,"explain":"i는 1, 4, 7, 10으로 바뀌며 s = 1+4+7+10 = 22다. 13은 10을 넘으므로 반복하지 않는다."},{"id":"ss-0185","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 횟수()\n    i = 1: n = 0\n    Do While i <= 20\n        n = n + 1\n        i = i * 2\n    Loop\n    MsgBox n\nEnd Sub","options":["4","6","5","20"],"answer":2,"explain":"i가 1, 2, 4, 8, 16일 때 5번 반복하고 i가 32가 되면 조건이 거짓이 되어 끝난다."},{"id":"ss-0186","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA에서 Range(\"A1\").Offset(2, 1).Select를 실행하면 선택되는 셀은?","options":["C2","A3","B2","B3"],"answer":3,"explain":"Offset(행, 열)은 기준 셀에서 2행 아래, 1열 오른쪽으로 이동한 셀이므로 B3이다."},{"id":"ss-0187","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA에서 Cells(4, 3)이 가리키는 셀은?","options":["D3","C4","C3","D4"],"answer":1,"explain":"Cells(행 번호, 열 번호)이므로 4행 3열, 즉 C4다."},{"id":"ss-0188","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA 기본 문법에 대한 설명으로 옳지 않은 것은?","options":["주석은 // 뒤에 쓴다.","Sub 프로시저는 Sub로 시작해 End Sub로 끝난다.","변수는 Dim 문으로 선언한다.","긴 문장은 공백과 밑줄( _)로 다음 줄에 이어 쓴다."],"answer":0,"explain":"VBA 주석은 작은따옴표(') 또는 Rem 뒤에 쓴다. //는 C 계열 언어의 주석이다."},{"id":"ss-0189","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"통합 문서를 열 때 자동으로 실행되는 이벤트 프로시저는?","options":["Workbook_BeforeClose","Workbook_Open","Worksheet_Change","Worksheet_Activate"],"answer":1,"explain":"Workbook_Open은 ThisWorkbook 모듈에 작성한다. Worksheet_Change는 셀 값이 바뀔 때, Workbook_BeforeClose는 닫기 직전에 실행된다."},{"id":"ss-0190","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA에서 셀 서식은 남기고 값(내용)만 지우는 메서드는?","options":["Clear","ClearFormats","Delete","ClearContents"],"answer":3,"explain":"Clear는 내용과 서식을 모두, ClearFormats는 서식만 지운다. Delete는 셀 자체를 삭제해 주변 셀이 당겨진다."},{"id":"ss-0191","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA 식 Range(\"A1:C5\").Rows.Count * Range(\"A1:C5\").Columns.Count 의 결과는?","options":["8","5","15","3"],"answer":2,"explain":"A1:C5는 5행 3열이므로 5 × 3 = 15다."},{"id":"ss-0192","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행한 뒤 B1 셀의 값은?\nx = 7\nIf x Mod 2 = 0 Then\n    Range(\"B1\").Value = \"짝수\"\nElse\n    Range(\"B1\").Value = \"홀수\"\nEnd If","options":["홀수","짝수","1","7"],"answer":0,"explain":"7 Mod 2는 1이므로 조건이 거짓이 되어 Else 부분이 실행된다."},{"id":"ss-0193","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행한 뒤 변수 g의 값은?\nscore = 85\nSelect Case score\n    Case Is >= 90: g = \"A\"\n    Case 80 To 89: g = \"B\"\n    Case Else: g = \"C\"\nEnd Select","options":["A","C","85","B"],"answer":3,"explain":"85는 첫 조건(90 이상)에 맞지 않고 80 To 89 범위에 들어가므로 \"B\"다."},{"id":"ss-0194","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA의 With … End With 문에 대한 설명으로 옳은 것은?","options":["조건이 참인 동안 문장을 반복해서 실행한다.","오류가 나면 다음 문장으로 넘어가게 한다.","같은 개체의 여러 속성을 개체 이름을 반복하지 않고 설정한다.","변수의 자료형을 선언할 때 쓴다."],"answer":2,"explain":"With Range(\"A1\") 안에서 .Font.Bold = True처럼 점(.)으로 시작해 같은 개체를 가리킨다. 반복은 Do While, 오류 무시는 On Error Resume Next다."},{"id":"ss-0195","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA의 개체·속성·메서드 구분으로 옳은 것은?","options":["Range(\"A1\").Select의 Select는 속성이다.","Range(\"A1\").Value의 Value는 속성이다.","Worksheets(\"Sheet1\")의 Worksheets는 메서드다.","ActiveCell.Font.Bold의 Bold는 메서드다."],"answer":1,"explain":"Value·Bold는 속성, Select는 동작이므로 메서드, Worksheets는 시트 개체들의 컬렉션이다."},{"id":"ss-0196","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"사용자에게 값을 입력받는 대화 상자를 표시하는 VBA 함수는?","options":["InputBox","MsgBox","Debug.Print","Format"],"answer":0,"explain":"InputBox는 입력 상자를 표시하고 입력한 값을 돌려준다. MsgBox는 메시지를 보여 주고 누른 단추 값을 돌려준다."},{"id":"ss-0197","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"Visual Basic 편집기에서 프로시저를 한 줄씩 실행(한 단계씩 코드 실행)하는 키는?","options":["F5","F9","F2","F8"],"answer":3,"explain":"F8은 한 단계씩 실행, F5는 실행, F9는 중단점 설정/해제, F2는 개체 찾아보기다."},{"id":"ss-0198","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"모듈 맨 위에 Option Explicit을 쓰면 어떻게 되는가?","options":["모든 변수가 자동으로 Variant가 된다.","선언하지 않은 변수를 쓰면 오류가 난다.","오류가 나도 다음 줄을 계속 실행한다.","배열의 첫 번호가 1부터 시작한다."],"answer":1,"explain":"Option Explicit은 모든 변수를 Dim 등으로 명시적으로 선언하게 한다. 배열 시작 번호는 Option Base 1이다."},{"id":"ss-0199","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA로 만든 사용자 정의 함수에 대한 설명으로 옳지 않은 것은?","options":["Function … End Function으로 작성한다.","함수 이름에 값을 대입해 결과를 돌려준다.","Sub … End Sub로 만들어야 셀 수식에서 쓸 수 있다.","만든 함수는 [함수 마법사]의 '사용자 정의' 범주에 나타난다."],"answer":2,"explain":"셀 수식에서 결과를 돌려받으려면 Function 프로시저로 만들어야 한다. Sub 프로시저는 값을 돌려주지 않는다."},{"id":"ss-0200","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행하면 A1:A3에 입력되는 값은?\nFor Each c In Range(\"A1:A3\")\n    c.Value = c.Row * 10\nNext c","options":["10, 20, 30","10, 10, 10","1, 2, 3","30, 20, 10"],"answer":0,"explain":"For Each는 범위의 셀을 하나씩 돌며, c.Row는 각 셀의 행 번호(1, 2, 3)이므로 10, 20, 30이 입력된다."},{"id":"ss-0201","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"현재 통합 문서에서 다음 워크시트로 이동하는 바로 가기 키는?","options":["Ctrl+Page Down","Ctrl+Tab","Shift+Page Down","Alt+Page Down"],"answer":0,"explain":"Ctrl+Page Down은 다음 시트, Ctrl+Page Up은 이전 시트로 이동한다. Ctrl+Tab은 열려 있는 다른 통합 문서 창으로 전환하고, Alt+Page Down은 한 화면 오른쪽으로 이동한다."},{"id":"ss-0202","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[파일]-[정보]-[통합 문서 보호]의 '최종본으로 표시'에 대한 설명으로 옳은 것은?","options":["모든 시트가 영구적으로 잠겨 어떤 방법으로도 편집 상태로 되돌릴 수 없다.","파일에 암호가 설정되어 암호를 모르면 파일을 열 수 없게 된다.","통합 문서가 PDF 형식으로 변환되어 원래 파일과 별도로 저장된다.","문서가 최종본임을 알리고 편집을 막은 상태로 열리지만, 사용자가 '그래도 편집'을 눌러 다시 수정할 수 있다."],"answer":3,"explain":"'최종본으로 표시'는 보안 기능이 아니라 최종본임을 알리는 표시이며 '그래도 편집'으로 해제할 수 있다. 암호 설정은 [암호를 사용하여 암호화]가 따로 있다."},{"id":"ss-0203","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[파일]-[옵션]-[저장]의 자동 복구 기능에 대한 설명으로 옳지 않은 것은?","options":["자동 복구 정보를 저장하는 시간 간격은 기본적으로 10분이다.","자동 복구 파일이 저장되는 위치를 다른 폴더로 바꿀 수 있다.","저장하지 않고 닫은 통합 문서의 마지막 자동 복구 버전을 유지하도록 설정할 수 있다.","자동 복구 정보가 저장될 때마다 원본 통합 문서 파일이 자동으로 덮어써진다."],"answer":3,"explain":"자동 복구는 원본과 별도의 복구용 파일을 만드는 기능이라 원본은 사용자가 저장할 때만 바뀐다."},{"id":"ss-0204","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[보기]-[나란히 보기]에 대한 설명으로 옳은 것은?","options":["열려 있는 두 통합 문서 창을 나란히 배치하고 '동시 스크롤'로 함께 스크롤하며 비교할 수 있다.","동시 스크롤은 나란히 보기를 켜면 자동으로 켜지지만 한번 켜면 끌 수 없다.","통합 문서가 하나만 열려 있을 때 가장 잘 동작하며 다른 창은 자동으로 닫힌다.","두 통합 문서의 시트를 하나의 시트로 합쳐 보여 주며 원본 파일도 함께 병합된다."],"answer":0,"explain":"나란히 보기는 창 배열만 바꾸며 데이터는 합쳐지지 않는다. 동시 스크롤은 [보기] 탭에서 켜고 끌 수 있다."},{"id":"ss-0205","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"A1:A3 범위를 선택한 상태에서 수식 =ROW()*2 를 입력하고 Ctrl+Enter 를 눌렀다. A3 셀의 값은?","options":["2","4","6","12"],"answer":2,"explain":"Ctrl+Enter는 선택한 모든 셀에 같은 수식을 한 번에 입력하며, ROW()는 각 셀 자신의 행 번호를 돌려주므로 A3은 3*2=6이다."},{"id":"ss-0206","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"워크시트에서 데이터가 입력된 범위의 오른쪽 아래 마지막 셀로 이동하는 바로 가기 키는?","options":["Ctrl+↓","Ctrl+Page Down","Ctrl+Home","Ctrl+End"],"answer":3,"explain":"Ctrl+End는 사용된 범위의 마지막 셀로 이동한다. Ctrl+Home은 A1, Ctrl+↓는 현재 열의 연속 데이터 끝, Ctrl+Page Down은 다음 시트로 이동한다."},{"id":"ss-0207","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"A1에 '2팀-10'을 입력하고 채우기 핸들을 A4까지 끌었을 때 A4의 값은?","options":["5팀-13","3팀-10","2팀-10","2팀-13"],"answer":3,"explain":"문자와 숫자가 섞인 데이터는 맨 끝의 숫자만 1씩 증가하고 나머지 문자는 그대로 복사된다."},{"id":"ss-0208","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"A1에 숫자 5를 입력하고 채우기 핸들을 A4까지 끌 때, 그냥 끌었을 때와 Ctrl 키를 누른 채 끌었을 때 A4의 값을 차례로 쓴 것은?","options":["5, 8","8, 8","5, 5","8, 5"],"answer":0,"explain":"숫자 하나만 선택하고 끌면 값이 복사되고(5), Ctrl 키를 누른 채 끌면 1씩 증가하는 연속 데이터(8)가 채워진다."},{"id":"ss-0209","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"자동 필터로 일부 행이 숨겨진 상태에서, 화면에 보이는 셀만 선택하는 바로 가기 키는?","options":["Ctrl+;","Ctrl+Shift+;","Alt+=","Alt+;"],"answer":3,"explain":"Alt+;는 [이동 옵션]의 '화면에 보이는 셀만'과 같다. Ctrl+;는 오늘 날짜, Ctrl+Shift+;는 현재 시간, Alt+=는 자동 합계를 입력한다."},{"id":"ss-0210","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 12345에 사용자 지정 표시 형식 00-000 을 적용한 결과는?","options":["12-345","00-12345","01-2345","123-45"],"answer":0,"explain":"숫자는 오른쪽 자릿수부터 0 자리 표시자에 채워지므로 뒤 3자리 앞에 하이픈이 들어가 12-345가 된다."},{"id":"ss-0211","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"날짜 2026-10-04에 사용자 지정 표시 형식 yy\"년\" m\"월\" d\"일\" 을 적용한 결과는?","options":["2026년 10월 04일","26년 10월 04일","2026년 10월 4일","26년 10월 4일"],"answer":3,"explain":"yy는 연도 2자리, m과 d는 앞의 0 없이 월·일을 표시한다. 따옴표 안의 글자는 그대로 표시된다."},{"id":"ss-0212","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"A2:A50 범위에서 값이 중복된 셀에만 서식을 적용하려 한다. [수식을 사용하여 서식을 지정할 셀 결정] 규칙을 만들 때(활성 셀 A2) 입력할 수식은?","options":["=COUNTIF(A2:A50,A2)>1","=COUNT($A$2:$A$50,A2)>1","=COUNTIF($A$2:$A$50,$A$2)>1","=COUNTIF($A$2:$A$50,A2)>1"],"answer":3,"explain":"비교 범위는 절대 참조로 고정하고 기준 셀 A2는 상대 참조로 두어야 셀마다 자기 값과 비교한다. COUNT는 숫자만 세므로 문자 중복을 찾지 못한다."},{"id":"ss-0213","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"[홈]-[서식 복사]에 대한 설명으로 옳지 않은 것은?","options":["서식을 복사할 셀을 먼저 선택한 뒤 단추를 눌러야 한다.","단추를 더블클릭하면 여러 곳에 연속해서 서식을 적용할 수 있고 Esc로 끝낸다.","복사한 서식을 다른 워크시트의 셀에도 적용할 수 있다.","원본 셀의 값과 서식이 함께 복사된다."],"answer":3,"explain":"서식 복사는 셀 서식만 복사하며 값은 복사하지 않는다."},{"id":"ss-0214","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 12345에 사용자 지정 표시 형식 0.00E+00 을 적용한 결과는?","options":["1.23E+04","1.2345E+04","1.23E+4","12.35E+03"],"answer":0,"explain":"지수 형식은 소수점 아래 자릿수를 0 두 개로 지정했으므로 1.23이 되고 E+ 뒤의 지수는 두 자리(04)로 표시된다."},{"id":"ss-0215","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"사용자 지정 형식 #,##0;-#,##0;;@ 를 적용한 셀에 숫자 0을 입력했을 때와 문자 '합계'를 입력했을 때의 표시를 차례로 쓴 것은?","options":["0, (아무것도 표시되지 않음)","(아무것도 표시되지 않음), (아무것도 표시되지 않음)","0, 합계","(아무것도 표시되지 않음), 합계"],"answer":3,"explain":"세 번째 구역(0)이 비어 있어 0은 표시되지 않고, 네 번째 구역 @ 덕분에 문자는 그대로 표시된다."},{"id":"ss-0216","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =ROUND(-2.5,0)+ROUND(2.45,1) 의 결과는?","options":["-1","-0.5","0","0.4"],"answer":1,"explain":"ROUND는 0.5를 절대값이 커지는 방향으로 올리므로 ROUND(-2.5,0)=-3, ROUND(2.45,1)=2.5이고 합은 -0.5다."},{"id":"ss-0217","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =CEILING(7.2,2)+FLOOR(7.8,2) 의 결과는?","options":["12","13","14","16"],"answer":2,"explain":"CEILING은 기준값 2의 배수로 올림(8), FLOOR는 2의 배수로 내림(6)하므로 합은 14다."},{"id":"ss-0218","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =RIGHT(LEFT(\"컴퓨터활용능력\",5),2) 의 결과는?","options":["능력","퓨터","터활","활용"],"answer":3,"explain":"LEFT로 앞 5글자 '컴퓨터활용'을 얻고, 그중 RIGHT로 뒤 2글자 '활용'을 얻는다."},{"id":"ss-0219","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =SUBSTITUTE(\"a-b-c-d\",\"-\",\"/\",2) 의 결과는?","options":["a/b-c-d","a-b-c/d","a/b/c/d","a-b/c-d"],"answer":3,"explain":"네 번째 인수 2는 두 번째로 나타나는 '-'만 바꾸라는 뜻이어서 b와 c 사이의 하이픈만 /로 바뀐다."},{"id":"ss-0220","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =PROPER(\"hello wORLD\")&\"-\"&LOWER(\"EX\") 의 결과는?","options":["Hello World-ex","HELLO WORLD-ex","Hello World-EX","Hello world-EX"],"answer":0,"explain":"PROPER는 각 단어의 첫 글자만 대문자, 나머지는 소문자로 바꾸고 LOWER는 모두 소문자로 바꾼다."},{"id":"ss-0221","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n위 표에서 수식 =COUNTIF(A2:A7,\"?펜\")+COUNTIF(A2:A7,\"*펜*\") 의 결과는?","options":["2","3","4","5"],"answer":2,"explain":"'?펜'은 글자 수가 2개이면서 '펜'으로 끝나는 볼펜 1개, '*펜*'은 펜이 들어간 볼펜·형광펜·샤프펜슬 3개이므로 합은 4다."},{"id":"ss-0222","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =LOOKUP(75,{0,60,70,80,90},{\"F\",\"D\",\"C\",\"B\",\"A\"}) 의 결과는?","options":["D","A","B","C"],"answer":3,"explain":"LOOKUP은 오름차순 목록에서 75 이하의 가장 큰 값(70)의 위치를 찾아 같은 위치의 'C'를 돌려준다."},{"id":"ss-0223","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =TEXT(EOMONTH(DATE(2028,1,31),1),\"yyyy-mm-dd\") 의 결과는?","options":["2028-03-31","2028-03-01","2028-02-28","2028-02-29"],"answer":3,"explain":"EOMONTH는 시작일에서 지정한 개월 수 뒤 달의 마지막 날을 돌려주며 2028년은 윤년이라 2월 29일이다."},{"id":"ss-0224","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =DATE(2026,10,4)-DATE(2026,1,1) 의 결과를 일반 숫자로 표시했을 때 값은?","options":["275","276","277","283"],"answer":1,"explain":"날짜는 일련번호이므로 뺄셈은 두 날짜 사이의 일수를 준다. 1월 1일부터 10월 4일까지는 273+3=276일 차이다."},{"id":"ss-0225","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n위 표에서 수식 =IFERROR(MATCH(\"지우개\",A2:A7,0),0)+COUNTIF(B2:B7,\"사무\") 의 결과는?","options":["1","#N/A","0","2"],"answer":0,"explain":"'지우개'가 없어 MATCH가 #N/A를 내지만 IFERROR가 0으로 바꾸고, '사무'는 1건이므로 합은 1이다."},{"id":"ss-0226","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n위 표에서 수식 =SUMIFS(C2:C7,B2:B7,\"문구\",C2:C7,\">30\") 의 결과는?","options":["50","90","120","165"],"answer":1,"explain":"분류가 문구이고 수량이 30을 초과(30은 제외)하는 연필 50과 노트 40의 합 90이다."},{"id":"ss-0227","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"A1에 텍스트 형식의 '5', A2에 숫자 3이 입력되어 있다. 수식 =SUM(A1:A2)+SUM(\"5\",A2,TRUE) 의 결과는?","options":["9","11","12","17"],"answer":2,"explain":"참조한 셀의 텍스트 '5'는 SUM에서 무시되어 SUM(A1:A2)는 3이 된다. SUM(\"5\",A2,TRUE)는 직접 쓴 \"5\"(5) + A2(3) + TRUE(1) = 9이므로 합은 3+9 = 12다."},{"id":"ss-0228","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n위 표에서 수식 =SUMPRODUCT((B2:B7=\"문구\")*C2:C7)/COUNTIF(B2:B7,\"문구\") 의 결과는?","options":["28","30","33","165"],"answer":2,"explain":"SUMPRODUCT는 분류가 문구인 수량의 합 165를 구하고 문구 개수 5로 나누므로 문구의 평균 수량 33이 된다."},{"id":"ss-0229","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n위 표에서 수식 =AGGREGATE(14,6,C2:C7/(B2:B7=\"문구\"),2) 의 결과는?","options":["25","30","40","50"],"answer":2,"explain":"함수 번호 14는 LARGE, 옵션 6은 오류 무시다. 문구가 아닌 행은 0으로 나눠 오류가 되어 제외되므로 문구 수량 중 두 번째로 큰 값 40이 된다."},{"id":"ss-0230","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"취득가 1,000, 잔존가치 100, 내용 연수 5년인 자산의 2년차 감가상각액을 구하는 수식 =SYD(1000,100,5,2) 의 결과는?","options":["180","240","300","360"],"answer":1,"explain":"SYD(연수합계법)의 감가상각액은 (1000-100)×(5-2+1)×2÷(5×6)=240이다. 180은 정액법, 300은 1년차 금액이다."},{"id":"ss-0231","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[데이터]-[정렬] 대화 상자의 '정렬 기준'으로 선택할 수 없는 것은?","options":["글꼴 색","셀 테두리 스타일","조건부 서식 아이콘","셀 값"],"answer":1,"explain":"정렬 기준은 셀 값·셀 색·글꼴 색·조건부 서식 아이콘이며 테두리 스타일로는 정렬할 수 없다."},{"id":"ss-0232","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"자동 필터의 [숫자 필터]에서 고를 수 없는 항목은?","options":["크거나 같음","평균 초과","시작 문자","상위 10"],"answer":2,"explain":"'시작 문자'는 텍스트 필터의 항목이다. 숫자 필터에는 같음·크거나 같음·상위 10·평균 초과·평균 미만 등이 있다."},{"id":"ss-0233","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[표] A1:C7\n상품명 | 분류 | 수량\n볼펜 | 문구 | 30\n형광펜 | 문구 | 20\n연필 | 문구 | 50\n스테이플러 | 사무 | 10\n샤프펜슬 | 문구 | 25\n노트 | 문구 | 40\n고급 필터의 조건 범위 E1:G2가 다음과 같을 때 추출되는 상품명은?\n상품명 | 분류 | 수량\n*펜* | 문구 | >=25","options":["볼펜, 샤프펜슬","볼펜, 연필, 샤프펜슬, 노트","볼펜, 형광펜, 샤프펜슬","볼펜"],"answer":0,"explain":"같은 행의 조건은 모두 만족해야(AND) 한다. 이름에 '펜'이 들어가고 문구이면서 수량이 25 이상인 볼펜(30)과 샤프펜슬(25)만 추출된다."},{"id":"ss-0234","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"A열에서 대분류(과일, 채소)를 고르면 B열에는 해당 소분류만 나타나게 하려 한다. 소분류 범위에 '과일', '채소'라는 이름을 정의해 두었을 때 B2의 데이터 유효성 검사(목록) 원본에 입력할 수식은?","options":["=INDIRECT($A2)","=INDEX($A2,1)","=$A2","=INDIRECT($A$2)"],"answer":0,"explain":"INDIRECT는 A2의 문자열을 같은 이름의 범위 참조로 바꾼다. $A$2로 고정하면 모든 행이 A2 기준이 되어 행마다 다른 목록이 나오지 않는다."},{"id":"ss-0235","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[텍스트 나누기] 마법사 3단계의 '열 데이터 서식'에서 고를 수 없는 것은?","options":["숫자","일반","텍스트","열 가져오지 않음(건너뜀)"],"answer":0,"explain":"열 데이터 서식은 일반·텍스트·날짜·열 가져오지 않음(건너뜀)이다. 숫자는 '일반'을 선택하면 숫자로 변환된다."},{"id":"ss-0236","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"[부분합] 대화 상자에서 '그룹 사이에서 페이지 나누기'를 선택하면 어떻게 되는가?","options":["그룹이 바뀌는 지점마다 페이지 나누기가 삽입되어 그룹별로 나뉘어 인쇄된다","부분합 결과 행만 따로 새 시트로 복사된다","그룹별 부분합 행이 데이터 위쪽에 표시된다","기존 부분합이 지워지고 새로 계산된다"],"answer":0,"explain":"'그룹 사이에서 페이지 나누기'를 선택하면 그룹이 바뀔 때마다 페이지 나누기가 들어가 그룹별로 인쇄할 수 있다. 요약 행을 위에 두려면 '데이터 아래에 요약 표시'를 해제하고, 중첩하려면 '새로운 값으로 대치'를 해제한다."},{"id":"ss-0237","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 테이블의 날짜 필드를 [그룹 선택]으로 묶을 때 '단위' 목록에 없는 것은?","options":["분기","일","월","주"],"answer":3,"explain":"날짜 그룹 단위는 초·분·시·일·월·분기·연이다. 주 단위로 묶으려면 '일'을 선택하고 일 수를 7로 지정한다."},{"id":"ss-0238","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"원본 데이터를 수정한 뒤 선택한 피벗 테이블에 변경 내용을 반영하는 바로 가기 키는?","options":["Shift+F9","F9","Alt+F5","F5"],"answer":2,"explain":"피벗 테이블은 원본이 바뀌어도 자동 갱신되지 않아 [새로 고침](Alt+F5)을 해야 한다. F9와 Shift+F9는 수식 재계산, F5는 이동 대화 상자다."},{"id":"ss-0239","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"시나리오 관리자의 [병합] 단추에 대한 설명으로 옳은 것은?","options":["이름이 같은 시나리오 중 결과 값이 큰 것만 남긴다.","다른 시트나 열려 있는 다른 통합 문서에 저장된 시나리오를 현재 시트로 가져와 합친다.","변경 셀로 지정한 셀들을 하나의 셀로 병합한다.","여러 시나리오의 결과를 하나의 피벗 테이블로 합쳐 준다."],"answer":1,"explain":"시나리오 병합은 시나리오를 한 시트에 모으는 기능이며, 결과 요약은 [요약] 단추로 만든다."},{"id":"ss-0240","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"x값이 {1,2,3,4}일 때 y값이 {10,14,18,22}이다. 수식 =FORECAST.LINEAR(6,{10,14,18,22},{1,2,3,4}) 의 결과는?","options":["26","28","30","32"],"answer":2,"explain":"데이터는 y=4x+6의 직선 관계이므로 선형 회귀로 x=6에서 예측한 값은 30이다."},{"id":"ss-0241","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"X값·Y값과 함께 세 번째 값을 원의 크기로 나타내어 세 가지 변수를 동시에 표현하는 차트는?","options":["표면형 차트","거품형 차트","방사형 차트","도넛형 차트"],"answer":1,"explain":"거품형은 분산형의 변형으로 거품의 크기가 세 번째 변수를 나타낸다."},{"id":"ss-0242","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트 아래쪽에 원본 데이터 값을 표 형태로 함께 표시하려면 [차트 요소]에서 무엇을 추가해야 하는가?","options":["데이터 표","데이터 레이블","눈금선","범례"],"answer":0,"explain":"데이터 표는 차트 아래에 계열별 값을 표로 보여 주며, 데이터 레이블은 각 요소 위에 값을 표시한다."},{"id":"ss-0243","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"도넛형 차트에 대한 설명으로 옳은 것은?","options":["도넛 구멍의 크기를 조절할 수 없다.","원형 차트와 달리 여러 데이터 계열을 동심원 고리로 함께 표시할 수 있다.","데이터 계열을 하나만 사용할 수 있다.","항목 축과 값 축으로 구성되어 값을 축에서 읽는다."],"answer":1,"explain":"도넛형은 계열마다 고리가 하나씩 생기며, [데이터 계열 서식]에서 도넛 구멍 크기를 조절할 수 있다."},{"id":"ss-0244","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"세로(값) 축 서식에서 '로그 눈금 간격'을 설정할 때의 설명으로 옳은 것은?","options":["가로(항목) 축에서만 설정할 수 있다.","눈금이 기본 10배씩 늘어나는 간격으로 표시되며, 0 이하의 값은 로그 눈금에 표시할 수 없다.","눈금이 일정한 차이로 늘어나며 음수 값도 문제없이 표시된다.","원형 차트에서도 설정할 수 있다."],"answer":1,"explain":"로그 눈금은 값의 차이가 매우 큰 데이터를 비교할 때 쓰며 로그는 양수에서만 정의된다."},{"id":"ss-0245","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"열 너비가 넓은 표를 용지 한 장의 너비에 맞추고 길이는 필요한 만큼 여러 쪽으로 나누어 인쇄하려 한다. [페이지 설정]-[페이지] 탭의 '자동 맞춤' 설정으로 옳은 것은?","options":["배율을 100%로 지정한다.","용지 너비와 용지 높이를 모두 1로 한다.","용지 너비는 비워 두고 용지 높이는 1로 한다.","용지 너비는 1, 용지 높이는 비워 둔다."],"answer":3,"explain":"자동 맞춤에서 높이를 비우면 너비 기준으로만 줄여 한 쪽 너비에 맞춘다. 둘 다 1이면 전체가 한 쪽에 들어간다."},{"id":"ss-0246","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"C5 셀을 선택한 상태에서 [페이지 나누기 삽입]을 실행하면 만들어지는 나누기 선의 위치는?","options":["4행과 5행 사이의 가로선만","B열과 C열 사이의 세로선만","4행과 5행 사이의 가로선, B열과 C열 사이의 세로선","5행과 6행 사이의 가로선, C열과 D열 사이의 세로선"],"answer":2,"explain":"활성 셀의 위쪽과 왼쪽에 나누기가 생긴다. 첫 행이나 첫 열의 셀을 선택하면 한 방향만 생긴다."},{"id":"ss-0247","subject":"spreadsheet","levels":["c1"],"topic":"출력","q":"서로 떨어진 두 범위 A1:C10, E1:G10을 함께 선택하고 [인쇄 영역 설정]을 한 뒤 인쇄하면?","options":["두 영역이 서로 다른 페이지에 각각 인쇄된다.","인쇄 영역은 하나만 지정할 수 있어 오류가 발생한다.","처음 선택한 영역만 인쇄된다.","두 영역이 한 페이지에 이어 붙여 인쇄된다."],"answer":0,"explain":"떨어진 인쇄 영역은 영역마다 별도의 페이지로 인쇄된다."},{"id":"ss-0248","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 합()\n    Dim s As Integer, i As Integer\n    For i = 1 To 6\n        If i Mod 3 = 0 Then s = s + i\n    Next i\n    MsgBox s\nEnd Sub","options":["3","6","9","21"],"answer":2,"explain":"i가 3과 6일 때만 s에 더해지므로 3+6=9다."},{"id":"ss-0249","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"특정 워크시트에서 사용자가 셀의 값을 바꿀 때마다 자동으로 실행되게 하려면 그 시트 모듈에 어떤 프로시저를 작성해야 하는가?","options":["Private Sub Worksheet_Change(ByVal Target As Range)","Private Sub Workbook_Open()","Private Sub Worksheet_Activate()","Private Sub Worksheet_SelectionChange(ByVal Target As Range)"],"answer":0,"explain":"Worksheet_Change는 셀 내용이 바뀔 때 발생하고 Target이 바뀐 범위다. SelectionChange는 선택 영역이 바뀔 때, Activate는 시트가 활성화될 때, Workbook_Open은 통합 문서를 열 때 발생한다."},{"id":"ss-0250","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드에서 사용자가 [예] 단추를 눌렀을 때 변수 r에 저장되는 값(상수)은?\nr = MsgBox(\"저장할까요?\", vbYesNo + vbQuestion)","options":["vbNo","vbRetry","vbYes","vbOK"],"answer":2,"explain":"MsgBox 함수는 누른 단추에 해당하는 상수(vbYes=6, vbNo=7 등)를 돌려준다."},{"id":"ss-0251","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"시트를 보호한 상태에서도 지정한 범위만 암호를 아는 사용자가 편집할 수 있게 하려면 사용하는 기능은?","options":["[파일]-[정보]-[최종본으로 표시]","[검토]-[통합 문서 보호]","[보기]-[사용자 지정 보기]","[검토]-[범위 편집 허용]"],"answer":3,"explain":"[범위 편집 허용]은 보호된 시트에서 범위별로 암호나 사용자를 지정해 편집을 허용한다. 통합 문서 보호는 시트 구조를 고정하는 기능이다."},{"id":"ss-0252","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"Microsoft 365 Excel 제목 표시줄의 '자동 저장' 스위치에 대한 설명으로 옳은 것은?","options":["OneDrive나 SharePoint 같은 클라우드에 저장된 파일에서 켜면 변경 내용이 자동으로 저장된다.","자동 복구와 같은 기능으로 10분마다만 저장한다.","로컬 PC에 저장된 모든 형식의 파일에서 항상 켤 수 있다.","켜면 통합 문서가 자동으로 암호화되어 저장된다."],"answer":0,"explain":"자동 저장은 클라우드 파일에서 변경 내용을 거의 실시간으로 저장한다. 자동 복구는 로컬에 복구용 임시 파일을 만드는 별개 기능이다."},{"id":"ss-0253","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"자주 쓰는 서식과 수식을 담은 틀을 만들어 두고 새 통합 문서의 바탕으로 쓰려 한다. 이때 저장하는 파일 형식은?","options":["Excel 서식 파일(*.xltx)","Excel 97-2003 통합 문서(*.xls)","텍스트(탭으로 분리)(*.txt)","Excel 이진 통합 문서(*.xlsb)"],"answer":0,"explain":"서식 파일(.xltx)은 열 때마다 사본으로 새 통합 문서가 만들어져 원본 틀이 보존된다."},{"id":"ss-0254","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"[파일]-[옵션]-[고급]에서 '소수점 자동 삽입'을 체크하고 소수 자릿수를 2로 설정했다. 이 상태에서 셀에 123을 입력하면 셀의 값은?","options":["0.123","1.23","123","12300"],"answer":1,"explain":"소수점 자동 삽입은 입력한 숫자의 오른쪽에서 지정한 자릿수 앞에 소수점을 붙이므로 123이 1.23이 된다. 직접 소수점을 입력하면 그 값이 우선한다."},{"id":"ss-0255","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"세로로 입력된 A1:A4를 복사해 C1 셀에 [선택하여 붙여넣기]의 '행/열 바꿈'으로 붙여 넣으면 데이터가 입력되는 범위는?","options":["C1:F4","C1:F1","C1:C4","A1:D1"],"answer":1,"explain":"행/열 바꿈은 세로 4칸을 가로 4칸으로 바꾸므로 C1에서 오른쪽으로 C1:F1에 채워진다."},{"id":"ss-0256","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"Windows 기본 설정에서 Excel 셀에 1/2 를 입력하면 어떻게 되는가?","options":["#DIV/0! 오류가 표시된다.","문자열 '1/2'로 입력된다.","분수 1/2, 즉 0.5로 입력된다.","올해 1월 2일 날짜로 입력된다."],"answer":3,"explain":"슬래시로 구분한 두 숫자는 날짜로 해석된다. 분수로 입력하려면 0 1/2 처럼 앞에 0과 공백을 넣는다."},{"id":"ss-0257","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"B1에 10이 있다. B1을 복사하고 A1:A3(값 5, 6, 7)을 선택해 [선택하여 붙여넣기]에서 '곱하기'를 선택한 뒤 확인했다. A3 셀의 값은?","options":["7","10","17","70"],"answer":3,"explain":"곱하기 연산은 복사한 값 10을 선택한 각 셀의 값에 곱하여 5, 6, 7이 50, 60, 70으로 바뀐다."},{"id":"ss-0258","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"표의 첫 행(머리글)을 이용해 각 열의 이름을 한 번에 정의하는 [선택 영역에서 만들기]의 바로 가기 키는?","options":["Ctrl+Shift+F3","F3","Shift+F3","Ctrl+F3"],"answer":0,"explain":"Ctrl+Shift+F3은 선택 영역의 머리글로 이름을 만든다. Ctrl+F3은 이름 관리자, F3은 이름 붙여넣기, Shift+F3은 함수 삽입 대화 상자다."},{"id":"ss-0259","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"표시 형식이 '텍스트'로 지정된 셀에 =SUM(B1:B3) 을 입력하고 Enter 키를 눌렀을 때 결과는?","options":["입력이 거부되고 경고 메시지가 나타난다.","#NAME? 오류 값이 표시된다.","수식이 계산되지 않고 입력한 문자열이 그대로 표시된다.","B1:B3의 합계가 계산되어 표시된다."],"answer":2,"explain":"텍스트 형식의 셀은 =로 시작하는 내용도 문자열로 저장한다. 표시 형식을 바꾸고 다시 입력해야 수식으로 계산된다."},{"id":"ss-0260","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 15500000에 사용자 지정 표시 형식 #,##0,\"천원\" 을 적용한 결과는?","options":["15.5천원","16천원","15,500,000천원","15,500천원"],"answer":3,"explain":"자릿수 자리표시자 뒤의 쉼표 하나는 값을 1,000으로 나누어 표시한다. 15,500,000÷1,000=15,500이다."},{"id":"ss-0261","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"날짜 2026-10-04에 사용자 지정 표시 형식 yyyy\"년\" m\"월\" d\"일\" 을 적용한 결과는?","options":["2026년 10월 4일","2026년 10월 04일","26년 10월 4일","2026-10-04"],"answer":0,"explain":"yyyy는 4자리 연도, m은 앞에 0을 붙이지 않는 월, d는 앞에 0을 붙이지 않는 일이다. dd를 쓰면 04일, yy를 쓰면 26년으로 표시된다."},{"id":"ss-0262","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"조건부 서식의 [데이터 막대]에 대한 설명으로 옳지 않은 것은?","options":["셀 값의 상대적인 크기를 막대 길이로 표시한다.","막대의 채우기를 그라데이션 또는 단색으로 선택할 수 있다.","음수 값이 있는 범위에는 사용할 수 없다.","'막대만 표시'를 선택하면 셀의 숫자를 숨기고 막대만 보인다."],"answer":2,"explain":"데이터 막대는 음수 값도 축을 기준으로 반대 방향 막대로 나타낼 수 있다."},{"id":"ss-0263","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"한 범위에 서로 충돌하는 조건부 서식 규칙이 여러 개 있을 때 적용 방식에 대한 설명으로 옳은 것은?","options":["항상 첫 번째로 만든 규칙만 적용되고 나머지는 자동으로 삭제된다.","충돌하는 규칙은 저장되지 않고 오류 메시지가 나타난다.","규칙이 충돌하면 모든 서식이 취소되어 아무것도 적용되지 않는다.","[규칙 관리]의 목록에서 위쪽에 있는 규칙이 우선 적용되며 순서를 바꿀 수 있다."],"answer":3,"explain":"조건부 서식 규칙 관리자의 목록 순서가 우선순위이며 ▲▼로 바꾼다. 서로 충돌하지 않는 서식은 함께 적용된다."},{"id":"ss-0264","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"A2:D50에서 C열 값이 C열의 최대값인 행 전체에 서식을 적용하려 한다. [수식을 사용하여 서식을 지정할 셀 결정] 규칙을 만들 때(활성 셀 A2) 입력할 수식은?","options":["=$C$2=MAX($C$2:$C$50)","=$C2=MAX($C$2:$C$50)","=C2=MAX(C2:C50)","=MAX($C$2:$C$50)"],"answer":1,"explain":"열 C는 고정($C), 행은 상대(2)로 두어야 행마다 자기 값을 최대값과 비교하고, 최대값 범위는 모두 절대 참조여야 한다."},{"id":"ss-0265","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"'회계' 표시 형식과 '통화' 표시 형식의 차이로 옳은 것은?","options":["회계 형식은 통화 기호가 셀 왼쪽 끝에 정렬되고 값이 0이면 '-'로 표시된다.","통화 형식은 음수 값을 표시할 수 없다.","회계 형식은 숫자를 항상 셀의 가운데에 맞춘다.","회계 형식은 통화 기호를 표시하지 않고 소수점 자리만 맞춘다."],"answer":0,"explain":"회계 형식은 통화 기호와 소수점을 열에 맞춰 정렬한다. 통화 형식은 숫자 바로 앞에 기호를 붙이고 0도 그대로 표시한다."},{"id":"ss-0266","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =AVERAGEIF(B2:B7,\"B\",D2:D7) 의 결과는?","options":["81","84.5","85.67","88"],"answer":1,"explain":"팀이 B인 오(88)와 임(81)의 점수 평균은 84.5다."},{"id":"ss-0267","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =INDEX(A2:A7,MATCH(LARGE(D2:D7,2),D2:D7,0)) 의 결과는?","options":["임","윤","오","서"],"answer":3,"explain":"LARGE(D2:D7,2)는 두 번째로 큰 점수 90이고, MATCH가 그 위치(6번째)를 찾아 INDEX가 사원 열에서 '서'를 돌려준다."},{"id":"ss-0268","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =COUNTIF(D2:D7,\">=\"&AVERAGE(D2:D7)) 의 결과는?","options":["2","3","4","6"],"answer":1,"explain":"평균은 약 81.67이므로 이상인 점수는 88, 95, 90의 3건이다(81은 평균보다 작다)."},{"id":"ss-0269","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =RANK(D3,D2:D7,0)+RANK(D6,D2:D7,1) 의 결과는?","options":["4","5","6","7"],"answer":2,"explain":"D3(88)은 내림차순 3위, D6(81)은 오름차순 3위이므로 합은 6이다."},{"id":"ss-0270","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =REPT(\"▶\",2)&TRIM(\"  a  b \")&LEFT(\"홍길동\",1) 의 결과는?","options":["▶▶  a  b 홍","▶▶a b홍","▶▶a b홍길동","▶a b홍"],"answer":1,"explain":"REPT는 문자를 반복하고, TRIM은 앞뒤 공백을 지우며 단어 사이 공백은 하나만 남긴다. LEFT는 첫 글자만 가져온다."},{"id":"ss-0271","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =VLOOKUP(\"윤\",A2:D7,MATCH(\"직급\",A1:D1,0),FALSE) 의 결과는?","options":["대리","A","95","과장"],"answer":0,"explain":"MATCH로 '직급'이 머리글의 3번째임을 구해 VLOOKUP의 열 번호로 쓰므로 윤의 직급 '대리'가 나온다."},{"id":"ss-0272","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:E2\n구분 | 1월 | 2월 | 3월 | 4월\n매출 | 120 | 150 | 90 | 200\n위 표에서 수식 =HLOOKUP(\"3월\",A1:E2,2,FALSE) 의 결과는?","options":["3","90","120","150"],"answer":1,"explain":"HLOOKUP은 첫 행에서 '3월'을 찾아 같은 열의 2번째 행 값 90을 돌려준다."},{"id":"ss-0273","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"2026-10-04는 일요일이다. 수식 =TEXT(DATE(2026,10,9),\"aaaa\") 의 결과는?","options":["토요일","금요일","목요일","Friday"],"answer":1,"explain":"표시 형식 aaaa는 요일을 한글 전체 이름으로 표시한다. 10월 9일은 일요일에서 5일 뒤인 금요일이며, Friday는 dddd 형식의 결과다."},{"id":"ss-0274","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =DATEDIF(DATE(2020,3,15),DATE(2026,10,4),\"y\")&\"년 \"&DATEDIF(DATE(2020,3,15),DATE(2026,10,4),\"ym\")&\"개월\" 의 결과는?","options":["6년 7개월","6년 6개월","6년 78개월","7년 6개월"],"answer":1,"explain":"\"y\"는 만 6년, \"ym\"은 연도를 제외한 개월 차이로 3월 15일에서 9월 15일까지 6개월이며 10월 4일은 아직 한 달이 차지 않았다."},{"id":"ss-0275","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =LARGE(D2:D7,2)-SMALL(D2:D7,2) 의 결과는?","options":["14","18","22","31"],"answer":1,"explain":"두 번째로 큰 값 90에서 두 번째로 작은 값 72를 빼면 18이다. 31은 최대값과 최소값의 차다."},{"id":"ss-0276","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =MID(TEXT(20261004,\"0000-00-00\"),6,2) 의 결과는?","options":["04","10","20","26"],"answer":1,"explain":"TEXT가 20261004를 '2026-10-04' 문자열로 바꾸고 MID가 6번째부터 2글자인 '10'을 가져온다."},{"id":"ss-0277","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 배열 수식 {=MAX(IF(B2:B7=\"A\",D2:D7))} 의 결과는?","options":["72","88","90","95"],"answer":3,"explain":"IF가 팀이 A인 점수(72, 95, 90)만 남기고 나머지는 FALSE로 만들어 MAX가 그중 최대값 95를 구한다."},{"id":"ss-0278","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =SUMPRODUCT(--(D2:D7>AVERAGE(D2:D7)),D2:D7) 의 결과는?","options":["3","183","273","490"],"answer":2,"explain":"평균(약 81.67)보다 큰 점수 88, 95, 90만 1로 남겨 곱해 더하므로 273이다. 3은 건수, 490은 전체 합이다."},{"id":"ss-0279","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n사원 | 팀 | 직급 | 점수\n한 | A | 사원 | 72\n오 | B | 대리 | 88\n윤 | A | 대리 | 95\n장 | C | 사원 | 64\n임 | B | 과장 | 81\n서 | A | 과장 | 90\n위 표에서 수식 =INDEX(D2:D7,MATCH(1,INDEX((B2:B7=\"B\")*(C2:C7=\"과장\"),0),0)) 의 결과는?","options":["81","88","90","95"],"answer":0,"explain":"팀 B이면서 직급이 과장인 조건을 곱해 1이 되는 행은 임(5번째)뿐이므로 그 점수 81이 나온다."},{"id":"ss-0280","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"연이율 12%로 1,200을 빌려 12개월 동안 원리금균등상환할 때, 수식 =IPMT(12%/12,1,12,-1200) 의 결과(1회차 납입액 중 이자)는?","options":["12","94.62","106.62","144"],"answer":0,"explain":"첫 회차의 이자는 남은 원금 1,200에 월이율 1%를 곱한 12다. 106.62는 매월 납입액(PMT), 94.62는 그중 원금(PPMT)이다."},{"id":"ss-0281","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[정렬] 대화 상자에서 '내 데이터에 머리글 표시'를 해제하고 정렬하면?","options":["첫 행이 자동으로 삭제된다.","행 방향 정렬만 할 수 있게 된다.","정렬 기준을 지정할 수 없게 된다.","첫 행도 일반 데이터로 보아 정렬 대상에 포함되고 정렬 기준이 '열 A'처럼 표시된다."],"answer":3,"explain":"머리글 표시를 해제하면 선택 범위의 모든 행이 데이터이므로 첫 행도 함께 정렬된다."},{"id":"ss-0282","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"필터가 적용된 목록에서 필터 단추는 그대로 두고 적용된 필터 조건만 모두 해제하는 메뉴는?","options":["[데이터]-[정렬 및 필터]-[필터]를 다시 클릭","[데이터]-[정렬 및 필터]-[고급]","[데이터]-[정렬 및 필터]-[다시 적용]","[데이터]-[정렬 및 필터]-[지우기]"],"answer":3,"explain":"[지우기]는 조건만 해제하고 필터 단추를 유지한다. [필터]를 다시 누르면 필터 자체가 꺼져 단추가 사라진다."},{"id":"ss-0283","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"고급 필터의 [다른 장소에 복사]로 필요한 열만 결과로 얻으려 한다. 어떻게 해야 하는가?","options":["[정렬] 대화 상자에서 가져올 열만 선택한다.","'복사 위치'로 지정할 범위의 머리글 행에 필요한 열 이름만 미리 입력해 둔다.","결과를 모두 복사한 뒤 불필요한 열을 삭제해야 하며 다른 방법은 없다.","조건 범위의 첫 행에 필요한 열 이름만 입력한다."],"answer":1,"explain":"복사 위치의 머리글에 적어 둔 열 이름과 순서대로만 결과가 복사된다."},{"id":"ss-0284","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"셀을 선택하면 입력 방법을 안내하는 풍선 도움말이 나타나도록 하려면 데이터 유효성 검사 대화 상자의 어느 탭에서 설정하는가?","options":["설정","오류 메시지","설명 메시지","IME 모드"],"answer":2,"explain":"설명 메시지 탭에 제목과 내용을 입력하면 해당 셀을 선택할 때 안내가 나타난다. 오류 메시지는 잘못된 값을 입력했을 때 나타난다."},{"id":"ss-0285","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"가로 방향으로 입력된 데이터를 열 단위로 정렬하려면 [정렬] 대화 상자의 [옵션]에서 무엇을 선택하는가?","options":["머리글 포함","대/소문자 구분","위쪽에서 아래쪽","왼쪽에서 오른쪽"],"answer":3,"explain":"정렬 방향의 기본은 위쪽에서 아래쪽(행 정렬)이며, 왼쪽에서 오른쪽을 선택하면 열 순서를 바꾸는 정렬이 된다."},{"id":"ss-0286","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"두 범위(사과 10, 배 20 / 사과 5, 포도 7)를 [통합]의 '합계', '첫 행'과 '왼쪽 열' 사용으로 통합했을 때 결과의 '사과' 값은?","options":["5","10","15","22"],"answer":2,"explain":"첫 행·왼쪽 열을 레이블로 사용하면 같은 레이블끼리 합산되어 사과는 10+5=15, 배는 20, 포도는 7이다."},{"id":"ss-0287","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"피벗 테이블의 값 영역에 문자 데이터가 들어 있는 필드를 놓았을 때 기본으로 적용되는 요약 함수는?","options":["개수","최대","합계","평균"],"answer":0,"explain":"숫자 필드는 기본적으로 합계, 문자 필드는 개수로 요약된다."},{"id":"ss-0288","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 테이블의 날짜 필드를 월·분기·연 단위로 막대를 끌어 필터링하는 도구는?","options":["슬라이서","계산 필드","타임라인","보고서 필터"],"answer":2,"explain":"타임라인은 날짜 필드를 시간 단위로 걸러 내는 시각적 필터다. 슬라이서는 단추 형태의 일반 필터다."},{"id":"ss-0289","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"이자율은 가로로, 기간은 세로로 나열해 두 변수의 데이터 표를 만들 때 [데이터 표] 대화 상자의 '행 입력 셀'에 지정하는 것은?","options":["결과 수식이 들어 있는 셀","세로로 나열한 값(기간)이 대입될 입력 셀","가로로 나열한 값(이자율)이 대입될 수식 속의 입력 셀","데이터 표의 결과가 표시될 범위"],"answer":2,"explain":"행 입력 셀은 첫 행에 나열된 값을, 열 입력 셀은 첫 열에 나열된 값을 대입할 입력 셀이다."},{"id":"ss-0290","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"부분합이 적용된 목록의 왼쪽 윤곽 기호에서 [1] 단추를 클릭하면 표시되는 내용은?","options":["첫 번째 그룹의 부분합만 표시된다.","총합계만 표시된다.","부분합과 총합계만 표시된다.","모든 상세 데이터가 표시된다."],"answer":1,"explain":"윤곽 기호 1은 총합계, 2는 부분합과 총합계, 3은 모든 데이터를 보여 준다(그룹이 한 단계일 때)."},{"id":"ss-0291","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트의 계열(범례 항목)과 항목(가로 축)을 서로 바꾸려면 [차트 디자인] 탭의 어떤 기능을 쓰는가?","options":["행/열 전환","차트 종류 변경","차트 이동","차트 스타일 변경"],"answer":0,"explain":"행/열 전환은 데이터 계열을 행에서 열로(또는 반대로) 바꿔 차트의 축 구성을 뒤집는다."},{"id":"ss-0292","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트 원본 데이터의 일부 행을 숨겼을 때의 기본 동작으로 옳은 것은?","options":["숨겨진 행의 값이 0으로 바뀌어 표시된다.","숨겨진 행이 있으면 차트가 삭제된다.","숨겨진 행의 데이터는 차트에 표시되지 않으며, '숨겨진 행 및 열의 데이터 표시'를 선택하면 표시된다.","숨겨진 행도 항상 차트에 그대로 표시된다."],"answer":2,"explain":"[데이터 원본 선택]의 [숨겨진 셀/빈 셀]에서 숨긴 데이터를 차트에 포함할지 정한다."},{"id":"ss-0293","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"추세선 옵션에서 'R-제곱 값을 차트에 표시'를 선택했을 때 R-제곱 값이 1에 가까울수록 의미하는 것은?","options":["예측 기간이 길어진다.","오차가 커진다.","추세선이 실제 데이터에 잘 맞는다.","데이터의 평균이 크다."],"answer":2,"explain":"R-제곱은 추세선이 데이터를 설명하는 정도를 나타내며 1에 가까울수록 적합하다."},{"id":"ss-0294","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"차트에 오차 막대를 추가할 때 [오차량]에서 고를 수 없는 항목은?","options":["중앙값","표준 편차","백분율","고정 값"],"answer":0,"explain":"오차량에는 고정 값, 백분율, 표준 편차, 표준 오차, 사용자 지정이 있다."},{"id":"ss-0295","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[보기]-[페이지 레이아웃] 보기에 대한 설명으로 옳지 않은 것은?","options":["머리글/바닥글 영역을 클릭해 바로 내용을 입력할 수 있다.","인쇄될 용지의 모양과 여백을 화면에서 확인하며 편집할 수 있다.","가로·세로 눈금자가 표시되어 여백을 가늠하기 쉽다.","머리글과 바닥글은 직접 편집할 수 없고 [페이지 설정] 대화 상자에서만 편집할 수 있다."],"answer":3,"explain":"페이지 레이아웃 보기에서는 머리글/바닥글을 클릭해 직접 입력·편집할 수 있다."},{"id":"ss-0296","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"인쇄할 때 A열과 B열을 모든 페이지의 왼쪽에 반복하려 한다. [페이지 설정]-[시트] 탭의 '반복할 열'에 입력하는 형식으로 옳은 것은?","options":["$1:$2","A1:B1","$A$1:$B$1","$A:$B"],"answer":3,"explain":"반복할 열은 $A:$B처럼 열 전체를 절대 참조로 쓰고, 반복할 행은 $1:$2처럼 쓴다."},{"id":"ss-0297","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 채우기()\n    Dim i As Integer\n    For i = 2 To 6 Step 2\n        Cells(i, 1).Value = i * 5\n    Next i\n    MsgBox Range(\"A2\").Value + Range(\"A4\").Value + Range(\"A6\").Value\nEnd Sub","options":["30","50","60","90"],"answer":2,"explain":"i가 2, 4, 6일 때 A2=10, A4=20, A6=30이 입력되어 합은 60이다."},{"id":"ss-0298","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행한 뒤 메시지 상자에 표시되는 값은?\nn = 1: s = 0\nDo Until n > 4\n    s = s + n * n\n    n = n + 1\nLoop\nMsgBox s","options":["14","25","30","55"],"answer":2,"explain":"Do Until은 조건이 참이 될 때까지 반복하므로 n=1~4일 때 제곱을 더해 1+4+9+16=30이다."},{"id":"ss-0299","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행했을 때 메시지 상자에 표시되는 값은?\nMsgBox (7 \\ 2) & \",\" & (7 Mod 2) & \",\" & (7 / 2)","options":["3,1,3.5","3,3,3.5","4,1,3.5","3.5,1,3"],"answer":0,"explain":"\\는 정수 나눗셈의 몫(3), Mod는 나머지(1), /는 일반 나눗셈(3.5)이다."},{"id":"ss-0300","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"A1:A10에는 값이 있고 A11 이하는 비어 있다. A열의 마지막 데이터 행 번호(10)를 구하는 VBA 식은?","options":["Cells(Rows.Count, 1).End(xlUp).Row","Cells(1, 1).End(xlToRight).Row","Range(\"A1\").End(xlUp).Row","Cells(Rows.Count, 1).End(xlDown).Row"],"answer":0,"explain":"맨 아래 셀에서 위쪽(xlUp)으로 올라가 처음 만나는 데이터 셀의 행을 구한다. 맨 아래에서 xlDown을 쓰면 계속 맨 아래 행이다."},{"id":"ss-0301","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"[보기]-[새 창]을 실행했을 때의 결과로 옳은 것은?","options":["현재 창이 닫히고 같은 파일이 처음부터 다시 열린다.","현재 통합 문서가 복사되어 별도의 새 파일이 만들어진다.","현재 시트가 새 통합 문서로 이동하고 원래 통합 문서에서는 사라진다.","같은 통합 문서를 보여 주는 새 창이 열리고 제목 표시줄에 ':1', ':2' 같은 번호가 붙는다."],"answer":3,"explain":"새 창은 같은 파일을 다른 창으로 보는 기능이라 한 창에서 고친 내용이 다른 창에도 즉시 반영된다. 파일이 복사되지는 않는다."},{"id":"ss-0302","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"이진 통합 문서(*.xlsb) 형식의 특징으로 옳은 것은?","options":["매크로를 포함할 수 없는 형식이다.","다른 프로그램과의 호환성이 가장 높은 형식이다.","메모장 같은 텍스트 편집기에서 열어 내용을 수정할 수 있는 XML 기반 형식이다.","용량이 큰 통합 문서를 빠르게 열고 저장할 수 있으며 VBA 매크로도 포함할 수 있다."],"answer":3,"explain":"xlsb는 바이너리 형식이라 크기가 작고 속도가 빠르지만 다른 프로그램과의 호환성은 낮다."},{"id":"ss-0303","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"리본 메뉴를 접거나 펼치는 바로 가기 키는?","options":["Ctrl+F12","Ctrl+F2","Ctrl+F1","Alt+F1"],"answer":2,"explain":"Ctrl+F1은 리본 표시를 토글한다. Ctrl+F12는 [열기], Alt+F1은 현재 데이터로 차트를 바로 삽입한다."},{"id":"ss-0304","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"수식이 자기 자신의 셀을 참조하는 순환 참조 경고를 피하고 반복 계산으로 값을 구하려면 [파일]-[옵션]-[수식]에서 무엇을 설정해야 하는가?","options":["자동 계산","수동 계산","R1C1 참조 스타일","반복 계산 사용"],"answer":3,"explain":"'반복 계산 사용'을 선택하면 최대 반복 횟수와 변화량 한도 안에서 순환 참조를 반복 계산한다."},{"id":"ss-0305","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"선택한 범위의 첫 번째 행 내용을 아래쪽 셀들에 복사해 채우는 바로 가기 키는?","options":["Ctrl+D","Ctrl+E","Ctrl+Enter","Ctrl+R"],"answer":0,"explain":"Ctrl+D는 위 셀의 내용을 아래로, Ctrl+R은 왼쪽 셀의 내용을 오른쪽으로 채운다. Ctrl+E는 빠른 채우기다."},{"id":"ss-0306","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"행 전체가 선택된 상태에서 그 행을 삭제하는 바로 가기 키는?","options":["Shift+Space","Ctrl++","Ctrl+Space","Ctrl+-"],"answer":3,"explain":"Ctrl+-는 삭제, Ctrl++는 삽입이다. Shift+Space는 행 선택, Ctrl+Space는 열 선택 키다."},{"id":"ss-0307","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"[이동 옵션] 대화 상자에서 선택할 수 없는 것은?","options":["중복된 값","빈 셀","조건부 서식","행 차이"],"answer":0,"explain":"이동 옵션에는 메모·상수·수식·빈 셀·현재 지역·행 차이·열 차이·조건부 서식·데이터 유효성 등이 있고 중복된 값은 없다."},{"id":"ss-0308","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"우편번호 01234를 앞의 0이 사라지지 않게 입력하는 방법으로 옳은 것은?","options":["표시 형식을 '일반'으로 두고 Ctrl+Shift+Enter로 입력한다.","입력 앞에 등호(=)를 붙여 입력한다.","셀 표시 형식을 '숫자'로 지정하고 소수 자릿수를 0으로 한다.","입력 앞에 작은따옴표(')를 붙이거나 셀 표시 형식을 '텍스트'로 지정한다."],"answer":3,"explain":"텍스트로 입력해야 앞의 0이 유지된다. 숫자로 입력하면 0이 사라지며 =01234는 숫자 1234로 계산된다."},{"id":"ss-0309","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"Sheet1의 A1을 복사해 Sheet2의 B2에 [선택하여 붙여넣기]-[연결하여 붙여넣기]를 했을 때 B2에 입력되는 수식은?","options":["=[Sheet1]A1","=Sheet1!A1","=Sheet1!B2","=Sheet1!$A$1"],"answer":3,"explain":"연결하여 붙여넣기는 원본 셀을 절대 참조로 연결하므로 원본이 바뀌면 값도 함께 바뀐다."},{"id":"ss-0310","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 5에 사용자 지정 표시 형식 #.## 을 적용했을 때 표시되는 결과는?","options":["5.0","5.","5","5.00"],"answer":1,"explain":"#은 값이 없으면 자릿수를 채우지 않지만 소수점은 형식에 있으므로 '5.'처럼 소수점만 남는다."},{"id":"ss-0311","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 0.5625에 사용자 지정 표시 형식 h\"시간\" mm\"분\" 을 적용한 결과는?","options":["13시간 30분","0시간 56분","13시간 3분","12시간 30분"],"answer":0,"explain":"시간은 하루를 1로 보므로 0.5625는 24×0.5625=13.5시간, 즉 13시 30분이다."},{"id":"ss-0312","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"표시 형식이 0.000인 셀의 값 3.14159에서 [자릿수 줄임]을 한 번 눌렀다. 셀에 표시되는 값과 수식 입력줄에 표시되는 값을 차례로 쓴 것은?","options":["3.14, 3.14159","3.142, 3.14159","3.14, 3.14","3.14, 3.142"],"answer":0,"explain":"자릿수 줄임은 표시 형식만 바꾸고 실제 저장된 값은 그대로이므로 수식 입력줄에는 원래 값이 보인다."},{"id":"ss-0313","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"사용자 지정 표시 형식 0.0# 을 적용한 두 셀에 각각 2와 2.346을 입력했을 때 표시를 차례로 쓴 것은?","options":["2, 2.346","2.00, 2.35","2.0, 2.35","2.0, 2.3"],"answer":2,"explain":"0.0#에서 0은 항상 한 자리를 표시하고 #은 필요할 때만 한 자리를 더 표시한다. 2는 2.0, 2.346은 소수 둘째 자리까지 반올림한 2.35가 된다."},{"id":"ss-0314","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"조건부 서식의 [아이콘 집합] 중 3가지 기호를 기본 설정으로 적용했을 때 아이콘이 나뉘는 기본 기준으로 옳은 것은?","options":["상위 10%는 첫 번째, 다음 20%는 두 번째, 나머지는 세 번째 아이콘","백분율 기준으로 75% 이상은 첫 번째, 50% 이상 75% 미만은 두 번째, 50% 미만은 세 번째 아이콘","평균 이상은 첫 번째, 평균 미만은 두 번째, 0 미만은 세 번째 아이콘","백분율 기준으로 67% 이상은 첫 번째, 33% 이상 67% 미만은 두 번째, 33% 미만은 세 번째 아이콘"],"answer":3,"explain":"3가지 아이콘 집합은 기본적으로 값의 범위를 33%, 67% 지점으로 나눈다. [규칙 편집]에서 기준을 바꿀 수 있다."},{"id":"ss-0315","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"조건부 서식에 대한 설명으로 옳은 것은?","options":["조건부 서식이 적용된 셀은 값을 수정할 수 없다.","한 셀에는 조건부 서식 규칙을 하나만 적용할 수 있다.","조건부 서식 규칙을 지워도 셀에 직접 지정한 글꼴·채우기 같은 일반 서식은 그대로 남는다.","조건부 서식은 셀 값으로만 지정할 수 있고 수식으로는 지정할 수 없다."],"answer":2,"explain":"조건부 서식은 일반 서식 위에 조건이 맞을 때만 덧씌워지는 서식이다. 한 범위에 여러 규칙을 둘 수 있고 수식 규칙도 쓸 수 있다."},{"id":"ss-0316","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =SUMPRODUCT(D2:D7,E2:E7) 의 결과는?","options":["25","510","1030","1130"],"answer":3,"explain":"수량×단가를 행마다 곱해 더한 값이다(400+200+150+200+60+120=1130). 25는 수량 합, 510은 단가 합이다."},{"id":"ss-0317","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =SUMIF(C2:C7,\"모니터\",E2:E7)+COUNTIF(B2:B7,\"나\") 의 결과는?","options":["5","400","402","410"],"answer":2,"explain":"모니터의 단가 합 400에 고객 '나'의 주문 수 2를 더해 402다."},{"id":"ss-0318","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =VLOOKUP(3.5,A2:E7,3) 의 결과는?","options":["#N/A","모니터","마우스","키보드"],"answer":2,"explain":"네 번째 인수를 생략하면 근사 일치로 3.5 이하의 가장 큰 값 3을 찾으므로 3번 주문의 제품 '마우스'가 나온다."},{"id":"ss-0319","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =AVERAGEIFS(D2:D7,B2:B7,\"가\",E2:E7,\"<100\") 의 결과는?","options":["5","6","6.5","15"],"answer":2,"explain":"고객이 가이면서 단가가 100 미만인 마우스(10)와 키보드(3)의 수량 평균은 6.5다. 5는 단가 조건 없이 가의 전체 평균이다."},{"id":"ss-0320","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =TEXTJOIN(\"-\",TRUE,B2:B4,\"\",\"끝\") 의 결과는?","options":["가-나-가--끝","가나가끝","가-나-가-끝-","가-나-가-끝"],"answer":3,"explain":"TEXTJOIN은 구분 기호로 값을 이어 붙이고, 두 번째 인수가 TRUE이면 빈 문자열(\"\")은 건너뛴다."},{"id":"ss-0321","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =DAY(EOMONTH(DATE(2028,2,1),0))+MONTH(DATE(2026,11,5)) 의 결과는?","options":["29","39","40","41"],"answer":2,"explain":"2028년 2월의 마지막 날은 29일(윤년)이고 MONTH는 11이므로 합은 40이다."},{"id":"ss-0322","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =IFS(D2>5,\"대\",D2>=2,\"중\",TRUE,\"소\") 의 결과는?","options":["중","대","소","#N/A"],"answer":0,"explain":"IFS는 조건을 순서대로 검사해 처음 참인 조건의 값을 돌려준다. D2는 2이므로 첫 조건은 거짓, 둘째 조건이 참이라 '중'이다."},{"id":"ss-0323","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =ROUNDUP(12.341,2)+ROUNDDOWN(-12.349,2) 의 결과는?","options":["-0.01","0","0.01","0.02"],"answer":2,"explain":"ROUNDUP은 0에서 멀어지게 올려 12.35, ROUNDDOWN은 0에 가깝게 내려 -12.34이므로 합은 0.01이다."},{"id":"ss-0324","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n시트의 3행과 4행을 숨기기한 상태에서 =SUBTOTAL(9,D2:D7) 과 =SUBTOTAL(109,D2:D7) 의 결과를 차례로 쓴 것은?","options":["25, 25","10, 10","10, 25","25, 10"],"answer":3,"explain":"SUBTOTAL의 9는 숨긴 행을 포함해 합계(25)를, 109는 직접 숨긴 행을 제외한 합계(2+1+4+3=10)를 구한다."},{"id":"ss-0325","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 배열 수식 {=SUM(IF(MOD(D2:D7,2)=0,D2:D7))} 의 결과는?","options":["9","16","20","25"],"answer":1,"explain":"MOD로 2로 나눈 나머지가 0인 짝수 수량(2, 10, 4)만 더해 16이다. 9는 홀수의 합이다."},{"id":"ss-0326","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 배열 수식 {=SUM((B2:B7=\"가\")*D2:D7*E2:E7)} 의 결과는?","options":["15","450","670","1130"],"answer":2,"explain":"고객이 가인 주문의 수량×단가(400+150+120)만 더해 670이다. 1130은 모든 고객의 합이다."},{"id":"ss-0327","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =LOOKUP(2,1/(B2:B7=\"가\"),D2:D7) 의 결과는?","options":["2","3","6","10"],"answer":1,"explain":"조건이 거짓인 행은 1/0 오류가 되어 무시되고 2는 1보다 크므로 마지막으로 조건에 맞는 행(6번 주문)의 수량 3이 나온다."},{"id":"ss-0328","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n위 표에서 수식 =SUMPRODUCT((C2:C7=\"모니터\")+(C2:C7=\"마우스\"),D2:D7) 의 결과는?","options":["3","14","17","25"],"answer":2,"explain":"더하기는 'OR' 조건이므로 모니터(2+1)와 마우스(10+4)의 수량을 모두 더해 17이다."},{"id":"ss-0329","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"취득가 1,000, 잔존가치 100, 내용 연수 5년인 자산의 3년차 감가상각액을 구하는 수식 =DDB(1000,100,5,3) 의 결과는?","options":["144","180","216","240"],"answer":0,"explain":"DDB(배율법)는 연도마다 장부 가치에 40%를 곱한다. 400, 240, 144 순이며 180은 정액법 금액이다."},{"id":"ss-0330","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =PV(10%,2,0,-1210) 의 결과를 숫자로 나타낸 것은? (2기간 뒤 1,210을 받기 위해 지금 필요한 금액)","options":["968","1000","1100","1210"],"answer":1,"explain":"연 10%로 2기간 뒤 1,210이 되려면 현재가치는 1,210÷1.1²=1,000이다."},{"id":"ss-0331","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"자동 필터에서 채우기 색이 노란색인 셀만 표시하려면 필터 단추 메뉴의 어떤 항목을 사용하는가?","options":["색 기준 필터","검색 상자","텍스트 필터","숫자 필터"],"answer":0,"explain":"색 기준 필터는 셀 색·글꼴 색·아이콘으로 데이터를 걸러 낸다."},{"id":"ss-0332","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"이미 입력된 데이터 중 유효성 검사 규칙에 맞지 않는 값에 빨간 원을 표시하는 기능은?","options":["[조건부 서식]-[셀 강조 규칙]","[오류 검사]-[오류 추적]","[수식 분석]-[참조되는 셀 추적]","[데이터 유효성 검사]-[잘못된 데이터 표시]"],"answer":3,"explain":"유효성 검사는 규칙 설정 이전에 입력된 값은 검사하지 않으므로 [잘못된 데이터 표시]로 위반 값을 찾는다."},{"id":"ss-0333","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[표] A1:E7\n주문번호 | 고객 | 제품 | 수량 | 단가\n1 | 가 | 모니터 | 2 | 200\n2 | 나 | 키보드 | 5 | 40\n3 | 가 | 마우스 | 10 | 15\n4 | 다 | 모니터 | 1 | 200\n5 | 나 | 마우스 | 4 | 15\n6 | 가 | 키보드 | 3 | 40\n고급 필터의 조건 범위가 다음과 같을 때 추출되는 주문번호는?\n고객 | 제품\n가 | 모니터\n나 | 마우스","options":["1, 3, 5, 6","1, 4","1, 5","1, 2, 3, 4, 5, 6"],"answer":2,"explain":"같은 행의 조건은 AND, 서로 다른 행의 조건은 OR다. 가이면서 모니터인 1번, 나이면서 마우스인 5번만 추출된다."},{"id":"ss-0334","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"표 이름이 '판매'이고 열 이름이 '금액'일 때 금액 열 전체의 합계를 구하는 구조적 참조 수식은?","options":["=SUM(금액[판매])","=SUM(판매.금액)","=SUM(판매!금액)","=SUM(판매[금액])"],"answer":3,"explain":"표의 열은 '표이름[열이름]' 형식의 구조적 참조로 쓰며 행이 추가되어도 범위가 자동으로 늘어난다."},{"id":"ss-0335","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[텍스트 나누기]에서 구분 기호를 쉼표로 지정하고 '연속된 구분 기호를 하나로 처리'를 선택했다. 셀의 내용 a,,b 는 몇 개의 열로 나누어지는가?","options":["3개(a, 빈 셀, b)","1개","4개","2개(a, b)"],"answer":3,"explain":"연속된 쉼표를 하나로 취급하므로 빈 열 없이 a와 b 두 열로 나뉜다. 선택하지 않으면 가운데 빈 열이 생긴다."},{"id":"ss-0336","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"부분합 대화 상자에서 사용할 함수를 '합계'로 하여 실행했을 때 부분합 행의 셀에 입력되는 수식 형태는?","options":["=SUMIF(범위)","=SUM(범위)","=SUBTOTAL(9,범위)","=AGGREGATE(9,범위)"],"answer":2,"explain":"부분합은 SUBTOTAL 함수를 사용하며 함수 번호 9가 합계, 1이 평균, 2가 개수다."},{"id":"ss-0337","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"피벗 차트로 만들 수 없는 차트 종류는?","options":["세로 막대형","분산형(XY)","꺾은선형","원형"],"answer":1,"explain":"피벗 차트는 분산형(XY), 거품형, 주식형 차트로는 만들 수 없다."},{"id":"ss-0338","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"[피벗 테이블 디자인] 탭의 [레이아웃] 그룹에 없는 항목은?","options":["슬라이서 삽입","보고서 레이아웃","부분합","총합계"],"answer":0,"explain":"슬라이서 삽입은 [피벗 테이블 분석] 탭에 있다. 디자인 탭의 레이아웃 그룹에는 부분합·총합계·보고서 레이아웃·빈 행이 있다."},{"id":"ss-0339","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"해 찾기의 [해법 선택]에서 고를 수 있는 풀이 방법이 아닌 것은?","options":["진화","몬테카를로 시뮬레이션","단순 LP","GRG 비선형"],"answer":1,"explain":"해 찾기 풀이 방법은 GRG 비선형, 단순 LP, 진화 세 가지다."},{"id":"ss-0340","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"[데이터 분석](분석 도구 추가 기능) 대화 상자에서 제공하지 않는 항목은?","options":["회귀 분석","피벗 테이블 만들기","기술 통계법","히스토그램"],"answer":1,"explain":"분석 도구는 기술 통계법·히스토그램·회귀 분석·상관 분석 같은 통계 분석을 제공하며 피벗 테이블은 [삽입] 탭 기능이다."},{"id":"ss-0341","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"항목별로 각 계열이 차지하는 비율(구성비)을 100% 기준으로 비교하는 데 가장 알맞은 차트는?","options":["분산형","100% 기준 누적 세로 막대형","묶은 세로 막대형","꺾은선형"],"answer":1,"explain":"100% 기준 누적 막대형은 모든 막대의 합이 같은 높이(100%)가 되어 구성비를 비교한다."},{"id":"ss-0342","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"원형 차트의 데이터 레이블에서 선택할 수 있는 내용이 아닌 것은?","options":["백분율","항목 이름","값","추세선 수식"],"answer":3,"explain":"원형 차트 레이블은 계열 이름·항목 이름·값·백분율을 표시할 수 있고, 추세선은 원형 차트에 추가할 수 없다."},{"id":"ss-0343","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"꺾은선형 차트에 기간이 3인 이동 평균 추세선을 추가하면 추세선의 첫 번째 점은 어디에 표시되는가?","options":["두 번째 데이터 시점","첫 번째 데이터 시점","네 번째 데이터 시점","세 번째 데이터 시점"],"answer":3,"explain":"이동 평균은 지정한 기간 수만큼의 값이 모여야 계산되므로 기간이 3이면 세 번째 점부터 표시된다."},{"id":"ss-0344","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"스파크라인 종류 중 값의 크기와 상관없이 양수는 위쪽, 음수는 아래쪽에 같은 크기의 막대로 표시하는 것은?","options":["승패","열","꺾은선형","도넛형"],"answer":0,"explain":"스파크라인에는 꺾은선형, 열, 승패가 있고 승패는 값의 부호만 보여 준다. 열은 값의 크기를 막대 높이로 나타낸다."},{"id":"ss-0345","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"인쇄 화면(인쇄 미리 보기)을 여는 바로 가기 키는?","options":["Ctrl+W","Ctrl+O","Ctrl+P","Ctrl+N"],"answer":2,"explain":"Ctrl+P는 [파일]-[인쇄] 화면을 연다. Ctrl+O는 열기, Ctrl+N은 새 통합 문서, Ctrl+W는 창 닫기다."},{"id":"ss-0346","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"워크시트에 삽입한 수동 페이지 나누기를 모두 제거하는 방법은?","options":["[검토]-[시트 보호]를 적용","[페이지 레이아웃]-[인쇄 영역]-[인쇄 영역 해제]","[보기]-[통합 문서 보기]-[기본]으로 전환","[페이지 레이아웃]-[나누기]-[모든 페이지 나누기 해제]"],"answer":3,"explain":"[모든 페이지 나누기 해제]는 수동으로 넣은 나누기를 한 번에 지운다. 인쇄 영역 해제는 인쇄 범위 지정만 없앤다."},{"id":"ss-0347","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[페이지] 탭의 '확대/축소 배율'로 지정할 수 있는 범위는?","options":["1%~200%","10%~400%","25%~200%","50%~500%"],"answer":1,"explain":"인쇄 배율은 10%에서 400%까지 지정할 수 있다."},{"id":"ss-0348","subject":"spreadsheet","levels":["c2","c1"],"topic":"매크로·VBA","q":"[파일]-[옵션]-[보안 센터]-[매크로 설정]에서 기본으로 선택되어 있는 항목은?","options":["알림이 포함된 VBA 매크로 사용 안 함","모든 매크로 포함(위험한 코드가 실행될 수 있으므로 권장하지 않음)","알림 없이 VBA 매크로 사용 안 함","디지털 서명된 매크로만 VBA 매크로 사용"],"answer":0,"explain":"기본값은 매크로를 막되 보안 경고 줄을 보여 사용자가 [콘텐츠 사용]을 누르면 실행할 수 있게 한다."},{"id":"ss-0349","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 최대()\n    Dim a(1 To 4) As Integer, i As Integer, m As Integer\n    a(1) = 7: a(2) = 3: a(3) = 9: a(4) = 5\n    m = a(1)\n    For i = 2 To 4\n        If a(i) > m Then m = a(i)\n    Next i\n    MsgBox m\nEnd Sub","options":["5","7","9","24"],"answer":2,"explain":"m을 첫 값 7로 두고 더 큰 값이 나오면 바꾸므로 9가 최대값으로 남는다. 24는 모든 값의 합이다."},{"id":"ss-0350","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"VBA에서 Range(\"B2\").Resize(2, 3) 이 가리키는 범위는?","options":["B2:D3","B2:C4","B2:E3","B2:D4"],"answer":0,"explain":"Resize(행 수, 열 수)는 시작 셀 기준으로 범위 크기를 바꾼다. 2행 3열이므로 B2:D3이다."},{"id":"ss-0351","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"워크시트 탭을 Ctrl 키를 누른 채 다른 위치로 끌었을 때의 결과는?","options":["여러 시트가 그룹으로 선택되어 함께 편집된다.","시트가 삭제되고 삭제 취소 단추만 남는다.","시트가 원래 통합 문서에서 사라지고 새 위치로 이동만 된다.","시트가 복사되어 'Sheet1 (2)'처럼 번호가 붙은 새 시트가 만들어진다."],"answer":3,"explain":"시트 탭을 그냥 끌면 이동, Ctrl 키를 누른 채 끌면 복사다. 그룹 선택은 Shift 또는 Ctrl 키를 누르고 탭을 클릭한다."},{"id":"ss-0352","subject":"spreadsheet","levels":["c2","c1"],"topic":"환경·파일","q":"열 머리글의 경계선을 더블클릭했을 때의 결과는?","options":["해당 열에서 가장 긴 데이터에 맞춰 열 너비가 자동으로 조정된다.","열 너비가 기본값으로 되돌아간다.","그 열이 숨겨진다.","그 열이 삭제된다."],"answer":0,"explain":"열 너비 자동 맞춤은 열 경계를 더블클릭하거나 [홈]-[서식]-[열 너비 자동 맞춤]으로 실행한다."},{"id":"ss-0353","subject":"spreadsheet","levels":["c1"],"topic":"환경·파일","q":"다른 통합 문서의 셀을 참조하는 수식(외부 링크)의 원본 파일을 바꾸거나 연결을 끊으려면 사용하는 기능은?","options":["[파일]-[정보]-[문서 검사]","[데이터]-[링크 편집]","[검토]-[통합 문서 보호]","[수식]-[이름 관리자]"],"answer":1,"explain":"[링크 편집] 대화 상자에서 원본 변경, 값 업데이트, 연결 끊기를 할 수 있다."},{"id":"ss-0354","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"선택한 셀에 노트(메모)를 삽입하거나 편집하는 바로 가기 키는?","options":["F2","Ctrl+F2","Shift+F2","Alt+Enter"],"answer":2,"explain":"Shift+F2는 노트 삽입·편집이다. F2는 셀 편집 모드, Ctrl+F2는 인쇄 미리 보기, Alt+Enter는 셀 안에서 줄 바꿈이다."},{"id":"ss-0355","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"선택한 셀에 하이퍼링크를 삽입하는 바로 가기 키는?","options":["Ctrl+L","Ctrl+K","Ctrl+H","Ctrl+B"],"answer":1,"explain":"Ctrl+K는 [하이퍼링크 삽입] 대화 상자를 연다. Ctrl+H는 바꾸기, Ctrl+L은 표 만들기, Ctrl+B는 굵게다."},{"id":"ss-0356","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"셀에 (100) 을 입력하면 저장되는 값은?","options":["-100","#NAME? 오류","100","문자열 (100)"],"answer":0,"explain":"괄호로 감싼 숫자는 음수로 인식되어 -100으로 저장되고 괄호가 있는 숫자 서식으로 표시된다."},{"id":"ss-0357","subject":"spreadsheet","levels":["c2","c1"],"topic":"입력·편집","q":"셀 범위의 경계선을 Shift 키를 누른 채 다른 위치로 끌어 놓으면?","options":["기존 데이터를 덮어쓰지 않고 그 위치에 끼워 넣어지며 이동된다.","대상 셀의 기존 값을 덮어쓰며 복사된다.","값은 빼고 서식만 이동된다.","수식이 값으로 바뀌어 복사된다."],"answer":0,"explain":"그냥 끌면 이동하며 덮어쓰고, Ctrl 키를 누르면 복사, Shift 키를 누르면 삽입 이동이 된다."},{"id":"ss-0358","subject":"spreadsheet","levels":["c1"],"topic":"입력·편집","q":"Shift+F8 키를 누르면 어떤 상태가 되는가?","options":["방향키로 선택 영역이 확장되는 확장 모드가 켜진다.","다음 시트로 이동한다.","함수 삽입 대화 상자가 열린다.","Shift 키 없이 마우스로 다른 범위를 선택해도 현재 선택 영역에 추가되는 상태가 된다."],"answer":3,"explain":"Shift+F8은 선택 영역에 추가 모드(떨어진 범위 선택)이고, F8은 확장 선택 모드다."},{"id":"ss-0359","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 0.15에 표시 형식 0.0% 를, 셀 값 15에 표시 형식 0\"%\" 를 각각 적용한 결과를 차례로 쓴 것은?","options":["15.0%, 15%","15%, 1500%","0.2%, 15%","15.0%, 1500%"],"answer":0,"explain":"% 기호가 따옴표 없이 쓰이면 값에 100을 곱해 표시하고, \"%\"처럼 따옴표로 묶으면 단순한 문자로 붙는다."},{"id":"ss-0360","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"셀 값 0.1(하루의 10%)에 사용자 지정 표시 형식 [mm] 을 적용한 결과는?","options":["2","14","24","144"],"answer":3,"explain":"대괄호 안의 mm은 경과한 총 분을 표시한다. 하루의 10%는 2시간 24분이므로 144분이다. 대괄호 없는 mm은 24(분 부분)만 표시한다."},{"id":"ss-0361","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"셀 값 5.25에 사용자 지정 표시 형식 000.0 을 적용한 결과는?","options":["005.3","05.25","5.3","005.2"],"answer":0,"explain":"정수 부분은 0 자리표시자 3개로 앞에 0을 채우고 소수 첫째 자리까지 반올림하므로 005.3이다."},{"id":"ss-0362","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"[셀 서식]-[맞춤]의 가로 맞춤 '선택 영역의 가운데로'에 대한 설명으로 옳은 것은?","options":["텍스트가 셀 안에서 세로로 회전한다.","텍스트가 셀 높이에 맞춰 여러 줄로 바뀐다.","선택한 셀이 하나로 병합되며 병합 영역의 첫 셀 외 값은 삭제된다.","셀을 병합하지 않고 선택한 여러 셀의 가운데에 제목을 표시한다."],"answer":3,"explain":"선택 영역의 가운데로는 셀 병합 없이 제목을 가운데 표시하므로 열 선택·정렬·필터를 할 때 병합 셀 문제가 없다."},{"id":"ss-0363","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"A2:A31에 날짜가 입력되어 있다. 토요일과 일요일이 있는 행에 서식을 적용하려고 [수식을 사용하여 서식을 지정할 셀 결정] 규칙을 만들 때(활성 셀 A2) 수식으로 옳은 것은?","options":["=WEEKDAY($A2,2)>5","=WEEKDAY($A2,2)>=5","=WEEKDAY(A$2,2)>5","=WEEKDAY($A2)>5"],"answer":0,"explain":"유형 2에서는 월요일=1~일요일=7이므로 5보다 크면 토·일이다. 유형을 생략하면 일요일=1이라 금·토가 걸리고, A$2는 행이 고정되어 모든 행이 A2만 본다."},{"id":"ss-0364","subject":"spreadsheet","levels":["c2","c1"],"topic":"서식","q":"[홈]-[셀 스타일]에 대한 설명으로 옳은 것은?","options":["스타일의 서식을 수정하면 그 스타일을 적용한 모든 셀의 서식이 함께 바뀐다.","스타일을 적용하면 셀의 값도 스타일에 맞게 변경된다.","새 셀 스타일은 만들 수 없고 기본 제공 스타일만 쓸 수 있다.","스타일은 시트 보호를 해제해야만 적용할 수 있다."],"answer":0,"explain":"셀 스타일은 글꼴·테두리·표시 형식 등의 묶음이며 사용자가 새로 만들 수 있다. 값에는 영향을 주지 않는다."},{"id":"ss-0365","subject":"spreadsheet","levels":["c1"],"topic":"서식","q":"사용자 지정 형식 [<1000]0;[<1000000]0.0,\"천\";0.0,,\"백만\" 을 적용한 두 셀에 각각 25000과 3500000을 입력했을 때 표시를 차례로 쓴 것은?","options":["25.0천, 3500.0천","25.0천, 3.5백만","25000, 3500000","25.0백만, 3.5백만"],"answer":1,"explain":"25000은 두 번째 구역(1,000 미만 아님·1,000,000 미만)에서 쉼표 하나로 1,000을 나눠 25.0천, 3500000은 세 번째 구역에서 쉼표 두 개로 1,000,000을 나눠 3.5백만이 된다."},{"id":"ss-0366","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =SUMIF(A2:A7,\"서울\",C2:C7)-SUMIF(A2:A7,\"서울\",D2:D7) 의 결과는?","options":["450","750","1050","1800"],"answer":1,"explain":"서울의 매출 합 1800에서 비용 합 1050을 빼면 750이다."},{"id":"ss-0367","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =COUNTIFS(A2:A7,\"<>서울\",C2:C7,\">=250\") 의 결과는?","options":["1","2","3","4"],"answer":1,"explain":"지점이 서울이 아니면서 매출이 250 이상인 행은 부산 300과 부산 250의 2건이다."},{"id":"ss-0368","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =INDEX(A2:A7,MATCH(MIN(D2:D7),D2:D7,0)) 의 결과는?","options":["대구","부산","120","서울"],"answer":0,"explain":"비용의 최소값 120이 있는 행(5번째)을 MATCH로 찾아 같은 행의 지점 '대구'를 돌려준다."},{"id":"ss-0369","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =IF(C5-D5<0,\"적자\",\"흑자\")&ABS(C5-D5) 의 결과는?","options":["적자-30","적자30","흑자30","적자 30"],"answer":1,"explain":"C5-D5는 250-280=-30으로 0보다 작아 '적자'이고, ABS는 절대값 30을 돌려주며 &로 이어 붙인다."},{"id":"ss-0370","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =AVERAGE(C2:C7)-MEDIAN(C2:C7) 의 결과는?","options":["0","15","25","50"],"answer":2,"explain":"매출 평균은 2550÷6=425이고, 중앙값은 정렬한 값의 가운데 두 값 300과 500의 평균 400이므로 차는 25다."},{"id":"ss-0371","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =A3&\"-\"&TEXT(C3,\"0000\") 의 결과는?","options":["부산-0300","부산-3000","부산-300","서울-0300"],"answer":0,"explain":"TEXT의 형식 0000은 네 자리로 맞춰 앞에 0을 채우므로 300이 0300이 된다."},{"id":"ss-0372","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =COUNTA(A1:D7)-COUNT(A1:D7) 의 결과는?","options":["12","16","24","28"],"answer":1,"explain":"COUNTA는 비어 있지 않은 셀 28개, COUNT는 숫자 셀 12개를 세므로 차는 문자 셀의 수 16이다."},{"id":"ss-0373","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =RANK(C3,C2:C7)&\"위\" 의 결과는?","options":["2위","3위","4위","5위"],"answer":2,"explain":"RANK는 순서를 생략하면 내림차순이다. 300은 700, 600, 500 다음인 4번째로 크다."},{"id":"ss-0374","subject":"spreadsheet","levels":["c2","c1"],"topic":"수식·함수","q":"수식 =TEXT(DATE(2026,10,4)+30,\"yyyy-mm-dd\") 의 결과는?","options":["2026-11-02","2026-11-04","2026-11-03","2026-10-30"],"answer":2,"explain":"날짜는 일련번호이므로 30을 더하면 30일 뒤가 된다. 10월 4일의 30일 뒤는 11월 3일이다."},{"id":"ss-0375","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 배열 수식 {=AVERAGE(IF((A2:A7=\"서울\")*(C2:C7>=600),C2:C7))} 의 결과는?","options":["500","600","650","700"],"answer":2,"explain":"지점이 서울이면서 매출이 600 이상인 값 600과 700만 남겨 평균을 구하면 650이다."},{"id":"ss-0376","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =SUMPRODUCT((A2:A7=\"서울\")*(B2:B7<>\"3Q\")*(C2:C7-D2:D7)) 의 결과는?","options":["200","450","750","1250"],"answer":1,"explain":"서울이면서 3Q가 아닌 행(1Q, 2Q)의 매출-비용(200, 250)을 더해 450이다. 750은 3Q까지 포함한 서울의 합이다."},{"id":"ss-0377","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =SUMPRODUCT(MAX((A2:A7=\"부산\")*C2:C7)) 의 결과는?","options":["250","300","550","700"],"answer":1,"explain":"부산이 아닌 행은 0으로 만들어 그중 최대값을 구하므로 부산의 최대 매출 300이다. SUMPRODUCT로 감싸 배열 수식으로 입력하지 않아도 계산된다."},{"id":"ss-0378","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =INDEX(C2:C7,MATCH(\"부산\"&\"2Q\",INDEX(A2:A7&B2:B7,0),0)) 의 결과는?","options":["200","250","300","600"],"answer":1,"explain":"지점과 분기를 이어 붙인 배열에서 '부산2Q'가 있는 4번째 행을 찾아 같은 행의 매출 250을 돌려준다."},{"id":"ss-0379","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"[표] A1:D7\n지점 | 분기 | 매출 | 비용\n서울 | 1Q | 500 | 300\n부산 | 1Q | 300 | 200\n서울 | 2Q | 600 | 350\n부산 | 2Q | 250 | 280\n대구 | 1Q | 200 | 120\n서울 | 3Q | 700 | 400\n위 표에서 수식 =AGGREGATE(15,6,C2:C7/(A2:A7=\"서울\"),2) 의 결과는?","options":["300","500","600","700"],"answer":2,"explain":"함수 번호 15는 SMALL, 옵션 6은 오류 무시다. 서울이 아닌 행은 0으로 나눈 오류로 제외되어 서울 매출 500, 600, 700 중 두 번째로 작은 값 600이 된다."},{"id":"ss-0380","subject":"spreadsheet","levels":["c1"],"topic":"수식·함수","q":"수식 =IRR({-100,0,121}) 의 결과를 백분율로 나타낸 것은?","options":["5%","10%","11%","21%"],"answer":1,"explain":"현금 흐름의 현재 가치 합이 0이 되는 이율을 구한다. -100+121/(1+r)²=0에서 (1+r)²=1.21이므로 r은 10%다."},{"id":"ss-0381","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[정렬] 대화 상자에서 지정할 수 있는 정렬 기준(수준)의 최대 개수는?","options":["3개","16개","64개","255개"],"answer":2,"explain":"Excel 2007 이후에는 정렬 기준을 최대 64개까지 추가할 수 있다. 이전 버전은 3개였다."},{"id":"ss-0382","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"데이터 유효성 검사 '목록'의 원본에 대한 설명으로 옳지 않은 것은?","options":["같은 시트의 셀 범위를 원본으로 지정할 수 있다.","다른 시트의 범위는 이름을 정의해야만 원본으로 지정할 수 있다.","'드롭다운 표시'를 해제하면 목록 단추는 숨겨지고 입력 제한은 유지된다.","항목을 쉼표(,)로 구분해 직접 입력할 수 있다."],"answer":1,"explain":"Excel 2010 이후에는 다른 시트의 범위도 직접 선택해 원본으로 지정할 수 있다."},{"id":"ss-0383","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 관리","q":"[데이터]-[그룹]과 [부분합]의 차이에 대한 설명으로 옳은 것은?","options":["그룹은 정렬된 데이터에서만 사용할 수 있다.","그룹은 계산 없이 선택한 행·열을 묶어 접고 펼치며, 부분합은 계산 결과 행을 자동으로 삽입한다.","그룹은 선택한 범위를 합계로 계산해 새 행에 나타낸다.","부분합은 행을 접고 펼치는 윤곽 기능이 없다."],"answer":1,"explain":"그룹은 윤곽만 만들고 값을 계산하지 않는다. 부분합은 SUBTOTAL 행을 만들면서 윤곽도 함께 만든다."},{"id":"ss-0384","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"원본 파일의 내용이 바뀔 때마다 통합 문서를 열 때 외부 데이터가 자동으로 갱신되게 하려면?","options":["[보기]-[새 창]으로 원본 파일을 함께 연다.","[연결 속성]에서 '파일을 열 때 데이터 새로 고침'을 선택한다.","[수식]-[계산 옵션]을 '자동'으로 설정한다.","[파일]-[옵션]-[저장]에서 자동 복구 간격을 짧게 한다."],"answer":1,"explain":"연결 속성의 '파일을 열 때 데이터 새로 고침'을 선택하면 열 때마다 외부 데이터를 다시 가져온다. 계산 옵션은 수식 재계산 설정이다."},{"id":"ss-0385","subject":"spreadsheet","levels":["c1"],"topic":"데이터 관리","q":"수식 =UNIQUE(A2:A20) 을 입력하면 결과 값이 인접한 여러 셀에 자동으로 펼쳐지는 Excel 2021·Microsoft 365의 기능 이름은?","options":["Ctrl+Shift+Enter 배열 수식","동적 배열(스필)","데이터 표","피벗 캐시"],"answer":1,"explain":"동적 배열은 수식 하나가 여러 값을 돌려주면 아래·옆 셀로 자동 확장(스필)된다. 기존 배열 수식은 Ctrl+Shift+Enter로 범위를 미리 지정해야 했다."},{"id":"ss-0386","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"피벗 테이블 필드 창의 '필터' 영역에 필드를 놓았을 때의 결과는?","options":["필드가 행 레이블로 이동한다.","보고서 위쪽에 드롭다운 단추가 생겨 전체 보고서를 선택한 항목만으로 걸러 볼 수 있다.","필드의 값이 합계로 계산되어 값 영역에 표시된다.","필드가 원본 데이터에서 삭제된다."],"answer":1,"explain":"필터 영역(보고서 필터)은 피벗 테이블 전체에 적용되는 조건을 지정한다."},{"id":"ss-0387","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"B1에 단가 20, B2에 수량 5, B3에 매출 =B1*B2 가 있다. 목표값 찾기로 B3이 300이 되도록 '값을 바꿀 셀'을 B2로 지정해 실행하면 B2의 값은?","options":["10","15","20","30"],"answer":1,"explain":"20×수량=300이 되는 수량은 15다. 목표값 찾기는 수식 셀의 결과가 찾는 값이 되도록 입력 셀의 값을 바꾼다."},{"id":"ss-0388","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"시나리오 요약 보고서의 '결과 셀'에 지정하는 것은?","options":["시나리오 설명을 입력할 셀","시나리오에서 값을 바꿀 입력 셀","시나리오별로 달라지는 값을 비교해 보고 싶은 결과 수식 셀","시나리오 이름을 저장할 셀"],"answer":2,"explain":"변경 셀에는 시나리오마다 다른 값을 넣을 입력 셀을, 결과 셀에는 그에 따라 변하는 수식 셀(예: 이익)을 지정한다."},{"id":"ss-0389","subject":"spreadsheet","levels":["c1"],"topic":"데이터 분석","q":"데이터 표로 채워진 결과 범위에서 셀 하나만 지우려 하면 어떻게 되는가?","options":["그 셀만 지워지고 나머지 결과는 그대로 유지된다.","해당 행 전체가 삭제된다.","'데이터 표의 일부를 변경할 수 없습니다' 경고가 나타나며, 범위 전체를 선택해야 지울 수 있다.","데이터 표가 자동으로 다시 계산되어 지운 셀이 복구된다."],"answer":2,"explain":"데이터 표의 결과는 {=TABLE(…)} 배열 수식으로 한 덩어리라 일부만 수정·삭제할 수 없다."},{"id":"ss-0390","subject":"spreadsheet","levels":["c2","c1"],"topic":"데이터 분석","q":"[통합] 대화 상자의 '함수' 목록에 없는 것은?","options":["최대","합계","표준 편차","중앙값"],"answer":3,"explain":"통합 함수에는 합계·개수·평균·최대·최소·곱·숫자 개수·표준 편차·분산 등이 있고 중앙값은 없다."},{"id":"ss-0391","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"가로 막대형 차트에서 표의 첫 항목이 맨 아래에 표시된다. 표의 순서대로 맨 위부터 표시하려면 세로(항목) 축 서식에서 무엇을 선택해야 하는가?","options":["로그 눈금 간격","항목을 거꾸로","가로 축 교차 위치 변경","표시 단위"],"answer":1,"explain":"가로 막대형은 첫 항목이 아래에서 시작한다. '항목을 거꾸로'를 선택하면 표의 순서와 같게 위에서부터 표시된다."},{"id":"ss-0392","subject":"spreadsheet","levels":["c1"],"topic":"차트","q":"차트 제목을 특정 셀의 내용과 연결하려면 어떻게 하는가?","options":["[셀 서식]의 '차트' 탭에서 연결할 셀을 지정한다.","차트 영역을 해당 셀로 끌어다 놓는다.","제목 상자에 셀 주소만 직접 입력한다.","차트 제목을 선택하고 수식 입력줄에 =시트이름!셀 주소 를 입력한다."],"answer":3,"explain":"제목을 선택한 상태에서 =Sheet1!$A$1 처럼 입력하면 셀 값이 바뀔 때 제목도 함께 바뀐다."},{"id":"ss-0393","subject":"spreadsheet","levels":["c2","c1"],"topic":"차트","q":"차트를 끌어 이동하거나 크기를 조절할 때 Alt 키를 누른 채 작업하면?","options":["차트가 그림으로 바뀐다.","셀 경계선에 맞추어 정확히 정렬된다.","차트의 가로세로 비율이 고정된다.","차트가 복사된다."],"answer":1,"explain":"Alt 키를 누르고 끌면 차트의 가장자리가 셀 경계에 달라붙어 위치와 크기를 셀에 맞출 수 있다."},{"id":"ss-0394","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"[페이지 설정]-[시트] 탭에서 '행/열 머리글'을 선택했을 때의 결과는?","options":["인쇄물에 행 번호와 열 문자(A, B, C...)도 함께 인쇄된다.","시트 이름이 모든 페이지의 위쪽에 인쇄된다.","머리글/바닥글에 행과 열의 정보가 추가된다.","표의 첫 행이 모든 페이지에 반복되어 인쇄된다."],"answer":0,"explain":"행/열 머리글은 화면의 행 번호·열 문자를 인쇄물에도 표시한다. 표 제목 반복은 '반복할 행'으로 지정한다."},{"id":"ss-0395","subject":"spreadsheet","levels":["c2","c1"],"topic":"출력","q":"페이지 나누기 미리 보기에서 가장 바깥쪽 파란색 실선 테두리를 끌어 조정하면 변경되는 것은?","options":["인쇄 영역","용지 크기","인쇄 배율","머리글 위치"],"answer":0,"explain":"바깥쪽 파란 테두리는 인쇄 영역의 경계이며 끌어서 인쇄 범위를 조정할 수 있다. 안쪽 점선은 자동, 실선은 수동 페이지 나누기다."},{"id":"ss-0396","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 문자()\n    Dim s As String\n    s = \"Excel2026\"\n    MsgBox Left(s, 2) & Len(s) & Right(s, 2)\nEnd Sub","options":["Ex926","Ex2026","Ec926","Ex26"],"answer":0,"explain":"Left(s,2)는 'Ex', Len(s)는 문자 수 9, Right(s,2)는 '26'이므로 이어 붙이면 Ex926이다."},{"id":"ss-0397","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"통합 문서를 닫기 직전에 자동으로 실행되는 이벤트 프로시저는?","options":["Workbook_AfterSave","Workbook_Deactivate","Workbook_BeforeClose","Workbook_Close"],"answer":2,"explain":"Workbook_BeforeClose는 통합 문서가 닫히기 전에 발생한다. Workbook_Close라는 이벤트는 없고, Deactivate는 다른 창으로 전환될 때, AfterSave는 저장한 뒤 발생한다."},{"id":"ss-0398","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행한 뒤 변수 r의 값은?\nn = 10\nIf n Mod 15 = 0 Then\n    r = \"FizzBuzz\"\nElseIf n Mod 5 = 0 Then\n    r = \"Buzz\"\nElseIf n Mod 3 = 0 Then\n    r = \"Fizz\"\nElse\n    r = n\nEnd If","options":["FizzBuzz","10","Fizz","Buzz"],"answer":3,"explain":"10은 15로 나누어떨어지지 않고 5로는 나누어떨어지므로 두 번째 조건이 참이 되어 r은 Buzz이며 이후 조건은 검사하지 않는다."},{"id":"ss-0399","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 프로시저를 실행했을 때 메시지 상자에 표시되는 값은?\nSub 곱()\n    Dim i As Integer, j As Integer\n    For i = 1 To 3\n        For j = 1 To 3\n            Cells(i, j).Value = i * j\n        Next j\n    Next i\n    MsgBox Cells(3, 2).Value + Cells(2, 3).Value\nEnd Sub","options":["5","9","12","18"],"answer":2,"explain":"Cells(3,2)=3×2=6, Cells(2,3)=2×3=6이므로 합은 12다."},{"id":"ss-0400","subject":"spreadsheet","levels":["c1"],"topic":"매크로·VBA","q":"다음 코드를 실행했을 때 메시지 상자에 표시되는 값은?\nFunction 제곱합(a, b)\n    제곱합 = a ^ 2 + b ^ 2\nEnd Function\n\nSub 실행()\n    MsgBox 제곱합(3, 4)\nEnd Sub","options":["7","14","25","49"],"answer":2,"explain":"Function은 함수 이름에 값을 대입해 결과를 돌려준다. 3²+4²=9+16=25다."}]};
